window.FIQH_DATA={"t":"Fiqh Syafi'i","c":[{"t":"Rubu' Ibadat","c":[{"t":"Pengenalan","c":[{"t":"Agama Islam","c":[{"t":"Erti Agama Islam","p":11,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Dibina (ditegakkan) Islam: itu di atas lima perkara: Pengakuan, bahawa tidak ada tuhan melainkan Allah, dan bahawa Muhammad itu Rasulullah. Menegakkan sembahyang, mengeluarkan zakat, haji ke baitullah dan berpuasa di bulan Ramadan.","r":"Bukhari dan Muslim"}],"te":"Meaning of the Religion of Islam"},{"t":"Islam Merupakan Rumahtangga yang Mudah","p":12,"v":1,"d":[{"y":"a","s":5,"a":44,"b":44,"m":"Dan sesiapa yang tidak menghukum (memberikan peraturan) menurut yang diturunkan Allah, maka mereka ini adalah orang yang kafir. |"},{"y":"a","s":5,"a":45,"b":45,"m":"Dan sesiapa yang tidak menghukum (memberikan peraturan) menurut yang diturunkan oleh Allah, maka merekalah orang-orang yang zalim"},{"y":"a","s":5,"a":47,"b":47,"m":"Dan sesiapa yang tidak menghukum (memberikan peraturan) menurut yang diturunkan oleh Allah, maka merekalah orang-orang yang fasik"}],"te":"Islam Is an Easy Household"}],"p":11,"v":1,"te":"The Religion of Islam"}],"p":11,"v":1,"te":"Introduction"},{"t":"Kitab Bersuci","c":[{"t":"Asas Bersuci","p":14,"v":1,"c":[{"t":"Erti Bersuci dan Hikmatnya","p":14,"v":1,"d":[{"y":"a","s":2,"a":222,"b":222,"m":"Sesungguhnya Allah menyukai orangorang yang bertaubat dan menyukai orang-orang yang bersuci"},{"y":"h","x":"Dari Ibnu Umar r.a. katanya: Bersabda Rasulullah s.a.w.: Tidak diterima Allah sesuatu sembahyang dengan tidak bersuci.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesungguhnya Allah tidak melihat kepada tubuh dan rupa kamu, tetapi Allah memandang kepada hati kamu.","r":"Muslim"}],"te":"Meaning and Wisdom of Purification"},{"t":"Air yang boleh Digunakan untuk Bersuci","p":15,"v":1,"d":[{"y":"a","s":8,"a":11,"b":11,"m":"Dan Allah menurunkan air ke atasmu dari langit, untuk mensucikan kamu dengannya"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. pernah bersabda tentang laut: Laut itu suci airnya, lagi halal bangkainya.","r":"Tirmizi"}],"te":"Water That May Be Used for Purification"},{"t":"Yang Dimaksud dengan Air Mutlak dan Air yang Dipanasi oleh Matahari","p":16,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a.: Bahawasanya ia pernah memanaskan air di cahaya matahari, lalu Rasulullah s.a.w. berkata kepadanya: Janganlah engkau berbuat (yang seperti itu) wahai, Humairah (panggilan kesayangan), kerana hal itu dapat mendatangkan pepenyakit balar'!","r":"Baihaqi"}],"te":"Pure Unrestricted Water (Mutlak) and Sun-Heated Water"},{"t":"Yang Dimaksud dengan Air yang Mustakmal dan Air yang Berubah","p":18,"v":1,"te":"Used Water (Mustakmal) and Altered Water"},{"t":"Air yang Banyak dan Air yang Sedikit","p":19,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. katanya: Bersabda Rasulullah s.a.w.: Bila air telah sampai dua kulah, maka tidaklah ia mengandung najis.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Amamah r.a. katanya: Telah bersabda Rasulullah s.a.w.: Bahawasanya air tidak sesuatupun menajisinya, kecuali bila telah berubah bau, rasa dan warna airnya.","r":"Ibnu Majah dan Baihaqi"}],"te":"Large and Small Amounts of Water"}],"te":"Basics of Purification"},{"t":"Najis","c":[{"t":"Najis Mughallazah","p":20,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a., ia berkata: Bersabda Rasullulah s.a.w.: Basuhlah bejana seseorang itu bila anjing telah menjilat ke dalamnya, ialah bahawa bejana itu dibasuh tujuh kali, salah satunya dicampur dengan tanah.","r":"Muslim"},{"y":"a","s":6,"a":145,"b":145,"m":"Atau yang diharamkan juga, daging babi itu adalah a (najis)"}],"te":"Heavy Impurity (Mughallazah)"},{"t":"Najis Mukhaffafah","p":21,"v":1,"d":[{"y":"h","x":"Dari Ali r.a.: Bahawasanya Nabi s.a.w. bersabda tentang anakanak bayi yang sedang menyusu: Baul (kencing) anak perempuan dibasuh, dan baul anak laki-laki dipercik dengan air.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ummi Qais r.a.: Sesungguhnya ia pernah membawa seorang anaknya laki-laki yang belum memakan makanan. Lalu didudukkan Rasulullah s.a.w. anak itu di pangkuannya, dan anak itu kencing di atas pangkuannya. Maka Rasullah s.a.w. meminta air, lalu dipercikkan air itu ke kencinga itu dan tidak dibasuhnya.","r":"Bukhari dan Muslim"}],"te":"Light Impurity (Mukhaffafah)"},{"t":"Najis Mutawassitah","p":22,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. telah berkata: Pernah datang seorang Arab dusun, lalu ia kencing di sudut masjid, lalu ia dibentak oleh orang ramai. Maka mereka dilarang oleh Rasulullah s.a.w. Setelah orang itu selesai kencingnya (baulnya), diperintahkan oleh Rasulullah s.a.w. mengambil setimba air, lalu disiramkan di atas kencingnya itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Ubaidah, dari Abdullah ia berkata: Nabi s.a.w. pernah keluar untuk buang air besar, lalu beliau bersabda: Carikan untukku tiga buah batu. Abdullah berkata: Lalu aku bawakan kepada beliau dua buah batu dan tahi kering. Maka beliau mengambil kedua batu itu dan membuang yang tahi kering, sambil bersabda: Sesungguhnya jahananan","r":"Tirmizi"},{"y":"h","x":"Dari Asma' binti Abu Bakar r.a.: Bahawasanya Nabi s.a.w. pernah bersabda tentang darah haid yang mengenai kain: Engkau buangkanlah darah itu, kemudian siram dengan air, kemudian gosoklah, (kemudian boleh engkau pakai sembahyang).","r":"Bukhari dan Muslim"},{"y":"a","s":6,"a":145,"b":145,"m":"Katakanlah Ya Muhammad! Tidak aku peroleh pada wahyu yang diturunkan kepadaku sesuatu makanan yang diharamkan atas orang yang memakannya, kecuali bangkai, darah mengalir atau daging ' babi, kerana sesungguhnya sekaliannya itu barang yang keji (najis) atau terlarang"},{"y":"h","x":"Dari Ali r.a. bahawasanya ia pernah berkata: Aku adalah seorang laki-laki yang sering keluar mazi. Maka malu aku menanyakan hukumnya kepada Rasulullah s.a.w. kerana ia mertuaku; lalu aku suruh Miqdad bin Aswad menanyakan. Lantas Miqdad menanyakan masalah itu. Maka berkata Rasulullah s.a.w.. Boleh dibasuhnya saja kemaluannya lalu berwuduk.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a.: Sesungguhnya ia pernah membuangkan mani dari kain Nabi s.a.w. kemudian beliau sembahyang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a.: Bahawasanya Nabi s.a.w. telah bersabda: Janganlah kamu anggap najis mayat kamu itu, kerana sesungguhnya orang mukmin itu tidak najis, biar pada waktu hidupnya mahupun di waktu matinya.","r":"Hakim dan Baihaqi"},{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. katanya: Dihalalkan bagi kita dua macam bangkai dan dua macam darah. Adapun dua macam bangkai, ialah ikan dan belalang, dan yang dua macam darah ialah kan dan ampa,","r":"Ibnu Majah dan Hakim"},{"y":"a","s":5,"a":90,"b":90,"m":"Sesungguhnya arak, judi, berhala dan mengundi nasib dengan anak panah itu adalah pekerjaan yang keji (najis), ia termasuk pekerjaan syaitan, oleh sebab itu hendaklah kamu jauhinya"},{"y":"h","x":"Dari Abu Waqid Al-Laisi r.a. katanya: Telah bersabda Rasulullah s.a.w.: “Sesuatu yang dipotong dari daging binatang yang masih hidup, maka daging itu sama dengan bangkai hukumnya.” :","r":"Abu Daud dan Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. katanya: Telah bersabda Rasulullah s.a.w: Bila lalat jatuh ke dalam minuman salah seorang di antara kamu, maka hendaklah rendamkan lalat itu, kerana pada salah satu sayapnya itu ada penyakit dan pada sayap yang lain ada ubat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. katanya: Telah bersabda Rasulullah s.a.w.: Bila kulit telah disamak, maka sesungguhnya telah sucilah ia.","r":"Muslim"}],"te":"Medium Impurity (Mutawassitah)"}],"p":20,"v":1,"te":"Impurity (Najis)"},{"t":"Beristinjak","c":[{"t":"Erti Beristinjak","p":29,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. Bahawa Nabi s.a.w. pernah bersabda: Bila seseorang pergi ke tempat buang air (hendak ghait), maka hendaklah ia membawa tiga buah batu.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. pernah bersabda: Maka hendaklah seseorang beristinjak dengan tiga buah batu.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa beristinjak dengan batu, maka hendaklah ia ganjilkan bilangannya, sesiapa yang memperbuat begitu, maka sungguh itulah yang lebih baik, tetapi sesiapa yang tidak berbuat begitu, maka tidaklah ia berdosa.","r":"Ahmad dan Abu Daud"}],"te":"Meaning of Istinjak"},{"t":"Beristinjak dengan Barang selain Air Mutlak","p":30,"v":1,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. Bahawa Nabi s.a.w. pernah bersabda: “Janganlah kamu beristinjak dengan tahi kering, dan jangan pula dengan tulang-tulang, kerana sesungguhnya tulang-tulang itu jadi makanan saudaramu bangsa jin.” |","r":"Tirmizi"}],"te":"Istinjak with Things Other Than Water"},{"t":"Keadaan Najis yang Keluar dan Cara Beristinjak dengan Batu dan Lain-Lainnya","p":31,"v":1,"te":"Impurity That Comes Out, and Istinjak with Stones and the Like"},{"t":"Tuntutan Beristinjak","p":31,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. katanya: Telah bersabda Nabi s.a.w.: Bersucilah kamu dari baul, kerana sesungguhnya kebanyakan seksaan kubur disebabkan baul itu.","r":"Daruqutni dengan Sanad Sahih"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. pernah melalui dua buah kubur, lalu beliau bersabda: Sesungguhnya kedua mayat yang ada di dalam kubur ini sedang diseksa. Dan apakah soal yang lebih berat yang menyeksa keduanya? Tanya para sahabat. Adapun salah seorang di antara keduanya, adalah ia berjalan dengan mengadu-ngadu memfitnahkan orang dan adapun yang lain, kerana ia tidak mahu membersihkan baulnya.","r":"Bukhari dan Muslim"}],"te":"The Requirement of Istinjak"},{"t":"Yang Wajib dalam Beristinjak","p":32,"v":1,"te":"What Is Obligatory in Istinjak"}],"p":29,"v":1,"te":"Cleaning After the Toilet (Istinjak)"},{"t":"Masuk Tandas","c":[{"t":"Adab Masuk ke dalam Tandas","p":33,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. katanya: Adalah Nabi s.a.w. bila masuk ke dalam tandas, beliau membaca: Ya Allah, sesungguhnya aku berlindung kepada Engkau dari syaitan laki-laki dan syaitan perempuan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. Bahawa Nabi s.a.w. apabila beliau masuk tandas, diletakkannya (dibukanya) cincinnya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Abbas bin Sarijir.a. berkataia: Adalah Rasulullah s.a.w. bila beliau masuk tandas, beliau memakai kasutnya.","r":"Baihaqi"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Rasulullah s.a.w. bila beliau hendak masuk tandas, beliau menutup kepalanya.","r":"Baihaqi"}],"te":"Etiquette of Entering the Toilet"},{"t":"Adab ketika Buang Air dan ketika Keluar dari Tandas","p":34,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawa Nabi s.a.w. bersabda: Bila seseorang duduk akan buang air, maka janganlah ia menghadap ke kiblat dan jangan pula membelakanginya.","r":"Muslim"},{"y":"h","x":"Dari Abdullah bin Sarjasa. Bahawasanya Nabi s.a.w. pernah melarang buang air kecil di lubang-lubang, mereka bertanya kepada Qatadah (sahabat Nabi), apakah yang menyebabkan Rasulullah melarang buang air di lubang-lubang. Ia menjawab: Pernah diceritakan orang, bahawa lubang-lubang itu tempat tinggal jin.","r":"Nasai dan Abu Daud"},{"y":"h","x":"Dari Muaz r.a. Bahawa Nabi s.a.w. telah bersabda: Hati-hatilah tentang kedatangan kutuk dari tiga macam iaitu, buang air di bandar-bandar (tempat mandi dll), di pinggir jalan dan di tempat manusia berlindung.","r":"Abu Daud dan Ibnu Majah"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Rasulullah s.a.w. telah bersabda: Jika dua orang hendak ghait (buang air besar), maka hendaklah tiap-tiap seorang dari keduanya bertutup dan janganlah berkata-kata, kerana sesungguhnya Allah sangat marah atas yang demikian itu.","r":"Ahmad"},{"y":"h","x":"Dari Abu Zar r.a. Bahawasanya Nabi s.a.w. apabila sudah keluar dari tandas, beliau membaca: Segala puji bagi Allah yang telah membuangkan penyakit dari diriku dan telah mengembalikan kesihatanku.","r":"Nasai"}],"te":"Etiquette While Relieving Oneself and When Leaving the Toilet"}],"p":33,"v":1,"te":"Entering the Toilet"},{"t":"Berwuduk","c":[{"t":"Erti Berwuduk dan Keutamaannya","p":36,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawa Rasulullah s.a.w. telah bersabda: Bila seseorang Muslim atau Mukmin berwuduk, lalau ia basuh mukanya, maka keluarlah dari mukanya semua kesalahan yang dilihat dengan dua matanya bersama air atau akhir titisan air wuduk- nya. Maka bila ia basuh tangannya, keluarlah semua kesalahan yang dibuat oleh dua tangannya bersama air atau akhir titisan air wuduknya. Maka bila ia basuh dua kakinya keluarlah semua kesalahan, yang dijalankan oleh dua kakinya bersama air atau akhir titisan air wuduknya, sehingga ia keluar bersih dari segala dosa.","r":"Muslim"}],"te":"Meaning and Virtues of Wudhu"},{"t":"Fardu atau Rukun Wuduk","p":37,"v":1,"d":[{"y":"h","x":"Dari Umar bin Khattab r.a. katanya: Pernah aku mendengar Rasulullah s.a.w bersabda: Amal ibadat itu hanya sah dengan berniat dan bagi tiap-tiap manusia itu diberi ganjaran menurut apa yang diniatkan.","r":"Bukhari dan Muslim"},{"y":"a","s":5,"a":6,"b":6,"m":"Hai orang-orang yang beriman! Bila kamu hendak mengerjakan sembahyang, maka basuhlah mukamu dan dua tanganmu hingga kedua mata siku dan sapulah kepalamu dan kedua kakimu hingga dua buku lali. Pu P TalwuUl"},{"y":"h","x":"Dari Jabir r.a. mengenai sifat haji Rasulullah s.a.w., beliau bersabda: Mulailah olehmu dengan apa yang telah dimulai oleh Allah.","r":"Muslim dan Nasai"}],"te":"Obligatory Acts (Pillars) of Wudhu"},{"t":"Sunat-Sunat Berwuduk","p":39,"v":1,"d":[{"y":"h","x":"Dari Abu Habbah r.a. katanya: Pernah aku melihat Ali r.a. berwuduk, maka dibasuhnya kedua tapak tangannya, hingga bersih. Dan hadis seterusnya... kemudian Ali berkata: Aku suka memperlihatkan kepadamu, bagaimana cara Rasulullah s.a.w. bersuci.","r":"Tirmizi"},{"y":"h","x":"Dari Laqit bin Shabrah r.a. katanya: Aku bertanya: Ya Rasulullah, ceritakanlah kepadaku tentang cara berwuduk. Jawab beliau: Sempurnakanlah berwuduk dan sela-selalah anak-anak jari dan bersungguh-sungguhlah beristinjak, kecuali bila engkau dalam berpuasa.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abdullah bin Zaid r.a. Bahawasanya ia pernah mensifatkan wuduk Rasulullah s.a.w. Maka dituangkannya air ke atas dua (telapak) tangannya, maka dibasuk keduanya. Kemudian dimasukkan tangannya ke dalam bejana, lalu ia membasuhnya, terus berkumurkumur, beristinsaq dan menghirup air sebanyak tiga kali sauk dari air itu.","r":"Bukhari"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. Bahawasanya beliai'\" pernah bersabda: Kalaulah tidak memberatkan kepada umatku, nes- - caya aku perintahkan (wajibkan) mereka bersugi pada tiap-tiap kali berwuduk.","r":"Malik dan Ahmad"},{"y":"h","x":"Dari Abu Hurairah r.a. katanya: Bersabda Rasulullah s.a.w.: Bila kamu hendak berwuduk, maka mulailah dengan kananmu.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Rafi' r.a. Adalah Rasulullah s.a.w. apabila berwuduk, di gerak-gerakkan cincinnya.","r":"Ibnu Majah dan Daruqutni"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. berwuduk dengan tiga kali-tiga kali.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Rasulullah s.a.w. telah menyapu kepalanya dan kedua telinganya luar dan dalam.","r":"Tirmizi"},{"y":"h","x":"Dari Abdullah bin Zaid bin Ashim r.a. mengenai sifat-sifat wuduk ia berkata: Rasulullah s.a.w. telah menyapukan kepalanya lalu diarahkan kedua tangannya ke depan, lalu digerak-gerakkan ke belakang dimualinya menyapu kepalanya bahagian depan, hingga disapukan kedua tangannya itu sampai ke kuduknya (kepala bahagian depan), kemudian dikembalikan kedua tangannya itu ke tempat beliau mulai.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Usman bin Affanr.a. Bahawasanya Nabi s.a.w. beliau selalu menggosok-gosok janggutnya waktu berwuduk.","r":"Tirmizi"},{"y":"h","x":"Dari Abu Amamah r.a. katanya: Adalah Rasulullah s.a.w. menggosoklmembersihkan kedua sudut matanya.","r":"Ahmad dan Ibnu Majah"},{"y":"h","x":"Dari Abu Hurairah r.a. katanya: Bersabda Rasulullah s.a.w.: “Wajahmu akan bercahaya nanti di hari kiamat disebabkan kesempurnaan wudukmu, maka sesiapa di antara kamu yang kuasa, hendaklah memanjangkan ghurrah dan tahjilnya.”'","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdullah bin Zaidr.a. Bahawasanya Nabi s.a.w. berwuduk, maka beliau bersabda: Beginilah lalu beliau menggosok-gosok anggota wuduknya. US ay,","r":"Ahmad"},{"y":"h","x":"Dari Umar r.a. Bahawasanya seorang laki-laki pernah berwuduk, maka tertinggal olehnya kira-kira sebesar kuku di atas tumitnya, maka nampak oleh Nabi s.a.w. lalu beliau bersabda: “Kembali dan sempurnakanlah wudukmu,” maka ia kembali menyempurnakan wuduk, kemudian ia sembahyang.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Umar r.a. dari Nabi s.a.w. bersabda: Apabila ada salah seorang di antara kamu yang berwuduk, lantas disempurnakan wuduknya, kemudian membaca: “Aku bersaksi, bahawa tidak ada tuhan melainkan Allah, dan aku bersaksi, bahawa Muhammad itu hambaNya dan Rasul-Nya.” Maka dibukakan baginya beberapa pintu syurga yang lapan yang akan dimasukinya dari mana saja dia kehendaki.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. pernah melihat seorang laki-laki yang tidak membasuh tumitnya, beliau bersabda: Seksaan nerakalah bagi orang-orang yang tidak membasuh tumitnya.","r":"Bukhari dan Muslim"}],"te":"Sunnah Acts of Wudhu"}],"p":36,"v":1,"te":"Ablution (Wudhu)"},{"t":"Yang Membatalkan Wuduk","c":[{"t":"Hadas Kecil","p":45,"v":1,"d":[{"y":"a","s":5,"a":6,"b":6,"m":"Atau (yang menyebabkan wajib wuduk juga, ialah) bila datang salah seorang daripada kamu dari ghait, atau kamu menyentuh perempuan"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Rasulullah s.a.w. pernah bersabda: Bila seseorang di antara kamu mengantuk sedang ia dalam sembahyang, maka hendaklah ia tidur lebih dahulu, hingga hilang mengantuknya itu. Maka sesungguhnya seseorang bila ia telah sembahyang, sedang ia mengantuk, ia tidak sedar barangkali dalam ia meminta ampun, tetapi ia mencaci dirinya.","r":"Bukhari"},{"y":"a","s":4,"a":43,"b":43,"m":"Hai orang-orang yang beriman, janganlah kamu kerjakan sembahyang apabila kamu sedang mabuk, sehingga kamu menyedari apa yang kamu baca"},{"y":"h","x":"Dari Abu Hurairah r.a. berkata ia: Bersabda Nabi s.a.w.: Tidak wajib berwuduk, kecuali kerana kedengaran bunyi (kentut) atau berbau busuk.","r":"Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Pernah aku tidur di sisi Rasulullah s.a.w., sedangkan dua kakiku berada di kiblatnya. Maka bila beliau sujud, beliau pegang aku (ghamazani), lalu aku ketubkan kakiku. Maka bila beliau berdiri, aku bujurkan kembali kakiku, sedang rumah ketika itu tidak ada lampu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. berkata: Pernah aku kehilangan Rasulullah s.a.w. pada sesuatu malam dari tempat tidurku. Lalu tiba-tiba tersentuh aku kepadanya, maka hinggaplah tanganku di perut dua telapak kakinya, sedang berada dalam masjid. Kedua-dua kakinya itu ditegakkan sambil berdoa: Ya Allah, Sesungguhnya aku berlindung dengan keredaan Engkau dan aku berlindung dengan Engkau Engkau dari seksaan Engkau dan aku berlindung dengan Engkau dari segala yang datang dari Engkau. Tidak dapat aku menghitung sanjungan di atas Engkau. Engkaulah, sebagaimana Engkau menyanjungi di atas diri Engkau Sendiri.","r":"Muslim"},{"y":"h","x":"Dari Busrah binti Shafwan: Bahawasanya Rasulullah s.a.w. telah bersabda: Barang siapa yang telah menyentuh kemaluannya, maka hendaklah ia berwuduk kembali.","r":"As-habus Sunan"},{"y":"h","x":"Dari Anas r.a. ia berkata: Adalah sahabat-sahabat Rasulullah s.a.w. pernah menunggu-nunggu waktu Isyak yang terakhir, hingga kepala mereka terlentok-lentok kian ke mari (kerana tertidur sambil) duduk), kemudian mereka sembahyang dan tidak mereka ulang kembali wuduk mereka.","r":"Abu Daud"},{"y":"h","x":"Dari Anas r.a. ia pernah berkata: Pernah sahabat-sahabat Rasulullah s.a.w. tertidur, kemudian mereka sembahyang dan tidak mereka berwuduk kembali.","r":"Muslim"}],"te":"Minor Ritual Impurity (Hadas Kecil)"},{"t":"Yang Diharamkan ketika Berhadas Kecil","p":51,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. bersabda: Allah tidak menerima sembahyang seseorang dari kamu bila ia telah berhadas sehingga ia bernyaduk kembali.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. katanya: Bersabda Rasulullah s.a.w.: Tawaf di rumah Allah (Kaabah) itu ialah sembahyang, bezanya, sesungguhnya Allah membolehkan berkata-kata dalam kedaaan tawaf.","r":"Baihaqi"},{"y":"h","x":"Dari Umar bin Hizam, dari Nabi s.a.w. katanya: Janganlah engkau menyentuh Quran itu, melainkan apabila engkau dalam keadaan suci.","r":"Malik dan Baihaqi"},{"y":"a","s":56,"a":79,"b":79,"m":"Tidak boleh menyentuh Al-Quran itu, melainkan orang yang suci"},{"y":"a","s":9,"a":20,"b":20,"m":"tahir mempunyai beberapa makna, iaitu: 1. Bererti mukmin, dengan alasan firman Allah: SESUNGGUHNYA ORANG MUSYRIK ITU NAJIS"},{"y":"a","s":56,"a":75,"b":75,"m":"Memakaikan kalimat yang musytarak untuk dua atau beberapa maknanya dibolehkan. Ini menurut mazhab Jumhur Ulama, Syafii, Al-Qadhi Abu Bakar dan Abu Ali Al-Jabbari. Dengan melihat kepada pendapat ini, maka orang yang boleh menyentuh Al-Quran (mashaf) itu ialah orang-orang yang suci dari segala apa yang telah disebutkan di atas itu. Berkata Ibnu Kasir dalam Tafsirnya. Dan berlain-lain faham orang dalam perkara makna, firman Allah yang berbunyi: yi a"}],"te":"What Is Forbidden in Minor Ritual Impurity"},{"t":"Hadas Besar","p":55,"v":1,"d":[{"y":"a","s":5,"a":6,"b":6,"m":"Dan apabila kamu dalam junub, maka mandilah kamu"},{"y":"h","x":"Dari Aisyah rja. ia berkata: Rasulullah s.a.w. bersabda: Bila seseorang telah duduk (menelengkup)' antara cabang-cabang yang empat (dari bidan perempuan), dan khitan telah menyentuh khitan, maka sungguh telah wajib mandi. Dalam satu riwayat, sekalipun tidak keluar mani.","r":"Muslim"},{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Pernah datang Ummu Sulaim kepada Rasulullah s.a.w. lalu ia bertanya: Sesungguhnya Allah tidak malu tentang pertanyaan yang sebenar; adakah wajib mandi atas perempuan, bila ia bermimpi? (maksudnya keluar air mani). Menjawab Rasulullah s.a.w.: Ya, bila ia melihat air mani.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Rasulullah s.a.w. bersabda kepada Fatimah binti Hubaisy: Bila datang haid, maka tinggalkanlah sembahyang, dan bila telah habis, maka mandilah engkau dan sembahyanglah.","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Rasulullah s.a.w. bersabda, tentang seorang laki-laki yang mati dalam keadaan mengerjakan ihram (haji): Mandikanlah dia dengan air dan sidir (bidara), kemudian kafanilah dia dengan dua helai kainnya.","r":"Bukhari dan Muslim"}],"te":"Major Ritual Impurity (Hadas Besar)"},{"t":"Tanda Baligh","p":57,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah aku dibawa kepada Rasulullah s.a.w. ketika perang Uhud, sedang aku baru berumur 14 tahun, maka aku ditolak beliau, kemudian aku dihadapkan pula kepada beliau pada perang khandak sedang aku ketika itu telah berumur 15 tahun, maka dibolehkan beliau aku ikut.","r":"Bukhari dan Muslim"},{"y":"a","s":24,"a":59,"b":59,"m":"Dan bila anak-anak kamu telah baligh, maka hendaklah mereka minta izin (keluar masuk bilik) sebagaimana minta izin orang-orang sebelum mereka"}],"te":"Signs of Puberty"},{"t":"Jumlah Hari Haid dan Warna Darahnya","p":28,"v":1,"d":[{"y":"h","x":"Dari Abu Amamah r.a. dari Nabi s.a.w. beliau bersabda: Tidak ada haid yang lebih bilangannya dari sepuluh hari, dan tidak pula ada yang kurang dari 3 hari.","r":"Daruquthi"},{"y":"h","x":"Dari Hamnah binti Jahsy: Bahawasanya Nabi s.a.w. pernah berkata kepadanya: Engkau haid dalam ilmu Allah enam atau tujuh hari, sebagaimana haid perempuan-perempuan lain, dan sebagaimana mereka suci menurut waktu haid dan waktu suci mereka pula.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Fatimah binti Hubaisy: Bahawasanya ia pernah bertanya: Ya Rasulullah, sesungguhnya aku ini sedang haid. Maka menjawab Rasulullah s.a.w. kepadanya: Jika darah itu betul darah haid, maka sesungguhnya darah haid itu hitam warnanya yang dikenal (di kalangan kaum perempuan) maka bila benar demikian itu, maka berhentilah engkau sembahyang, tetapi bila lain warnanya (bukan seperti darah haid), maka berwuduklah dan sembahyanglah engkau, kerana darah yang semacam itu keluar dari urat.","r":"Abu Daud dan Nasai"}],"te":"Length of Menstruation and the Colour of Its Blood"},{"t":"Darah Istihadhah dan Cara Mengerjakan Sembahyang","p":60,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a.: Bahawasanya Fatimah binti Hubaisy pernah bertanya kepada Nabi s.a.w. katanya: Sesungguhnya aku sedang haid, belum juga aku suci, akan kutinggalkankah sembahyang? Lalu Rasulullah menjawab: Jangan, sesungguhnya itu darah urat (yang keluar dari urat) bukan haid, tetapi tinggalkanlah sembahyang selama hari haid engkau yang biasa kemudian mandilah dan sembahyanglah.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Adi bin Sabit, dari bapanya dari datuknya, dari Nabi s.a.w.: Buhawasanya Rasulullah berkata tentang perempuan yang sedang beristhadhah: Engkau tinggalkan sembahyang selama keluarnya (haidnya) yang biasa, kemudian engkau mandi dan berwuduk tiaptiap akan sembahyang, dan hendaklah ia puasa dan sembahyang.","r":"Tirmizi dan Abu Daud"}],"te":"Irregular Bleeding (Istihadhah) and How to Pray"},{"t":"Darah Haid yang Putus-Putus Datangnya","p":61,"v":1,"d":[{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Adalah perempuan-perempuan nifas duduk di zaman Nabi s.a.w. sesudah nifasnya empat puluh hari.","r":"Abu Daud dan Tirmizi"}],"te":"Menstrual Blood That Stops and Starts"},{"t":"Hal-Hal yang Diharamkan ketika Junub","p":63,"v":1,"d":[{"y":"a","s":4,"a":43,"b":43,"m":"Janganlah kamu kerjakan sembahyang ketika kamu sedang mabuk hingga kamu mengetahui apa yang kamu katakan, dan jangan pula kamu kerjakan sembahyang ketika kamu sedang junub, kecuali sekadar melalui tempat sembahyang saja, sebelum kamu mandi lebih dahulu. ;"},{"y":"h","x":"Dari Ibnu Umar r.a., bahawasanya Nabi s.a.w. bersabda: “Tidak boleh membaca sesuatu ayat Al-Quran bagi orang junub dan tidak pula perempuan-perempuan haid.” :","r":"Tirmizi dan Ibnu Majah"},{"y":"a","s":56,"a":79,"b":79,"m":"Tidak boleh menyentuh Quran, melainkan orang yang suci"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Rasulullah s.a.w. telah bersabda: Sesungguhnya aku tidak membolehkan masjid bagi orang yang haid dan tidak pula bagi orang yang junub.","r":"Abu Daud"}],"te":"What Is Forbidden When in Janabah"},{"t":"Hal-Hal yang Diharamkan ketika Haid dan Nifas","p":64,"v":1,"d":[{"y":"h","x":"Dari Abu Said Al-Khudri r.a. berkata: Rasulullah s.a.w. telah bersabda: Bukankah bila perempuan-perempuan sedang haid tidak boleh sembahyang dan tidak boleh pula puasa? Perempuan-perempuan menjawab: Ya, itulah tanda kurang (kewajipan) agamanya.","r":"Bukhari"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Tatkala kami datang ke Sarif (suatu tempat antara Mekah dan Madinah) aku sedang haid, maka berkata Rasulullah: “Perbuatlah oleh engkau apa yang diperbuat oleh yang haji, selain engkau jangan tawaf di Kaabah, hingga engkau suci lebih dahulu.” iw*","r":"Bukhari dan Muslim"},{"y":"a","s":2,"a":222,"b":222,"m":"Dan mereka bertanya kepada engkau, ya Muhammad, tentang haid. Katakanlah, haid itu suatu penyakit, oleh sebab itu jauhilah olehmu perempuan-perempuan (isterimu) ketika mereka sedang haid itu dan jangan kamu dekati mereka, hingga mereka suci lebih dahulu"},{"y":"h","x":"Dari Anas r.a. Bahawasanya orang Yahudi apabila perempuanperempuan mereka sedang haid, tak mahu mereka membawanya makan bersama-sama, dan mereka tak mahu membawanya berkumpul di rumah-rumah, maka berkata Nabi s.a.w.: Perbuatlah olehmu segala sesuatu, tetapi tak boleh bersetubuh. di","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umarr.a. Bahawasanya ia pada masa Rasulullah pernah menceraikan isterinya, sedang isterinya itu dalam haid, lalu bertanya Umar (bapanya) kepada Rasulullah -s.a.w. tentang hal itu, maka dijawab Rasulullah: Surahlah dia merujuk isterinya itu kembali, kemudian hendaklah ia menanti isterinya itu sehingga suci kembali, kemudian ia haid pula, kemudian ia suci pula, kemudian jika dikehendakinya, boleh ditahannya (tidak diceraikannya), dan bila dikehendakinya, boleh ia ceraikan sebelum ia campuri.","r":"Bukhari dan Muslim"}],"te":"What Is Forbidden During Menstruation and Postnatal Bleeding"},{"t":"Qada Sembahyang dan Puasa bagi Wanita Haid dan Nifas","p":67,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Kami diperintah membayar puasa, dan tidak diperintah membayar sembahyang.","r":"Bukhari dan Muslim"}],"te":"Making Up Prayer and Fasting After Menstruation and Postnatal Bleeding"},{"t":"Erti Mandi","p":67,"v":1,"te":"Meaning of the Ritual Bath"}],"p":45,"v":1,"te":"What Breaks Wudhu"},{"t":"Mandi","c":[{"t":"Erti Mandi","p":67,"v":1,"d":[{"y":"a","s":2,"a":222,"b":222,"m":"Dan janganlah kamu mendekati mereka (isteri sedang haid) hingga mereka mandi lebih dahulu. Bila mereka telah mandi, maka kamu boleh mendatangi mereka, menurut cara yang kamu diperintah oleh Allah"},{"y":"a","s":5,"a":6,"b":6,"m":"Dan jika kamu sedang junub maka mandilah kamu"}],"te":"Meaning of the Ritual Bath"},{"t":"Fardu Mandi Haid dan Mandi Junub","p":68,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. bersabda: Sesungguhnya di bawah tiap-tiap helai rambut itu junub sekaliannya, oleh sebab itu mandikanlah rambut itu dan bersihkanlah kulitnya.","r":"Abu Daud dan Tirmizi"}],"te":"Obligatory Acts of the Bath After Menstruation and Janabah"},{"t":"Cara Mandi Haid dan Mandi Junub","p":69,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Rasulullah s.a.w. telah bersabda: Bila perempuan mandi sehabis haidnya, hendaklah ia membuka rambut nya sama sekali, dan digosoknya dengan daun bidara dan air limau, dan bila ia mandi junub, dituangkannya air itu di atas kepalanya, lalu digusurkannya.","r":"Daruqutni dan Tabarani"},{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Aku pernah bertanya: Ya Rasulullah, sesungguhnya aku seorang yang berambut sangat bergumpal-gumpal, apakah akan aku buka gumpalan itu untuk mandi junub? Rasulullah menjawab: Tidak, hanya cukuplah jika engkau tumpahkan saja air di atas kepalamu tiga kali, kemudian engkau tuangkan air itu di atas badanmu, maka setelah itu sucilah engkau.","r":"Muslim"},{"y":"h","x":"Dari Aisyah r.a. Pernah bertanya seorang perempuan kepada Nabi s.a.w. tentang mandinya sehabis haid, maka perempuan itu ditanya oleh Rasulullah s.a.w. bagaimana caranya ia mandi. Lalu Rasulullah bersabda: “Ambillah sepotong kapas yang telah diberi wangiwangian, lalu berharum-harumlah engkau dengannya.” Berkata pula perempuan itu, bagaimana aku berharum dengannya. Maka Rasulullah menjawab pula: “Subhanallah, engkau berharum-harum dengannya.” Aisyah berkata: Maka aku tarik tangannya dan kukatakan padanya: Engkau tutupi dengannya bekas-bekas darah.","r":"Bukhari dan Muslim"}],"te":"How to Bathe After Menstruation and Janabah"},{"t":"Sunat-Sunat Mandi","p":70,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a.: Bahawa Nabi s.a.w. bila beliau mandi junub dimulainya dengan membasuh kedua tangannya, kemudian ia tuangkan air dengan tangan kanannya ke tangan kirinya, maka dibasuh kemaluannya, lalu ia wuduk sebagaimana wuduk untuk sembahyang, kemudian dimasukkan jarinya ke dalam air, maka diselisikselisikkan jari-jarinya itu ke sela-sela rambutnya, kemudian dituangkan air itu ke atas kepalanya tiga kali sauk dengan tangannya, kemudian ditumpahkan air itu ke seluruh badannya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Rasulullah s.a.w beliau sangat menyukai mendahulukan yang kanan dalam segala pekerjaannya, pada kap tiap beliau bersuci, melangkah dan memakai kasutnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Rasulullah s.a.w. telah melarang masuk ke dalam kamar mandi, kemudian dibolehkannya kaum lakilaki memasukinya dengan memakai kain basahan.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Tidak ada seorang pun perempuan yang menanggalkan kainnya tidak di biliknya sendiri, maka rosaklah hubungan antaranya dan antara Allah.","r":"Abu Daud dan Tirmizi"}],"te":"Sunnah Acts of the Bath"},{"t":"Jenis-Jenis Mandi yang Disunatkan","p":70,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Rasulullah s.a.w. selalu mandi dari empat macam perkara: Kerana junub, hari Jumaat, kerana habis berbekam dan kerana sesudah memandikan mayat.","r":"Abu Daud dan Ibnu Khuzaimah"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesiapa di antaramu yang hendak pergi sembahyang Jumaat, maka hendaklah ia mandi.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Zaid bin Sabit r.a. ia berkata: Pernah aku melihat Nabi s.a.w. menanggalkan pakaian kerana ihramnya, lalu beliau mandi.","r":"Tirmizi"},{"y":"h","x":"Dari Qais bin Ashim, tatkala ia memeluk agama Islam, maka dia disuruh oleh Rasulullah s.a.w. supaya mandi dengan air dan bidara (atau sabun wangi).","r":"Tirmizi dan Nasai"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah mandi Rasulullah San w. ketika hendak masuk ke kota Mekah.","r":"Tirmizi"}],"te":"Kinds of Recommended Baths"}],"p":67,"v":1,"te":"The Ritual Bath (Mandi)"},{"t":"Menyapu Kasut","c":[{"t":"Erti Menyapu Kasut","p":74,"v":1,"d":[{"y":"h","x":"Dari Mughirah bin Syw'bah r.a. Bahawasanya Rasulullah s.a.w. pernah berwuduk dan beliau menyapu kedua stokin dan kasut beliau.","r":"Abu Daud dan Ibnu Majah"},{"y":"h","x":"Dari Abu Bakrah r.a. Bahawasanya Rasulullah s.a.w. telah memberi keringanan bagi seorang musafir selama tiga hari dan tiga malam, dan bagi orang yang tetap di kampung sehari semalam, apabila ia telah bersuci, lalu dipakainya kedua kasutnya, kemudian disapunya kedua kasutnya itu.","r":"Ibnu Khuzaimah dan Ibnu Hibban"}],"te":"Meaning of Wiping Over Footwear"},{"t":"Syarat-Syarat Sah Menyapu Kasut","p":74,"v":1,"d":[{"y":"h","x":"Dari Mughirah bin Syu'bah ia berkata: Pernah aku melihat Rasulullah s.a.w. menyapu punggung dua kasutnya.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Ali r.a. ia berkata: Andaikata agama itu boleh menurut pendapat sendiri tentu kasut yang sebelah bawah yang lebih baik (patut) disapu daripada yang sebelah atasnya. Demi sesungguhnya aku telah melihat Rasulullah s.a.w. menyapu punggung kedua belah kasutnya. ?","r":"Abu Daud dan Daruqutni"}],"te":"Conditions for Valid Wiping Over Footwear"}],"p":74,"v":1,"te":"Wiping Over Footwear"},{"t":"Tayamum","c":[{"t":"Erti Bertayamum","p":74,"v":1,"d":[{"y":"a","s":4,"a":43,"b":43,"m":"Dan apabila kamu dalam keadaan sakit, atau engkau sedang dalam perjalanan, atau salah seorang di antara kamu pulang dari ghait, atau kamu menyentuh perempuan, sedang kamu tidak mendapati air, maka kamu carilah tanah yang suci kemudian sapulah mukamu dan kedua tanganmu"}],"te":"Meaning of Tayammum"},{"t":"Syarat Sah Bertayamum","p":74,"v":1,"d":[{"y":"a","s":4,"a":43,"b":43,"m":"Apabila kamu tidak memperoleh air, maka carilah olehmu tanah yang suci"},{"y":"h","x":"Dari Huzaifah bin Yaman. Bahawasanya Rasulullah s.a.w. pernah bersabda: Tuhan menjadikan bumi untukku sebagai barang yang bersih dan suci, dan untuk tempat bersujud.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ammar bin Yasirr.a. ia berkata: Pernah aku junub, maka aku gosokkan tanganku ke tanah, lalu aku ceritakan hal itu kepada Nabi s.a.w., lalu Rasulullah s.a.w. bersabda: “Sesungguhnya cukuplah begini bagimu,” lalu Rasulullah memukulkan kedua tangannya ke tanah dan dihembusnya kedua tangannya, kemudian menyapukan mukanya dengan kedua tapak tangannya serta dua telapak tangannya.","r":"Bukhari dan Muslim"}],"te":"Conditions for Valid Tayammum"},{"t":"Cara-Cara Bertayamum","p":77,"v":1,"d":[{"y":"a","s":5,"a":6,"b":6,"m":"Maka sapulah olehmu mukamu dan kedua tanganmu dengan tanah itu. dea"}],"te":"How to Perform Tayammum"}],"p":74,"v":1,"te":"Dry Ablution (Tayammum)"},{"t":"Masjid","c":[{"t":"Erti Masjid","p":79,"v":1,"d":[{"y":"a","s":9,"a":18,"b":18,"m":"Hanya yang mahu meramaikan masjid Allah, ialah orang-orang yang beriman dengan Allah dan hari yang akhir. Ia menegakkan sembahyang, mengeluarkan zakat dan ia tidak takut melainkan akhirat Allah. Mudah-mudahan mereka ini adalah orang yang masuk mendapat petunjuk"}],"te":"Meaning of Mosque"},{"t":"Masjid Taqwa dan Masjid Dirar","p":79,"v":1,"d":[{"y":"a","s":9,"a":108,"b":108,"m":"Sesungguhnya Masjid yang dibangunkan di atas dasar takwa itulah yang hak bahawa engkau berdiri (beribadat), di dalamnya ada orang-orang yang ingin mensucikan diri, sedang Allah sangat suka sekali kepada orang yang membersihkan diri itu"},{"y":"a","s":9,"a":107,"b":108,"m":"Dan mereka (orang-orang munafik) itu telah membangun masjid, kerana hendak menimbulkan bahaya, kerana kekafiran, kerana memecah persatuan antara orang mukmin dan kerana hendak menyambut orang yang semenjak dahulu telah memerangi Allah dan rasul-Nya, dan mereka sungguh bersumpah, tidaklah kami kehendaki melainkan kebaikan. Dan Allah menyaksikan, bahawa mereka adalah pendusta. Janganlah kamu sembahyang di masjid itu selamalamanya"}],"te":"The Mosque of Piety and the Mosque of Harm (Dirar)"},{"t":"Keutamaan Membangun Masjid","p":81,"v":1,"d":[{"y":"h","x":"Dari Usman bin Affan r.a. ia berkata: Rasulullah s.a.w. bersabda: Sesiapa yang telah membangunkan sebuah masjid, yang sengaja mencari keredaan Allah, nanti Allah buatkan pula untuknya sebuah masjid sebesar itu pula di dalam syurga.'","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w., beliau bersabda: Negeri yang paling dicintai Allah ialah masjidnya, sedang negeri yang paling dimurkai Allah ialah pasarnya.","r":"Muslim"}],"te":"Virtue of Building a Mosque"},{"t":"Hukum Mendirikan Masjid di Atas Kuburan","p":81,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. telah bersabda: Allah telah mengutuki orang-orang Yahudi dan Nasrani, yang mereka telah mengambil kuburan nabi-nabi mereka sebagai masjid.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Mursid Al-Ghanawi r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Janganlah kamu duduk di atas kuburan dan jangan pula kamu sembahyang menghadap kepadanya.","r":"Muslim"}],"te":"Ruling on Building a Mosque over Graves"},{"t":"Hukum Haram Jual Beli dalam Masjid","p":83,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. telah bersabda: Sesiapa yang melihat orang yang berjual beli di dalam masjid, maka katakanlah kepadanya: Semoga Allah tidak akan memberikan keuntungan dagangan engkau.","r":"Tirmizi dan Nasai"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang mendengar orang yang meneriakkan barang hilang di masjid, maka hendaklah ia katakan: Allah (mudahmudahan) tidak akan mengembalikan barang engkau yang hilang itu, kerana masjid tidak dibuat untuk ini.","r":"Muslim"}],"te":"Buying and Selling in the Mosque Is Forbidden"},{"t":"Hukum Makruh Mengukir Masjid","p":83,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tidak akan berdiri hari kiamat, hingga manusia bermegah-megah dalam perkara masjid.","r":"Abu Daud dan Ibnu Majah"}],"te":"Decorative Carving of Mosques Is Disliked"},{"t":"Hukum Wajib Membersihkan Masjid","p":84,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah menyuruh Rasulullah s.a.w. supaya membuat masjid di kampung-kampung, dan supaya masjid itu dibersihkan dan dibaguskan.","r":"Abu Daud dan Tirmizi"}],"te":"Keeping the Mosque Clean Is Obligatory"},{"t":"Adab Masuk ke dalam Masjid","p":84,"v":1,"d":[{"y":"h","x":"Dari Abu Qatadah r.a. Bahawa Rasulullah s.a.w. telah bersabda: Bila salah seorang di antara kamu memasuki masjid, hendaklah ia sembahyang lebih dahulu dua rakaat, sebelum ia duduk.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. Bahawasanya Nabi s.a.w. telah bersabda: Sesiapa yang telah memakan bawang merah, bawang putih dan lobak cina, maka janganlah ia mendekati masjid kami, kerana sesungguhnya malaikat berasa sakit (benci) dengan apa yang dibenci oleh anak adam.","r":"Bukhari dan Mulsim"}],"te":"Etiquette of Entering the Mosque"},{"t":"Keutamaan Masjidilharam Mekah dan Masjid Nabawi di Madinah","p":86,"v":1,"d":[{"y":"h","x":"Dari Ibnu Zubair r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Satu kali sembahyang di masjidku ini (masjid Madinah), lebih utama daripada sembahyang seribu kali di masjid lainnya, kecuali Masjidilharam. Dan sembahyang satu kali di Masjidilharam lebih utama daripada sembahyang seratus kali di masjidku.","r":"Ahmad"}],"te":"Virtue of Masjid al-Haram in Makkah and the Prophet's Mosque in Madinah"}],"p":79,"v":1,"te":"The Mosque"}],"p":14,"v":1,"te":"Book of Purification"},{"t":"Kitab Sembahyang","c":[{"t":"Asas Sembahyang","p":86,"v":1,"c":[{"t":"Sembahyang Itu Dapat Menghapuskan Dosa","p":86,"v":1,"d":[{"y":"a","s":11,"a":114,"b":114,"m":"Dan tegakkanlah sembahyang pada dua pinggir siang dan sebahagian dari malam. Sesungguhnya kebaikan itu menghilangkan kejahatan"},{"y":"h","x":"Dari Jabirr.a. berkata: Rasulullah s.a.w. telah bersabda: Umpama sembahyang yang lima waktu, umpama sungai yang mengalir di pintu salah seorangmu, ia mandi daripadanya lima kali setiap hari.","r":"Muslim"}],"te":"Prayer Wipes Away Sins"},{"t":"Hikmat Sembahyang","p":87,"v":1,"d":[{"y":"a","s":20,"a":14,"b":14,"m":"Dirikanlah sembahyang itu untuk mengingat Aku"},{"y":"h","x":"Dari Anas r.a. berkata: Nabi s.a.w. telah bersabda: Allah telah mewajibkan kepada umatku pada malam Israk sembahyang lima puluh kali, maka aku senantiasa berulang-alik mengadap Tuhan untuk memohon keringanan kepada-Nya, sehingga akhirnya Allah jadikannya lima kali sehari semalam.","r":"Bukhari dan Muslim"}],"te":"Wisdom of Prayer"}],"te":"Basics of Prayer"},{"t":"Azan dan Iqamat","c":[{"t":"Erti Azan dan Iqamat","p":89,"v":1,"d":[{"y":"h","x":"Dari Malik bin Huwairis r.a. berkata: Telah bersabda kepada kami Nabi s.a.w.: Bila waktu sembahyang telah tiba, maka hendaklah salah seorang di antara kamu azan bagimu.","r":"Bukhari dan Muslim"}],"te":"Meaning of Azan and Iqamah"},{"t":"Lafaz Azan dan Iqamat","p":90,"v":1,"d":[{"y":"h","x":"Dari Abdullah bin Zaid bin Abdul Rabbih Al-Ansarir.a. berkata: Ketika Rasulullah s.a.w. memerintahkan untuk memukul naqus (genta) yang biasa dipergunakan waktu itu untuk mengumpulkan manusia mengerjakan sembahyang, maka ada seorang lakilaki berjalan mengelilingi aku (ketika aku tidur bermimpi), sedang tangannya ia membawa sebuah naqus pula, lalu aku bertanya kepadanya: Akan engkau jualkah naqus itu? Ia bertanya pula: Apa gunanya? Lalu aku jawab: Dengan memukul naqus itu kita panggil manusia untuk bersembahyang. Ia berkata pula: Mahukah engkau aku tunjuki sesuatu yang lebih baik daripada memukul naqus ini? Aku menjawab: Mahu. Lalu ia berkata pula: Engkau ucapkanlah: an PER AA Da DI SAN Je S Kemudian ia pergi daripadaku, tetapi tidak jauh. Kemudian ia berkata pula: Sesudah itu engkau katakan, bila aan telah berdiri akan sembahyang: - PERAK SAAT ia a A TA SG SS. D aa D Maka tatkala aku bangun di waktu subuh, maka aku datang kepada Rasulullah s.a.w., lalu aku ceritakan mimpiku itu kepadanya. Rasulullah s.a.w. lalu menjawab: Sesungguhnya itulah mimpi yang sebenarnya, apabila Tuhan menghendaki. Waktu berdirilah, ya Bilal, maka ajarkanlah kepadanya (ya Abdullah) apa-apa yang telah engkau mimpikan itu. Kemudian hendaklah Bilal azan seperti itu, sesungguhnya Bilal suaranya lebih…","r":"Abu Daud"}],"te":"Words of the Azan and Iqamah"},{"t":"Yang Disunatkan ketika Azan","p":92,"v":1,"d":[{"y":"h","x":"Dari Abdul Jabbar bin Wail dari bapanya, ia berkata: Sebagai suatu hak dan menjadi sunnah, bahawa seseorang janganlah azan kecuali bila ia suci, dan tidak boleh azan kecuali berdiri.","r":"Baihaqi dan Daruqutni"},{"y":"h","x":"Dari Abu Juhaifah r.a. berakat: Pernah aku melihat Bilal keluar ke Abthah (salah satu tempat yang agak tinggi), lalu ia azan sambil menghadap ke kiblat. Maka tatkala ia sampai membaca hayya alashshalah, hayya alalfalah, ia gelengkan kuduknya ke kanan dan ke kiri, dan bukan i ia berputar.","r":"Abu Daud"},{"y":"h","x":"Dari Abu Juhaifah r.a. berkata: Pernah aku melihat Bilal azan, dan ia berputar dan menunjukkan mulutnya ke sana dan ke sini (ke kanan ke kiri) dan anak-anak jari tangannya diletakkan di telinganya.","r":"Tirmizi"},{"y":"h","x":"Dari Anas r.a. berkata: Sebahagian dari sunnah Rasulullah s.a.w., bila orang yang azan di waktu Subuh membaca: CM! j -, hendaklah disambung dengan: (Al x Di (Sembah yang itu lebih baik daripada tidur — sebanyak dua kali), Allah Maha Besar, Allah Maha Besar, tidak ada tuhan selain Allah.","r":"Ibnu Khuzaimah, Baihaqi dan Daruqutni"},{"y":"h","x":"Dari Bilal ia berkata: Telah bersabda kepadaku Rasulullah s.a.w.: Janganlah kamu bertaswib pada suatu sembahyang, kecuali dalam sembahyang Subuh.","r":"Tirmizi dan Ibnu Majah"},{"y":"h","x":"Dari Abu Mahzurah r.a. ia berkata: Rasulullah s.a.w. telah mengajarkan kepadaku tentang azan, dan bersabda: Bila engkau azan pada sembahyang Subuh, lalu kamu membaca: pi je kemudian bacalah olehmu: pj! yy. ps dai (dua kali).","r":"Abu Daud dan Ibnu Hibban"},{"y":"h","x":"Dari Abdullah bin Zaid, bahawasanya Rasulullah s.a.w. bersabda kepadanya tentang azan: Ajarkan azan itu kepada Bilal, kerana sesungguhnya Bilal lebih lantang suaranya dari engkau.","r":"Abu Daud dan lainnya"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Tiada dibolehkan perempuan azan.","r":"Baihaqi"}],"te":"What Is Recommended During the Azan"},{"t":"Mengikuti Bacaan Orang yang Azan","p":95,"v":1,"d":[{"y":"h","x":"Dari Umar bin Khattab r.a. ia berkata: Rasulullah s.a.w. bersabda: Bila dikatakan oleh orang yang azan: Allah Maha Besar, Allah Maha Besar, lalu kamu katakan pula: Allah Maha Besar, Allah Maha Besar. Kemudian orang yang azan itu mengatakan: Saya bersaksi, bahawa tidak ada tuhan melainkan Allah, maka kamu mengatakan pula: Saya bersaksi, bahawa tidak ada tuhan melainkan Allah. Kemudian orang yang azan itu berkata pula: Saya bersaksi, sesungguhnya Nabi Muhammad itu utusan Allah, maka kamu berkata pula: Saya bersaksi, sesungguhnya Nabi Muhammad itu utusan Allah. Kemudian orang azan itu mengatakan pula: Marilah kita bersembahyang, lalu kamu menyahut: Tidak ada daya upaya dan tidak ada kekuatan melainkan dengan izin Allah. Kemudian orang yang azan itu berkata pula: Marilah mencari kemenangan, lalu kamu berkata: Tidak ada daya upaya dan tidak ada kekuatan melainkan dengan izin Allah. Kemudian orang yang azan itu berkata pula: Allah Maha Besar, Allah Maha Besar, lalu kamu berkata: Allah Maha Besar, Allah Maha Besar. Kemudian orang yang azan itu berkata pula: Tidak ada tuhan melainkan Allah, kamupun mengatakan: Tidak ada tuhan melainkan Allah. Perkataan itu betul-betul datang dari hatimu, maka masuklah kamu ke dalam syurga.","r":"Muslim"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia berkata: Bersabda Rasulullah s.a.w.:Bila kamu mendengar azan, maka katakan pulalah olehmu seperti yang dikatakan orang yang azan itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Umamah r.a. Bahawasanya Bilal pernah berdiri iqamat, maka tatkala ia sampai kepada: Da MG Ig Nabi s.a.w. menjawab: Berdirilah sembahyang hendaknya dan kekallah hendaknya.","r":"Abu Daud"}],"te":"Repeating After the Muezzin"},{"t":"Doa sesudah Azan","p":3,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a., bahawasanya Rasulullah s.a.w. bersabda: Sesiapa yang membaca ketika mendengar azan: Ya Allah, Tuhan yang memperkenankan doa yang sempurna ini — hingga - yang telah Engkau janjikan kepadanya (doa yang telah tersebut di atas), maka terhulurlah kepadanya syafaatku di hari kiamat.","r":"Bukhari"},{"y":"h","x":"Dari Abdullah bin Amr bin Al-Ash r.a. sesungguhnya ia pernah mendengar Rasulullah s.a.w. bersabda: Bila kamu telah mendengar azan, maka katakanlah olehmu seperti yang dikatakan oleh yang azan itu kemudian berselawatlah kamu atas diriku, sesungguhnya orang-orang yang berselawat atasku satu selawat, Allah memberi selawat pula kepadanya sepuluh kali, kemudian mintalah olehmu bagiku wasilah kepada Tuhan.","r":"Muslim"}],"te":"Supplication After the Azan"},{"t":"Siapa yang Azan, Dialah yang Iqamat","p":98,"v":1,"d":[{"y":"h","x":"Dari Ziad bin Haris Ash-Shadai. Sesungguhnya ia pernah azan, maka Bilal datang untuk iqamat. Maka Nabi s.a.w. bersabda: Sesungguhnya saudara Shada' (Zaid bin Haris) telah azan, dan sesiapa yang azan, maka dialah yang iqamat.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Anas r.a. ia berkata: Bersabda Rasulullah s.a..W.: Doa kepada Tuhan, tidak akan ditolak antara azan dan iqamat.","r":"Abu Daud dan Tirmizi"}],"te":"Whoever Calls the Azan Calls the Iqamah"},{"t":"Mengazankan Bayi yang Lahir","p":99,"v":1,"d":[{"y":"h","x":"Dari Abu Rafi' r.a. ia berkata: Pernah aku melihat Nabi s.a.w. azan (sebagai) azan sembahyang di telinga Hasan bin Ali ketika ia dilahirkan oleh Fatimah r.a.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Hasan bin Ali r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesiapa yang lahir baginya seorang anak lalu diazankan di telinganya yang kanan dan dibacakan iqamat sembahyang di telinganya yang kiri, maka tidaklah ia akan disakiti oleh Ummu Sibyan (jin.)","r":"Ibnu Suni"}],"te":"Calling the Azan for a Newborn"}],"p":89,"v":1,"te":"Azan and Iqamah"},{"t":"Mengambil Sitrah","c":[{"t":"Erti Sitrah","p":99,"v":1,"d":[{"y":"h","x":"Dari Sahl' bin Abu Khusaimah r.a. Bahawasanya Nabi s.a.w. pernah bersabda: Bila salah seorang di antara kamu sembahyang dekat satu sitrah!pendinding, maka hendaklah ia hampir kepadanya agar syaitan tidak dapat memutuskan sembahyangnya.","r":"Abu Daud dan Nasai"}],"te":"Meaning of Sutrah"},{"t":"Gunanya Sitrah Diadakan","p":101,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. berkata: Rasulullah s.a.w. bersabda: Bila salah seorang di antara kamu hendak sembahyang maka hendaklah ia dirikan sesuatu di sebelah depannya, jika ia tidak memperoleh sesuatu, maka hendaklah ia dirikan sebuah tongkat, jika ia tidak memperoleh tongkat, maka hendaklah ia membuat suatu garis supaya jangan menyusahkan sesuatu yang lalu di hadapannya.","r":"Abu Daud dan Ibnu Majah"},{"y":"h","x":"Dari Sibrah bin Muabbad r.a. Bahawasanya Nabi s.a.w. pernah bersabda: Buatlah pendinding di waktu kamu sembahyang walaupun dengan sebuah anak panah.","r":"Hakim di dalam Mustadrak"},{"y":"h","x":"Dari Ibnu Umar r.a. Bahawasanya Rasulullah s.a.w. telah bersabda: Bila salah seorang sedang sembahyang, maka hendaklah di larang orang lalu di hadapannya, apabila ia enggan, maka boleh orang itu dibunuhnya, kerana sesungguhnya berserta orang itu ada iblis.","r":"Muslim"},{"y":"h","x":"Dari Abu Juhaim Al-Ansari r.a. Bahawasanya Rasulullah s.a.w. bersabda: Kalaulah tahu orang yang lalu di hadapan orang yang sembahyang betapa dosa yang akan ditimpakan Tuhan atas dirinya, sesungguhnya jika ia berdiri 40 tahun di depan orang yang sembahyang itu lebih baik baginya daripada ia lewat di hadapan orang yang sembahyang itu.","r":"Bukhari dan Muslim"}],"te":"Purpose of the Sutrah"}],"p":99,"v":1,"te":"Using a Prayer Barrier (Sutrah)"},{"t":"Waktu untuk Sembahyang","c":[{"t":"Sembahyang Ibadat yang Ditentukan Waktunya","p":103,"v":1,"d":[{"y":"a","s":4,"a":103,"b":103,"m":"Dirikanlah olehmu sembahyang, sesungguhnya sembahyang itu satu kewajipan atas orang mukmin yang ditentukan waktu-waktunya"},{"y":"h","x":"Dari Abdullah bin Amr r.a. Bahawasanya Nabi s.a.w. telah bersabda: Waktu zuhur ialah, bila telah tergelincir matahari dan akhirnya apabila bayang-bayang seseorang telah sepanjang badannya, iaitu sebelum datang waktu Asar.","r":"Muslim"},{"y":"h","x":"Dari Abdullah bin Amr bin Al-Ash, bahawa Nabi s.a.w. bersabda: Adapun waktu asar ialah, selama matahari belum terbenam.","r":"Muslim"},{"y":"h","x":"Dari Abdullah bin Amr Al-Ash. Bahawasanya s.a.w. telah bersabda: Adapun waktu maghrib, ialah bila terbenam matahari, selama belum hilang syafaq merah.","r":"Muslim"},{"y":"h","x":"Dari Abdullah bin Amr Al-Ash. Bahawasanya s.a.w. telah bersabda: Adapun waktu isyak ialah, hingga separuh pertengahan malam.","r":"Muslim"},{"y":"h","x":"Dari Abdullah bin Amr Al-Ash. Bahawasanya s.a.w telah bersabda: Adapun waktu sembah yang subuh, ialah mulai terbit fajar hingga terbit matahari.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. telah bersabda: Kalau tidaklah sangat menyusahkan di atas umatku, nescaya aku perintah mereka, supaya melambatkan sembahyang isyak hingga sepertiga malam, atau seperduanya.","r":"Tirmizi"},{"y":"h","x":"Dari Abu Qatadah r.a. Bahawasanya Nabi s.a.w. telah berspbda: Bukanlah dinamakan sia-sia dalam perkara tertidur, hanya yang dinamakan sia-sia, ialah orang yang belum sembahyang hingga datang pula (masuk) waktu sembahyang yang lain.","r":"Muslim"}],"te":"Prayer Is Worship Fixed to Its Times"},{"t":"Tuntutan Wajib Sembahyang Mulai dari Awal Waktu","p":106,"v":1,"d":[{"y":"h","x":"Dari Ibnu Mas'udr.a. ia berkata: Telah bersabda Rasulullah s.a.w.\" Amal ibadat yang lebih utama, ialah mengerjakan sembahyang di awal waktunya.","r":"Tirmizi dan Hakim"},{"y":"h","x":"Dari Abu Mahzurah r.a. Bahawasanya Nabi s.a.w. bersabda: Permulaan waktu itu adalah keredaan Allah, dan pertengahnya adalah rahmat Allah, dan akhirnya kemaafan Allah.","r":"Daruqutni"}],"te":"Praying Early in the Time"},{"t":"Waktu yang Makruh Mengerjakan Sembahyang","p":10,"v":1,"d":[{"y":"h","x":"Dari Uqbah bin Amir Al-Juhni r.a. sesungguhnya ia berkata: Tiga macam waktu yang oleh Rasulullah s.a.w. kami dilarang sembahyang padanya, dan dilarang kami menguburkan mayat kami padanya, iaitu ketika matahari sedang terbit hingga matahari itu tinggi dan ketika matahari tepat di kepala (sedang tengahari) hingga ia tergelincir (condong ke barat) dan ketika matahari hampir terbenam.","r":"Muslim"}],"te":"Times When Praying Is Disliked"},{"t":"Sembahyang Adak dan Qada","p":108,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang tertidur sampai luput sembahyang, atau ia lupa, maka hendaklah ia sembahyang bila ia telah ingat kembali.","r":"Bukhari"}],"te":"Praying on Time (Ada') and Making Up (Qada')"}],"p":103,"v":1,"te":"Prayer Times"},{"t":"Syarat Wajib Sembahyang","c":[{"t":"Syarat-Syarat Wajib Sembahyang","p":109,"v":1,"d":[{"y":"h","x":"Dari Abu Talhah bin Ubaidillah r.a. Bahawasanya Rasulullah s.a.w. pernah ditanya orang tentang Islam, maka Rasulullah menjawab: Iaitu sembahyang lima waktu sehari semalam.","r":"Bukhari dan Muslim"},{"y":"a","s":74,"a":40,"b":46,"m":"Di dalam syurga bertanya-tanya mereka tentang orang yang berdosa. Apakah yang menyebabkan kamu masuk neraka hai orang yang berdosa? Mereka menjawab: Kami tidak pernah mengerjakan sembahyang dan kami tidak pula memberi makanan orang miskin dan kami sentiasa berlumuran dosa bersama orang yang berdosa dan kami selalu membohongkan hari kiamat"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Rasulullah s.a.w. bersabda: Dicabut tuntutan beribadat pada tiga perkara: Dari anak kecil hingga ia baligh, dari orang yang tidur hingga ia bangun dan dari orang gila hingga ia sembuh.","r":"Abu Daud"},{"y":"h","x":"Dari Umar bin Syuib dari bapanya, dari datuknya, ia berkata: Rasulullah s.a.w. telah bersabda: Suruhlah anak-anakmu itu melakukan sembahyang ketika anak-anak itu berumur tujuh tahun, dan pukullah mereka bila meninggalkan sembahyang ketika anak-anak itu berumur sepuluh tahun dan pisahkanlah tempat tidur mereka.","r":"Abu Daud"}],"te":"Conditions That Make Prayer Obligatory"},{"t":"Syarat-Syarat Sah Mengerjakan Sembahyang","p":111,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Nabi s.a.w.: Allah tidak akan menerima sembahyang seseorang apabila ia berhadas, sebelum ia berwuduk.","r":"Bukhari dan Muslim"},{"y":"a","s":5,"a":6,"b":6,"m":"Allah Taala berfirman: Dan bila kamu sedang junub, maka bersucilah kamu. (Iaitu mandi)"},{"y":"a","s":74,"a":3,"b":4,"m":"Allah Taala berfirman: Dan kepada Tuhanmu sajalah engkau besarkan dan pakaianmu engkau sucikan"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. bersabda: Tujuh tempat yang tidak boleh ditempati untuk sembahyang iaitu; di tempat penyembelihan binatang, di tempat pembuangan sampah, di perkuburan, di kandang unta, di tempat mandi, di tempat laluan orang dan di atas Baitullah Al-Atiq.","r":"Tirmizi dan Ibnu Majah"},{"y":"h","x":"Dari Jabir r.a., sesungguhnya Rasulullah s.a.w. pernah bersabda: Telah dijadikan Allah bagiku bumi sebagai tempat yang suci dan akan jadi masjid. Maka di mana saja orang laki-laki didapati oleh waktu sembahyang, maka hendaklah ia sembahyang di saat itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Sa'id Al-Khudri r.a. Bahawasanya Nabi s.a.w. pernah menanggalkan seliparnya di waktu sembahyang, lalu orang-orang menanggalkan seliparnya pula. Maka Rasulullah s.a.w. bersabda: Apakah sebabnya kamu menanggalkan seliparmu? Mereka menjawab: Kerana kami lihat engkau menanggalkan selipar engkau, maka kami tinggalkan pula selipar kami. Maka apabila beliau berpaling beliau bersabda: Telah datang kepadaku Jibril, lalu dikhabarkannya kepadaku, bahawa di dalam seliparku itu ada kotoran (najis).","r":"Abu Daud dan Ahmad"},{"y":"a","s":7,"a":31,"b":31,"m":"Hai Bani Adam (manusia)! pakailah pakaianmu tatkala hendak sembahyang"},{"y":"h","x":"Dari Abu Sa'id Al-Khudri r.a. Bahawasanya Nabi s.a.w. bersabda: Aurat laki-laki ialah antara pusat dan lututnya.","r":"Baihaqi"},{"y":"h","x":"Dari Jarhad r.a. Bahawasanya Nabi s.a.w. bersabda: Paha itu masuk aurat.","r":"Bukhari"},{"y":"a","s":24,"a":31,"b":31,"m":"Dan tidak boleh kaum wanita itu melahirkan kecantikan badan mereka, melainkan barang yang lahir daripadanya, dan hendaklah mereka tutupkan telekung mereka ke dada mereka"},{"y":"h","x":"Dari Aisyah r.a., sesungguhnya Nabi s.a.w. bersabda: Allah tidak akan menerima sembahyang orang perempuan yang telah baligh kecuali dengan telekung.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ummu Salamah r.a. Bahawasanya dia pernah bertanya kepada Nabi s.a.w. Apakah perempuan itu boleh sembahyang dengan baju kurung serta tutup kepala yang di atas baju itu tidak ditutup dengan sarung. Rasulullah menjawab: Boleh, apabila ada baju kurung itu lapang yang menutupi kedua mata kaki.","r":"Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. melarang menjela-jelakan sarung (menyumbaikan kain lebih dari mata kaki) dalam sembahyang.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Kain sarung yang melebihi kedua mata kaki maka dia masuk neraka.","r":"Bukhari"},{"y":"a","s":17,"a":78,"b":78,"m":"Dirikanlah sembahyang, bila tergelincir matahari"},{"y":"a","s":2,"a":150,"b":150,"m":"Dan di mana pun engkau pergi, maka hadapkanlah mukamu ke arah Masjidilharam, dan di mana engkau ada, maka arahkanlah mukamu ke jurusannya"},{"y":"h","x":"Dari Abu Hurairah r.a., sesungguhnya Nabi s.a.w. bersabda: Bila engkau berdiri hendak sembahyang maka sempurnakanlah wudukmu kemudian menghadaplah ke kiblat lalu takbirlah.","r":"Bukhari dan Muslim"},{"y":"a","s":67,"a":13,"b":13,"m":"Sama ada kamu rahsiakan perkataanmu ataupun kamu nyatakan, sesungguhnya Allah Maha Mengetahui segala isi hati manusia"}],"te":"Conditions for a Valid Prayer"},{"t":"Meninggalkan Kiblat","p":119,"v":1,"d":[{"y":"h","x":"Apabila kamu takut, maka sembahyanglah cara berjalan kaki atau berkenderaan. Berkata Ibnu Umar: Menghadap pla atau pun tidak menghadap kiblat.","r":"Bukhari"},{"y":"h","x":"Dari Jabir r.a. Pernah Rasulullah s.a.w. sembahyang di atas kenderaannya, beliau mengadap ke mana saja arah kenderaannya. Kemudian apabila beliau hendak mengerjakan sembahyang yang fardu itu berhenti lalu beliau menghadap ke kiblat.","r":"Bukhari"},{"y":"h","x":"Dari Anas r.a., bahawa Rasulullah s.a.w. apabila beliau berjalan jauh, jika hendak mengerjakan sembahyang sunat, beliau mengadap ke kiblat dengan untanya lalu beliau bertakbir, kemudian sembahyang mengadap ke mana saja beliau dibawa kenderaannya.","r":"Abu Daud"},{"y":"h","x":"Dari Anas r.a., bahawa Rasulullah s.a.w. apabila beliau berjalan jauh, jika hendak mengerjakan sembahyang sunat, beliau mengadap ke kiblat dengan untanya lalu beliau bertakbir, kemudian sembahyang mengadap ke mana saja beliau dibawa kenderaannya.” (Diriwayatkan oleh Abu Daud). Ketiga: Kerana sangat lemah dan sukar menghadap ke kiblat, umpamanya ketika malam gelap-gelita dalam perjalanan, serta pedoman telah hilang, seperti hari hujan yang amat lebat, atau badai di laut dan sebagainya. GG aa Kua ai Sa aaa a P a 4 P 2R ae.. Kn w | EA Aa g “Jabir berkata: Kami sembahyang di malam hari di waktu awan gelap, sehingga kami tidak jelas arah kiblat. Tatkala kami selesai sembahyang, kami dapat tahu bahawa kami sembahyang tidak menurut arah kiblat. Lalu kami terangkan hal ini kepada Nabi s.a.w. Beliau bersabda: “Kamu telah mengerjakan kebaikan.” Kata Jabir: Nabi tidak menyuruh kami mengulangi sembahyang.","r":"Baihaqi"}],"te":"Not Facing the Qiblah"}],"p":109,"v":1,"te":"Conditions That Make Prayer Obligatory"},{"t":"Rukun Sembahyang","c":[{"t":"Hikmat Berniat","p":121,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesungguhnya salah seorang di antara kamu bila berada di dalam sembahyang, maka sesungguhnya ia berbisik-bisik dengan Tuhannya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Umar bin Khattab r.a. ia berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Segala amal ibadat itu hanya sah dengan berniat, dan bagi tiap-tiap manusia diberi ganjaran menurut apa yang diniatkannya.","r":"Bukhari dan Muslim"},{"y":"a","s":98,"a":5,"b":5,"m":"Tidaklah mereka diperintah, melainkan untuk menyembah Allah, mereka bersihkan agama itu bagi-Nya"},{"y":"h","x":"Dari Imran bin Hushainr.a. Bahawasanya ia bercerita: Pernah aku menderita sakit bawasir (keluar ujung usus), lalu aku bertanya kepada Nabi s.a.w.: Bagaimana caranya melakukan sembahyang. Maka Nabi menjawab: Sembahyanglah engkau berdiri, jika kamu tidak kuasa berdiri, maka sembahyanglah kamu dengan duduk, jika kamu tidak kuasa duduk, maka sembahyanglah kamu dengan berbaring.","r":"Bukhari"},{"y":"h","x":"Dari Ali r.a. ia berkata: Bersabda Nabi s.a.w.: Sembahyanglah orang yang sakit secara berdiri jika ia kuasa, apabila ia tidak kuasa, maka sembahyanglah ia secara duduk, apabila ia tidak kuasa untuk sujud, maka diisyaratkannyalah dengan kepalanya, dan dijadikan sujudnya itu lebih rendah dari rukuknya, jika ia tidak kuasa sembahyang secara duduk, maka sembahyanglah ia berbaring ke kanan serta menghadap ke kiblat; apabila ia tidak kuasa juga, sembahyanglahia menelentang sedang kedua kakinya membujur ke arah kiblat.","r":"Daruqutni"},{"y":"h","x":"Dari Imran bin Hushain r.a. ia berkata: Bersabda Nabi s.a.w.: Sesiapa yang sembahyang berdiri, maka itulah yang lebih utama dan siapa yang sembahyang duduk, maka baginya seperdua pahala orang yang sembahyang berdiri dan siapa yang sembahyang tidur (berbaring) maka baginya pahala separuh orang yang sembahyang duduk.","r":"Bukhari"},{"y":"h","x":"Dari Abu Humaid As-Saidi r.a. sesungguhnya ia berkata: Adalah Rasulullah s.a.w. apabila beliau memulai mengerjakan sembahyang beliau mengadap ke kiblat dan beliau mengangkat kedua tangannya lalu membaca Allahu Akbar.","r":"Ibnu Majah"},{"y":"h","x":"Dari Rifaah bin Rafi' ia berkata: Bersabda Rasulullah s.a.w.: Bila engkau hendak berdiri sembahyang, maka takbirlah engkau.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ali r.a., sesungguhnya Nabi s.a.w. bersabda: Kunci sembahyang itu ialah suci, dan yang mengharamkannya ialah takbir, dan yang menghalalkannya ialah salam.","r":"Abu Daud dan Tirmizi"}],"te":"Wisdom of the Intention"},{"t":"Wajib Membaca Fatihah bagi Imam dan Makmum","p":127,"v":1,"d":[{"y":"h","x":"Dari Ubadah bin Shamit r.a. dari Nabi s.a.w. beliau bersabda: Tidaklah sah sembahyang bagi sesiapa yang tidak membaca Fatihah dalam sembahyangnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ubadah bin Shamit r.a. ia berkata: Pernah Rasulullah s.a.w. sembahyang dengan kami iaitu sebahagian yang di jahar' 1. Menjahar - membaca ayat dengan keras. padanya ayat Al-Quran, lalu Nabi bersabda: Tidak boleh seseorang di antaramu membaca bila aku sedang menjahar ayat Al-Quran kecuali membaca Ummul Quran.","r":"Baiqani dan Daruqutni"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang mengerjakan sesuatu sembahyang, yang padanya tidak dibaca Ummul Quran (Al-Fatihah), maka sembahyangnya itu adalah rosak; perkataan ini diulang oleh Nabi dan disambung beliau dengan perkataan tiga kali, iaitu tidak sempurna.","r":"Muslim dan Abu Daud"}],"te":"Reciting al-Fatihah Is Obligatory for Imam and Follower"},{"t":"Wajib Mendengarkan Pembacaan Imam","p":128,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Adapun imam itu diadakan untuk diikuti orang, maka bila ia takbir, maka takbirlah kamu dan bilaia membaca maka diamlah kamu.","r":"Abu Daud dan Ibnu Majah"}],"te":"Listening to the Imam's Recitation Is Obligatory"},{"t":"Catatan Lanjut","p":3,"v":1,"d":[{"y":"h","x":"Dari Abdullah bin Syaddadr.a., sesungguhnya Nabi s.a.w. bersabda: Sesiapa yang sembahyang berjemaah, maka pembacaan imam menjadi pembacaannya pula.","r":"Ahmad"}],"te":"Further Notes"},{"t":"Bismillah Adalah Satu Ayat dari Al-Fatihah","p":3,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Bila kamu hendak membaca Alhamdulillah (Al-Fatihah), maka bacalah olehmu jl pj al. kerana sesungguhnya Alhamdulillah itu (Al-Fatihah) ialah Ummul Kitab dan Sab'ulmatsani (tujuh kali yang diulang-ulang) dan pj ye jl dl itwadalah salah satu ayatnya.","r":"Daruqutni"},{"y":"h","x":"Dari Ummu Salamah r.a. Bahawasanya Nabi s.a.w. dalam sembahyang membaca p— )! yr Jl al pi awal Fatihah, dan dihitungnya itu masuk satu ayat daripadanya.","r":"Ibnu Khuzaimah dan Baihaqi"}],"te":"Bismillah Is a Verse of al-Fatihah"},{"t":"Menjaharkan Kalimat Bismillah","p":130,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia telah berkata: Adalah Nabi s.a.w. menjahar pembacaan","r":"Daruqutn:"},{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah aku sembahyang berserta Rasulullah s.a.w. serta Abu Bakar, Umar dan Usman r.a., aku tak pernah mendengar salah seorang dari mereka yang membaca","r":"Bukhari dan Muslim"}],"te":"Reciting Bismillah Aloud"},{"t":"Orang-Orang yang tidak Kuasa Membaca Al-Fatihah","p":131,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. pernah bersabda: Bila kamu diperintah mengerjakan sesuatu, maka.kerjakanlah mengikut kemampuanmu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. berkata perihal mensifatkan sembahyang: Rasulullah s.a.w. bersabda: Kemudian rukuklah kamu hingga kamu tamakninah ketika rukuk itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Humaid As-Saidi r.a. ia berkata: Pernah aku lihat Rasulullah s.a.w. apabila beliau bertakbir dijadikan dua tangannya setentang dengan dua bidang bahunya dan apabila beliau rukuk diletakkan kedua tangannya pada kedua lututnya, kemudian diluruskan belakangnya. a","r":"Bukhari"},{"y":"h","x":"Dari Abu Mas'ud Al-Badrir.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Tidak sempurna (memadai) sembahyang seseorang hingga diluruskan belakangnya di waktu rukuk dan di waktu sujud.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. perihal mensifatkan sembahyang ia berkata: Bersabda Rasulullah s.a.w. Kemudian bangkitlah engkau, hingga engkau berdiri i'tidal kembali.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Malik bin Huwairis r.a.: Bahawasanya Nabi s.a.w. pernah bersabda: Sembahyanglah kamu sebagaimana kamu melihat aku sembahyang.","r":"Bukhari dan Muslim"},{"y":"a","s":22,"a":77,"b":77,"m":"Hai orang-orang yang beriman! Rukuklah kamu dan sujudlah"},{"y":"h","x":"Dari Abu Humaid As-Saidi r.a. berkata: Bahawa Nabi s.a.w. apabila beliau sujud ditekankan hidungnya dan dahinya ke bumi dan direnggangkan kedua tangannya dari dua rusuknya.'","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. Bahawasanya Nabi s.a.w. bersabda: Bila kamu sujud, maka tekankanlah dahimu ke bumi dan janganlah mengangkat-angkat dahi seperti burung mematuk.","r":"Ibnu Hibban"},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. bersabda: Disuruh aku sujud (oleh Tuhan) supaya aku sujud di atas tujuh tulang, iaitu di atas dahi dan diisyaratkan (ditunjukkan) dengan tangannya di atas hidungnya, dua hujung tangannya, dua lututnya dan dua telapak kakinya, dan kami tak boleh menghalangkan kain (yang sedang dipakai) dan rambut.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. ia telah berkata: Pernah kami sembahyang berserta Rasulullah s.a.w. ketika hari sangat panas, maka ketika itu tidak seorang juga di antara kami yang kuasa menekankan dahinya ke bumi, lalu dihamparkan kainnya lalu beliau sujud di atasnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Hasan r.a. ia berkata: Adalah sahabat-sahabat Rasulullah s.a.w. mereka sujud, sedang kedua tangan mereka di kain mereka, dan sujud pula seorang laki-laki di atas serbannya.","r":"Baihaqi"},{"y":"h","x":"Dari Khabab bin Art r.a. ia berkata: Pernah kami mengadu kepada Rasulullah s.a.w. tentang panas cahaya matahari di dahi kami dan tapak tangan kami, maka tidaklah dijawabnya pertanyaan kami.","r":"Baihaqi dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dalam perkara mensifatkan sembahyang ia berkata: Bersabda Nabi s.a.w.: Kemudian sujudlah engkau, hingga engkau tamakninah dalam sujud itu, kemudian bangkitlah hingga engkau thama'ninah dalam duduk engkau, kemudian sujudlah pula hingga engkau tamakninah dalam sujud itu, kemudian perbuatlah seperti demikian dalam semua sembahyang engkau.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. berkata: Adalah Rasulullah s.a.w. mengajarkan tasyahud kepada kami, sebagaimana beliau mengajarkan surah kepada kami, lalu beliau bersabda: Katakanlah olehmu: Segala kehormatan, keberkatan dan selawat/rahmat yang baik-baik adalah bagi Allah. Selamatlah atas engakau wahai Nabi, dan rahmat Allah beserta berkatNya. Selamatlah atas kami dan atas hamba Allah yang salih-salih. Aku mengaku, bahawa tidak ada Tuhan melainkan Allah, dan aku mengaku bahawa Muhammad itu utusan Allah.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Bersabda Rasulullah s.a.w.: Bila telah sembahyang salah seorang di antara kamu maka hendaklah dibacanya: Segala kehormatan, segala selawat dan segala yang baik-baik bagi Allah. Selamatlah atas engkau hai Nabi, dan rahmat Allah serta berkat-Nya. Selamatlah atas kami dan atas hamba Allah yang salih-salih. Saya mengaku, bahawa tidak ada tuhan melainkan Allah; dan saya mengaku bahawa Muhammad itu hamba dan utusan-Nya.","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia telah berkata: Sebahagian dari sunah Nabi, ialah melunakkan suara ketika membaca tasyahud.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Kaab bin Ajrah: Bahawasanya Nabi s.a.w. pernah ditanya orang tentang cara mengucapkan selawat atasnya, lalu Rasulullah s.a.w. bersabda: Ucapkanlah olehmu: Ya Allah! Berilah rahmat atas Muhammad dan atas keluarga Muhammad, sebagaimana yang telah Engkau beri selawat atas Ibrahim dan atas keluarga Ibrahim, dan berkatilah Muhammad dan atas keluarga Muhammad, sebagaimana Engkau telah memberi berkat atas Ibrahim, dan atas keluarga Ibrahim, sesungguhnya Engkau Maha dipuji lagi Maha Mulia.","r":"Nasai dan Hakim"},{"y":"h","x":"Dari Kaab bin Ajrah r.a. ia berkata: Pernah datang kepada kami Rasulullah s.a.w. lalu kami bertanya: Sesungguhnya telah kami ketahui atau kami kenal, bagaimana caranya kami memberi salam atas engkau, tetapi bagaimanakah caranya kami mengucapkan selawat atas engkau?” Maka menjawab Rasulullah s.a.w.: “Katakanlah: Ya Allah! Berilah selawat atas Muhammad dan atas keluarga Muhammad, sebagaimana engkau telah memberi selawat atas Ibrahim, sesungguhnya Engkau amat terpuji lagi Maha Mulia.","r":"Bukhari"},{"y":"h","x":"Dari Kaab bin Ajrah, dari Nabi s.a.w.: Bahawa beliau membaca dalam sembahyangnya: Ya Allah, berilah selawat atas Muhammad dan atas keluarga Muhammad; sebagaimana Engkau telah memberi selawat atas Ibrahim dan atas keluarga Ibrahim, dan berilah berkat atas Muhammad dan atas keluarga Muhammad, sebagaimana telah Engkau beri berkat atas Ibrahim, dan atas keluarga Ibrahim, sesungguhnya Engkau amat terpuji dan Maha Mulia.","r":"Syafii"},{"y":"h","x":"Dari Ali r.a. berkata: Adalah Rasulullah s.a.w. bila beliau telah berdiri sembahyang, maka akhir bacaan yang dibacanya antara tasyahud dan salam ialah: Ya Allah, ampunilah aku, iaitu dosadosaku yang terdahulu dan dosaku yang kemudian, dosa-dosaku yang tersembunyi dan dosaku yang nyata, dan perbuatanku yang berlebih-lebihan dan segala perbuatan yang Engkau lebih mengetahuinya daripadaku, Engkau yang tidak berpermulaan (terdahulu) dan Engkau yang bersifat abadi (tidak berkesudahan), tidak ada tuhan melainkan Engkau.","r":"Muslim"},{"y":"h","x":"Dari Abdullah bin Mas'ud r.a. bahawa Rasulullah s.a.w. adalah ia memberi salam ke sebelah kanannya iaitu Assalamualaikum warahmatullah hingga terlihat putih pipinya yang kanan, dan ke sebelah kirinya iaitu Assalamualaikum warahmatullah hingga terlihat putih pipinya yang kiri.","r":"An-Nisai' Erti “4 22"},{"y":"h","x":"Dari Aisyah r.a.: Bahawasanya Nabi s.a.w. pernah ia memberi salam satu kali saja memalingkan mukanya.","r":"Tirmizi dan Ibnu Majah"}],"te":"Those Unable to Recite al-Fatihah"}],"p":121,"v":1,"te":"Pillars of Prayer"},{"t":"Yang Disunatkan dalam Sembahyang","c":[{"t":"Doa Iftitah","p":145,"v":1,"d":[{"y":"h","x":"Dari Ali bin Abi Talib r.a. dari Nabi s.a.w.: Bahawasanya apabila beliau berdiri untuk sembahyang dibacanya: Kuhadapkan mukaku kepada Tuhan yang telah menjadikan langit dan bumi selurus-lurusnya sebagai orang Islam dan aku bukan termasuk orang-orang Musyrik. Sesungguhnya sembahyangku, ibadatku, hidupku dan matiku adalah bagi Allah, Tuhar semesta alam, tidak ada sekutu bagi-Nya. Dan kerana itu aku disuruh (mengerjakan perintah), dan aku adalah termasuk orang-orang Islam.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Pernah Rasulullah s.a.w. diam antara membaca takbiratul-ihram dan membaca Fatihah, lalu aku bertanya: Demi bapa dan ibuku', ya Rasulullah! Ketika engkau diam antara membaca takbir dan membaca Al-Fatihah, apakah yang engkau baca? Rasulullah menjawab: Aku baca: Ya Allah, jauhkanlah aku dari kesalahan-kesalahanku sebagaimana Engkau menjauhkan antara timur dan barat. Ya Allah, bersihkanlah aku dari segala kesalahanku sebagaimana bersihnya kain putih dari daki — Ya Allah, basuhlah aku dari kesalahan-kesalahanku dengan air, salji dan embun.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Pada suatu kali kami sembahyang bersama Rasulullah s.a.w. tiba-tiba seorang laki-laki yang berjemaah membaca: Yol, 1S, dl gla IS & dad, LS AS AI (Allah Maha Besar dengan sebesar-besarnya. Dan segala puji bagi Allah sebanyak-banyaknya. Dan Maha Suci Allah di waktu pagi dan petang). Lalu Rasulullah s.a.w. bersabda: siapakah yang membaca kalimat begini dan begitu? Seorang laki-laki dari kaum itu berkata: Saya wahai Rasulullah! Rasulullah s.a.w. bersabda: Hairan aku terhadap kalimat itu, di mana pintu langit telah terbuka kerana bacaan kalimat-kalimat itu. Ibnu Umar berkata: Maka akupun tidak meninggalkan membaca kalimat-kalimat itu sejak aku mendengar Rasulullah s.a.w. mengatakan yang demikian.","r":"Muslim"},{"y":"h","x":"Dari Iv-bair bin Muth'amr.a. Bahawasanya Nabi s.a.w. membaca isti'az..1( Ab 5ysl ) sebelum ia membaca Al-Fatihah.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Huzaifah r.a. ia berkata: Pernah aku sembahyang berserta Rasulullah s.a.w. pada suatu malam, lalu beliau mulai membaca surah Al-Baqarah, aku kira beliau rukuk, tatkala beliau sampai pada ayat 100 kemudian beliau meneruskannya, lalu aku kira beliau sembahyang membaca surah Al-Baqarah itu dalam satu rakaat, kemudia diteruskannya, lalu aku kira beliau akan rukuk sehabis membaca surah itu, kemudian beliau memulai surah Ali Imran, maka beliau membaca surah itu dengan suara yang tenang (tidak tepat), bila sampai kepada ayat tasbih beliau bertasbih pula, bila sampai kepada kalimat meminta, beliau pun meminta pula dan bila sampai kepada kalimat berlindung'' beliau pun memohon perlindungan pula (membaca isti'azah).","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. berkata: Adalah bacaan Nabi s.a.w. pada waktu malam kadang-kadang beliau merendahkan suaranya dan kadang-kadang ditinggikannya. |","r":"Abu Daud"},{"y":"h","x":"Dari Imran bin Hushain r.a. sesungguhnya Rasulullah s.a.w. pernah sembahyang Zuhur, lalu masuklah seseorang laki-laki membaca surah TAI da a di belakangnya, maka tatkala Nabi selesai sembahyang beliau bertanya: Siapa yang membaca tadilsiapa di antara kamu yang membaca? lalu seorang laki-laki menjawab: Saya, ya Rasulullah! Lalu Rasulullah bersabda: Sesungguhnya aku kira sebahagian mereka membantah aku.","r":"Muslim"},{"y":"h","x":"Dari Wail bin Hujr r.a. ia berkata: Pernah aku dengar, bahawasanya Nabi s.a.w. pernah membaca: (Bukan jalan mereka yang dimarahi dan bukan pula jalan orangorang yang sesat), lalu ia membaca “Amin” dan dipanjangkan suaranya membaca “Amin” itu.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia. berkata: Adalah Rasulullah s.a.w. bila telah selesai membaca Ummul Quran (Al-Fatihah), ditinggikan suaranya, lalu beliau membaca Amin.","r":"Abu Daud dan Daruqutni"},{"y":"h","x":"Dari Bilal r.a. ia telah berkata: Bersabda Nabi s.a.w.: Janganlah engkau mendahului akan membaca amin.","r":"Abu Daud"},{"y":"h","x":"Dari Wail bin Hujr r.a. Bahawasanya ia pernah mendengar Rasulullah s.a.w. ketika membaca: “dal Y, pg paid 1” Beliau membaca: “JH oo)” (ampunilah daku). Amin.","r":"Tabarani dan Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Telah bersabda Nabi s.a.w.: Bila imam telah membaca amin, maka aminkan pulalah olehmu, kerana sesungguhnya malaikat-malaikat mengaminkan pula berserta amin imam. Maka sesiapa yang sama aminnya dengan amin malaikat, diampuni Tuhan dosanya yang telah terdahulu.","r":"Bukhari dan Muslim"}],"te":"The Opening Supplication (Iftitah)"},{"t":"Membaca Surah sesudah Membaca Fatihah","p":152,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Adalah Nabi s.a.w. membaca surah Alif Lam Mim Tanzil As-Sajdah dan surah Hal Ata 'Alalinsan pada sembahyang Subuh pada hari Jumaat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir bin Samurah r.a. ia berkata: Adalah Nabi s.a.w. membaca surah Pe Ja pada sembahyang Zuhur, dan surah yang sepanjang itu juga pada waktu Asar dan surah yang lebih panjang dari itu pada waktu Subuh.","r":"Muslim"},{"y":"h","x":"Dari Jabir bin Samurah r.a. bahawasanya Nabi s.a.w. di waktu sembahyang Zuhur dan di waktu sembahyang Asar telah membaca surah “gssdl OB A” dan surah “Gi, AA,” - dan surah-surah yang seperti itu.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Jabir bin Muth'im r.a. ia telah berkata: Aku dengar Rasulullah s.a.w. membaca surah “ At-Tur” pada sembahyang Maghrib.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir bin Samurah r.a. ia berkata: Adalah Nabi s.a.w. dalam sembahyang Maghrib di malam Jumaat membaca: SA lb dan lagu dan dalam sembahyang Isyak pada malam Jumaat beliau membaca surah Al-Jum'at dan surah Al-Munafiqun. nn :","r":"Baihaqi"},{"y":"h","x":"Dari Al-Barrak r.a. ia berkata: Aku dengar Rasulullah s.a.w. pada waktu sembahyang Isyak membaca surah. “yy sel,” dan belum pernah aku dengar seseorang yang lebih baik suaranya atau bacaannya daripada beliau.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. Bahawasanya Nabi s.a.w. pernah berpesan kepada Muaz, ketika ia membaca ayat yang panjang di waktu Isyak: Ya Muaz! Bila engkau menjadi imam manusia, maka engkau bacalah surah Lal, pal, dan Je dog paul 4 dan Cak, nn Lal dan A sl Wi.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir bin Samurah r.a. Bahawasanya Rasulullah s.a.w. di waktu sembahyang Subuh telah membaca surah “sd ll GG” dan sesudah membaca ayat itu sembahyangnya dipendekkan, yakni; pada rakaat yang kedua.","r":"Muslim"}],"te":"Reciting a Surah After al-Fatihah"},{"t":"Yang Wajib bagi Makmum hanya Fatihah Sahaja","p":156,"v":1,"d":[{"y":"h","x":"Dari Ubadah bin Shamit r.a. ia berkata: Bersabda Rasulullah s.a.w.: Bila kamu sembahyang di belakangku, maka janganlah kamu baca, selain Umul-Kitab (Fatihah), kerana sesungguhnya a bererti (tidak sah) sembahyang orang yang tidak membaca Fatihah.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Qatadah r.a. Bahawa Rasulullah s.a.w. membaca Ummul Kitab (Al-Fatihah) dan dua surah pada dua rakaat yang pertama pada sembahyang Zuhur dan Asar dan dua rakaat yang akhir dengan Fatihatulkitab (Al-Fatihah). Dan beliau memperdengarkan kepada kami ayat itu sewaktu-waktu dan beliau memanjangkannya di rakaat yang pertama dan tidak memanjangkan di rakaat yang kedua. Begitu pula pada sembahyang Subuh.","r":"Bukhari dan Muslim"}],"te":"The Follower Is Obliged to Recite Only al-Fatihah"},{"t":"Surah-Surah yang Dibaca dalam Sembahyang Jumaat","p":157,"v":1,"d":[{"y":"h","x":"Dari Nukman bin Basyir r.a. ia berkata: Adalah Rasulullah s.a.w. pada sembahyang dua hari raya (hari raya Fithir dan hari raya Adha) dan pada sembahyang Jumaat membaca surah: SJ da pal — dan surah: AW Syam BERA. Berkata Nukman bin Basyir: Dan bila jatuh hari raya pada hari Jumaat dibacanya keduanya pada kedua sembahyang itu.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. dalam sembahyang Jumaat beliau membaca surah Al-Jum'at dan surah AlMunafiqun.","r":"Muslim"}],"te":"Surahs Recited in the Friday Prayer"},{"t":"Bacaan Apabila Bertemu dengan Ayat Rahmat, Azab, Tasbih atau Contoh","p":158,"v":1,"d":[{"y":"h","x":"Dari Ismail bin Umaiyah r.a. ia berkata: Pernah aku mendengar seseorang Arab bercerita: Aku mendengar Abu Hurairah r.a. berkata: Rasulullah s.a.w. bersabad: Sesiapa yang membaca surah on), kemudian sampai akhir surah itu, maka hendaklah membaca: pal x di jee (Dan atas yang demikian itu saya turut menjadi saksi). Dan sesiapa yang membaca surah (Al pp ll Y sampai akhirnya, iaitu Al 40 jpa An hendaklah membaca: s4 (benar). Dan sesiapa yang membaca surah Sy. jl, kemudia ia sampai kepada ayat os wi Cia SS maka hendaklah ia membaca dl LI (kami telah beriman kepada Allah).","r":"Abu Daud dan Tirmizi"}],"te":"What to Say on Verses of Mercy, Punishment, Glorification or Parables"},{"t":"Membaca Surah dalam Kedua Rakaat","p":160,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Pernah aku mendekati Rasulullah s.a.w. sebulan lamanya, yang dibacanya di dua rakaat sebelum fajar ialah surah os ASI Yi 6 ps dan surah al dl ya pi.","r":"Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Adalah Rasulullah s.a.w. apabila berdiri sembahyang, beliau takbir ketika berdiri, kemudian beliau takbir ketika rukuk, kemudian membaca: ada ya  hingga beliau mengangkat tulang sulbinya (pinggangnya) dari rukuk, kemudian beliau membaca sambil beridi: aan AI 4, kemudian beliau takbir ketika turun untuk sujud, kemudian takbir ketika bangkit dari sujud. Kemudian beliau melakukannya di dalam semua sembahyang beliau.","r":"Bukhari dan Muslim"}],"te":"Reciting Surahs in Both Rakaat"},{"t":"Bacaan ketika Bangkit dari Rukuk","p":161,"v":1,"d":[{"y":"h","x":"Dari Abdullah bin Abu Aufa ia berkata: Adalah Rasulullah s.a.w. bila mengangkat kepalanya dari rukuk, beliau membaca: Allah telah mendengar kepada sesiapa yang memuji-Nya. Wahai Tuhan kami, bagi Engkaulah segala puji sepenuh langit dan sepenuh bumi, dan sepenuh apa yang telah Engkau kehendaki selain itu.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. pernah bersabda: Bila imam telah membaca: “0... dl —” maka bacalah olehmu “sl 4 Gu)”.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Malik bin Huwairis r.a. pernah ia berkata: Bersabda Rasululah s.a.w.: Sembahyanglah kamu sebagaimana kamu melihat aku sembahyang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. Bahawasanya Nabi s.a.w. bersabda: Bila seseorang telah rukuk lalu ia membaca dalam rukuknya: “pad! 3) lma” sebanyak tiga kali, maka sesungguhnya telah sempurna rukuknya dan itulah sekurang-kurangnya, dan apabila seseorang telah sujud, lalu di dalam sujudnya ia membaca: SGS a) tiga kali, maka sesingguanya telah sempurna sujudnya, dan itulah yang sekurang-kurangnya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. ia telah berkata: Adalah Nabi s.a.w. di dalam rukuk dan sujudnya banyak membaca: Maha Suci Engkau ya Allah, ya Tuhan kami. Dan dengan puji Engkau ya Allah, ampunilah aku","r":"Bukhari dan Muslim"}],"te":"What to Say When Rising from Bowing"},{"t":"Jangan Menderum ketika Hendak Sujud","p":164,"v":1,"d":[{"y":"h","x":"Dari Wail bin Hujr r.a. berkata: Adalah Nabi s.a.w. bila beliau sujud, beliau meletakkan kedua lututnya sebelum meletakkan kedua tangannya dan bila bangun, beliau mengangkat kedua tangannya sebelum kedua lututnya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. bersabda: Bila seseorang sujud, maka janganlah ia menderum, seperti unta betina menderum dan hendaklah diletakkan kedua tangannya sebelum kedua lututnya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Al-Barrak bin Azib r.a. ia berkata: Bersabda Rasulullah s.a.w.: Bila engkau sujud, maka letakkanlah kedua telapak tangan engkau dan angkatlah kedua siku engkau.","r":"Muslim"},{"y":"h","x":"Dari Abu Humaid As-Saidi r.a. Bahawasanya ia pernah mensifatkan sembahyang Nabi s.a.w. ia berkata: Bila beliau sujud, direnggangkan kedua kakinya.","r":"Abu Daud dan Baihaqi"},{"y":"h","x":"Dari Abu Humaid As-Saidi r.a. Bahawasanya Nabi s.a.w. sujud dan beliau hadapkan anak-anak jarinya ke kiblat.","r":"Bukhari"},{"y":"h","x":"Dari Al-Barrak r.a. ia berkata: Adalah Rasulullah s.a.w. bila beliau sujud, beliau letakkan kedua tangannya ke bumi, dihadapkan kedua tapak tangannya dan anak-anak jarinya ke kiblat.","r":"Baihaqi"},{"y":"h","x":"Dari Anas r.a. dari Nabi s.a.w. beliau bersabda: Luruskanlah badanmu di dalam sujud dan janganlah salah seorang dari kamu menghamparkan kedua lengan tangannya seperti anjing menghamparkan tangannya (kakinya).","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. ketika duduk antara dua sujud beliau membaca: Ya Allah! ampunilah dosaku, kasihanilah aku, sihatkanlah aku serta tunjukkanlah aku dan berilah aku rezeki.","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. ketika duduk antara dua sujud beliau membaca: Ya Allah! ampunilah dosaku, kasihanilah aku, sihatkanlah aku serta tunjukkanlah aku dan berilah aku rezeki. (Diriwayatkan oleh Abu Daud). Yang lebih afdal ialah supaya seseorang membaca doa yang tersebut di bawah ini: 0.4779 Ia. ERA :.e g, Se Ga TS San SA Ga Jd pa P) g - - Ga  - an A0 - P. a ek KSM ci ols, — Ya Tuhanku!! Ampunilah dosaku, berilah aku rahmat (kasihanilah aku), tambahilah ibadatku (sempurnakanlah mana yang kurang), angkatlah martabatku, berilah aku rezeki, tunjukkanlah aku, sihatkanlah aku dan maafkanlah segala kesalahanku.","r":"Ash-habus Sunan"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Nabi s.a.w. adalah menghamparkan kakinya yang kiri dan menegakkan kakinya yang kanan.","r":"Baihaqi"},{"y":"h","x":"Dari Abu Humaid As-Saidi r.a. Bahawasanya ia pernah mensifatkan sembahyang Nabi s.a.w. lalu ia berkata: Maka bila Nabi duduk sesudah dua rakaat, beliau duduk di atas kakinya yang kiri dan ditegakkan kakinya yang kanan, apabila beliau duduk pada rakaat yang penghabisan dikedepankan kakinya yang kiri dan ditegakkan kakinya yang kanan dan beliau duduk di atas pinggulnya (punggungnya) di bumi.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Aisyah pernah mensifatkan sembahyang Nabi s.a.w. lalu berkata: Rasulullah s.a.w. apabila beliau mengangkat kepalanya dari sujud, beliau tidak sujud kembali sebelum beliau menyempurnakan duduknya lebih dahulu dan pada tiap-tiap dua rakaat beliau membaca tahiyat.","r":"Abu Daud dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Aisyah pernah mensifatkan sembahyang Nabi s.a.w. lalu berkata: Rasulullah s.a.w. apabila beliau mengangkat kepalanya dari sujud, beliau tidak sujud kembali sebelum beliau menyempurnakan duduknya lebih dahulu dan pada tiap-tiap dua rakaat beliau membaca tahiyat. (Diriwayatkan oleh Abu Daud dan Muslim). Yang dimaksud dengan tahiyat di sini ialah membaca tasyahud yang pertama. Berkata Imam Syafii: Disunatkan berselawat kepada Nabi dalam tasyahud yang pertama, dan tidak disunatkan membaca selawat atas keluarganya. Jika sembahyang itu hanya serakaat atau dua rakaat, maka hingga ini cukuplah sembahyang itu dan sudah boleh memberi salam ke kanan dan ke kiri. Akan tetapi bila sembahyang itu lebih dari dua rakaat, maka hendaklah berdiri kembali sambil membaca takbir intiqal. Dan perbuatlah pada rakaat berikutnya seperti pada rakaat yang pertama, seperti membaca Fatihah, rukuk, sujud dan lain-lain sebagainya. Sebagaimana sabda Rasulullah s.a.w. dalam hadis: Dg - ! 0g pas Sa a, ka na -  Je Perbuatlah yang demikian itu di dalam sembahyang engkau semuanya.","r":"Bukhari dan Muslim"}],"te":"Do Not Kneel Like a Camel When Going Down to Prostrate"},{"t":"Menggerakkan Telunjuk ketika Membaca Tasyahud","p":170,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. Bahawasanya Rasulullah s.a.w. apabila beliau duduk hendak membaca tasyahud, diletakkan tangannya yang kiri di atas lututnya yang kiri dan tangannya yang kanan di atas lututnya yang kanan, dan diakadkan bilangan lima puluh tiga, dan diisyaratkannya dengan anak jarinya, iaitu telunjuknya.","r":"Muslim"},{"y":"h","x":"Dari Wail bin Hujrr.a. Bahawasanya Nabi s.a.w. meletakkan sikunya yang kanan di atas pahanya yang kanan, kemudian diakadkannya jari-jarinya, iaitu kelingking dan yang mengiringnya (jari manis dan jari tengah), dan dibuatnya satu lingkaran dengan jarinya di atas ibu jarinya, lalu diangkat telunjuknya. Kulihat beliau mengisyaratkan dengan telunjuknya itu.","r":"Baihaqi"},{"y":"h","x":"Dari Ibnu Zubair ia berkata mengenai perkara tasyahud, katanya: Bahawasanya Rasulullah s.a.w. selalu mengisyaratkan telunjuknya, dan tidak digerak-gerakkannya.","r":"Ahmad, Abu Daud dan Nasai"},{"y":"h","x":"Dari Wail r.a. berkata dalam perkara tasyahud, katanya: Bahawasanya Rasulullah s.a.w. telah mengangkat anak-anak jarinya, lalu aku lihat beliau menggerak-gerakkannya sambil memanggil-manggil (yakni mengisyaratkan) dengan jarinya itu.","r":"Ibnu Khuzaimah dan Baihaqi"},{"y":"h","x":"Dari Abu Humaid As-Saidi r.a. Bahawasanya dia pernah mensifatkan sembahyang Rasulullah s.a.w. lalu berkata: Apabila beliau telah duduk di rakaat yang akhir, dikedepankan kakinya yang kiri dan ditegakkan kakinya yang lain (kanan) dan beliau duduk di atas pinggulnya (punggungnya).","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. Bahawasanya Rasulullah s.a.w. memberi salam ke kanan dan ke kiri hingga terlihat putih pipinya, iaitu: Ca ag a D ag a DUA.","r":"Abu Daud"}],"te":"Moving the Index Finger in the Tashahhud"},{"t":"Sunat-Sunat ketika Membaca Salam","p":173,"v":1,"d":[{"y":"h","x":"Dari Samurah bin Jundab ia telah berkata: Nabi s.a.w. telah memerintahkan kepada kami supaya kami menjawab salam kepada imam, dan sebahagian kami memberi salam kepada yang lain.","r":"Abu Daud dan Baihaqi"},{"y":"h","x":"Dari Ali r.a. ia telah berkata: Pernah Nabi s.a.w. sembahyang sebelum Asar empat rakaat, yang dibacanya antara rakaat-rakaat itu dengan salam kepada malaikat-malaikat yang dekat (di kiri dan di kanan), dan orang-orang yang mengikut mereka dari kaum Muslimin dan Mukminin.","r":"Tirmizi"}],"te":"Sunnah Acts of the Salam"}],"p":142,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. berkata: Adalah Rasulullah s.a.w. apabila beliau memulakan sembahyang, beliau mengangkat kedua tangannya sampai setentang dengan kedua bidang bahunya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. biasa mengembangkan anak jarinya di dalam sembahyang.","r":"Ibnu Hibban"},{"y":"h","x":"Dari Ibnu Umar r.a., bahawa Nabi s.a.w. apabila beliau memulakan sembahyang, beliau mengangkat kedua tangannya sampai setentang dengan kedua bidang bahunya, juga ketika takbir akan ruku dan ketika bangun dari rukuk.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Halab At-Thai ia berkata: Pernah Rasulullah s.a.w. menjadi imam kami, maka dipegangnya tangan kirinya dengan tangan kanannya.","r":"Tirmizi"},{"y":"h","x":"Dari Wail bin Hujr r.a. ia telah berkata: Aku telah berkata: Sesungguhnya aku memperhatikan benar kepada sembahyang Rasulullah s.a.w. bagaimana cara beliau sembahyang, maka aku lihat beliau meletakkan tangannya yang kanan di atas belakang tangannya yang kiri, memegang pergelangan dan hasta tangan kiri itu.","r":"Abu Daud"},{"y":"h","x":"Dari Wail bin Hujr r.a. ia berkata: Pernah aku sembahyang bersama-sama Rasulullah s.a.w. lalu beliau meletakkan tangan kanan di atas tangan kirinya ke dadanya.","r":"Abu Bakar bin Khuzaimah"},{"y":"h","x":"Dari Anas bin Malik r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Apakah sebabnya kaum-kaum itu menunjukkan pandangan mereka ke langit ketika mereka sembahyang, lalu Nabi memperkeras dalam perkataannya itu, akhirnya beliau bersabda: Hendaklah mereka berhenti dari perbuatan itu, atau pemandangan mereka akan dicabut.","r":"Bukhari"}],"te":"What Is Recommended in Prayer"},{"t":"Qunut","c":[{"t":"Erti Qunut","p":175,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. Bahawasanya Rasulullah s.a.w. telah bersabda: Sembahyang yang lebih utama ialah memanjangkan qunut.","r":"Muslim"}],"te":"Meaning of Qunut"},{"t":"Qunut Nazilah","p":175,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia telah berkata: Telah qunut Rasulullah s.a.w. berturut-turut selama sebulan di dalam sembahyang Zuhur, Asar, Maghrib, Isyak dan Subuh, iaitu pada akhir tiap-tiap sembahyang, ketika beliau membaca: aka ya — di rakaat yang akhir, beliau berdoa atas suku-suku dan qabilah Bani Sulaim, iaitu atas suku Ri'l, Zikwan dan Ushaiyah, dan diaminkan oleh orang-orang yang di belakangnya.","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. Bahawa ia pernah mendengar Rasulullah s.a.w. apabila beliau mengangkat kepalanya dari rukuk di rakaat yang akhir pada sembahyang Subuh, beliau membaca: Ya Allah, laknatilah si anu dan si anu (yang tidak disebutkan namanya), sesudah membaca: AJ! AI Lu) 2d ya Lalu Allah menurunkan ayat-Nya: Itu bukan urusan engkau, hai Muhammad! sama ada Allah akan menerima taubat mereka atau akan mengazab mereka sebab mereka orang yang zalim.","r":"Bukhari"}],"te":"Qunut in Calamity (Nazilah)"},{"t":"Qunut Witir","p":177,"v":1,"d":[{"y":"h","x":"Dari Hasan bin Ali bin Abi Talib r.a. ia berkata: Rasulullah s.a.w. telah mengajarkan kepadaku beberapa kalimat yang akan aku baca disembahyang witir: Ya Allah. Tunjukilah aku seperti orang yang telah Engkau tunjuki, sihatkanlah aku seperti orang yang telah Engkau sihatkan, muliakanlah aku seperti orang yang telah Engkau muliakan, turunkan berkat kepadaku pada apa yang telah Engkau berikan dan jauhkan aku (dari) segala kejahatan yang telah Engkau tentukan, kerana sesungguhnya Engkaulah yang menetapkan, dan tidak ada seorang pun yang dapat mengubah ketetapan-Mu. Sesungguhnya tidak akan hina orang yang telah Engkau muliakan dan tidak pula akan mulia orang-orang yang telah Engkau hinakan. Bertambah-tambah berkat-Mu, ya Tuhanku! dan Maha Tinggi Engkau.","r":"Abu Daud dan Tirmizi"}],"te":"Qunut in Witr"},{"t":"Qunut Subuh","p":178,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. Bahawasanya Nabi s.a.w. pernah qunut sebulan lamanya. Ia berdoa atas orang yang membunuh, kemudian qunut itu ditinggalkannya. Adapun pada sembahyang Subuh, beliau sentiasa qunut hingga beliau meninggal! dunia.","r":"Jama'atul Huffaz"},{"y":"h","x":"Dari Anas r.a. Bahawasanya Nabi s.a.w. pernah qunut sebulan lamanya. Ia berdoa atas orang yang membunuh, kemudian qunut itu ditinggalkannya. Adapun pada sembahyang Subuh, beliau sentiasa qunut hingga beliau meninggal! dunia. (Diriwayatkan oleh Jama'atul Huffaz). Keterangan kedua: a Di ra If Sa Ia - a DAR A v 0 3 \"Dari Al-Barra r.a. ia berkata: Adalah Rasulullah s.a.w membaca qunut pada sembahyang Subuh dan Maghrib.","r":"Muslim"},{"y":"h","x":"Dari Anas r.a. ia telah berkata: Adalah Qunut itu di sembahyang Maghrib dan Subuh. Sa,","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Sirin ia telah berkata: Pernah aku bertanya kepada Anas: Pernahkah Rasulullah s.a.w. qunut di sembahyang Subuh? Ia menjawab: Ya, iaitu sesudah rukuk sebentar.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. pernah qunut disembahyang Subuh. Hingga katanya: Kemudian sampai khabar kepada kami, bahawa qunut itu telah ditinggalkannya tatkala turun ayat: Itu bukan urusan engkau, hai Muhammad! sama ada Allah menerima taubat atau mengazab mereka sebab mereka orang yang zalim.","r":"Muslim"},{"y":"h","x":"Dari Anas r.a. Bahawasanya Nabi s.a.w. pernah qunut sebulan lamanya sesudah rukuk, yang mendoakan suku-suku Arab, kemudian ditinggalkannya.","r":"Bukhari dan Musim"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. pernah mengajarkan kepada mereka akan doa ini yakni Allahummahdini hingga akhirnya, supaya mereka membacanya di waktu Subuh.","r":"Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. apabila beliau mengangkat kepalanya dari rukuk sembahyang Subuh pada rakaat yang kedua, beliau mengangkat dua belah tangannya lalu berdoa dengan doa ini: Ya Allah! tunjukkanlah aku seperti orang yang telah Engkau tunjukkan, sihatkanlah aku seperti orang yang telah Engkau sihatkan...... hingga akhir hadis.","r":"Al-Hakim"}],"te":"Qunut in Subuh"},{"t":"Doa untuk Qunut dan Mengangkat Dua Tangan","p":182,"v":1,"d":[{"y":"h","x":"Dari Abu Rafi' r.a. ia telah berkata: Pernah aku sembahyang di belakang Umar bin Khattab r.a. dibacanya qunut sesudah rukuk, maka ia mengangkat dua tangannya dan ia mengeraskan membaca doa.","r":"Baihaqi"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa Rasulullah s.a.w. telah bersabda: Mendoalah (meminta) kepada Allah dengan telapak tanganmu dan janganlah kamu mendoa dengan belakangnya.","r":"Abu Daud"}],"te":"The Qunut Supplication and Raising the Hands"}],"p":175,"v":1,"te":"Qunut"},{"t":"Yang Makruh dalam Sembahyang","p":184,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. telah melarang seseorang sembahyang dengan bertolak pinggang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. Pernah aku bertanya kepada Rasulullah s.a.w. tentang “tengok-tengok” atau menoleh-noleh di dalam sembahyang, lalu Rasulullah s.a.w. menjawab: Perbuatan itu adalah suatu “tarikan” cepat yang dicubakan--oleh syaitan dari sembahyang seseorang.","r":"Bukhari"},{"y":"h","x":"Dari Abu Zar r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Allah senantiasa menghadap kepada hamba-Nya di dalam sembahyang, selama hamba-Nya itu tidak menoleh; apabila dia palingkan mukanya maka Allah berpaling pula daripadanya.","r":"Nasai dan Ahmad"},{"y":"h","x":"Dari Ibnu Umar r.a. pernah aku bertanya kepada Bilal r.a.: Bagaimana caranya Rasulullah s.a.w. menjawab salam mereka, ketika mereka memberi salam kepadanya, sedang beliau dalam sembahyang. Ia menjawab: Diisyaratkan dengan tangannya.","r":"Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Bila seseorang meludah, maka janganlah ia meludah ke sebelah depan dan jangan pula ke sebelah kanan, tetapi hendaklah ia meludah ke sebelah kirinya, atau ke bawah telapak kakinya yang kiri.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. berkata: Rasulullah s.a.w. telah melarang kepada seseorang menutup mulutnya di dalam sembahyang.","r":"Ibnu Majah dan Abu Daud"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Rasulullah s.a.w. disuruh (Tuhan) sujud di atas anggota yang tujuh dan dilarang menahan rambut dan kainnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Mwaiqibr.a. Bahawasanya Nabi s.a.w. bersabda: Janganlah engkau menyapu tanah sedang engkau dalam sembahyang, maka apabila engkau terpaksa melakukannya maka perbuatlah sekali saja untuk menyapu tanah itu (pasir-pasir halus).","r":"Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Menguap di dalam sembahyang adalah datang dari syaitan, maka bila seseorang menguap, maka hendaklah ia menahan selagi ia mampu.","r":"Tirmizi dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. dari Rasulullah s.a.w. beliau bersabda: Tidak ada ertinya sembahyang, bila makanan telah terhidang, dan tidak pula ada ertinya sembahyang sedang dia didesak oleh dua yang keji, iaitu baul (kencing) dan gaith (berak).","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Bila sembahyang telah diiqamatkan, maka tidaklah ada sembahyang lagi, melainkan sembahyang yang fardu.","r":"Muslim"}],"te":"What Is Disliked in Prayer"},{"t":"Yang Membatalkan Sembahyang","p":188,"v":1,"d":[{"y":"h","x":"Dari Muawiyah r.a. ia berkata: Rasulullah s.a.w. bersabda: Sesungguhnya sembahyang ini tidak patut dicampuri dengan sesuatu dari perkataan manusia, hanya yang patut padanya ialah tasbih, dan membaca Al-Quran.","r":"Muslim"},{"y":"h","x":"Dari Zaid bin Arqam r.a. ia berkata: Pernah kami berkatakata di dalam sembahyang, yang seseorang berkata-kata kepada temannya, sedang temannya itu berkata-kata pula (melengong) ke pihaknya di dalam sembahyang, hingga turunlah ayat: Berdirilah kamu kerana Allah secara patuh dan taat. Lalu kami disuruhnya diam dan kami dilarang berkata-kata.","r":"Muslim"},{"y":"h","x":"Dari Abu Mas'ud r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Sungguh di dalam sembahyang itu sudah cukup pekerjaan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Rasulullah s.a.w. bersabda: Bunuhlah olehmu dua macam binatang berbisa di dalam sembahyang, iaitu ular dan kala.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. beliau bersabda: Tertawa-tawa itu membatalkan sembahyang, tetapi tidak membatalkan wuduk.","r":"Daruqutni dan Baihaqi"}],"te":"What Invalidates Prayer"},{"t":"Memberitahukan Imam dalam Sembahyang","p":191,"v":1,"d":[{"y":"h","x":"Dari Sahal bin Saad r.a. ia telah berkata: Bersabda Rasulullah s.a.w. :Bila salah seorang di antara kamu nampak sesuatu di dalam sembahyang, maka hendaklah ia membaca tasbih, kerana hanya tasbih itu yang dibolehkan bagi laki-laki dan bertepuk tangan bagi perempuan.","r":"Bukhari dan Muslim"}],"te":"Alerting the Imam During Prayer"},{"t":"Macam Sujud","c":[{"t":"Sujud Sahwi","p":191,"v":1,"d":[{"y":"h","x":"Dari Al-Mughirah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Bila salah seorang berdiri dari rakaat yang kedua, tetapi belum sempurna berdirinya, maka hendaklah ia duduk kembali; dan jika telah sempurna berdiri, maka janganlah i ia duduk, dan hendaklah ia sujud dua kali, iaitu sujud sahwi.","r":"Ahmad"},{"y":"h","x":"Dari Abdullah bin Buhainah r.a. Bahawasanya Nabi s.a.w. pernah sembahyang Zuhur bersama mereka, lalu beliau langsung berdiri di dua rakaat yang pertama tanpa duduk (tasyahud awal), maka orang-orang pun ikut berdiri pula, hingga ketika beliau akan selesai sembahyang, orang-orang yang lain menanti-nanti salamnya, malah beliau takbir sambil duduk, lalu beliau sujud dua laki sebelum salam. Sesudah itu barulah beliau memberi salam.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia berkata: Bersabda Rasulullah s.a.w.: Bila seseorang ragu di dalam sembahyangnya, sedang ia tidak mengetahui lagi apakah ia telah sembahyang tiga rakaat atau empat rakaat, maka hendaklah dibuangkannya keraguannya itu, dan hendaklah ditetapkannya yang diyakininya itu, pa apabila sembahyang dia sampai lima rakaat maka sempurnalah sembahyangnya dan jika ia sembahyang menepati jumlah rakaatnya, adalah dua sujud itu sebagai kutuk bagi syaitan.","r":"Ahmad dan Muslim"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. Bahawasanya Nabi s.a.w. pernah sembahyang Zuhur lima rakaat, lalu dikatakan orang kepadanya: Apakah sembahyangnya itu dengan sengaja ditambahi? Lalu Rasulullah s.a.w. menjawab: Benarkah demikian! Mereka mengatakan: Benar, tuan telah sembahyang lima rakaat. Lalu beliau sujud dua kali selepas beliau memberi salam.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Pernah Nabi s.a.w. mengerjakan salah satu sembahyang petang (Zuhur atau Asar) sebanyak dua rakaat, lalu beliau terus memberi salam. Kemudian beliau berdiri di suatu kayu mati yang ada di depan masjid, lalu beliau letakkan tangannya di atasnya. Dan hadis seterusnya.... Lalu Zulyadain berkata: Ya Rasulullah! Apakah tuan lupa ataukah sembahyang yang sengaja dipendekkan? Maka Rasulullah s.a.w. menjawab: Bukan aku lupa, dan bukan pula sembahyang itu sengaja \"dipendekkan. Maka berkata Zulyadain : Betul engkau lupa Rasulullah. Lalu Rasulullah s.a.w. mengerjakan sembahyang yang dua rakaat lagi.","r":"Bukhari"}],"te":"Prostration of Forgetfulness (Sahwi)"},{"t":"Sujud Tilawat","p":195,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Bila anak Adam (seseorang) membaca surah As-Sajdah, lalu ia sujud, menyingkirlah syaitan, sambil menangis ia berkata: “Aduh celaka aku.” Anak Adam diperintah sujud, lalu iapun sujud, maka baginya syurga; dan aku diperintah pula sujud tetapi aku enggan (derhaka), maka disediakan bagiku api neraka.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. Bahawasanya Nabi s.a.w. membacakan ayat Al-Quran kepada kami, maka bila beliau sampai kepada ayat AsSajdah, beliau pun takbir lalu sujud, maka kami pun ikut sujud bersamanya.","r":"Abu Daud dan Hakim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Rasulullah s.a.w. membaca Al-Quran dalam sujud (sujud ketika membaca Al-Quran): Kutundukkan wajahku kepada Tuhan yang telah menjadikan daku dan yang telah membelah pendengaranku dan pemandanganku, dengan daya-upaya-Nya dan kekuatan-Nya.","r":"Abu Daud dan Tirmizi"}],"te":"Prostration of Recitation (Tilawah)"},{"t":"Sujud Syukur","p":198,"v":1,"d":[{"y":"h","x":"Dari Abu Bakrah r.a. Bahawasanya Nabi s.a.w. apabila telah datang kepadanya suatu urusan yang menyenangkannya, atau beliau gembira kerana sesuatu, beliau sujud menekurkan ke tanah sebagai berterima kasih kepada Allah Taala.","r":"Abu Daud dan Tirmizi"}],"te":"Prostration of Thankfulness (Syukur)"}],"p":191,"v":1,"te":"Kinds of Prostration"},{"t":"Sembahyang Berjamaah","c":[{"t":"Hukum Sembahyang Berjamaah","p":199,"v":1,"d":[{"y":"h","x":"Dari Abu Darda' r.a. Bahawasanya Nabi s.a.w. bersabda: Tidaklah dari tiga orang di dalam satu kampung, atau dalam satu dusun yang tidak bersembahyang jamaah di kalangan mereka, melainkan telah berkuasa syaitan (iblis) di atas mereka, sebab itu usahakanlah mengadakan sembahyang berjamaah. Ingatlah serigala itu baru dapat menangkap seekor kambing yang terpisah dari kumpulannya.","r":"Abu Daud dan Tirmizi"}],"te":"Ruling on Congregational Prayer"},{"t":"Hikmat Sembahyang Berjamaah","p":200,"v":1,"te":"Wisdom of Congregational Prayer"},{"t":"Keutamaan Sembahyang Berjamaah","p":201,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sembahyang berjamaah itu lebih utama pahalanya dari sembahyang sendiri sebanyak dua puluh tujuh darjat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Demi Tuhan yang berkuasa atas diriku, sesungguhnya sudah menjadi cita-citaku supaya aku perintahkan mengerjakan sembahyang, lalu dikerjakan orang sembahyang itu, kemudian aku perintah pula seorang laki-laki supaya sembahyang bersama-sama dengan manusia, kemudian aku berjalan, bersama-sama dengan aku ada beberapa orang laki-laki yang membawa seikat kayu api akan dibawa kepada kaum yang tidak mahu menghadiri sembah yang berjamaah, lantas dengan api itu aku buat bakar rumah mereka.","r":"Bukhari dan Muslim"}],"te":"Virtue of Congregational Prayer"},{"t":"Berjamaah di Masjid Lebih Utama dari di Rumah","p":202,"v":1,"d":[{"y":"h","x":"Dari Zaid bin Sabit r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Sembahyanglah kamu hai manusia di rumahmu masingmasing, kerana sesungguhnya yang seutama-utamanya ialah semg ng bahyang manusia di rumahnya, kecuali sembahyang yang difardukan. !","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ubayyu bin Kaab r.a. Bahawasanya Nabi s.a.w. bersabda: Sembahyang seorang laki-laki bersama laki-laki lain, lebih suci dari sembahyang seorang dirinya, dan sembahyang laki-laki dengan dua orang laki-laki, lebih suci pula dari sembahyangnya bersama seseorang laki-laki, dan bila sembahyang berjamaah itu lebih banyak, maka itulah yang lebih disukai oleh Allah.","r":"Abu Daud"}],"te":"Praying in Congregation at the Mosque Is Better Than at Home"},{"t":"Sekurang-Kurang Berjamaah","p":203,"v":1,"d":[{"y":"h","x":"Dari Malik bin Huwairis r.a. ia berkata: Pernah kami datang kepada Nabi s.a.w., saya dan seorang teman saya, maka tatkala kami hendak kembali, beliau bersabda kepada kami: Bila waktusembahyang telah datang maka azanlah salah seorang antara kamu kemudian iqamatlah dan hendaklah salah seorang di antara kamu kedua-duanya menjadi imam, yang mana yang lebih utama.'","r":"Bukhari dan Muslim"}],"te":"The Minimum Congregation"},{"t":"Sembahyang Berjamaah bagi Kaum Perempuan","p":204,"v":1,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. Bahawasanya Nabi s.a.w. bersabda: Sembahyang perempuan di rumahnya lebih utama dari sembahyangnya di ruangnya dan sembahyang di biliknya, lebih utama daripada sembahyang di rumahnya.","r":"Abu Daud"},{"y":"h","x":"Dari Ummu Waraqah r.a. Bahawasanya Nabi s.a.w. pernah menyuruh dia menjadi imam untuk ahli rumahnya.","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: Janganlah kamu larang perempuan kamu datang ke masjid, walaupun rumah mereka sendiri lebih baik bagi mereka.","r":"Abu Daud"},{"y":"h","x":"Dari Ribthah Al-Hanafiah r.a. ia berkata: Pernah Siti Aisyah menjadi imam kami, lalu ia berdiri di antara barisan mereka pada sembahyang wajib.","r":"Daruqutni dan Baihaqi"},{"y":"h","x":"Dari Atha' r.a. dari Siti Aisyah r.a.: Sesungguhnya ia pernah jadi imam kaum perempuan, lalu ia berdiri di barisan mereka.","r":"Ibnu Abu Syaibah dan Hakim"}],"te":"Congregational Prayer for Women"},{"t":"Keutamaan Berjamaah dalam Sembahyang Isyak dan Subuh","p":205,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Andaikata mereka mengetahui, tentang pahala yang ada dalam sembahyang Isyak dan sembahyang Subuh, nescaya mereka mendatangi kedua waktu itu (dengan berjemaah) walaupun dengan merangkak kalau ia lemah.","r":"Bukhari"},{"y":"h","x":"Dari Abu Musa Al-Asy'ari r.a. telah berkata: Bersabda Rasulullah s.a.w.: Sesungguhnya yang sebesar-besar pahala manusia\" mengerjakan sembahyang, ialah mereka yang paling jauh berjalan menuju tempat sembahyang itu, dan mereka yang menunggununggu sembahyang sehingga dikerjakan sembahyang itu bersama imam, lebih besar pahalanya daripada orang yang mengerjakan sembahyang itu kemudian ia pergi tidur.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Yazid bin Aswad Al-Amiry r.a. Bahawasanya Nabi s.a.w. pernah bersabda kepada dua orang laki-laki yang telah sembahyang di dalam pondok mereka: Bila engkau berdua telah sembahyang dipondokmu, kemudian engkau datang ke masjid ada orang yang sedang sembahyang berjemaah, maka sembahyanglah kamu bersama mereka, maka sesungguhnya bagi kamu sembahyang itu sunat.","r":"Abu Daud dan Tirmizi"}],"te":"Virtue of Praying Isyak and Subuh in Congregation"},{"t":"Uzur-Uzur yang Menghilangkan Tuntutan Sembahyang Berjamaah","p":207,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah kami di kala kami bersama Rasulullah s.a.w. di dalam suatu perjalanan, ketika itu malam gelap gelita atau turun hujan lebat, berteriaklah tukang serunya: Sembahyanglah kamu di dalam pondokmu (kemahmu).","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Nafi'. Bahawasanya Ibnu Umar r.a. pernah azan memberitahukan sembahyang pada suatu malam yang sangat dingin serta hari berangin, kemudian ia berkata: Sembahyanglah kamu di pondokmu (kemahmu)! Kemudian ia berkata pula: Sesungguhnya Rasululullah s.a.w. pernah menyuruh muazzin bila ada malam sangat dingin dan hari hujan, supaya ia menyerukan: Sembahyanglah kamu di tempatmu masing-masing.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Tak ada ertinya sembahyang bila makanan sedang terhidang, dan tak ada pula ertinya sembahyang apabila ia sedang didesak oleh dua yang keji (Baul dan Ghait).","r":"Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. pernah bersabda: Sesiapa yang mendengar azan, lalu ia tidak mahu mendatanginya, maka tidaklah ada erti sembahyang baginya, kecuali kalau ada uzur. Mereka bertanya: Ya Rasulullah, apakah uzur itu? Nabi menjawab: Takut, atau sakit.","r":"Abu Daud"},{"y":"h","x":"Dari Jabir r.a. ia berkata bahawa Nabi s.a.w. pernah bersabda: Sesiapa yang memakan bawang atau dasun, maka hendaklah ia jauhi masjid kami (tempat sembahyang kami).","r":"Bukhari dan Muslim"}],"te":"Excuses That Lift the Call to Congregational Prayer"},{"t":"Berjalan Tenang Pergi Berjamaah","p":210,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. Bahawasanya Nabi bersabda: Bila sembahyang hendak dilakukan, maka janganlah kamu datang kepadanya dengan berjalan cepat (jangan tergesa-gesa), tetapi datanglah dengan berjalan lambat-lambat, dan hendaklah kamu berjalan dengan tenang, mana yang masih kamu dapati, maka kerjakanlah dan mana yang luput daripadamu, maka sempurnakanlah.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Sesungguhnya imam itu dijadikan untuk menjadi ikutan apabila ia membaca takbir, maka baca pulalah. (jangan dilalaikan dan jangan berantara).","r":"Bukhari dan Muslim"}],"te":"Walking Calmly to the Congregation"}],"p":199,"v":1,"te":"Congregational Prayer"},{"t":"Hubungan antara Imam dan Makmum","c":[{"t":"Syarat-Syarat Sah Mengikut Imam","p":211,"v":1,"d":[{"y":"h","x":"Dari Umar bin Khattab r.a. ia berkata: Nabi s.a.w. telah bersabda: Bahawa tiap-tiap amalan itu harus disertai dengan niat dan bahawa bagi tiap-tiap seseorang adalah apa yang dia niatkan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. bersabda: Sesungguhnya dijadikan imam itu untuk menjadi ikutan, oleh sebab itu janganlah kamu menyalahi perbuatannya, bila ia takbir, maka takbirlah engkau dan bila ia rukuk, maka rukuklah engkau, dan jika ia ana “aan ad al a” maka katakanlah olehmu “al dt GG,” danbilaia sujud, maka sujudlah kamu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah Rasulullah s.a.w. berkhutbah kepada kami, maka beliau bersabda: Tak boleh kaum perempuan mengimami kaum laki-laki.","r":"Ibnu Majah dan Baihaqi"},{"y":"h","x":"Dari Aisyah r.a. pada suatu kali pernah perempuan-perempuan sembahyang di dalam kamarnya mengikut sembahyang imam, lalu Aisyah berkata: Janganlah kamu sembahyang menuruti sembahyang imam, kerana ada yang menutup antara kamu dengan imam Dia.","r":"Syafii dalam Baihaqi"}],"te":"Conditions for Validly Following an Imam"},{"t":"Tempat Imam tidak boleh Lebih Tinggi dari Makmum","p":215,"v":1,"d":[{"y":"h","x":"Dari Huzaifah r.a. sesungguhnya ia pernah sembahyang di atas tumpukan barang-barang, sedang orang-orang sembahyang di tempat yang lebih rendah, lalu ia ditarik oleh Abu Mas'ud hingga sama barisannya dengan mereka dan ketika berpaling (selesai sembahyang), Abu Mas'ud berkata: Tidakkah engkau mengetahui, bahawa sahabat-sahabatmu benci bila imam sembahyang di atas sesuatu, sedang orang sembahyang di tempat yang lebih rendah? Menjawab Huzaifah: “Ya,” sesungguhnya baru aku ingat ketika engkau telah menarikku.","r":"Syafii, Abu Daud dan Baihaqi"},{"y":"h","x":"Dari Sahal bin Saad r.a. ia berkata: Pernah Rasulullah s.a.w. sembahyang di atas mimbar, lalu beliau takbir, dan takbir pulalah orangorang di belakangnya, atau beliau rukuk maka rukuk pulalah orangorang di belakangnya, demikian kata Sahal: Kemudian Rasulullah s.a.w. menghadap kepada orang ramai lalu berkata: Sesungguhnnya aku perbuat yang begini, supaya kamu mengikut aku, dan supaya kamu mengetahui cara sembahyangku.","r":"Bukhari dan Muslim"}],"te":"The Imam May Not Stand Higher Than the Followers"},{"t":"Yang Disunatkan dalam Melakukan Sembahyang Berjamaah","p":216,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. bersabda: Kalau tahulah manusia akan apa yang ada dalam azan dan dalam saf yang pertama, kemudian tidak mereka dapati kecuali dengan undian, nescaya mereka mengambil undian.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. Bahawasanya Nabi s.a.w. telah bersabda: Sempurnakanlah saf yang paling depan, kemudian saf yang berikutnya (saf yang kedua), maka apabila masih kurang (saf yang belum sempurna berisi) maka hendaklah ia memenuhkan saf yang belakang itu.","r":"Abu Daud"},{"y":"h","x":"Dari Al-Barrak bin Azib r.a. ia berkata: Adalah kami bila kami sembahyang di belakang Rasulullah s.a.w. kami lebih suka berdiri di sebelah kanan beliau. Beliau menghadap mukanya kepada kami, dan aku dengar beliau berdoa: Hai Tuhan!! Peliharalah saya dari seksaan Engkau, pada hari Engkau bangkitkan atau Engkau kumpulkan hamba-hamba-Mu.","r":"Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Se-.sungguhnya Allah dan malaikat-malaikat-Nya memberi selawat (mendoakan) akan saf yang sebelah kanan.","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. sesungguhnya Rasulullah s.a.w. pernah bersabda: Samakanlah saf kamu, dan hendaklah luruskan bidang bahumu, dan tutuplah celah-celah saf yang renggang dan rapatkanlah tanganmu ke tangan saudaramu, dan jangan kamu biarkan ada yang renggang tempat lalu syaitan.","r":"Abu Daud"},{"y":"h","x":"Dari Anasr.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Samakanlah barisanmu (saf), sesungguhnya menyamakan saf itu termasuk kesempurnaan sembahyang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. ia berkata: Telah dibaca iqamah akan sembahyang maka Rasulullah s.a.w. menghadapkan mukanya kepada kami lalu berkata: Samakanlah safmu, dan rapatkanlah barisanmu, kerana sesungguhnya aku melihatmu dari belakangku.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sebaik-baik saf laki-laki ialah saf yang pertama dan yang seburukburuknya ialah saf yang paling belakang. Dan sebaik-baiknya saf perempuan ialah saf yang paling belakang, dan yang seburuk-buruknya saf yang paling depan.","r":"Muslim"}],"te":"What Is Recommended in Congregational Prayer"},{"t":"Mengatur Saf","p":219,"v":1,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Bersabda Rasulullah s.a.w.: Hendaklah di antara kamu yang mengiringi aku, pertama orangorang yang baligh berakal, kemudian yang mengiringi mereka (maksudnya yang di bawah mereka) kemudian bagi orang-orang yang mengiringi mereka. ;","r":"Ahmad dan Muslim"},{"y":"h","x":"Dari Jabirr.a. ia berkata: Pernah Rasulullah s.a.w. berdiri hendak sembahyang. Lalu aku datang, maka aku berdiri di sebelah kirinya. Maka diambilnya tanganku, lalu diputarkannya aku, hingga ditegakkannya aku di sebelah kanannya. Kemudian datang Jabar bin Shakhar, lalu ia berdiri di sebelah kiri Rasulullah s.a.w. Maka diambilnya tangan kami sekaliannya, lalu badan kami berdompak (bertemu) hingga kami berdiri di belakangnya.","r":"Muslim dan Abu Daud"}],"te":"Arranging the Rows"},{"t":"Orang yang Lebih Berhak Menjadi Imam","p":220,"v":1,"d":[{"y":"h","x":"Dari Abu Said r.a. ia berkata: Bersabda Rasulullah s.a.w.: Bila mereka ada tiga orang, maka hendaklah mereka jadikan imam salah seorang di antara mereka, dan yang lebih patut di antara mereka menjadi imam ialah yang lebih baik pembacaannya.","r":"Muslim"},{"y":"h","x":"Dari Abu Mas'ud r.a. ia berkata: Bersabda Rasulullah s.a.w.: Hendaklah satu kaum mengangkat seseorang jadi imam, iaitu mereka yang lebih pandai membaca kitab suci (Al-Quran). Jika sekiranya mereka dalam pembacaan itu sama, maka hendaklah mereka angkat seorang dari mereka yang lebih tahu dengan sunah (hadis-hadis Nabi s.a.w.). Jika mereka dalam pengetahuan sunah itu sama pula, maka hendaklah mereka angkat salah seorang dari mereka yang lebih dahulu hijrah. Jika mereka dalam hijrah itu sama, maka hendaklah mereka angkat seseorang yang lebih dahulu masuk Islam. Dan pada satu riwayat, orang yang lebih tua umurnya.'","r":"Muslim"},{"y":"h","x":"Dari Abu Zaid Umar bin Ahtab r.a. dari Nabi s.a.w. beliau bersabda: Bila ada mereka tiga orang, maka hendaklah mereka jadikan imam orang yang lebih pandai membaca kitab Allah a.w.' jika sekiranya mereka dalam pembacaan itu bersamaan, maka hendaklah dijadikan imam yang lebih tua umurnya, dan apabila mereka dalam umur itu: bersamaan pula, maka hendaklah jadikan imam yang lebih menarik rupanya.","r":"Baihaqi"},{"y":"h","x":"Dari Abu Mas'ud Al-Ansari r.a. Bahawasanya Nabi s.a.w. bersabda: Jangan mengimami seseorang akan seorang di tempatnya dan tidak pula dalam kekuasaannya dan jangan pula menduduki seseorang akan tempat duduk-seseorang, kecuali dengan izinnya.","r":"Muslim"}],"te":"Who Has Most Right to Lead the Prayer"},{"t":"Orang yang Makruh Menjadi Imam","p":223,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Tiga macam yang tidak diangkat sembahyang mereka melampaui kepala mereka, sekalipun sejengkal (maksudnya tidak diterima), iaitu orang yang mengimami suatu kaum yang membencinya dan perempuan yang senantiasa dimarahi suaminya serta dua orang yang sedang berselisih.","r":"Ibnu Majah"},{"y":"h","x":"Dari Amr bin Ashr.a. Bahawasanya Nabi s.a.w. telah bersabda di atas mimbar: Sesudah hariku ini tidak boleh seorang laki-laki masuk ke tempat seorang perempuan lain (perempuan yang suaminya tidak di rumah), kecuali bila besertanya ada seorang atau dua orang lakilaki.","r":"Muslim"}],"te":"Who Is Disliked as Imam"},{"t":"Hukum Makmum yang Jadi Muwafiq atau Masbuq","p":224,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Siapa yang mendapati satu rakaat (rukuk) dari sembahyang bersama imam, maka sesungguhnya ia telah mendapati sembahyang itu seluruhnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Sahal bin Saad r.a. Bahawasanya Nabi s.a.w. bersabda: Imam ialah yang menanggung pembacaan; apabila baik pembacaannya maka pahalanya untuk dirinya dan untuk mereka (makmum) dan jika rosak bacaannya maka dosanya di atas dirinya sendiri, dan bukan atas mereka.","r":"Ibnu Majah dan Al-Hakim"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. telah bersabda: Imam ialah yang menanggung pembacaan, dan muazzin orang yang diberi amanah (kepercayaan). Ya Allah!! Tunjukilah imam-imam itu, dan ampunilah tukang-tukang azan itu.","r":"Abu Daud, Tirmizi dan lain-lain"}],"te":"Ruling on the Follower Who Is Muwafiq or Masbuq"},{"t":"Imam Hendaklah Membaca Surah yang Agak Pendek","p":226,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. bersabda: Bila seseorang di antara kamu sembahyang bersama-sama dengan manusia, maka hendaklah dipendekkannya membaca surah (supaya sembahyang itu jangan terlalu lama), kerana sesungguhnya di antara mereka ada yang tak tahan lama berdiri, dan ada yang sakit dan ada pula yang sudah tua. Dan bila seseorang sembahyang untuk dirinya sendiri (sembahyang seorang), maka boleh dipanjangkannya sekehendak hatinya. —","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. Bahawasanya Nabi s.a.w. bersabda: Sesungguhnya aku bermaksud berdiri agak lama di dalam sembahyang. Ketika aku dengar tangis kanak-kanak, lalu aku pendekkan saja sembahyangku itu, kerana takut aku mempersusah (memberatkan) ibunya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. telah berkata: Adalah sahabat-sahabat Rasulullah s.a.w. menunjuki (memperingatkan) yang lain di dalam sembahyang.","r":"Daruqutni dan Baihaqi"}],"te":"The Imam Should Recite Fairly Short Surahs"},{"t":"Menggantikan Imam bila Imam Ada Halangan","p":227,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Rasulullah s.a.w. bersabda: Suruhlah Abu Bakar; dirikanlah sembahyang dengan orang-orang. Lalu Rasulullah s.a.w. mendapati merasa dirinya agak ringan (merasa sembuh sedikit), maka beliau pun pergi ke masjid. Ketika itu, Abu Bakar sedang mengimami orang ramai. Maka apabila Abu Bakar nampak beliau (di belakang), diapun pergi untuk berundur ke belakang, lalu memberi isyarat kepada Rasulullah dengan tangannya, maka Rasulullah s.a.w. pun datang sehingga beliau duduk di sebelah Abu Bakar. Maka sembahyanglah Rasulullah s.a.w. dengan orang ramai, sedang Abu Bakar memperdengarkan (menyampaikan) takbir kepada mereka (jadi mubaligh).","r":"Bukhari dan Muslim"}],"te":"Replacing the Imam When He Is Prevented"},{"t":"Mengulang Sembahyang untuk Orang yang Baru Datang","p":229,"v":1,"d":[{"y":"h","x":"Dari Abu Said Al-Khudri r.a. Bahawa pernah datang seorang lakilaki sedang Rasulullah s.a.w. telah selesai sembahyang, maka Rasulullah s.a.w. bersabda: Siapakah yang mahu bersedekah atas orang lain? Maka salah seorang berdiri lalu sembahyang bersama orang yang datang itu.","r":"Abu Daud dan Tirmizi"}],"te":"Repeating the Prayer for a Latecomer"}],"p":211,"v":1,"te":"The Imam and the Followers"},{"t":"Sembahyang Qasar dan Jamak","c":[{"t":"Sembahyang Qasar","p":230,"v":1,"d":[{"y":"a","s":4,"a":101,"b":101,"m":"Dan bila kamu mengadakan perjalanan di muka bumi, maka tiadalah dosa atasmu jika kamu memendekkan sembahyang"},{"y":"h","x":"Dari Ya'la bin Umayyah ia berkata: Pernah aku bertanya kepada Umar r.a.: Maka tiadalah dosa atasmu jika kamu memendekkan sembahyang bila kamu takut bahawa kamu akan dibinasakan oleh orang-orang kafir, padahal sesungguhnya manusia telah aman. Umar menjawab: Aku benar-benar tercengan, tercengan tentang itu, lalu aku bertanya kepada Rasulullah s.a.w. Maka Rasulullah s.a.w. menjawab: (Sembahyang qasar) itu adalah kurnia yang dikurniakan Allah s.w.t. kepadamu, maka terimalah olehmu kurniaNya.","r":"Muslim"}],"te":"Shortened Prayer (Qasar)"},{"t":"Jarak Jauh Perjalanan yang boleh Sembahyang Qasar","p":231,"v":1,"d":[{"y":"h","x":"Ibnu Umar dan Ibnu Abbas r.a. pernah mengqasar dan berbuka dalam perjalanan empat burud, iaitu enam belas farsakh.","r":"Bukhari"},{"y":"h","x":"Dari Atha' r.a. sesungguhnya ia pernah berkata: Bertanya seseorang kepada Ibnu Abbas r.a.: Apakah aku boleh mengqasar (dalam perjalanan sejauh) ke Arafah? Maka Ibnu Abbas menjawab: “Tidak,” maka orang itu bertanya pula: Ke Mina? Ibnu Abbas menjawab: Tidak, tetapi ke Jedah, ke Usfan dan ke Taif.","r":"Syafii dan Baihaqi"},{"y":"h","x":"Dari Yahya bin Mazid ia berkata: Pernah aku bertanya kepada Anas tentang mengqasar sembahyang, lalu ia menjawab: Adalah Rasulullah s.a.w. bila beliau melakukan perjalanan sejauh tiga mil, atau tiga farsakh, beliau sembahyang dua rakaat.","r":"Muslim"}],"te":"Travel Distance for Shortening Prayer"},{"t":"Batas Masa Jadi Musafir","p":234,"v":1,"d":[{"y":"h","x":"Dari Al-Ula' bin Al-Hadrami r.a. ia berkata: Nabi s.a.w. bersabda: Telah tinggal kaum Muhajirin di Mekah selama tiga hari sesudah membayar rukun hajinya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Umar r.a. Bahawasanya ia pernah membawa orang Yahudi dari Hijaz, kemudian diizinkannya orang yang datang diantara mereka untuk bermukim selama tiga hari.","r":"Malik dalam kitab Al-Muwatak"},{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah kami keluar (pergi haji) beserta Nabi s.a.w. ke Mekah, maka beliau kerjakan sembahyang dua rakaatdua rakaat sehingga kami kembali ke Madinah.","r":"Bukhari dan Muslim"}],"te":"How Long One Counts as a Traveller"},{"t":"Sembahyang Jamak","p":236,"v":1,"te":"Combined Prayer (Jamak)"},{"t":"Uzur-Uzur yang Membolehkan Jamak Sembahyang","p":236,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Adalah Rasulullah s.a.w. apabila beliau terburu-buru berjalan, beliau menjamak sembahyang Maghrib dengan sembahyang Isyak.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anasr.a. Bahawasanya Nabi s.a.w. ada (pernah) menjamakkan antara Zuhur dan Asar.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. menceritakan Nabi s.a.w. : Bahawasanya beliau bila terburu-buru berjalan, ditakkhirkannya sembahyang Zuhur pada waktu Asar lalu dijamakkannya antara keduanya dan ditakkhirkannya pula sembahyang Maghrib hingga dijamakkan antara Maghrib dan Isyak apabila hilang cahaya merah.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah Rasulullah s.a.w. mengerjakan sembahyang Zuhur dengan Asar dan Maghrib dengan Isyak secara menjamak, bukan kerana takut dan bukan pula kerana perjalanan. Berkata Malik: Aku berpendapat hal itu di waktu hari hujan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah Rasulullah s.a.w. menjamak antara Zuhur dan Asar, Maghrib dan Isyak di Madinah, tidak kerana takut dan tidak pula kerana hujan.","r":"Muslim"}],"te":"Excuses That Permit Combining Prayers"},{"t":"Mengerjakan Jamak Taqdim bagi Orang yang Hendak Berjalan Jauh","p":239,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Mahukah kamu aku khabarkan tentang sembahyang Rasulullah s.a.w. iaitu: Bila matahari telah condong, sedang beliau masih di rumah, beliau dahulukan mengerjakan sembahyang Asar (jamak taqdim) pada waktu Zuhur, dan dijamakkanya keduanya ketika matahari telah condong.","r":"Baihaqi"}],"te":"Combining Early (Jamak Taqdim) for Travellers"},{"t":"Syarat Jamak Taqdim dan Jamak Takkhir","p":239,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. Bahawasanya Rasulullah s.a.w. pernah sembahyang Maghrib dan Isyak di Muzdalifah secara menjamakkan, tiap-tiap satu dari kedua sembahyang itu dikerjakannya dengan satu kali iqamat, dan beliau tidak membaca tasbih (sembahyang) antara keduanya.","r":"Bukhari dan Nasai"}],"te":"Conditions of Early and Late Combining"},{"t":"Boleh Jamak dan Qasar dalam Perjalanan Jauh","p":241,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah Rasulullah s.a.w. menjamakkan antara sembahyang Maghrib dan Isyak dengan jamak, yang ia kerjakan sembahyang Maghrib tiga rakaat, dan Isyak dua rakaat dengan satu kali iqamat saja.","r":"Abu Daud dan Tirmizi"}],"te":"Combining and Shortening on a Long Journey"}],"p":230,"v":1,"te":"Shortened and Combined Prayers"},{"t":"Sembahyang Jumaat","c":[{"t":"Hukum Sembahyang Jumaat","p":242,"v":1,"d":[{"y":"h","x":"Dari Tariq bin Syihab r.a.: Bahawa Nabi s.a.w. pernah bersabda: Sembahyang Jumaat itu hak dan wajib atas tiap-tiap orang Islam secara berjemaah, kecuali atas empat macam, iaitu hamba yang dimiliki, kaum perempuan, kanak-kanak, atau orang sakit.","r":"Abu Daud"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Bersabda Rasulullah s.a.w. : Siapa yang percaya kepada Allah dan hari yang akhir, maka wajiblah atasnya mengerjakan sembahyang Jumaat, kecuali perempuan, musafir (orang yang sedang dalam perjalanan), hamba sahaya atau orang sakit.","r":"Abu Daud dan Baihaqi"}],"te":"Ruling on the Friday Prayer"},{"t":"Sembahyang Jumaat hanya Dua Rakaat","p":243,"v":1,"d":[{"y":"h","x":"Dari Umar r.a. Bahawasanya ia berkata: Sembahyang hari raya Adha dua rakaat, sembahyang hari raya Fitri dua rakaat, sembahyang musafir dua rakaat, sembahyang Jumaat dua rakaat, sempurnalah sembahyang itu, bukan qasar demikianlah mengikut perkataan Nabimu s.a.w. dan sungguh rugilah siapa yang mengabaikannya.","r":"Ahmad dan Nasai dan lain-lain"}],"te":"The Friday Prayer Is Only Two Rakaat"},{"t":"Syarat-Syarat Sah Mendirikan Jumaat","p":244,"v":1,"d":[{"y":"h","x":"Dari Abdurrahman bin Kaab, dari bapanya ia berkata: Mula-mula orang yang mendirikan sembahyang Jumaat padu kami di Madinah ialah Asad bin Zararah sebelum Nabi s.a.w. datang ke Madinah iaitu di Naqi' Al-Khidmat. Aku bertanya: Berapa orang kamu ketika itu? Ia (bapanya) menjawab: Seramai empat puluh orang laki-laki.","r":"Abu Daud dan Baihaqi"},{"y":"h","x":"Dari Jabir r.a. Bahawasanya Nabi s.a.w. pernah berkhutbah berdiri, lalu datang unta (yang membawa makanan) dari Syam, maka berkerumunlah manusia kepadanya. Hingga tidak tinggal (di dalam masjid), melainkan dua belas orang laki-laki.","r":"Muslim"},{"y":"h","x":"Dari Anas r.a. Bahawasanya Nabi s.a.w. mengerjakan sembahyang Jumaat tatkala matahari telah condong.","r":"Bukhari"}],"te":"Conditions for Establishing the Friday Prayer"},{"t":"Sembahyang Jumaat bagi Orang yang Jauh Tinggal di Desa","p":246,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. Bahawasanya Nabi s.a.w pernah bersabda: Jumaat itu diwajibkan atas orang yang mendengar seruan azan.","r":"Abu Daud dan lain-lain"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. pernah bersabda: Siapa yang memperoleh satu rakaat sembahyang Jumaat, maka hendaklah ia sembahyangkan (ditambahnya) rakaat yang lain. Dan apabila didapatinya mereka sedang duduk, hendaklah dikerjakannya sembahyang Zuhur empat rakaat.","r":"Daruqutni"}],"te":"Friday Prayer for Those Living Far Away in Villages"}],"p":242,"v":1,"d":[{"y":"a","s":62,"a":9,"b":9,"m":"Hai orang-orang yang beriman! Apabila diseru untuk sembahyang di hari Jumaat, maka bersegeralah kamu pergi mengingat Allah dan tinggalkanlah jual beli. Itulah yang lebih baik bagimu jika kamu mengetahui"}],"te":"Friday Prayer"},{"t":"Khutbah Jumaat","c":[{"t":"Syarat Khutbah Jumaat","p":247,"v":1,"d":[{"y":"h","x":"Dari Jabir bin Samurah r.a., bahawasanya Rasulullah s.a.w. adalah beliau membaca khutbah secara berdiri, kemudian beliau duduk, kemudian beliau berdiri, lalu beliau membaca khutbah secara berdiri. Dan pada satu riwayat: Adalah bagi Nabi s.a.w. dua khutbah, yang beliau duduk antara keduanya, sambil membaca ayat AlQuran dan beliau beri manusia peringatan.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. berkata ia: Adalah Rasulullah s.a.w. di hari Jumaat membaca dua khutbah dan beliau duduk antara keduanya.","r":"Bukhari dan Muslim"}],"te":"Conditions of the Friday Sermon"},{"t":"Rukun Khutbah","p":248,"v":1,"d":[{"y":"h","x":"Dari Jabirr.a. bahawasanya Nabi s.a.w. telah membaca khutbah di hari Jumaat, lalu beliau memuji Allah dan menyanjung-Nya.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Nabi s.a.w. telah bersabda: Berfirman Allah Taala: Telah aku jadikan umatmu, yang tidak boleh (tidak sah) khutbah bagi mereka, kecuali mereka mengaku, bahawa engkau hamba-Ku dan rasul-Ku.'","r":"Baihaqi"}],"te":"Pillars of the Sermon"},{"t":"Wasiat Bertakwa kepada Allah","p":251,"v":1,"d":[{"y":"a","s":14,"a":4,"b":4,"m":"Dan tidaklah kami utus seorang Rasul melainkan dengan bahasa kaumnya, supaya ia dapat memberi keterangan kepada mereka"},{"y":"h","x":"Dari Abu Darda' r.a. ia berkata: Aku dengar Rasulullah s.a.w. bersabda: Bahawasanya ulama-ulama itu waris nabi-nabi.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ali bin Abi Talib r.a. berkata: Sampaikanlah kepada manusia dengan apa (bahasa) yang mereka fahami. Apakah kamu menyukai, bahawa Allah dan Rasul itu didustakan orang.","r":"Bukhari"}],"te":"The Advice to Fear Allah"},{"t":"Sunat-Sunat Khutbah","p":252,"v":1,"d":[{"y":"h","x":"Dari As-Sya'bi r.a. Bahawasanya Nabi s.a.w. bila beliau telah naik ke atas mimbar pada hari Jumaat, dan menghadapkan mukanya kepada manusia, beliau mengucapakan: Assalamu'alaikum.","r":"Ibnu Abi Syaibah"},{"y":"h","x":"Dari Ibnu Umar r.a. Bahawa Nabi s.a.w. apabila beliau keluar pada hari Jumaat, beliau duduk iaitu di atas mimbar, hingga muazzin selesai azannya, kemudian beliau berdiri, lalu berkhutbah.","r":"Abu Daud"},{"y":"h","x":"Dari Hakim bin Khazan r.a. ia berkata: Aku pernah diutus kepada Nabi s.a.w. maka kami pergi dengan beliau ke Jumaat, lalu beliau berdiri bertelekan ke sebuah panah atau sebuah tongkat lantas beliau memuji Allah dan menyanjung-Nya, dengan kalimat-kalimat yang sederhana dan baik-baik, lagi mengandung berkat.","r":"Abu Daud"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Adalah Rasulullah s.a.w. bila beliau berkhutbah merah dua matanya, dan tinggi suaranya, dan sangat marahnya, hingga seolah-olah beliau seorang panglima tentera. Ah bs","r":"Muslim"},{"y":"h","x":"Dari Ammar bin Yasirr.a. ia berkata: Pernah aku mendengar Nabi s.a.w. bersabda: Sesungguhnya seseorang yang memanjangkan sembahyangnya dan memendekkan khutbahnya, adalah tanda kealimannya (tanda orang Faqih), sebab itu panjangkanlah sembahyang dan pendekkanlah khutbah.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda: Bila engkau mengatakan kepada temanmu di hari Jumaat: “diamlah” sedang imam membaca khutbah, maka sungguh telah habis pahala Jumaatmu itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda: Bila engkau mengatakan kepada temanmu di hari Jumaat: diamlah sedang imam membaca khutbah, maka sungguh telah habis pahala Jumaatmu itu. (Diriwayatkan oleh Bukhari dan Muslim). Hadis ini menunjukkan bahawa berkata-kata sama ada sifatnya melarang orang mahupun tidak menghilangkan pahala sembahyang Jumaat, tetapi tidak menafikan sah Jumaat. Dari itu umumnya ulama berpendapat, bahawa berkata-kata waktu imam berkhutbah makruh hukumnya. Tetapi ulama Hadawiyah, Hanafia dan Malikiah mengharamkan berkata-kata ketika Imam berkhutbah. Sebab itu hendaklah kita diam ketika khutbah dibacakan. Kesembilan: Membaca surah Al-Ikhlas dalam duduk antara keduanya; kerana Nabi s.a.w. membaca surah Al-Ikhlas apabila beliau duduk istirahat antara dua khutbah itu.","r":"Ibnu Hibban"}],"te":"Sunnah Acts of the Sermon"}],"p":247,"v":1,"te":"Friday Sermon"},{"t":"Azan Jumaat","p":254,"v":1,"d":[{"y":"h","x":"Dari Saib bin Yazid r.a. ia berkata: Adalah azan di hari Jumaat, pada mulanya ialah bila imam telah duduk di atas mimbar demikian di zaman Rasulullah s.a.w., di zaman Abu Bakar dan di zaman Umar; maka tatkala sampai di zaman Usman dan manusia telah makin ramai, ditambahnyalah azan yang ketiga' iaitu di atas zaurak. ;","r":"Bukhari"},{"y":"h","x":"Dari Saib bin Yazidr.a. ia berkata: Adalah azan di hari Jumaat, ketika telah duduk imam di atas mimbar demikian di zaman Rasulullah 1. Yang dimaksudkan dengan azan ketiga ialah azan yang dikerjakan sebelum imam naik mimbar sedang azan yang kedua ialah azan ketika imam naik mimbar dan azan yang pertama ialah qamat. Dan dalam riwayat Syafii azan yang ketiga itu ialah yang kedua. s.a.w.,di zaman Abu Bakar dan di zaman Umar r.a.: maka tatkala sampai ke zaman khalifah Usman dan manusia makin ramai, maka disuruh oleh Usman untuk mengadakan azan yang kedua lalu dilakukan azan itu, kemudian tetaplah perintah itu seperti demikian.","r":"Syafii"}],"te":"The Friday Azan"},{"t":"Sunat-Sunat sebelum Jumaat dan Keutamaan Hari Jumaat","c":[{"t":"Pekerjaan Sunat sebelum Pergi Jumaat","p":258,"v":1,"d":[{"y":"h","x":"Dari Salman r.a. ia berkata: Bersabda Rasulullah s.a.w.: Tiadalah mandi seseorang pada hari Jumaat lalu bersuci sekadar kuasanya bersuci serta memakai minyak dengan minyak, dan dipakainya harumharuman rumahnya, kemudian keluarlah id dengan tidak menceraikan' antara dua orang, kemudian mengerjakan sembahyang yang telah : diperintahkan baginya (sembahyang tahiyat masjid), kemudian berdiam diri bila imam telah berkata-kata (berkhutbah), melainkan diampunilah baginya dosanya antara Jumaat itu dengan Jumaat yang lain.","r":"Bukhari"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. telah bersabda: Bila tiba hari Jumaat, berdirilah malaikat-malaikat di tiap-tiap pintu masjid menuliskan nama orang-orang yang masuk masjid, satu demi satu, mdka apabila imam telah duduk di atas mimbar, mereka lipatlah buku catatan mereka, dan mereka bersama-sama datang mendengarkan khutbah itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Nabi s.a.w. biasa mengerat kukunya pada hari Jumaat, dan mencukur misainya sebelum beliau berangkat pergi sembahyang.","r":"Al-Bazzar dan At-Tabarani"},{"y":"h","x":"Dari Aus bin Aus r.a. dari Nabi s.a.w. beliau bersabda: Siapa yang telah bersetubuh lalu ia mandi di hari Jumaat, berpagi-pagi ia datang ke masjid dan ia mendapati permulaan khutbah, sedang ia datang dengan berjalan kaki, tidak berkenderaan, memperhatikan khutbah, dan tidak dirosakkannya pahalanya (kerana berkata-kata di waktu khutbah dibacakan), adalah baginya upah (pahala) pada tiap-tiap langkah setahun amal puasanya dan.sembahyang malamnya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. Sesungguhnya beliau bersabda: Bila sembahyang telah diqamatkan maka janganlah kamu datang kepadanya (ke tempat sembahyang) sedang kamu berlari-lari (tergesa-gesa) tetapi datanglah kamu kepadanya sedang kamu berjalan kaki, dan hendaklah kamu berjalan tenang.'","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdullah bin Basrr.a. ia berkata: Pernah datang seorang lakilaki dengan melangkahi tengkuk orang lain di hari Jumaat, sedang Nabi s.a.w. berkhutbah, maka beliau berseru kepadanya: Duduklah engkau, maka sesungguhnya engkau telah menyakiti orang.'","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Arqam bin Abu Aqram r.a. ia berkata: Telah bersabda Nabi s.a.w.: Orang-orang yang melangkahi pundak orang lain di hari Jumaat, dan diceraikannya dua orang yang sedang duduk, setelah Imam keluar (berkhutbah), tak ubahnya seperti orang yang menghela perut panjangnya sendiri ke dalam neraka.","r":"Abu Daud"}],"te":"Sunnah Acts Before Going to Friday Prayer"},{"t":"Keutamaan Hari Jumaat","p":263,"v":1,"d":[{"y":"h","x":"Dari Abu Lubabah bin Abdul Munzir ia berkata: Telah bersabda Rasulullah s.a.w.: “Sesungguhnya hari Jumaat itu, ialah kepala sekalian hari, dan hari yang terbesar di sisi Allah, lebih besar daripada hari raya Adha dan hari raya Fitri.” |","r":"Ibnu Majah dan Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sebaik-baik hari yang memancarkan matahari, ialah hari Jumaat, pada hari itu dijadikan Adam a.s. dan pada hari itu pula dimasukkan ke dalam syurga serta pada hari itu pula ia dikeluarkan dari dalam syurga dan tidak akan terjadi hari kiamat, kecuali pada hari Jumaat.","r":"Muslim dan Tirmizi"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Hari Jumaat itu ialah hari haji bagi orang-orang miskin.","r":"Humaid bin Zanjawiyah"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. dari Nabi s.a.w. bahawa beliau bersabda: Siapa yang membaca surah Al-Kahfi pada hari Jumaat, maka disinari Allah dia dengan cahaya antara dua Jumaat.....","r":"Baihaqi"},{"y":"h","x":"Dari Aus bin Aus r.a. ia berkata: Bersabda Rasulullah s.a.w.:Sesungguhnya harimu yang paling utama ialah hari Jumaat, sebab itu perbanyaklah olehmu membaca selawat kepadaku pada hari itu. kerana sesungguhnya selawatmu itu dipersembahkan kepadaku.","r":"Abu Daud dan lain-lain"},{"y":"h","x":"Dari Abu Musa Al-Asy'arir.aia berkata: Saya mendengar Rasulullah s.a.w. bersabda tentang saat mustajab di hari Jumaat, ialah antara duduknya imam (di atas mimbar) hingga selesai sembahyang Jumaat.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Abdullah bin Amr r.a. Dari Nabi s.a.w. beliau bersabda: Tidaklah dari seseorang muslim yang mati pada hari atau pada malam Jumaat, melainkan ia dipelihara Allah dari fitnah kubur.","r":"Tirmizi"},{"y":"h","x":"Dari Umar r.a. ia berkata: Bila manusia telah bersesak-sesak bersembahyang, maka bolehlah sujud seseorang di atas punggung saudaranya.","r":"Baihaqi"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah sembahyang Rasulullah s.a.w. beliau membaca surah An-Najm, lalu sujud, lantas dipanjangkannya sujud itu, sedang manusia sangat ramai, sehingga sembahyanglah sebahagian di atas punggung sebahagian yang lain.","r":"Baihaqi"}],"te":"Virtues of Friday"},{"t":"Bertepatan Dua Hari Raya dengan Hari Jumaat","p":266,"v":1,"d":[{"y":"h","x":"Dari Zaid bin Arqam r.a. ia berkata: Pernah aku mengalami bersama Nabi s.a.w. dua hari raya yang bertepatan, lalu disembahyangkannya hari raya itu, kemudian beliau memberi kelonggaran tentang sembahyang Jumaat, dengan mengatakan: Siapa-siapa yang hendak sembahyang maka sembahyanglah.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Rasulullah s.a.w. telah bersabda: Sesungguhnya telah berkumpul pada harimu ini dua hari raya, maka siapa yang menghendaki mencukupilah kepadanya sembahyang hari Raya ini sebagai ganti sembahyang Jumaat sedang kami terus juga mengerjakannya.","r":"Abu Daud dan Ibnu Majah"},{"y":"h","x":"Dari Atha' r.a. ia berkata: Pernah Ibnu Zubair sembahyang hari raya pada hari Jumaat pagi-pagi hari, kemudian kami pergi ke Jumaat, maka tidaklah ia (Ibnu Zubair) keluar ke tempat kami, maka sembahyanglah kami sendiri-sendiri. Ketika itu Ibnu Abbas sedang di Taif. Setelah ia kembali maka kami beritahukan hal itu kepadanya, maka ia menjawab: Itu menurut sunah.","r":"Abu Daud"},{"y":"h","x":"Dari Usman r.a. bahawasanya ia pernah berkata di dalam khutbahnya: Hai manusia! Sesungguhnya ini adalah sesuatu hari yang sesungguhnya telah berkumpul bagimu padanya dua hari raya, maka siapa-siapa yang ingin menunggu sembahyang Jumaat dari orang-orang kampung (orang-orang pergunungan), maka boleh ia menunggu. Maka siapa-siapa yang ingin hendak pulang, maka sudah aku izinkan baginya.","r":"Bukhari"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda pada suatu hari Jumaat di antara beberapa hari Jumaat: Hai sekalian kaum Muslimin, sesungguhnya hari ini telah dijadikan Allah bagimu menjadi hari raya, sebab itu mandilah kamu, dan kamu biasakanlah bersugi (memberus gigi).","r":"Tabarani"}],"te":"When Eid Falls on a Friday"},{"t":"Hukum Meninggalkan Sembahyang Jumaat","p":269,"v":1,"d":[{"y":"h","x":"Dari Abu Ja'di Adh-Dhamari r.a. dari Rasulullah s.a.w. beliau telah bersabda: Sesiapa yang meninggalkan Jumaat tiga kali berturut-turut dengan tidak ada uzur, maka dihukum orang munafik.","r":"Ibnu Hibban"},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Rasulullah s.a.w. beliau bersabda: Siapa yang meninggalkan Jumaat tiga kali berturut-turut maka sesungguhnya ia telah melemparkan agama Islam ke belakangnya.","r":"Abu Ya'la"},{"y":"h","x":"Dari Ibnu As'ad bin Zararah, dari Pakciknya, dari Nabi s.a.w. bersabda: Siapa yang meninggalkan Jumaat tiga kali telah mencap Allah akan hatinya, dan dijadikan-Nya hatinya itu seperti hati orang munafik.","r":"Abu Bakar bin Ali Al-Marwazi dan Abu Ya'la"}],"te":"Ruling on Missing the Friday Prayer"}],"p":258,"v":1,"te":"Sunnah Acts Before Friday and the Virtues of Friday"},{"t":"Zikir sesudah Sembahyang","p":271,"v":1,"d":[{"y":"h","x":"Dari Saubanr.a. ia berkata: Adalah Rasulullah s.a.w. apabila telah berpaling dari sembahyangnya (menghadap kepada makmum), beliau membaca “istighfar” (astaghfirullah) sebanyak tiga kali, dan beliau terus membaca: SI DAN 4 SS a ag a Sa","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda: Sesiapa yang membaca tasbih “Al jln.—” sesudah tiap-tiap selesai sembahyang sebanyak 33 kali, dan memuji Allah “dd sebanyak 33 kali, dan membesarkan Allah CS dl” sebanyak 33 kali pula, dan ia berkata waktu sempurna 100 kali: Sd pp a a, Ya a YI pa DE (ertinya: Tidak ada Tuhan melainkan Allah Yang Maha Esa, tidak ada sekutu bagi-Nya dan bagi-Nya segala puji, dan Dia adalah Maha Kuasa di atas tiap-tiap sesuatu), nescaya diampuni Allah baginya seluruh kesalahannya, walaupun kesalahannya itu seumpama buih di laut banyaknya.","r":"Muslim"},{"y":"h","x":"Dari Abu Umamah r.a. ia berkata: Ditanya orang Rasulullah s.a.w.: dimana doa yang lebih didengar (diperhatikan Allah)? Rasulullah s.a.w. menjawab: Di waktu rongga malam yang terakhir dan sesudah setiap selesai sembahyang yang lima waktu.","r":"Tirmizi"},{"y":"h","x":"Dari Mughirah bin Syu'bah r.a. ia berkata: Bersabda Rasulullah s.a.w. Janganlah sembahyang imam di tempatnya yang ia telah mengerjakan sembahyang yang fardu padanya, hingga ia menghindar daripadanya.","r":"Ibnu Majah dan Abu Daud"}],"te":"Remembrance After Prayer"},{"t":"Sembahyang Waktu Takut","c":[{"t":"Macam-Macam Sembahyang Takut","p":274,"v":1,"d":[{"y":"h","x":"Maka jika kamu takut, maka sembahyanglah kamu secara berjalan kaki atau berkenderaan. Berkata Ibnu Umar r.a: dengan menghadap kiblat ataupun tidak.","r":"Bukhari"}],"te":"Kinds of the Fear Prayer"},{"t":"Musuh di Arah Kiblat","p":274,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah aku hadir bersama Nabi s.a.w. pada sembahyang khauf, lalu kami buat dua barisan, satu barisan di belakang Rasulullah s.a.w. sedang musuh di antara kami dan kiblat, maka Rasulullah s.a.w. takbir dan bertakbir pula kami semuanya, kemudian beliau rukuk, dan rukuk pula kami semuanya, kemudian diangkat kepalanya dari rukuk (iktidal), dan kami angkat pula kepala kami semuanya, kemudian beliau turun untuk sujud diiringi oleh barisan yang di belakangnya, dan barisan yang di belakang sekali berdiri menghadap musuh, maka tatkala Rasulullah melakukan sujudnya dan telah berdiri pula barisan yang mengiringinya, turun pulalah barisan yang di belakang untuk sujud dan mereka terus berdiri, kemudian barisan yang di belakang maju ke depan dan barisan yang di depan ke belakang, kemudian Nabi s.a.w. rukuk dan rukuk pula kamu semuanya, kemudian diangkatnya kepalanya dari rukuk dan kami angkat pula kepala kami semuanya, kemudian beliau turun hendak sujud dan barisan yang mengiringinya yang ada di belakang di rakaat yang pertama, maka berdiri pula barisan yang di belakang menghadapi musuh, maka tatkala Nabi s.a..w melakukan sujudnya bersama-sama dengan barisan yang mengiringinya, turun pula barisan yang di belakang untuk sujud lalu mereka sujud, kemudian Nabi s.a.w.…","r":"Muslim"}],"te":"Enemy in the Direction of the Qiblah"},{"t":"Musuh di Arah selain Kiblat","p":277,"v":1,"d":[{"y":"h","x":"Dari Abu Bakrah r.a. bahawasanya Nabi s.a.w. pernah mengerjakan sembahyang takut dengan orang-orang yang ada bersamanya dua rakaat dan dengan orang yang datang dua rakaat pula, maka sembahyang Nabi s.a.w. adalah empat rakaat dan bagi merekamereka yang datang dua rakaat pula.","r":"Abu Daud"},{"y":"h","x":"Dari Saleh bin Khawwat r.a. dari orang yang pernah sembahyang takut bersama dengan Nabi s.a.w. di hari peperangan di Zaturriqa'. Sesungguhnya satu bahagian dari sahabat-sahabat Nabi s.a.w. berbaris bersamanya dan satu bahagian lagi menghadapi musuh, lalu sembahyang Rasulullah dengan orang-orang yang bersamanya serakaat, kemudian beliau tetap berdiri, dan mereka menyempurnakan sembahyang mereka masing-masing, kemudian mereka berpaling, lalu berbaris menghadap musuh, dan datang pula bahagian yang lain, lalu sembahyang Rasulullah dengan mereka menyempurnakan rakaat berikutnya, kemudian Rasulullah tetap duduk, sedang mereka menyempurnakan sembahyang mereka masing-masing, kemudian Nabi memberi salam dengan mereka.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah aku berperang bersamasama dengan Rasulullah s.a.w. di sebelah Nijed, maka menghadaplah kami kepada musuh, kami jadikan mereka berbaris-baris, maka Rasulullah s.a.w. berdiri dengan kami, lalu berdiri satu kaum bersamanya dan satu kaum (barisan) menghadap kepada musuh, dan beliau rukuk dengan orang yang bersamanya hingga sampai serakaat sembahyang dan dia sujud dua kali sujud, kemudian mereka berpaling kepada tempat kaum yang belum sembahyang, maka datang mereka kemudian Rasulullah s.a.w. rukuk (sembahyang) dengan mereka serakaat dan sujud dua kali sujud, kemudian Rasulullah s.a.w. memberi salam, lalu tiap-tiap seorang berdiri lalu rukuk serakaat bagi masingmasing dan ia sujud dua kali.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a, bahawasanya Nabi s.a.w. pernah sembahyang khauf serakaat dengan salah satu di antara dua barisan sedang barisan lain menghadap musuh, kemudian mereka berpaling, lalu berdiri pada tempat teman-teman mereka (barisan penjaga musuh) dan datanglah mereka, kemudian Nabi s.a.w. sembahyang pula dengan mereka serakaat, lalu beliau memberi salam; kemudian mereka kerjakan serakaat lagi, dan yang lain serakaat lagi pula.","r":"Muslim"}],"te":"Enemy in Another Direction"},{"t":"Melepaskan Senjata dari Tangan ketika Ada Uzur","p":281,"v":1,"d":[{"y":"a","s":4,"a":102,"b":102,"m":"Dan tidak ada dosa atasmu meletakkan senjata-senjatamu jika kamu mendapat suatu kesusahan kerana hujan atau kerana kamu sedang sakit. Sea"}],"te":"Putting Down Weapons When There Is an Excuse"}],"p":273,"v":1,"d":[{"y":"a","s":4,"a":102,"b":102,"m":"Dan apabila engkau ada pada mereka, lalu engkau hendak mengerjakan sembahyang beserta mereka, maka hendaklah berjaga sebahagian di antara mereka bersama-sama dengan engkau dan hendaklah mereka ada di belakang kamu, kemudian datang pula golongan yang lain yang belum sembahyang hendaklah mereka sembahyang bersama-sama dengan engkau dan yang lain mengambil penjagaan dan memegang senjata mereka"}],"te":"Prayer in Times of Fear"},{"t":"Sembahyang Tatawwuk","c":[{"t":"Erti Sembahyang Tatawwuk","p":281,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia bekata: Telah bersabda Rasulullah s.a.w. Sesungguhnya manusia yang mula-mula dihitung amalannya di hari kiamat, ialah sembahyangnya, jika baik sembahyangnya, maka menanglah dia dan selamatlah dari seksaan Tuhan, dan bila rosak sembahyangnya, sungguh rugilah dia. Maka apabila kurang sesuatu dari sembahyangnya yang fardu, berkatalah Tuhan Azza Wajalla: Lihatlah, apakah bagi hamba-Ku itu ada ibadat tambahan (ibadat yang sunat), sekiranya ada maka dengan itu boleh menyempurnakan kekurangan-kekurangan pada fardu itu, kemudian dilakukan semua amalnya atas jalan yang begitu.","r":"Tirmizi"}],"te":"Meaning of Voluntary Prayer"},{"t":"Pembahagian Sembahyang Sunat","p":281,"v":1,"te":"Categories of Sunnah Prayer"},{"t":"Sembahyang Sunat selain Sunat Rawatib","p":283,"v":1,"te":"Sunnah Prayers Other Than Rawatib"}],"p":281,"v":1,"te":"Voluntary Prayer (Tatawwuk)"},{"t":"Sembahyang Dua Hari Raya","c":[{"t":"Tempat Menunaikan Dua Sembahyang Hari Raya","p":284,"v":1,"d":[{"y":"h","x":"Dari Abu Said Al-Khudri r.a. bahawasanya Nabi s.a.w. telah keluar pada hari raya Fitri dan Adha ke tempat sembahyang, iaitu ke tanah lapang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Pernah turun hujan pada suatu hari raya, maka Rasulullah s.a.w. sembahyang dengan kami di dalam masjid.","r":"Abu Daud dan Hakim"},{"y":"h","x":"Dari Jabir bin Samurah r.a. ia berkata: Aku telah menghadiri sembahyang dua hari raya bersama Nabi s.a.w bukan sekali dua kali dengan tidak menyerukan azan dan tidak pula iqamat.'","r":"Muslim"},{"y":"h","x":"Dari Az-Zuhrir.a. ia berkata: Adalah Nabi s.a.w. memerintahkan muazzin pada dua hari raya, maka ia mengatakan; aa at ertinya: Marilah sembahyang bersama-sama.","r":"Syafii"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Adalah Rasulullah s.a.w. dan Abu Bakar dan Umar melakukan sembahyang hari raya sebelum membaca khutbah.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Nabi s.a.w. telah mengerjakan sembahyang hari raya dua rakaat, beliau tidak sembahyang sebelum itu dan tidak pula sesudahnya.","r":"Bukhari dan Muslim"}],"te":"Where to Perform the Two Eid Prayers"},{"t":"Sunat-Sunat pada Dua Sembahyang Hari Raya","p":287,"v":1,"d":[{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya r.a. ia berkata: Bersabda Nabi Allah s.a.w.: Takbir dalam sembahyang hari raya fitri tujuh kali di rakaat pertama dan lima kali di rakaat kedua dan bacaan sesudah tiap-tiap keduanya.","r":"Abu Daud"},{"y":"h","x":"Dari Nu'man bin Basyir r.a. ia berkata: Adalah Rasulullah s.a.w. pada dua hari raya dan pada Jumaat, membaca Surah Al-A'la dan Surah Al-Ghasyiah. Dan Apabila berkumpul hari raya dan hari Jumaat pada suatu hari, dibacanya keduanya dalam masing-masing sembahyang itu.'","r":"Muslim"},{"y":"h","x":"Dari Ubaidillah r.a. ia berkata: Menurut sunah supaya khutbah dimulai dengan sembilan takbir berturut-turut dan khutbah yang kedua dengan tujuh takbir berturut-turut.","r":"Baihaqi"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Nabi s.a.w. mandi pada hari Arafah, pada hari raya Fitri dan pada hari raya Nahar (Adha).","r":"Ibnu Majah Al-Bazzar"},{"y":"h","x":"Dari Abdullah r.a. bahawasanya Rasulullah s.a.w. telah keluar pada dua hari raya bersama Fadhal iaitu Ibnu Abbas, Abdullah bin Abbas, Ali, Jaafar, Hasan, Husain, Usamah bin Zaid, Yazid bin Harisah dan Aiman bin Ummi Aiman, dengan meninggikan (mengeraskan) suaranya membaca tahlil dan takbir, dan diambilnya jalan Jaddad (tukang-tukang mengambil buah korma) hingga sampai ia ke tempat sembahyang.","r":"Baihaqi"},{"y":"h","x":"Dari Hasan bin Ali r.a. ia berkata: Kami telah diperintah oleh Rasulullah s.a.w. pada dua hari raya, supaya kami memakai pakaian yang sebaik-baiknya yang kami peroleh, dan supaya kami berharum-haruman dengan harum-haruman yang sebaik-baiknya yang kami peroleh dan supaya kami berkorban dengan segemuk-gemuknya binatang yang kami peroleh.","r":"Ibnu Hibban dan Hakim"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Rasulullah s.a.w. pernah mengambil jalan keluar (untuk pergi) berhari raya di sesuatu jalan, kemudian beliau kembali di jalan yang lain.","r":"Abu Daud"},{"y":"a","s":2,"a":185,"b":185,"m":"Hendaklah kamu sempurnakan bilangan puasamu, dan hendaklah kamu memuliakan Allah atas petunjukpetunjuk yang telah diberikan-Nya kepada kamu"},{"y":"h","x":"Dari Jabir r.a. bahawasanya Nabi s.a.w. pernah membaca takbir sesudah sembahyang Subuh pada hari Arafah, dan dilanjutkannya takbir itu hingga waktu Asar di akhir hari Tasyrik.","r":"Baihaqi"},{"y":"h","x":"Dari Buraidah r.a. ia berkata: Adalah Nabi s.a.w. tidak keluar di hari raya Fitri, hingga beliau makan lebih dahulu, dan pada hari raya Nahar (korban) beliau tidak makan sebelum kembali dari sembah-yang, lalu dimakannya daging korbannya.","r":"Ahmad dan Tirmizi"}],"te":"Sunnah Acts of the Two Eid Prayers"},{"t":"Kalimat-Kalimat Takbir pada Dua Sembahyang Hari Raya","p":292,"v":1,"d":[{"y":"h","x":"Allah Maha besar, sungguh sempurna besar. Segala puji bagi Allah, sungguh banyak sekali. Amat suci Allah pagi dan petang. Tidak ada tuhan melainkan Allah. Tak lain yang kami sembah melainkan Dia, kami sucikan agama itu kerana-Nya; sekalipun dibenci oleh orang-orang kafir. Tidak ada tuhan melainkan Allah, Allah menepati janji-Nya, menolong hamba-Nya dan telah memburu kaum sekutu musyrikin dengan sendiri-Nya. Tidak ada tuhan melainkan Allah dan Allah Maha Besar.","r":"Muslim"}],"te":"Words of the Takbir for the Two Eids"}],"p":283,"v":1,"d":[{"y":"a","s":2,"a":185,"b":185,"m":"Dan hendaklah kamu sempurnakan bilangan hari puasamu dan hendaklah kamu besarkan (muliakan) Allah atas sekalian yang telah ditunjuki-Nya, mudah-mudahan kamu berterima kasih"},{"y":"h","x":"Dari Ummu Atiyah r.a. ia berkata: Pernah kami disuruh Rasulullah s.a.w. di hariraya Fitri dan hari raya Adha supaya mengeluarkan perempuan-perempuan gadis, perempuan-perempuan haid dan perempuan-perempuan yang bertuiup muka, akan tetapi perempuan-perempuan haid hendaklah mereka menjauhi sembahyang, dan mereka boleh mendengar kebaikan (khutbah dan nasihatnasihat) dan panggilan kaum Muslimin.'","r":"Bukhari dan Muslim"}],"te":"The Two Eid Prayers"},{"t":"Sembahyang Minta Hujan","c":[{"t":"Cara-Cara yang Dilakukan untuk Minta Hujan","p":293,"v":1,"d":[{"y":"h","x":"Dari Ubadah bin Tamim r.a. bahawasanya Rasulullah s.a.w. pernah keluar dengan manusia berdoa meminta hujan, maka beliau mengerjakan sembahyang dua rakaat dengan mereka, pada keduanya dijaharkan pembacaannya dan diangkat kedua tangannya seten-tang bidang bahunya, dan diputar kain serbannya lalu menghadap ke kiblat sambil meminta hujan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. bahawasanya pernah masuk seorang laki-laki ke dalam masjid pada hari Jumaat sedang Rasulullah s.a.w. tegak berkhutbah, maka laki-laki itu mengadap Rasulullah s.a.w. sambil berdiri, kemudian berkata: Ya Rasulullah! Telah banyak harta benda yang rosak, dan jalan telah putus, maka berdoalah kepada Allah, supaya menurunkan hujan kepada kita. Berkata Anas: Maka Rasulullah s.a.w. mengangkat kedua tangannya kemudian berdoa: Ya Allah! Turunka lah hujan kepada kami.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Lahm r.a. Bahawasanya ia pernah melihat Rasulullah s.a.w. di dekat Hajar Zait (satu tempat di Madinah) supaya hujan turun, sambil beliau mengangkat kedua belah telapak tangannya sambil berdoa.","r":"Tirmizi dan Abu Daud"}],"te":"What Is Done to Ask for Rain"},{"t":"Keluar Bersama Anak-Anak Orang Tua dan Binatang Ternak ke Tanah Lapang","p":295,"v":1,"d":[{"y":"h","x":"Dari Ibnu Saad bin Abi Waqas r.a. ia berkata: Telah bersabda Nabi s.a.w.: Kamu tak dapat diberi pertolongan dan kamu belum diberi rezeki melainkan bersama-sama dengan kamu yang lemah daripada kamu.","r":"Bukhari"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Nabi s.a.w.: Kalau tidaklah ada orang tua yang telah bongkok dan anak-anak bayi yang masih menetek, dan binatang-binatang ternak yang memamah biak, nescaya akan diturunkan kepadamu seksaan dengan sempurna.","r":"Al-Bazzar dan Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Nabi s.a.w.: Pernah Nabi Sulaiman keluar memiria hujan, lalu dilihatnya seekor semut menelentang (di atas belakangnya) mengangkatkan kakitangannya ke langit sambil berdoa: Ya Allah kami adalah sebangsa makhluk dari makhluk Engkau, tidaklah cukup untuk kami pengairan Engkau. Maka berkata Nabi Sulaiman: Kembalilah kamu ke lubangmu, sungguhnya kamu akan diberi air kerana doa temanmu yang lain.","r":"Hakim dan Ahmad"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Rasulullah s.a.w. pernah keluar dengan pakaian biasa tunduk dan berhina diri, hingga sampai ke tanah lapang (tempat sembahyang).","r":"Tirmizi"}],"te":"Going Out to Open Ground with Children, the Elderly and Livestock"},{"t":"Khutbah Sembahyang Istisqak","p":297,"v":1,"te":"Sermon of the Rain Prayer (Istisqak)"},{"t":"Membalikkan Serban atau Songkok","p":298,"v":1,"d":[{"y":"h","x":"Dari Abdullah bin Zaid, bahawasanya Rasulullah s.a.w. pernah keluar ke tanah lapang meminta hujan, lalu beliau menghadap ke kiblat sambil berdoa dan memutar kain serbannya, dan meletakkan yang kanan di sebelah kiri dan yang kiri ke sebelah kanan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdullah bin Zaid bahawa Rasulullah s.a.w. ketika meminta hujan beliau berpaling ke arah kiblat dan memutar kain serbannya dan dibalikkan yang luar ke dalam, dan orang ramai pun turut memutar pula bersama beliau.","r":"Imam Ahmad bin Hambal"}],"te":"Turning the Turban or Cap Around"},{"t":"Doa Istisqak (Minta Hujan)","p":299,"v":1,"te":"Supplication for Rain (Istisqak)"},{"t":"Membalikkan Dua Telapak Tangan","p":300,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. bahawasanya Nabi s.a.w. pernah beristisqak, lalu diisyaratkan belakang tangannya ke langit.","r":"Muslim"}],"te":"Turning the Palms Over"}],"p":293,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Pernah manusia mengadu kepada Rasulullah s.a.w. tentang keputusan hujan, maka Rasulullah memerintahkan mengambil mimbar (sebagai tempatnya), maka diletakkanlah baginya mimbar itu di tanah lapang dan dijanjikannya kepada manusia pada suatu hari supaya mereka keluar kepadanya.","r":"Abu Daud"}],"te":"Prayer for Rain"},{"t":"Sembahyang Gerhana","c":[{"t":"Erti Gerhana","p":300,"v":1,"te":"Meaning of Eclipse"},{"t":"Cara Mengerjakan Sembahyang Gerhana","p":301,"v":1,"d":[{"y":"h","x":"Dari Mughirah bin Syu'bah r.a. ia berkata: Rasulullah s.a.w. telah bersabda: Sesungguhnya matahari dan bulan keduanya adalah tanda dari tanda-tanda kebesaran Allah, tidaklah terjadi gerhana, kerana matinya seseorang dan tidak pula kerana hidupnya (lahirnya), apabila kamu telah melihatnya, maka berdoalah kepada Allah dan sembahyanglah kamu hingga ia terang kembali.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Bakrah r.a. bahawasanya Nabi s.a.w. pernah sembahyang dua rakaat, seperti sembahyang kamu ini dan beliau sebutkan gerhana matahari.","r":"Nasai"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Pernah terjadi gerhana matahari semasa Rasulullah s.a.w. lalu beliau disuruhnya seseorang supaya menyerukan il","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah terjadi gerhana matahari semasa Rasulullah s.a.w. lalu beliau sembahyang, maka beliau berdiri agak lama, selama membaca surah Al-Baqarah, kemudian beliau rukuk, rukuk yang agak lama pula, kemudian beliau bangkit berdiri kembali, berdiri yang agak lama pula, tetapi tidak selama berdiri yang mula-mula, kemudian beliau rukuk, rukuk yang agak lama juga tetapi tidak selama rukuk yang mula-mula; kemudian beliau sujud, kemudian beliau berdiri, berdiri yang agak lama, tetapi tidak selama rukuk yang pertama; kemudian beliau bangkit lalu berdiri, berdiri agak lama; tetapi tidak pula selama berdiri yang pertama, kemudian beliau rukuk, rukuk yang agak lama juga, tetapi tidak selama rukuk yang mula-mula; kemudian diangkatnya kepalanya kemudian beliau sujud lalu berpaling, dan sesungguhnya matahari telah kelihatan kembali; lalu Nabi berkhutbah kepada yang hadir.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah terjadi gerhana matahari di zaman Rasulullah s.a.w. lalu beliau sembahyang enam kali rukuk (dalam dua rakaat) dengan empat kali sujud.","r":"Bukhari dan Muslim"}],"te":"How to Perform the Eclipse Prayer"},{"t":"Macam-Macam Cara Mengerjakan Sembahyang Gerhana","p":303,"v":1,"te":"Ways of Performing the Eclipse Prayer"},{"t":"Menjaharkan dalam Sembahyang Gerhana Bulan","p":304,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a ia berkata: Nabi s.a.w. telah menjahar pembacaannya dalam sembahyang gerhana bulan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Samurah r.a. ia berkata: Pernah sembahyang dengan kami Nabi s.a.w. dalam gerhana matahari yang kami tak mendengar suara beliau.","r":"Abu Daud dan Tirmizi"}],"te":"Reciting Aloud in the Lunar Eclipse Prayer"},{"t":"Khutbah sesudah Sembahyang Gerhana","p":305,"v":1,"d":[{"y":"h","x":"Dari Asma' binti Abu Bakar r.a. dalam perkara sembahyang gerhana matahari ia berkata: Maka berpaling Rasulullah s.a.w. dan sungguh matahari telah terang kembali, lalu beliau berkhutbah, beliau pun memuji Allah, menurut aturan-aturan khutbah khusuf itu, kemudian beliau berkata: Addpun kemudian..........","r":"Bukhari dan Muslim"}],"te":"Sermon After the Eclipse Prayer"}],"p":300,"v":1,"te":"Eclipse Prayer"},{"t":"Sembahyang Tarawih","c":[{"t":"Erti Sembahyang Tarawih dan Keutamaannya","p":306,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda: Sesiapa yang mendirikan ibadat dengan beriman dan dengan perhitungan di bulan Ramadan, diampuni Allah dosanya yang telah terdahulu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Zarr r.a. ia berkata: Pernah kami berpuasa bersama Nabi s.a.w., tetapi beliau tidak mendirikan sesuatu apa dengan kami di bulan itu, hingga tinggal lagi tujuh malam. Lalu beliau berdiri (menghidupkan malam Ramadan) dengan kami, hingga lewat sepertiga malam. Maka tatkala ada tinggal malam keenam, beliau tidak berdiri lagi dengan kami. Maka tatkala ada malam kelima (tinggal lima malam lagi), beliau berdiri dengan kami, hingga lewat setengah malam. Lalu aku berkata: Ya, Rasulullah alangkah baiknya, kalau kita penuhi saja malam ini dengan cara berbuat yang sunat-sunat. Lalu beliau bersabda: Sesungguhnya seorang laki-laki, bila ia telah sembahyang bersama Imam, hingga ia berpaling, dihitungkan baginya menghidupkan malam. Ia berkata: Maka tatkala ada malam keempat (empat malam yang tinggal), beliau tidak berdiri lagi dengan kami. Waktu ada malam ketiga (tiga malam yang tinggal), beliau kumpulkan keluarganya dan isterinya dan orang-orang lainnya, lalu beliau berdiri dengan kami, hingga kami khuatir, bahawa falah'' akan luput dari kami. Aku bertanya: Apakah falah itu? Ia menjawab: Makan sahur. Kemudian beliau tidak berdiri lagi dengan kami pada penghabisan bulan.","r":"As-Habussunan"},{"y":"h","x":"Dari Arfajah As-Saqfi r.a. ia berkata:, Pernah Ali bin Abu Talib menyuruh mereka mengerjakan sembahyang tarawih di bulan Ramadan dan diangkatnya bagi kaum laki-laki seorang imam dan untuk kaum perempuan akulah yang menjadi imamnya.","r":"Baihaqi"}],"te":"Meaning and Virtue of Tarawih"},{"t":"Bilangan Rakaat Sembahyang Tarawih","p":307,"v":1,"te":"Number of Rakaat in Tarawih"},{"t":"Dalil-Dalil untuk Menetapkan Jumlah Rakaat Sembahyang Tarawih","p":309,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Tidaklah ada Rasulullah s.a.w. menambahi sembahyang di dalam bulan Ramadan dan tidak pula di lainnya atas sebelas rakaat, yang dikerjakannya sembahyang itu empat rakaat, maka janganlah engkau tanya tentang bagus dan panjangnya sembahyang itu, kemudian dikerjakannya pula empat rakaat, maka janganlah engkau tanya tentang bagus dan panjangnya sembahyang itu, kemudian beliau kerjakan pula tiga rakaat, lalu aku bertanya: Ya Rasulullah, apakah engkau tidur sebelum engkau witir? Nabi menjawab: Ya Aisyah, sesungguhnya dua mataku tertidur tetapi hatiku tidak tidur.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Saib bin Yazid As-Sahabi r.a. ia berkata: Pernah mereka mendirikan ibadat pada malam bulan Ramadhan di zaman Umar bin Khattab r.a. dengan sembahyang dua puluh rakaat.","r":"Baihaqi"},{"y":"h","x":"Dari Yazid bin Rauman r.a. ia berkata: Pernah manusia mendirikan ibadat di bulan Ramadan di zaman Umar bin Khattab r.a. dengan sembahyang dua puluh tiga rakaat.","r":"Malik dalam kitab Al-Muwattak"}],"te":"Evidence for the Number of Tarawih Rakaat"}],"p":306,"v":1,"te":"Tarawih Prayer"},{"t":"Sembahyang Sunat Rawatib","c":[{"t":"Sunat Zuhur","p":311,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah aku sembahyang beserta Rasulullah s.a.w. dua rakaat sebelum Zuhur dan dua rakaat sesudahnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ummi Habibah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Siapa-siapa yang memelihara sembahyang empat rakaat sebelum Zuhur dan empat rakaat sesudahnya, maka ia diharamkan Allah dari neraka.","r":"Abu Daud dan Tirmizi"}],"te":"Sunnah of Zuhur"},{"t":"Sunat Asar","p":311,"v":1,"d":[{"y":"h","x":"Dari Ali bin Abu Talibr.a. bahawasanya Nabi s.a.w. telah sembahyang sebelum Asar dua rakaat. Ta Kata 3g yi ols,","r":"Abu Daud"},{"y":"h","x":"Dari Aisyahr.a. ia berkata: Adalah Rasulullah s.a.w. mengerjakan sembahyang Maghrib dengan manusia, kemudian beliau masuk ke rumahku, lalu sembahyang pula dua rakaat.","r":"Muslim"},{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah kami sembahyang di masa Rasulullah s.a.w. dua rakaat sesudah terbenam matahari, iaitu sebelum mengerjakan sembahyang Maghrib, lalu ditanya orang, apa pula Rasulullah s.a.w. mengerjakan sembahyang itu, ia menjawab: Ada beliau melihat kami mengerjakan sembahyang itu, maka tidaklah diperintahnya kami dan tidak pula dilarangnya.","r":"Muslim"}],"te":"Sunnah of Asar"},{"t":"Sunat Isyak","p":313,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah aku sembahyang berserta Rasulullah s.a.w. dua rakaat sebelum Zuhur, dan dua rakaat sesudahnya, dan dua rakaat sesudah Jumaat, dan dua rakaat sesudah Maghrib, dan dua rakaat sesudah Isyak.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdillah bin Mughaffal r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Antara tiap-tiap dua azan ada sembahyang, antara tiap-tiap dua azan ada sembahyang, antara tiap-tiap dua azan ada sembahyang. Dan ia berkata pada yang ketiga: Bagi siapa yang menghendakinya.","r":"Bukhari dan Muslim"}],"te":"Sunnah of Isyak"},{"t":"Sunat Subuh","p":314,"v":1,"d":[{"y":"h","x":"Dari Aisyahr.a. dari Nabi s.a.w. beliau bersabda: Dua rakaat fajar itu lebih baik dari dunia dan segala yang ada di dalamnya.","r":"Muslim"},{"y":"h","x":"Dari Aisyah r.a. bahawa Rasulullah s.a.w. telah sembahyang dua rakaat yang pendek antara azan dan iqamat sembahyang Subuh.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah membaca pada kedua rakaat fajar y, ASI! Lol LB dan al dl ya P.","r":"Muslim"}],"te":"Sunnah of Subuh"}],"p":309,"v":1,"te":"Regular Sunnah Prayers (Rawatib)"},{"t":"Sembahyang Sunat selain Rawatib","c":[{"t":"Sunat Witir","p":315,"v":1,"d":[{"y":"h","x":"Dari Ali r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesungguhnya Allah itu witir (ganjil) Ia sukakan perkara yang witir (yang ganjil); oleh sebab itu, witirlah kamu, hai ahli Al-Quran.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. bahawasanya Nabi s.a.w. bersabda: Witirlah kamu sebelum datang waktu Subuh.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. Nabi s.a.w. beliau bersabda: Jadikanlah sembahyang witir penutup (akhir) sembahyangmu di waktu malam.","r":"Muslim"}],"te":"Witr Prayer"},{"t":"Sekurang-Kurang dan Sebanyakbanyaknya Witir","p":317,"v":1,"d":[{"y":"h","x":"Dari Abu Ayub Al-Ansari r.a. bahawasanya Nabi s.a.w. pernah bersabda: Sembahyang witir itu adalah hak di atas tiap-tiap orang Islam dan bukan wajib, maka sesiapa yang suka mengerjakan witir dengan lima rakaat maka hendaklah diperbuatnya, dan sesiapa yang menghendaki tiga, maka hendaklah diperbuatnya, maka sesiapa yang menghendaki serakaat, maka hendaklah diperbuatnya.","r":"Abu Daud"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Rasulullah s.a.w. sembahyang malam tiga belas rakaat dan dilakukannya witir dalam yang demikian itu lima rakaat, beliau sama sekali tidak duduk, melainkan pada akhir saja.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Sembahyang malam itu ialah dua-dua, maka jika engkau khuatir tentang adanya waktu Subuh, maka witirlah serakaat saja.","r":"Bukhari"},{"y":"h","x":"Dari Aisyah r.a. bahawasanya Rasulullah s.a.w. tidak memberi salam pada dua rakaat witir.","r":"Nasai dan Baihaqi"}],"te":"The Fewest and the Most Rakaat of Witr"},{"t":"Sembahyang Witir tidak boleh Diserupakan dengan Sembahyang Maghrib","p":318,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Nabi s.a.w. pernah bersabda: Perihal sembahyang witir: Janganlah kamu serupakan sembahyang itu dengan sembahyang Maghrib.","r":"Daruqutni"}],"te":"Witr Must Not Be Made to Resemble Maghrib"},{"t":"Surah yang Dibaca dalam Sembahyang Witir","p":319,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. bahawasanya Nabi s.a.w. a; beliau dalam sembahyang witir membaca Kp Da ce pada rakaat yang pertama dan os SS IL p pada rakaat yang kedua dan ll ya dan surah Muawwizatain, iaitu Surah Al-Alaq dan Surah An-Nas pada rakaat yang ketiga.","r":"Abu Daud dan Tirmizi"}],"te":"Surahs Recited in Witr"},{"t":"Sembahyang Malam","p":320,"v":1,"d":[{"y":"a","s":17,"a":79,"b":79,"m":"Pada malam hari, hendaklah engkau sembahyang tahajud sebagai tambahan bagi engkau, mudah-mudahan Tuhan mengangkat engkau ke tempat yang dipuji. Aa"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Nabi s.a.w. telah bersabda: “Bila seseorang telah bangun di waktu malam, maka hendaklah ia mulai sembahyang dua rakaat.” :","r":"Muslim"},{"y":"h","x":"Dari Aisyah r.a. bahawasanya Nabi s.a.w beliau sembahyang di waktu malam sebelas rakaat, dan diwitirkan padanya satu rakaat. rakaat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah aku dengar Rasulullah s.a.w. bersabda: “Sesungguhnya pada waktu malam itu ada satu saat yang tidak bertepatan permintaan seorang Islam kepada Allah Taala tentang kebaikan di dunia dan di akhirat, melainkan diberi Allah apa yang dimintanya itu dan saat yang seperti itu ada pada tiap-tiap malam.” AN P I—","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. bersabda: Turun Tuhan kami Tabaraka Watala pada tiap-tiap malam ketika tinggal sepertiga malam yang akhir, Dia berfirman: Sesiapa berdoa akan Aku maka aku perkenankan doanya, sesiapa yang meminta kepada-Ku, Aku perkenankan permintaannya, sesiapa meminta ampun kepada-Ku, Aku ampuni dia.","r":"Bukhari dan Muslim"}],"te":"Night Prayer"},{"t":"Sunat Qabliyah dan Bakdiyah Jumaat","p":321,"v":1,"d":[{"y":"h","x":"Dari Abdillah bin Mas'ud r.a. bahawasanya ia telah sembahyang empat rakaat sebelum Jumaat dan empat rakaat pula sesudahnya.","r":"Abdul Razak dan Tabarani"},{"y":"h","x":"Dari Abdullah bin Zubair r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tidaklah dilakukan sembahyang yang wajib, melainkan antaranya ada sembahyang dua rakaat.","r":"Ibnu Hibban dan Tabarani"},{"y":"h","x":"Dari Abu Hurairah r.a. Dari Nabi s.a.w. bersabda: Sesiapa yang mandi di hari Jumaat, kemudian ia datang ke Jumaat, lalu ia kerjakan sembahyang menurut sekuasanya, kemudian ia diam hingga selesai imam deri Khutbahnya, kemudian ia sembahyang bersama imam, diampuni dosanya, dosa di antaranya dan antara Jumaat yang akan datang, dan ditambah tiga hari.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. Bahawasanya ia selalu memanjangkan sembahyang sebelum mengerjakan sembahyang Jumaat dan ia kerjakan dua rakaat sesudah Jumaat dan ia bercerita: Bahawa Rasulullah s.a.w. selalu memperbuat yang demikian.","r":"Abu Daud"}],"te":"Sunnah Before and After Friday Prayer"},{"t":"Sunat Tahiyat Masjid","p":324,"v":1,"d":[{"y":"h","x":"Dari Abu Qatadah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Bila seseorang masuk ke dalam masjid, maka janganlah ia duduk, sebelum ia sembahyang lebih dahulu dua rakaat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah datang Sulaik Al-Ghuthfani (seorang sahabat Nabi) di hari Jumaat, sedang Nabi s.a.w. berkhutbah, maka duduklah Sulaik, lalu bersabda: Rasulullah s.a.w. kepadanya: Hai Sulaik, bangunlah engkau kembali, lalu sembahyanglah dua rakaat dan 'pendekkanlah pembacaan pada keduanya, kemudian Rasulullah s.a.w. bersabda: Bila kamu datang pada hari Jumaat sedang imam berkhutbah, maka hendaklah kamu sembahyang dua rakaat.","r":"Bukhari dan Muslim"}],"te":"Greeting the Mosque (Tahiyyatul Masjid)"},{"t":"Sunat sesudah Berwuduk","p":325,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda kepada Bilal: *Ceritakanlah kepadaku amalan yang telah engkau kerjakan yang lebih engkau harap cepat terkabul di dalam Islam, kerana sesungguhnya aku telah mendengar bunyi dua selipar engkau di hadapanku di dalam syurga.' Ia menjawab: Saya tidak pernah mengerjakan suatu amalan yang lebih saya harapkan cepat terkabul, yakni sesungguhnya saya tidak pernah bersudi sekalipun baik di waktu malam mahupun di waktu siang hari, melainkan aku sembahyang dengan wuduk itu, menurut apa yang sudah ditentukan bagiku agar aku mengerjakan sembahyang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Seorang kekasihku: Nabi s.a.w. berpesan kepadaku supaya berpuasa tiga hari tiap-tiap bulan, dan sembahyang dua rakaat Duha dan supaya aku witir sebelum aku tidur.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ummu Hanik binti Abu Talib r.a. bahawasanya Nabi s.a.w. pernah mengerjakan sembahyang Duha sebanyak lapan rakaat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Zaid bin Arqam r.a. bahawasanya Rasulullah s.a.w. pernah bersabda: Sembahyang Awwabin (Duha) itu ialah ketika telah hangat cahaya matahari.","r":"Muslim"}],"te":"Sunnah After Wudhu"},{"t":"Sunat Istikharah","p":327,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Bila seseorangmu bercita-cita hendak mengerjakan suatu pekerjaan, maka hendaklah ia sembahyang dua rakaat, bukan sembahyang fardu.","r":"Bukhari"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Bila seseorangmu bercita-cita hendak mengerjakan suatu pekerjaan, maka hendaklah ia sembahyang dua rakaat, bukan sembahyang fardu.” (Diriwayatkan oleh Bukhari). Dibaca surah Al-Kafirun pada rakaat pertama dan surah AlIkhlas pada rakaat kedua. Bila sembahyang telah selesai dikerjakan, maka hendaklah ia taubat kepada Tuhan, kemudian membaca doa di bawah ini: Da Aan D ba a D a, A pe Jd. D. DE 2 a e ee PERARAKAN PER a” 2. so Pp : dd aa aa ar Pa Pa - bi Ha. *| La “A Se 0g, “Ya Allah! Sesungguhnya aku meminta penjelasan kepada Engkau dengan ilmu Engkau, dan aku meminta ketentuan dengan kekuasaan Engkau, dan aku meminta kepada Engkau dari kurnia Engkau yang sangat agung, kerana sesungguhnya Engkaulah yang berkuasa menentukan dan bukan aku yang berkuasa, dan Engkaulah yang Maha Mengetahui, dan bukan aku yang mengetahui, dan Engkau yang Maha Mengetahui segala yang ghaib. Ya Allah! Jika Engkau tahu, bahawa pekerjaan ini baik bagiku, dalam agama ku dan dalam kehidupanku, dan pada akibat pekerjaanku, maka tentukanlah dia bagiku dan mudahkanlah dia bagiku, kemudian berilah aku berkat padanya, Ya Allah!! Dan jika Engkau mengetahui, bahawa pekerjaan ini buruk bagiku dalam agamaku, kehidupanku dan akibat pekerjaanku, maka…","r":"Bukhari"}],"te":"Istikharah Prayer"},{"t":"Sunat Hajat","p":329,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abi Aufa ia berkata: Bersabda Rasulullah s.a.w. : Siapa yang ada mempunyai hajat kepada Allah, atau kepada seseorang di antara anak Adam (manusia), maka hendaklah ia berwuduk, lalu disempurnakannya wuduknya itu. Kemudian hendaklah ia sembahyang dua rakaat; kemudian hendaklah ia menyanjung Allah Azza Wajalla, dan hendaklah ia berselawat kepada Nabi s.a.w.'","r":"Tirmizi dan Nasai"}],"te":"Prayer of Need (Hajat)"},{"t":"Sunat Taubat","p":329,"v":1,"d":[{"y":"h","x":"Tidak ada Tuhan melainkan Allah, yang Maha Penyantun lagi Maha Pemurah. Amat suci Allah, Tuhan Arasy yang maha besar. Puji-pujian bagi Allah, Tuhan yang menjadikan seluruh alam, Aku meminta kepada Engkau, Ya Allah akan sesuatu yang mewajibkan rahmat Engkau, dan segala harapan yang mendatangkan ampunan Engkau, (taufiq) dan keberuntungan tiap-tiap kebaikan dan keselamatan dari tiap-tiap dosa. Tidak Engkau biarkan dosa padaku, melainkan Engkau ampuni dan tidak pula suatu kepentingan, melainkan Engkau bukakan dan tidak pula sesuatu hajat yang Engkau sukai, melainkan Engkau kabulkan. Wahai Yang Paling Pengasih dan Yang Paling Penyayang.","r":"Tirmizi dari Ibni Abi Aufa"}],"te":"Prayer of Repentance (Taubat)"}],"p":315,"v":1,"te":"Sunnah Prayers Other Than Rawatib"}],"p":86,"v":1,"te":"Book of Prayer"},{"t":"Kitab Jenazah","c":[{"t":"Asas Jenazah","p":331,"v":1,"c":[{"t":"Erti Jenazah","p":331,"v":1,"te":"Meaning of Janazah"},{"t":"Memandikan Mayat","p":332,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia telah berkata: Telah bersabda Rasulullah s.a.w. perihal orang yang jatuh dari atas untanya: Mandikanlah dia dengan air dan dengan sidir (bidara).","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ummi Athiyah r.a. bahawasanya Nabi s.a.w. bersabda kepada orang-orang yang memandikan anak perempuannya yang meninggal: Mandikanlah dia, tiga, lima atau tujuh kali.","r":"Bukhari dan Muslim"}],"te":"Washing the Deceased"},{"t":"Cara Memandikan Mayat","p":333,"v":1,"d":[{"y":"h","x":"Dari Ummi Athiyah r.a. bahawasanya Rasulullah s.a.w. menyuruh memandikan anak perempuannya beliau bersabda: “Mulailah membasuh di sebelah badannya yang kanan dan tempat (anggota) wuduknya.” :","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ummu Athiyah r.a. ia berkata: Telah meninggal salah seorang anak perempuan Rasulullah s.a.w. lalu beliau datang kepada kami, dan bersabda: Mandikanlah ia dengan sidir menurut bilangan yang ganjil, hingga katanya: Dan jadikanlah di akhir mandinya itu air kafur atau sesuatu yang harum.","r":"Bukhari"}],"te":"How to Wash the Deceased"},{"t":"Mayat Orang yang Haram Disembahyangkan dan Dimandikan","p":335,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. bahawasanya Nabi s.a.w. telah menyuruh perihal orang-orang yang mati di padang Uhud, untuk menguburkan mereka dengan darah mereka dan tidak mereka dimandikan dan tidak pula mereka disembahyangkan.","r":"Bukhari"},{"y":"h","x":"Dari Jabir r.a. bahawasanya Nabi s.a.w. pernah bersabda tentang orang-orang yang mati di Uhud: Janganlah kamu mandikan mereka kerana sesungguhnya tiap-tiap luka itu atau tiap-tiap titis darah yang melumurinya itu, akan menjadi kesturi di hari kiamat dan tidak boleh pula disembahyangkan mereka.","r":"Imam Ahmad"},{"y":"a","s":9,"a":84,"b":84,"m":"Dan janganlah engkau sembahyangkan di atas salah seorang dari mereka (orang kafir itu) yang ia telah mati buat selamanya dan janganlah engkau berdiri di kuburnya. Sesungguhnya mereka kafir dengan Allah dan Rasul-Nya dan mereka mati sedang mereka orang yang fasik"}],"te":"The Deceased Who May Not Be Prayed Over or Washed"},{"t":"Pembahagian Syahid dan Soal Mati Membunuh Diri","p":337,"v":1,"d":[{"y":"h","x":"Dari Jabir bin Samurah r.a. ia berkata: Pernah didatangkan kepada Nabi s.a.w. seorang laki-laki yang mati membunuh diri dengan anak panahnya, maka tidak disembahyangkan oleh Rasulullah s.a.w.","r":"Muslim dan Abu Daud"}],"te":"Kinds of Martyrs, and the Question of Suicide"},{"t":"Mengafani Mayat","p":338,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. bahawasanya Rasulullah s.a.w. dikafani orang dengan tiga lapis kain putih. Sahul' dari kapas yang tidak masuk di dalamnya, baju dan tidak pula serban.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Bahawa Rasulullah s.a.w. bersabda: Pakailah di antara kainmu yang putih, sesungguhnya kain putih adalah sebaik-baik kain, dan kafanilah mayatmu dengan kain yang putih. :","r":"Abu Daud dan Tirmizi"}],"te":"Shrouding the Deceased"}],"te":"Basics of Funerals"},{"t":"Sembahyang Jenazah","c":[{"t":"Keutamaan Banyak Menyembahyangkan Jenazah","p":339,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah aku mendengar Rasullullah s.a.w. beliau bersabda: Tidaklah seorang laki-laki Islam yang meninggal berdiri menyembahyangkan jenazahnya itu empatpuluh orang yang betul-betul tidak mempersekutukan Allah, melainkan dijadikan Allah doa mereka jadi makbul padanya.","r":"Muslim"},{"y":"h","x":"Dari Malik bin Hubairah r.a. dari Nabi s.a.w. beliau bersabda: Tiadalah seseorang (mayat) yang meninggal dunia disembahyangkan oleh tiga saf kaum Muslimin, melainkan mestilah ia ditolong.","r":"Abu Daud dan Tirmizi"}],"te":"Virtue of Many People Praying over the Deceased"},{"t":"Cara-Cara Menyembahyangkan Jenazah","p":340,"v":1,"d":[{"y":"h","x":"Dari Talhah bin Abdullah bin Auf ia berkata: Pernah aku sembahyang jenazah di belakang Ibnu Abbas, lalu dibacanya Fatihah lalu ia berkata: Supaya kamu tahu sesungguhnya membaca Al-Fatihah itu sunah Nabi.","r":"Bukhari"},{"y":"h","x":"Dari Abu Amamah bin Sahal, bahawasanya seorang di antara sahabat-sahabat Nabi pernah bercerita kepadanya: Sesungguhnya sudah menjadi sunah pada sembahyang jenazah, mula-mula takbir imam kemudian sesudah takbir yang pertama dibacanya Al-Fatihah secara perlahan-lahan (untuk dirinya sendiri), kemudian diucapkannya selawat kepada Nabi s.a.w. dan diikhlaskannya membaca doa untuk jenazah di dalam takbir itu.","r":"Syafii"},{"y":"h","x":"Ya Allah! Ampunilah dosa mayat ini, kasihilah dia, peliharalah jiwanya, maafkanlah kesalahannya, muliakanlah tempatnya dan lapangkanlah kuburnya. Ya Allah! Ampunilah dosa orang-orang yang hidup di antara kami, dan yang mati kami, dan kanak-kanak kami, dan orang-orang tua kami, laki-laki kami serta kaum perempuan kami, dan orang-orang yang hadir di antara kami, dan orang-orang yang jauh di antara kami. Ya Allah! Orang-orang yang Engkau hidupkan di antara kami, maka hidupkanlah dia dalam Islam, dan orang-orang yang Engkau wafatkan di antara kami, maka wafatkanlah dia dalam beriman. Ya Allah! Janganlah Engkau larang kami menerima pahala kami, dan selanjutnya janganlah Engkau datangkan fitnah kepada kami.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Bila kamu menyembahyangkan mayat, maka ikhlaskanlah hatimu berdoa baginya.","r":"Abu Daud"},{"y":"a","s":59,"a":10,"b":10,"m":"Hai Tuhan kami ampunilah dosa-dosa kami dan segala dosa saudara kami, iaitu orang-orang yang telah lebih dahulu beriman daripada kami, dan janganlah Engkau masukkan dengki-khianat di hati kami terhadap orang-orang yang beriman. Hai Tuhan kami! Sesungguhnya Engkau Maha Pengasih lagi Maha Penyayang"},{"y":"h","x":"Dari Abdullah bin Abi Aufa r.a. sesungguhnya dia pernah menyembahyangkan jenazah salah seorang anak perempuannya, dengan empat takbir, maka ia berdiri sesudah takbir yang keempat kira-kira selama berdiri antara dua takbir, dimintakannya ampun untuk anaknya itu dan berdoa, kemudian ia berkata: Adalah Rasulullah s.a.w. mengerjakan seperti ini.","r":"Hakim"},{"y":"h","x":"Dari Abdullah bin Abi Aufa r.a. sesungguhnya dia pernah menyembahyangkan jenazah salah seorang anak perempuannya, dengan empat takbir, maka ia berdiri sesudah takbir yang keempat kira-kira selama berdiri antara dua takbir, dimintakannya ampun untuk anaknya itu dan berdoa, kemudian ia berkata: Adalah Rasulullah s.a.w. mengerjakan seperti ini. (Diriwayatkan oleh Hakim). Kalau anak-anak bayi yang meninggal, atau anak kecil maka doanya adalah: dah a Li a Son ole, Ya, Allah - Jadikanlah dia untuk kami sebagai orang yang tidak berdosa, sebagai orang yang dahulu dari kami yang bersih dan suci, dan berikan pahalanya untuk kami.","r":"Bukhari"}],"te":"How to Perform the Funeral Prayer"},{"t":"Mengangkat Dua Tangan dalam Takbir Sembahyang Jenazah","p":3,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah takbir di waktu sembahyang jenazah, lalu diangkatnya kedua belah tangannya di uwal takbir itu, dan diletakkannya tangan yang kanan di atas yang kiri.","r":"Tirmizi"}],"te":"Raising the Hands in the Takbirs of the Funeral Prayer"},{"t":"Sembahyang Ghaib","p":345,"v":1,"te":"Prayer in Absentia (Ghaib)"},{"t":"Menyembahyangkan Jenazah Bayi yang Mati Lahir","p":346,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. Dari Nabi s.a.w. beliau bersabda: Bayi yang lahir, tidak perlu disembahyangkan, ia tidak mempusakai dan tidak pula dipusakai, hingga ia bersuara menangis.","r":"Tirmizi"},{"y":"h","x":"Dari Al-Mughirah r.a. dari Nabi s.a.w. beliau bersabda: Orang yang berkenderaan berjalan di belakang jenazah, orang yang berjalan kaki, di mana saja ia kehendaki daripadanya, sedang bayi itu perlu disembahyangkan.","r":"As-habussunan"}],"te":"Funeral Prayer for a Stillborn Baby"},{"t":"Menyegerakan Urusan Jenazah","p":347,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. bersabda: Segerakanlah urusan jenazah, jika ia orang baik, maka itulah orang yang sebaikbaiknya yang kamu segerakan, dan jika ia bukan orang baik, maka itulah orang yang seburuk-buruknya yang kamu buangkan keburukannya dari pundak kamu, (iaitu memasukkannya ke dalam lahad).","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ali r.a. dari Nabi s.a.w. bersabda: Tiga perkara yang tak boleh engkau lambatkan, iaitu sembahyang bila telah tiba waktunya, jenazah bila telah terbujur dan janda bila telah ada jodohnya.","r":"Tirmizi"}],"te":"Hastening the Funeral"},{"t":"Jiwa Mayat Berteriak Waktu Dibawa ke Kubur","p":348,"v":1,"d":[{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia berkata: Nabi s.a.w. pernah bersabda: Bila telah diletakkan jenazah, lalu dipikul orang di atas bahunya, apabila ia seorang baik, beliau bersabda: Lekaskanlah aku! dan jika ia seorang tidak baik (banyak berdosa), berkata ia kepada keluarganya yang membawanya itu: Aduuh!! ke manakah akan kamu bawa jenazahku? Suara itu terdengar oleh segala yang bernyawa, kecuali manusia, andaikata terdengar olehnya, nescaya ia pengsan (kelengar) ketakutan.","r":"Bukhari"}],"te":"The Soul of the Deceased Cries Out on the Way to the Grave"},{"t":"Erti Menyegerakan Mengurus Jenazah","p":349,"v":1,"d":[{"y":"h","x":"Dari Hushain bin Wahawhin r.a. Bahawasanya Talhah bin Barrah bin Azib. r.a. sedang sakit, lalu datang Rasulullah s.a.w. menengoknya, Rasulullah s.a.w. bersabda (ketika si sakit telah meninggal): Sesungguhnya aku belum melihat Talhah ini, melainkan ketika akan mati ini saja, oleh sebab itu beritahulah mengurusnya;, kerana sesungguhnya tidaklah patut mayat orang Islam ditahan-tahan dalam lingkungan keluarganya.","r":"Abu Daud"}],"te":"Meaning of Hastening the Funeral"},{"t":"Mengiringkan Mayat ke Kuburan","p":349,"v":1,"d":[{"y":"h","x":"Dari Barra' bin Azibr.a. ia berkata: Kami diperintah oleh Rasulullah s.a.w. untuk menengok orang sakit, mengiring jenazah ke kubur, mendoakan orang yang bersin, memberikan sumpah, menolong orang teraniaya memuliakan (mendatangi) undangan dan membalas salam orang lain.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ummu Athiyah r.a. ia berkata: Kami dilarang oleh Nabi s.a.w. untuk mengiring jenazah ke kubur tetapi tidak diperkenalkan larangan itu.","r":"Bukhari dan Muslim"}],"te":"Following the Body to the Graveyard"},{"t":"Berdiri Melihat Mayat yang Sedang Diusung ke Kuburan","p":350,"v":1,"d":[{"y":"h","x":"Dari Amir bin Rabiah, dari Rasulullah s.a.w. beliau bersabda: Bila kamu melihat jenazah, maka berdirilah kamu menghormatinya hingga ia hilang dari pandanganmu, atau ia telah diletakkan ke dalam lahad. !","r":"Tirmizi"}],"te":"Standing When a Funeral Passes"}],"p":339,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. Bahawasanya ia pernah menyembahyangkan seorang laki-laki lalu ia berdiri di dekat kepalanya, dan pernah pula ia menyembahyangkan seorang mayat perempuan, maka ia berdiri di dekat bingku-bingkunya (pinggangnya).","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Samurah r.a. itu berkata: Pernah aku turut menyembahyangkan seorang perempuan yang mati dalam nifasnya (waktu ia bernifas) di belakang Nabi s.a.w. lalu beliau berdiri di dekat pertengahan badannya.","r":"Bukhari dan Muslim"}],"te":"Funeral Prayer"},{"t":"Tentang Kuburan","c":[{"t":"Menggali Kuburan","p":351,"v":1,"d":[{"y":"h","x":"Dari Hisyam bin Urwah r.a. ia berkata: Pernah datang kepada Rasulullah s.a.w. beberapa orang Ansar pada hari perang di Uhud, lalu mereka berkata: Telah sampai kepada kami musibah, iaitu kepayahan dan mati serta luka-luka, bagaimanakah perintah engkau kepada kami? Rasullulah s.a.w. menjawab: Galilah lubang (kubur), dan dalamkanlah dan lapangkanlah kemudian masukkanlah dua atau tiga orang laki-laki ke dalam kubur itu. Ditanya orang pula: Manakah di antara mereka yang akan didahulukan? Ia berkata: Mereka yang paling banyak menghafaz Al-Quran.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Saad bin Abi Waqas r.a. berpesan di waktu sakitnya yang membawa matinya: Buatkan lahad untukku dan dirikanlah batu mejun (nisan) di atas kuburku itu, sebagaimana yang diperbuat orang di kubur Rasulullah s.a.w.","r":"Muslim dan Tirmizi"},{"y":"h","x":"Dari Ashim bin Kalib bin Syihab, dari bapanya (katanya) bahawasanya Nabi s.a.w. bersabda kepada orang-orang yang menggali kuburan: Lapangkanlah di sebelah kepalanya dan (lapangkanlah) di sebelah kedua kakinya.","r":"Abu Daud"}],"te":"Digging the Grave"},{"t":"Membuat Lubang Lahad dan Menguburkan Mayat","p":352,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas dari Nabi s.a.w. beliau bersabda: Lahad itu untuk ' kita (orang Islam) dan lubang itu bukanlah untuk kita (bukan untuk orang Islam).","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Adalah Nabi s.a.w. bila beliau memasukkan mayat ke alam kubur, beliau bersabda: Dengan nama Allah dan atas sunah Rasulullah s.a.w.","r":"Tirmizi dan Ibnu Majah"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. bahawasanya Rasulullah s.a.w. bila beliau memasukkan mayat ke kubur, dibaringkannya mayat di lahad, di atas badannya yang kanan dan menghadap ke kiblat.","r":"Ibnu Majah"}],"te":"Making the Niche (Lahad) and Burying the Deceased"},{"t":"Berdiri untuk Memohonkan Keampunan bagi Mayat Setelah Dikuburkan","p":354,"v":1,"d":[{"y":"h","x":"Dari Usman bin Affan r.a. ia berkata: Adalah Ngbi s.a.w. bila beliau telah selesai menguburkan mayat, beliau berdiri sebentar dekat kubur itu, dan bersabda: Mintakanlah ampun (berdoa bagi) saudaramu ini, dan mohonkanlah kelapangan baginya di dalam kubur (supaya ia tetap di dalam kalimat tauhid), kerana sesungguhnya ia sekarang sedang ditanya.","r":"Abu Daud"}],"te":"Standing to Ask Forgiveness for the Deceased After Burial"},{"t":"Menyirami Kuburan dengan Air","p":355,"v":1,"d":[{"y":"h","x":"Dari Jabirr.a. ia berkata: Disiramkan air ke atas kubur Nabi s.a.w. sebasah-basahnya. Maka orang yang menyiramkan air ke atas kubur beliau ialah Bilal bin Rabah, ia memulakan dari kepalanya sebelah kanan hingga sampai kedua kakinya.","r":"Baihaqi"},{"y":"h","x":"Dari Jabirr.a. ia telah berkata: Rasulullah s.a.w. melarang menembok kuburan dan duduk di atasnya, atau dibuatkan rumah-rumahan,di atasnya.","r":"Muslim"}],"te":"Sprinkling Water on the Grave"},{"t":"Pertanyaan di dalam Kubur","p":355,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. ia telah berkata: Bersabda Rasulullah s.a.w. Sesungguhnya hamba (manusia) bila telah diletakkan di dalam kuburnya, dan kawan-kawannya yang menghantarkannya telah berbalik pulang, maka sesungguhnya ia mendengar pula bunyi derap kasut (telapak kaki) mereka, datanglah kepadanya dua orang malaikat, lalu keduanya duduk didekatnya. Keduanya lalu berkata kepadanya: Apakah yang pernah engkau katakan tentang laki-laki ini yang dimaksudkan ialah Nabi Muhammad s.a.w.). Adapun orang itu apabila ia seorang mukmin, maka ia akan menjawab: Aku bersaksi, bahawa ia adalah hamba Allah dan Rasul-Nya. Maka dikatakan kepadanya (kepada mayat itu). Menengoklah ke tempat engkau yang sedianya di neraka, sungguh telah diganti Allah untuk engkau tempat itu dengan syurga. Maka ia pun melihat keduanya semua. Dan adapun orang yang kafir dan munafik. maka dikatakan kepadanya: Apakah yang pernah engkau katakan pada orang ini. Ia pun berkata: Aku tidak tahu sama sekali. Pernah aku berkata' menurut yang dikatakan oleh orang-orang. Lalu dikatakan kepadanya: Engkau tidak tahu? Dan engkau tidak pernah membaca? Sambil dipukulkan kepadanya tongkat daripada besi satu kali pukul. Ia pun berteriak satu kali teriakan yang didengar oleh orang-orang yang sekitar (makhluk yang bernyawa) selain bangsa jin dan…","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Barrak r.a. ia telah berkata: Pernah Rasulullah s.a.w. bersabda: Bahawasanya orang mukmin bila ia telah ditanamkan di dalam kuburnya, dan kawan-kawan yang menghantarnya telah kembali, sedang ia mendengar derapan selipar mereka, datanglah kepadanya dua orang malaikat lalu kedua malaikat itu duduk di dekatnya, lantas bertanya: Siapakah tuhan engkau, lalu dijawabnya: Tuhanku ialah Allah. Keduanya bertanya lagi: Apakah Agama engkau. Dijawabnya: Agamaku ialah Islam. Keduanya bertanya lagi: Siapakah laki-laki ini yang telah diutus kepadamu. Lalu ia menjawab: Dia adalah Rasulullah. Lalu keduanya bertanya lagi. Di mana engkau tahu. Ia menjawab: Sebab aku membaca kitab Allah (Al-Quran), lalu aku percaya dengannya dan aku benarkan. Seterusnya hadis itu berbunyi hingga katanya: Dan sesungguhnya orang-orang kafir atau munafik, bila telah diletakkan di dalam kuburnya, dan rohnya telah kembali ke jasadnya datanglah kepadanya dua orang malaikat, lalu keduanya duduk di dekatnya, lalu bertanya: Siapakah Tuhan engkau. Dijawabnya: Haah -— haah, aku tak tahu. Keduanya bertanya lagi: Apakah Agama engkau. Ia menjawab: Haah —- haah -— aku tak tahu. Keduanya bertanya lagi: Siapakah yang telah diutus kepadamu. Ia menjawab: Haah - haah, aku tak tahu. Bersabda Rasulullah s.a.w.: Maka…","r":"Abu Daud"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. Bahawasanya Rasulullah s.a.w. telah bersabda: Sesungguhnya kubur itu merupakan satu taman dari taman Syurga, atau merupakan satu jurang dari jurang api neraka.","r":"Tirmizi"},{"y":"h","x":"Dari Usman bin Affan r.a. ia telah berkata: Telah bersabda Rasulullah s.a.w.: Sesungguhnya kuburan itu mula-mula tempat kampung akhirat. Maka jika seseorang lulus daripadanya, maka apa yang sesudahnya lebih mudah daripadanya. Dan jika seseorang tidak lulus daripadanya, maka apa yang sesudahnya lebih sulit daripadanya. Tidaklah aku pernah melihat satu pemandangan yang sangat mengerikan selain kuburan.","r":"Tirmizi"}],"te":"Questioning in the Grave"},{"t":"Hukum Haram Meratapi Mayat","p":359,"v":1,"d":[{"y":"h","x":"Dari Umar bin Khattab r.a. ia berkata: Telah bersabda Nabi s.a.w.: Mayat itu diseksa di dalam kuburnya kerana dia diratapi.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Bersabda Rasulullah s.a.w.: Bukanlah masuk umat kami, orang-orang yang memukul pipinya dan orang yang merobek baju di dada, serta berdendang-dendang dengan dendang jahiliah (meratap).","r":"Bukhari dan Muslim"},{"y":"a","s":35,"a":18,"b":18,"m":"TIDAKLAH DAPAT MEMIKUL ORANG YANG BERDOSA AKAN DOSA ORANG LAIN"},{"y":"a","s":8,"a":25,"b":25,"m":"DAN HATI-HATILAH KAMU TERHADAP BENCANA, YANG MANA BENCANA ITU TIDAK SAHAJA KHUSUS MENGENAI ORANG-ORANG YANG ZALIM PADA GOLONGANMU"},{"y":"h","x":"Dari Abu Malik Al-Asyari r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Perempuan-perempuan yang meratap itu, bila ia tidak taubat sebelum mati, di hari kiamat ia akan ditegakkan, sedang dipundaknya dipakaikan selendang dari api neraka dan baju besi dari karat-karat besi neraka.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Rasulullah s.a.w. bersabda: Tidaklah kamu dengar, bahawa Allah tidak menyeksa dengan titisan air mata dan tidak pula dengan kerisauan hati, akan tetapi ia menyeksa dengan ini, atau ia menyayangi, dan Nabi menunjuk lidahnya.","r":"Bukhari dan Muslim"}],"te":"Wailing over the Dead Is Forbidden"},{"t":"Menghibur Keluarga Si Mayat","p":362,"v":1,"d":[{"y":"h","x":"Dari Abdullah bin Ja'far bin Abu Talib ia berkata: Telah bersabda Nabi s.a.w.: Buatkanlah untuk keluarga Ja'afar makanan, maka sungguh telah datang kepada mereka urusan yang membimbangkan mereka.","r":"Abu Daud dan Tirmizi"}],"te":"Consoling the Family of the Deceased"},{"t":"Hukum Makruh Makan-Makan di Rumah Mayat","p":362,"v":1,"d":[{"y":"h","x":"Dari Jurair bin Abdullahr.a. ia berkata: Adalah kami beranggapan bahawa berkumpul (berpesta) pada keluarga mayat dan membuat makanan sesudah menguburkannya itu, sebahagian dari meratap.","r":"Ahmad dan Ibnu Majah"}],"te":"Feasting at the House of the Deceased Is Disliked"},{"t":"Membongkar Kuburan dan Memindahkan Mayat","p":363,"v":1,"d":[{"y":"h","x":"Dari Jabirr.a. ia berkata: Telah dikuburkan bersama-sama dengan bapaku seorang laki-laki, kemudian tidak senang hatiku, maka aku bongkarlah kubur itu, lalu aku pindahkan kedalam sebuah kubur yang tersendiri. M In","r":"Bukhari dan Nasai"},{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah datang Nabi s.a.w. ke Madinah, dan beliau diminta orang supaya membuat masjid, kemudian beliau bersabda: Ya Bani Najar! Juallah kepadaku pekaranganmu ini! Maka mereka menjawab: Tidak, demi Allah, kami tidak akan meminta harganya melainkan (kami serahkan) kepada Allah sematamata, maka diperintahkannya membongkar segala kuburan orang yang musyrik, kemudian ditimbuni segala lubang-lubang itu lalu diratakan.","r":"Bukhari dan Muslim"}],"te":"Opening a Grave and Moving the Body"},{"t":"Larangan Memecah Tulang Mayat","p":364,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Memecahmecah (mematah) tulang mayat, tak ubahnya seperti memecah (mematahnya) di waktu hidupnya.","r":"Abu Daud dan Ibnu Majah"}],"te":"Breaking the Bones of the Dead Is Forbidden"},{"t":"Anak Dagang yang Mati di Rantau dan Soal Memuji Mayat","p":365,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesungguhnya laki-laki itu, bila ia mati di luar tanah kelahirannya (di rantau orang), diumpamakan baginya dari negeri tempat kelahirannya pergi ke perantauan tempat ia menghembuskan nafas itu, seperti (ia masuk) ke dalam syurga.","r":"Nasai"},{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Bila kamu menghadapi orang sakit atau mayat, maka keluarkanlah olehmu ucapan kebaikan, kerana sesungguhnya malaikat mengaminkan segala yang kamu katakan itu.","r":"Muslim"}],"te":"A Stranger Who Dies Abroad, and Praising the Dead"},{"t":"Bacaan ketika Mendengar Musibah","p":366,"v":1,"d":[{"y":"a","s":2,"a":155,"b":156,"m":"Dan berikanlah khabar gembira kepada orang-orang yang sabar, iaitu orang-orang apabila mereka ditimpa suatu cubaan (musibah), mereka berkata: Sesungguhnya kami kepunyaan Allah, dan sesungguhnya kami akan kembali kepadaNya"},{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Tiadalah seorang hamba yang dikenai bahaya, lalu membaca: yaa MI GS SI. Ya Allah! Berilah aku pahala kerana musibahku, dan gantilah ia dengan kebaikan bagiku. Melainkan Allah memberi pahala kepadanya dalam musibahnya itu.","r":"Muslim"}],"te":"What to Say on Hearing of a Calamity"}],"p":351,"v":1,"te":"About Graves"},{"t":"Orang yang Sedang dalam Sakaratul Maut","c":[{"t":"Mengajarkan Kalimat Tauhid kepada Orang Akan Meninggal","p":367,"v":1,"d":[{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia telah berkata: Telah bersabda Rasulullah s.a.w.: Ajarkanlah kepada mayat kamu (orang yang menghadapi mati), tiada tuhan selain Allah.","r":"Muslim"},{"y":"h","x":"Dari Muaz bin Jabal r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang akhir ucapannya: Tiada ada Tuhan melainkan Allah masuklah ia ke dalam syurga.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Mu'qal bin Yasar r.a. bahawasanya Nabi s.a.w. bersabda: Bacakanlah olehmu surah Yasin kepada mayatmu. (Orang akan mati). San DAN MI ole,","r":"Abu Daud dan Nasai"}],"te":"Teaching the Words of Tauhid to the Dying"},{"t":"Berdoa ketika Sakaratul Maut","p":368,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Pernah aku melihat Rasulullah s.a.w. ketika akan wafat dan didekatnya ada sebuah mangkok berisi air, lalu dimasukkan tangannya ke dalam mangkuk itu, kemudian disapukan mukanya dengan air itu seraya berkata: Ya Allah! Tolonglah aku atas kesusahan mati dan mabuk sakaratul maut.","r":"Tirmizi"}],"te":"Supplication at the Time of Death"},{"t":"Terlihat Syurga atau Neraka ketika Sakaratul Maut","p":369,"v":1,"d":[{"y":"h","x":"Dari Ubadah bin Shamit r.a. dari Nabi s.a.w. bersabda: Orang mukmin, bila ia telah mendekat mati, ia diberi kegembiraan dengan memperlihatkan keredaan dan kemuliaan Allah. Maka tidaklah sesuatu yang lebih disukainya, selain dari apa yang ada di depannya itu. Maka iapun suka menjumpai Allah, dan Allah pun suka pula menjumpainya. Dan sesungguhnya orang kafir, bila ia telah mendekat mati, ia diberi gembira dengan azab dan seksaan Allah. Maka tidaklah sesuatu yang lebih dibencinya selain apa yang ada di depannya itu. Maka ia benci menjumpai Allah dan Allah benci pula menjumpainya.","r":"Bukhari dan Muslim"}],"te":"Seeing Paradise or Hell at the Time of Death"},{"t":"Memperbanyak Mengingat Mati","p":370,"v":1,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. bahawasanya Rasulullah s.a.w. pernah berkata kepada sahabat-sahabatnya: Malulah kamu kepada Allah sebenar-benarnya malu. Mereka menjawab: Sungguh kami malu, ya Rasulullah, dan segala puji bagi Allah. Rasulullah menjawab: Bukan seperti yang kamu katakan itu, akan tetapi orang yang malu kepada Allah sebenar-benarnya malu maka hendaklah dijaganya kepalanya dan apa yang berharga di sekitarnya, dan hendaklah dijaga perutnya dan apa yang terkandung di dalamnya dan hendaklah ia ingati mati dan bangkai (yang bakal hancur di dalam kubur) dan sesiapa yang ingin kebahagiaan akhirat, hendaklah meninggalkan kemewahan hidup di dunia dan sesiapa yang telah mengerjakan yang demikian, maka sesungguhnya ia betul malu kepada Allah sebenarbenarnya malu.","r":"Tirmizi"}],"te":"Remembering Death Often"},{"t":"Menziarahi Kubur","p":371,"v":1,"d":[{"y":"h","x":"Dari Sulaiman bin Buraidah, dari bapanya r.a. dari Nabi s.a.w. berliau bersabda: Pernah aku melarangmu dari menziarahi kubur, maka sungguh telah diizinkan bagi Muhammad menziarahi kubur ibunya, maka oleh sebab itu ziarahlah kubur itu, kerana sesungguhnya menziarahi kubur itu mengingatkan kepada hari akhirat.","r":"Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. pernah datang ke tempat perkuburan, lalu beliau mengucapkan: Selamatlah atasmu hai ahli kubur kaum mukminin dan sesungguhnya kami insya Allah akan menyusul juga dengan kamu.","r":"Ahmad dan Muslim"}],"te":"Visiting Graves"},{"t":"Menghadiahkan Pahala Amal untuk Mayat","p":372,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a.: Bahawasanya seorang laki-laki bertanya kepada Rasulullah: Ya, Rasulullah. Sesungguhnya aku mempunyai dua ibubapa yang pernah aku berbuat baik (berbakti) ketika keduanya masih hidup. Maka bagaimanakah jalan bagiku untuk berbakti kepada keduanya sesudah keduanya meninggal? Rasulullah s.a.w. bersabda: Sesungguhnya termasuk berbakti, ialah: Bahawa engkau sembahyang untuk keduanya bersama sembahyang engkau, dan bahawa engkau berpuasa untuk keduanya bersama puasa engkau.","r":"Daruquthni"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Rasulullah s.a.w ketika hendak menyembelih korbannya, beliau mengucapkan: Dengan nama Allah. Ya Allah, terimalah pahala korbanku ini untuk Muhammad, untuk keluarga Muhammad dan untuk umat Muhammad, kemudian beliau sembelih korbannya.","r":"Muslim"},{"y":"h","x":"Dari Saad bin Ubadah r.a. Bahawasanya ia berkata: Ya Rasulullah. Sesungguhnya Ibu Saad telah meninggal. Maka apakah sedekah yang lebih utama. Rasulullah s.a.w. bersabda: Sedekah air. Lalu kami gali perigi, dan dia berkata; sumur ini untuk ibu Saad.","r":"Abu Daud dan Ahmad"}],"te":"Gifting the Reward of Deeds to the Dead"}],"p":367,"v":1,"te":"One Who Is Dying (Sakaratul Maut)"}],"p":330,"v":1,"d":[{"y":"a","s":4,"a":78,"b":78,"m":"Di mana saja kamu berada, kamu dikejar oleh mati, sekalipun kamu di dalam benteng yang kukuh"},{"y":"h","x":"Dari Abu Hurairah r.a. telah berkata: Rasulullah s.a.w. bersabda: Perbanyaklah olehmu mengingati peristiwa yang memutuskan kesenangan, iaitu mati.","r":"Tirmizi dan Nasai"}],"te":"Book of Funerals"},{"t":"Kitab Zakat","c":[{"t":"Asas Zakat","p":373,"v":1,"c":[{"t":"Erti Zakat","p":373,"v":1,"d":[{"y":"a","s":2,"a":43,"b":43,"m":"Dan dirikanlah sembahyang dan keluarkanlah zakat serta rukuklah bersama orang-orang yang rukuk"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. telah mengutus Muaz ke Yaman, lalu beliau berkata: Ajaklah mereka kepada pengakuan, bahawa tidak ada tuhan melainkan Allah, dan bahawasanya aku Rasulullah. Maka jika mereka telah mentaatinya yang demikian itu, maka beritahukan kepada mereka, bahawa Allah telah mewajibkan sembahyang lima kali sehari semalam di atas mereka. Maka jika mereka telah mentaati pula yang demikian itu, maka beritahukan pula kepada mereka, bahawa Allah telah mewajibkan zakat di atas mereka, yang dipungut dari orang-orang kaya mereka, dan diberikan kepada orang-orang miskin mereka.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar berkata: Telah diwajibkan oleh Rasulullah s.a.w. zakat fitrah di bulan Ramadan atas tiap orang, satu gantang tamar.","r":"Bukhari dan Muslim"}],"te":"Meaning of Zakat"},{"t":"Zakat Unta","p":376,"v":1,"d":[{"y":"h","x":"Dari 121 ekor unta sampai ke atas, maka tiaptiap 40 ekor unta wajib dizakatkan seekor unta yang berumur 2 tahun. Dan tiap-tiap yang lebih dari 50 ekor unta dizakatkan 1 ekor unta yang berumur 3 tahun.","r":"Bukhari dari Anas"},{"y":"h","x":"Dari Anas r.a. bahawa Abu Bakar r.a. pernah berkirim surat dan di dalam surat tertulis: Pada tiap-tiap 24 ekor unta lantas yang lebih kurang dari itu, wajib dikeluarkan zakatnya binatang kambing, iaitu dari tiap-tiap 5 ekor unta, dizakatkan seekor kambing. Bila unta itu telah sampai 25 ekor hingga 35 ekor, maka wajib dikeluarkan zakatnya seekor unta betina yang berumur satu tahun masuk yang kedua. Maka bila unta itu sampai 36 hingga 45 ekor, maka wajib dikeluarkan zakatnya seekor unta betina yang berumur dua tahun masuk yang ketiga. Maka bila unta itu sampai 46 hingga 60 ekor, maka wajib dikeluarkan zakatnya seekor unta betina yang berumur 3 tahun. Maka bila unta itu sampai 61 ekor hingga 75 ekor, maka wajib dikeluarkan zakatnya seekor unta betina yang berumur 4 tahun. Maka bila unta itu sampai 76 hingga 90 ekor, maka wajib dikeluarkan zakatnya dua ekor unta betina yang berumur dua tahun masuk yang ketiga. Maka bila itu telah sampai 91 hingga 120 ekor, maka wajib dikeluarkan zakatnya 2 ekor unta yang berumur 3 tahun. Maka bila unta itu lebih dari 120 ekor, maka pada tiap-tiap 40 ekor, wajib dikeluarkan zakatnya seekor unta betina yang berumur dua tahun. Dan tiap-tiap 50 ekor wajib dikeluarkan zakatnya unta betina yang berumur dua tahun.","r":"Bukhari dan Abu Daud"}],"te":"Zakat on Camels"},{"t":"Zakat Sapi","p":378,"v":1,"d":[{"y":"h","x":"Dari Muaz r.a. berkata: Aku telah diutus oleh Rasulullah s.a.w. ke Yaman dan diperintahkannya aku supaya mengambil dari tiap-tiap 40 ekor sapi, seekor sapi yang berumur 2 tahun dan dari tiap-tiap 30 ekor, seekor sapi jantan atau sapi betina yang berumur 1 tahun.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: 'Tidaklah wajib atas kaum Muslimin zakat hamba, dan tidak pula kudanya.","r":"Bukhari"}],"te":"Zakat on Cattle"},{"t":"Zakat Biri-Biri atau Kambing","p":378,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Nabi s.a.w. pernah menulis sebuah kitab zakat yang di dalamnya tertulis: Pada tiap-tiap 40 ekor kambing dizakatkan seekor kambing, sehingga 120 ekor kambing, apabila bertambah 1 ekor (dari 120 ekor), maka zakatnya 2 ekor kambing. Apabila bertambah (lebih) dari 200 ekor kambing maka zakatnya 3 ekor kambing sehingga 300 ekor. Apabila lebih dari itu, maka tiap-tiap seratus ekor, zakatnya 1 ekor kambing.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Bahzi bin Hakim, dari bapanya, dari datuknya r.a. dari Nabi s.a.w. bersabda: Pada tiap-tiap binatang unta yang lepas, dalam 40 (empat puluh) ekor, zakatnya seekor unta betina yang berumur 2 tahun, yang tidak boleh diceraikan unta itu dari perhitungannya.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Alir.a. dari Nabi s.a.w. bersabda: Dan pada sapi pada tiap-tiap 30 ekor, wajib dizakatkan satu ekor sapi yang berumur satu tahun, dan dalam empat puluh ekor, maka wajib dikeluarkan 1 (satu) ekor sapi yang berumur 2 tahun, dan tidaklah wajib zakat pada binatang yang dipergunakan untuk penjajar sawah, ladang dan sebagainya.","r":"Abu Daud"}],"te":"Zakat on Sheep and Goats"},{"t":"Syarat Wajib Zakat Binatang Ternak","p":380,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. bahawasanya Nabi s.a.w. bersabda: Tidak wajib zakat pada harta, hingga telah sampai tahunnya.","r":"Abu Daud"},{"y":"h","x":"Dari Anas r.a. berkata: Telah bersabda Nabi s.a.w.: Dan tidaklah diambil untuk zakat binatang-binatang yang terlampau tua, atau binatang yang buta dan tidak pula bapa kambing.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Umar bin Khattab r.a. sesungguhnya ia berkata kepada amilnya yang bernama Sufian: Katakanlah kepada kaummu: Sesungguhnya kami tinggalkan untukmu binatang-binatang yang beranak kecil, binatang yang mengandung (hamil), binatang yang disediakan unitik dipotong dan biri-biri jantan yang dibawa untuk berjalan. Dan kami ambil binatang yang berumur setahun dan dua tahun. Demikianlah aturan yang seadil-adilnya yang kami jalankan padamu dalam urusan harta ini.","r":"Malik dalam Kitab Al-Muwatak"}],"te":"Conditions of Zakat on Livestock"},{"t":"Zakat pada Barang Milik Bersama","p":381,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Rasulullah s.a.w. pernah menuliskan sebuah kitab zakat, dan disertakannya surat itu dengan pedangnya. Maka dipraktiskan orang pekerjaan itu, dan oleh Abu Bakar dan Umar r.a. yang tertulis di dalamnya: Tidaklah boleh dipisah-pisahkan antara binatang-binatang yang berkumpul, dan tak boleh pula dikumpulkan binatang-binatang yang terpisah-pisah kerana takut berzakat. Dan semua yang ada antara dua percampuran (persekutuan) maka sesungguhnya jatuh wajibnya antara keduanya bersamaan.","r":"Abu Daud dan Tirmizi"}],"te":"Zakat on Jointly Owned Property"},{"t":"Zakat Tanam-Tanaman dan Buah-Buahan","p":383,"v":1,"d":[{"y":"h","x":"Dari Ibnu Asid r.a. sesungguhnya Rasulullah s.a.w. bersabda tentang buah korma: Sesungguhnya buah korma (anggur) itu akan dikira (sebab ia akan kering), sebagaimana mengira buah nakhal kering, lalu dikeluarkanlah zakatnya ketika telah jadi zabib (buah anggur yang kering), sebagaimana dikeluarkan zakat nakhal ketika jadi tamar.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. sesungguhnya Rasulullah s.a.w. berbersabda: Pada barang yang kurang lima ausuq seperti tamar dan tanaman berbutir-butir' tidaklah dizakatkan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Rasulullah s.a.w. telah mewajibkan pada barang-barang yang diairi oleh air langit (hujan) dan air sungai dan air mata air atau air bandar, maka wajib dikeluarkan zakatnya satu persepuluh dari hasilnya. Dan pada tanaman yang diari dengan air yang diangkut oleh unta, maka wajib dikeluarkan zakatnya satu perduapuluh dari hasilnya.","r":"Abu Daud"},{"y":"a","s":6,"a":141,"b":141,"m":"Makanlah olehmu buahnya bila ia telah berbuah, dan keluarkanlah haknya (zakatnya) pada hari menyabitnya. Janganlah kamu berlebih-lebihan. Allah tidak suka kepada orang yang berlebihlebihan"}],"te":"Zakat on Crops and Fruit"},{"t":"Zakat Emas dan Perak","p":386,"v":1,"d":[{"y":"a","s":9,"a":34,"b":34,"m":"Dan orang-orang yang menyimpan emas dan perak, dan tak mahu mereka membelanjakannya di jalan Allah, maka berilah mereka khabar gembira (hai Muhammad) dengan seksaan yang pedih"},{"y":"h","x":"Dari Umar bin Syuib, dari datuknya dari Nabi s.a.w. beliau bersabda: Dan tidaklah wajib berzakat pada yang kurang dari 20 misqal.","r":"Daruqutni"},{"y":"h","x":"Dari Ali r.a. katanya; Telah bersabda Rasulullah s.a.w. : Bila ada bagimu dua ratus dirham, dan telah sampai pula satu tahun, maka wajib dikeluarkan daripadanya lima dirham, dan tidaklah wajib atas engkau berzakat hingga ada dua puluh dinar (misqal) dan telah sampai bilangannya satu tahun, maka wajib dikeluarkan setengah dinar.","r":"Abu Daud"},{"y":"h","x":"Dari Ali r.a. dari Nabi s.a.w. beliau bersabda: Keluarkanlah 1/40 wang perak, dan tak wajib berzakat sebelum sampai 200 dirham. Adapun kelebihan (daripada 200 dirham) maka zakatnya menurut perhitungannya.","r":"Abu Daud"}],"te":"Zakat on Gold and Silver"},{"t":"Zakat Rikaz","p":388,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda: Pada rikaz, wajib dikeluarkan zakatnya! 1/5 (seperlimanya).","r":"Bukhari"},{"y":"h","x":"Dari Umar bin Syuaib r.a. sesungguhnya ada seorang perempuan datang kepada Nabi s.a.w. dan sertanya ada seorang anaknya perempuan. Pada kedua belah tangan anak perempuannya itu ada dua perhiasan gelang emas yang tebal kelihatannya. Maka Rasulullah bersabda kepadanya: “Apakah kau keluarkan zakat ini?” Ia menjawab: “Tidak” Rasulullah s.a.w. bersabda pula: Apakah engkau mahu diberi gelang oleh Allah iaitu gelang dari api neraka pada hari kiamat tersebab dengan gelang yang dua ini? Maka ditinggalkan gelang itu, lalu diberikannya kepada Rasulullah s.a.w. sambil berkata: Kedua-duanya ini kepunyaan Allah dan Rasul-Nya.","r":"Abu Daud"},{"y":"h","x":"Dari Siti Aisyah r.a. ia berkata: Pernah aku datang kepada Nabi s.a.w. maka dilihatnya di tanganku beberapa gelang kecil terbuat dari perak, lalu beliau bersabda: Apakah ini hai Aisyah? Lalu aku menjawab: Aku buat dia, supaya aku berhias di hadapan engkau, ya Rasulullah. Nabi bertanya: Apakah engkau mahu mengeluarkan zakat? Aku menjawab: Tidak, kecuali kalau Tuhan menghendaki. Beliau bersabda: Cukuplah dia memasukkan engkau ke dalam neraka. ar - & pa","r":"Daruqutni"},{"y":"h","x":"Dari Ali bin Abu Talib r.a. ia berkata: Tak wajib berzakat pada barang-barang intan berlian.","r":"Baihaqi"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia telah berkata: Tidaklah wajib berzakat pada barang-barang batu (batu-batu cincin yang diambil dari laut. Dan permata itu sesuatu yang dihidangkan oleh laut).","r":"Baihaqi"}],"te":"Zakat on Buried Treasure (Rikaz)"},{"t":"Zakat Tijarah (Perdagangan)","p":390,"v":1,"d":[{"y":"a","s":2,"a":267,"b":267,"m":"Hai orang-orang yang beriman! Belanjakanlah dari barang-barang halal, apa-apa yang telah kamu usahakan, dan dari apa-apa yang telah Kami keluarkan untukmu dari dalam bumi"},{"y":"h","x":"Dari Samurah ia berkata: Bahawasanya Nabi s.a.w. pernah menyuruh kami supaya mengeluarkan zakat dari barang-barang yang disediakan untuk dijual.","r":"Abu Daud"}],"te":"Zakat on Trade"}],"te":"Basics of Zakat"},{"t":"Zakat Fitrah","c":[{"t":"Erti Zakat Fitrah","p":392,"v":1,"d":[{"y":"a","s":87,"a":14,"b":15,"m":"Sungguh menanglah orang-orang yang telah membersihkan dirinya. Serta menyebut nama Allah kemudian ia sembahyang"}],"te":"Meaning of Zakat al-Fitr"},{"t":"Gunanya Zakat Fitrah","p":392,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Telah diwajibkan Rasulullah s.a.w. zakat fitrah, guna mensucikan orang yang berpuasa dari kata-kata dan perbuatan-perbuatan yang keji dan untuk memberi makan bagi kaum vang miskin. Siapa yang mengeluarkan zakat fitrah sebelum sembahyang hari raya maka itulah zakat yang diterima, dan siapa yang membayarkannya sesudah sembahyang hari raya, maka itu adalah semacam sedekah dari beberapa sedekah.","r":"Abu Daud dan Ibnu Majah"}],"te":"Purpose of Zakat al-Fitr"},{"t":"Orang yang Wajib Mengeluarkan Zakat Fitrah","p":393,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah mewajibkan Rasulullah s.a.w. akan zakat fitrah' segantang dari tamar atau segantang dari syair, di atas hamba sahaya dan orang merdeka, laki-laki, perempuan, kanak-kanak dan orang tua dari kaum muslimin.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia telah berkata: Pernah kami mengeluarkan zakat fitrah ketika Rasulullah s.a.w. ada pada kami di Madinah iaitu segantang makanan atau segantang tamar atau segantang gandum syair atau segantang zabib (buah anggur kering). Maka adapun aku senantiasalah mengeluarkan fitrah itu, sebagaimana yang aku keluarkan untuk makananku sendiri.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia berkata: Pernah kami pada hari raya fitri di masa Rasulullah s.a.w. mengeluarkan segantang makanan, dan selanjutnya berkata Abu Said: Dan adalah makanan kami ketika itu gandum (syair), zabib, aqith dan tamar.","r":"Bukhari"}],"te":"Who Must Pay Zakat al-Fitr"},{"t":"Anak yang Lahir sesudah Matahari Terbenam di Akhir Bulan Ramadan","p":395,"v":1,"te":"A Child Born After Sunset on the Last Day of Ramadan"},{"t":"Waktu Mulainya Membayar Zakat Fitrah","p":396,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Rasulullah s.a.w. telah memerintahkan untuk mengeluarkan zakat fitrah sebelum manusia keluar pergi sembahyang hari raya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Nafi' r.a. ia berkata: Adalah Ibnu Umar r.a. memberikan zakat fitrah itu kepada orang-orang yang berhak menerimanya, dan adalah mereka mengeluarkan fitrah itu sehari atau dua hari sebelum hari raya Fitri.","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah bersabda Rasulullah s.a.w. Bayarkanlah zakat fitrah orang-orang yang kamu belanjai.","r":"Daruqutni dan Baihaqi"}],"te":"When Zakat al-Fitr Payment Begins"},{"t":"Mengeluarkan Nilai Harga Zakat Fitrah","p":398,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. berkata: Rasulullah s.a.w. telah bersabda: Cukuplah keperluan mereka (fakir miskin itu) supaya jangan berkeliling meminta-minta pada hari itu.","r":"Daruqutni dan Baihaqi"}],"te":"Paying Zakat al-Fitr in Money"},{"t":"Wajib Difitrahkan Lebih Dahulu Diri Sendiri Lalu Orang yang Jadi Tanggungjawab","p":399,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Mulailah dengan diri engkau sendiri lebih dahulu, maka bersedekahlah untuk dirimu sendiri, maka jika ada lebihnya, sedekahkanlah untuk isterimu, maka jika masih ada juga lebihnya, sedekahkanlah untuk karib-kerabatmu.","r":"Muslim"}],"te":"Pay First for Yourself, Then for Your Dependants"},{"t":"Orang-Orang yang tidak Wajib Dibayarkan Zakat Fitrahnya","p":399,"v":1,"te":"Those Whose Zakat al-Fitr Need Not Be Paid"}],"p":392,"v":1,"te":"Zakat al-Fitr"},{"t":"Orang yang Berhak Menerima Zakat Fitrah","c":[{"t":"Orang yang Termasuk Golongan Fakir","p":401,"v":1,"d":[{"y":"a","s":2,"a":273,"b":273,"m":"Zakat itu hanya diberikan kepada orang-orang fakir, yang terlantar pada jalan Allah; mereka tak kuasa berjalan di muka bumi. Orangorang yang tak tahu mengira, bahawa mereka orang kaya, iaitu orang yang berkecukupan, engkau kenal mereka dengan tandatanda bahawa mereka tak mahu meminta-minta kepada manusia dengan terus-terusan diketahui segala yang engkau belanjakan dari kebaikan, sesungguhnya diketahui Allah"}],"te":"Who Counts as the Destitute (Fakir)"},{"t":"Orang yang Termasuk Miskin","p":402,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Nabi s.a.w. bersabda: Bukanlah yang dinamakan miskin orang-orang yang berkeliling meminta-minta kepada manusia, yang diberinya sesuap dua nasi makanan, sebiji atau dua biji tamar, tetapi yang dinamakan miskin ialah orang-orang yang tak memperoleh kecukupan dan tak diketahui orang pula tentang kemiskinannya itu, lalu diberi orang dia sedekah, serta ia tak keluar untuk meminta-minta kepada manusia.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Sahal r.a. ia berkata: Telah bersabda s.a.w. : Siapa-siapa yang meminta-minta dan di sisinya ada makanan yang mencukupi \"keperluannya, maka sesungguhnya ia memperbanyak bara api jahanam (neraka). Bertanya seorang sahabat: Ya Rasulullah! Apakah maksudnya makanan yang mencukupi itu? Rasulullah s.a.w. menjawab: Iaitu makan sekadar dapat mengenyanginya untuk makan pagi dan untuk makan petang.","r":"Abu Daud dan Ibnu Hibban"}],"te":"Who Counts as the Poor (Miskin)"},{"t":"Orang yang Termasuk Amil","p":404,"v":1,"d":[{"y":"h","x":"Dari Abu Hamid As-Saidi r.a. Pernah Rasulullah s.a.w. memakai seorang laki-laki dari suku Asad untuk urusan zakat Bani Sulaim, laki-laki itu bernama Ibnu Latbiyah, maka tatkala ia datang, dihitungnyalah zakat-zakat itu.","r":"Bukhari"}],"te":"Who Counts as a Zakat Worker (Amil)"},{"t":"Orang yang Termasuk Mualaf","p":404,"v":1,"d":[{"y":"h","x":"Dari Rafi' bin Khadij r.a. bahawasanya Rasulullah s.a.w. pernah memberi Abu Sufian bin Harab, Shafwan bin Umaiyah, Uyainah bin Hishn dan Aqra' bin Habis masing-masing daa yai. menerima 100 unta.","r":"Muslim"}],"te":"Who Counts as One Whose Heart Is Reconciled (Mualaf)"},{"t":"Orang yang Termasuk Hamba","p":405,"v":1,"te":"Who Counts as a Slave"},{"t":"Orang yang Berhutang Banyak","p":406,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. bahawasanya Nabi s.a.w. telah bersabda: Sesungguhnya meminta-minta tidak halal, melainkan kerana tiga perkara: iaitu kerana kemiskinan yang sangat, kerana hutang yang melebihi batas kekayaan dan kerana pembayar diat (tebusan jiwa).","r":"Ahmad dan Abu Daud"}],"te":"Those Heavily in Debt"},{"t":"Yang Dimaksud dengan Sabilillah","p":407,"v":1,"te":"What Is Meant by \"In the Way of Allah\""},{"t":"Yang Dimaksud dengan Anak Sabil","p":408,"v":1,"te":"What Is Meant by the Wayfarer"},{"t":"Orang yang tidak boleh Menerima Zakat","p":408,"v":1,"d":[{"y":"h","x":"Dari Abdullah bin Adi bin Khiyar r.a. menceritakan dua orang laki-laki yang datang kepada Nabi s.a.w. hendak meminta sebahagian sedekah. Dia berkata: Rasulullah s.a.w. bersabda: Jika kamu keduanya mahu, aku beri kamu. Dan tidaklah ada bahagian padanya bagi orang yang kaya, dan tidak pula orang yang kuat berusaha.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Abdullah bin Haris r.a. diceritakannya sebuah hadis sampai ia berkata: Sesungguhnya sedekah (zakat) ini hanyalah daki manusia, dan sesungguhnya zakat itu tidak halal bagi Muhammad dan tidak pula bagi keluarga Muhammad.","r":"Muslim dan Nasai"},{"y":"h","x":"Dari Abdullah bin Haris r.a. diceritakannya sebuah hadis sampai ia berkata: Sesungguhnya sedekah (zakat) ini hanyalah daki manusia, dan sesungguhnya zakat itu tidak halal bagi Muhammad dan tidak pula bagi keluarga Muhammad.” (Diriwayatkan oleh Muslim dan Nasai). Yang dimaksudkan dengan “daki manusia” di sini, ialah daki dari harta manusia. Sebelum zakat itu dikeluarkan, bererti harta manusia masih kotor. Tidak dihalalkan bagi Nabi s.a.w. dan keluarganya, adalah kerana sangat sucinya diri Nabi Muhammad dan keluarganya. Adapun orang yang berzakat, tidaklah sah zakat itu diberikannya kepada orang yang menjadi tanggungannya atau orang yang wajib atasnya menanggung nafkahnya. Umpamanya ibu, anak dan lain-lainnya kecuali kalau masing-masing sudah lepas dari tanggungannya. Adapun orang-orang kafir yang mereka tidak berhak menerima zakat ialah kerana hadis Rasulullah s.a.w. berbunyi: “Sesungguhnya Allah telah mewajibkan di atas mereka mengeluarkan zakat harta mereka. Zakat itu diambil dari merekamereka (orang Islam) yang kaya, dan diberikan kepada merekamereka yang fakir.","r":"Bukhari dari Ibnu Abbas"}],"te":"Who May Not Receive Zakat"},{"t":"Hukuman Orang yang tidak Mahu Mengeluarkan Zakat","p":410,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tiadalah orang-orang yang mempunyai emas dan perak, yang tidak mengeluarkan zakatnya, melainkan bila terjadi hari kiamat maka dibuatkan baginya beberapa bingkah besi dari neraka, lalu dipanaskan dalam api neraka, kemudian bingkah-bingkah besi itu digosokkan (diseterika) kepada kedua belah badannya serta dahinya dan punggungnya, apabila api itu telah dingin, dikembalikan pula panasnya pada waktu yang lamanya 50,000 tahun, hingga Allah menghukum sekalian hamba-Nya. Maka dilihat jalannya, adakalanya ke syurga dan adakalanya ke neraka.","r":"Bukhari dan Muslim"}],"te":"Punishment for Refusing to Pay Zakat"},{"t":"Rahsia Berzakat","p":411,"v":1,"te":"The Inner Meaning of Zakat"}],"p":400,"v":1,"d":[{"y":"a","s":9,"a":60,"b":60,"m":"Hanya sedekah-sedekah itu (zakat) diberikan kepada fakir miskin, orang yang bekerja mengurus zakat, orang-orang yang mulai dijinaki hatinya terhadap Islam (baru masuk Islam), hamba-hamba orang-orang yang berhutang dan kepada jalan Allah serta kepada anak-anak sabil"},{"y":"a","s":2,"a":177,"b":177,"m":"Dan ia berikanlah harta yang dicintai itu kepada karib (keluarga) yang dekat, kepada anak yatim, kepada kaum miskin, kepada anak sabil, orang yang meminta-minta dan kepada hamba-hamba"}],"te":"Who May Receive Zakat"}],"p":373,"v":1,"te":"Book of Zakat"},{"t":"Kitab Berpuasa","c":[{"t":"Asas Berpuasa","p":413,"v":1,"c":[{"t":"Erti Puasa","p":413,"v":1,"d":[{"y":"h","x":"Dari Ali r.a. ia berkata: Nabi s.a.w. telah bersabda: Diangkatkan tuntutan hukum dari tiga macam orang, dari kanak-kanak hingga ia balig, dari orang yang tidur hingga ia bangun dan dari orang gila hingga id sembuh. SAN 3g yi ols,","r":"Abu Daud dan Nasai"}],"te":"Meaning of Fasting"},{"t":"Yang Mewajibkan Puasa dan Fardunya","p":414,"v":1,"d":[{"y":"a","s":2,"a":185,"b":185,"m":"Barangsiapa di antara kamu yang telah melihat anak bulan hendaklah ia berpuasa"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Puasalah kamu kerana telah melihat bulan dan berbukalah kerana telah melihat bulan, apabila bulan itu tertutup (kerana awan tebal), maka sempurnakanlah bilangan bulan Syaaban iaitu tiga puluh hari.","r":"Bukhair dan Muslim"},{"y":"a","s":10,"a":5,"b":5,"m":"Dia (Tuhan) telah menjadikan matahari bersinar-sinar dan bulan bercahaya-cahaya, dan ditentukan-Nya perjalanannya supaya kamu mengetahui bilangan tahun dan hitungannya (hisabnya)"}],"te":"What Makes Fasting Obligatory, and Its Obligatory Acts"},{"t":"Untuk Menetapkan Rukyatul-Hilal","p":415,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah datang seorang Arab Badui kepada Nabi s.a.w. Lalu ia berkata: Sungguh aku telah melihat hilal (bulan). Maka Raulullah s.a.w. bersabda: Mahukah engkau mengaku bahawa tidak ada tuhan melainkan Allah? Ia menjawab mahu Ya Rasulullah s.a.w. Beliau bersabda: Mahukah engkau mengaku, bahawa Muhammad itu Rasul Allah? Ia menjawab: Mahu Ya Rasulullah s.a.w. Beliau bersabda lagi: Ya Bilal! Beritahulah kepada manusia, agar mereka puasa esok hari.","r":"Tirmizi dan Ibnu Hibban"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah ribut manusia mengatakan hilal Ramadan telah ada, lalu aku khabarkan kepada Rasulullah s.a.w. bahawa aku telah melihatnya, lalu beliau terus berpuasa, dan disuruhnya manusia mulai berpuasa.","r":"Abu Daud dan Ibnu Hibban"},{"y":"h","x":"Dari Hafsah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Siapa yang tidak mempermalamkan niat puasa sebelum terbit fajar, maka tidaklah sah puasanya.","r":"Abu Daud dan Tirmizi"}],"te":"Sighting the New Moon"},{"t":"Yang Membatalkan Puasa","p":417,"v":1,"d":[{"y":"h","x":"Dari Ibni Abbas r.a. ia telah berkata: Adapun yang mewajibkan berwuduk kerana ada sesuatu yang keluar (dari kubul atau dubur), dan bukan kerana sesuatu yang masuk. Adapun yang membukakan puasa ialah kerana ada barang yang masuk dan bukan kerana barang yang keluar.","r":"Bukhari"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Nabi s.a.w. bersabda: Sesiapa yang mencari jalan untuk muntah (lalu ia muntah) maka wajib atasnya qada dan barangsiapa yang terpaksa muntah, maka tidaklah wajib qada atasnya (tidaklah batal puasanya).","r":"Baihaqi"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia telah berkata: Telah bersabda Nabi s.a.w.: Bukankah apabila perempuan-perempuan itu haid tak boleh mereka sembahyang dan tak boleh pula puasa. Mereka menjawab: Ya, sebab itu menandakan kurang agamanya.","r":"Bukhari"}],"te":"What Breaks the Fast"},{"t":"Hukum Orang yang Bersetubuh di Siang Hari Bulan Ramadan","p":419,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya seorang laki-laki pernah bersetubuh dengan isterinya pada siang hari bulan Ramadan, lalu ia meminta fatwa (keterangan) kepada Rasulullah s.a.w. tentang itu. Maka menjawab Rasulullah s.a.w.: Engkau perolehkah seorang hamba (untuk dimerdekakan). Ia menjawab: Tidak. Beliau bertanyalagi: Kuatkah engkau puasa dua bulan berturut-turut? Ia menjawab tidak: Maka (beliau pun bersabda): Berilah makan kepada ampelarorang pakan:","r":"Muslim"}],"te":"Ruling on Intercourse During the Day in Ramadan"},{"t":"Terlupa Makan/minum di Siang Hari Ramadan bagi Orang yang Berpuasa","p":420,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang makan atau minum kerana lupa, maka tidaklah ia berbuka (batal puasanya), kerana itu semata-mata satu rezeki yang diberikan Allah kepadanya.","r":"Tirmizi dan Baihaqi"}],"te":"Eating or Drinking by Mistake While Fasting in Ramadan"},{"t":"Macam-Macam Sunat Puasa","p":420,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Bersabda Nabi s.a.w.: Sahurlah kamu, sesungguhnya pada makan sahur itu ada keberkatan.","r":"Bukhari dan Muslim"},{"y":"a","s":2,"a":187,"b":187,"m":"Makanlah dan minumlah kamu, hingga telah terang bagimu cahaya putih dari cahaya yang hitam waktu fajar"},{"y":"h","x":"Dari Samurah bin Jundab r.a. dari Nabi s.a.w. beliau bersabda: Janganlah kamu tertipu (terhalang) oleh azan Bilal untuk makan sahur, jangan pula oleh cahaya putih memanjang begini, hingga cahaya itu melintang begini.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Sahal bin Said r.a. bahawasanya s.a.w. bersabda. Sentiasalah manusia itu tinggal dalam kebaikan selama mereka menyegerakan berbuka.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Zaid bin Sabit r.a. ia telah berkata: Pernah kami makan sahur bersama Rasulullah s.a.w. kemudian kami berdiri melakukan sembahyang. Ditanya orang: Berapa lamanya antara keduanya? Ia menjawab: Sekadar membaca 50 ayat Al-Quran.","r":"Bukhari"},{"y":"h","x":"Dari Abu Zarr r.a. dari Nabi s.a.w. beliau bersabda: Sentiasalah umatku tetap dalam kebaikan, selama mereka menyegerakan berbuka dan melambatkan makan sahur.","r":"Ahmad"},{"y":"h","x":"Dari Abu Hurairah r.a. sesungguhnya Rasulullah s.a.w. pernah bersabda: Sesiapa yang tak mahu meninggalkan pekerjaan yang keji itu, maka tiadalah keperluan bagi Allah, supaya ia meninggalkan makan dan minum.","r":"Bukhari"},{"y":"h","x":"Dari Anas r.a. telah berkata: Pernah ditanya orang: Ya Rasulullah! Mana sedekah yang lebih utama? Beliau menjawab: Sedekah di bulan Ramadan itu.","r":"Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. telah berkata: Telah bersabda Nabi s.a.w.: Sesiapa yang mendirikan (beribadat) pada bulan Ramadan secara iman dan perhitungan, diampuni Allah apa-apa yang telah terdahulu dari dosanya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Zaid bin Khalid Al-Juhanni r.a. telah berkata: Nabi s.a.w. telah bersabda: Sesiapa yang memberi buka kepada orang yang berpuasa, adalah baginya mendapat upah (pahala) tidak kurang dari upah (pahala) orang yang puasa itu.","r":"Tirmizi"},{"y":"h","x":"Dari Anas r.a. bahawasanya Rasulullah s.a.w. pernah datang kepada Saad bin Ubadah r.a., maka beliau dihidangkan sepotong roti dan minyaak sapi, lalu dimakan oleh beliau. Kemudian beliau s.a.w. bersabda: Telah berbuka di dekatmu orang yang puasa, dan telah berselawat (berdoa) atasmu malaikat. berselawat (berdoa) atasmu malaikat.","r":"Abu Daud"}],"te":"Sunnah Acts of Fasting"},{"t":"Macam-Macam yang Makruh bagi Orang Puasa","p":425,"v":1,"d":[{"y":"h","x":"Dari Khabab r.a. bahawasanya Rasulullah s.a.w. telah bersabda: Bila kamu berpuasa maka bersugilah (menggosok gigi) kamu di waktu pagi, dan janganlah kamu bersugi di waktu petang, kerana sesungguhnya tiadalah bagi orang yang puasa yang kering kedua bibirnya, melainkan akan jadi cahaya antara kedua matanya di hari kiamat.","r":"Daruqutni dan Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. beliau bersabda: Pernah saya mendengar Rasulullah s.a.w. bersabda: Sesungguhnya bau busuk mulut orang yang puasa itu, lebih harum di sisi Allah daripada bau kesturi.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Laqit bin Sabrah r.a. dari Nabi s.a.w. beliau telah bersabda: Sempurnakanlah berwuduk, dan silang-silangkan anak jari, dan persangatlah istinsyaq, kecuali bila engkau sedang puasa.","r":"Tirmizi"}],"te":"What Is Disliked for the Fasting Person"}],"te":"Basics of Fasting"},{"t":"Berbuka Puasa","c":[{"t":"Erti Berbuka Puasa","p":427,"v":1,"d":[{"y":"h","x":"Dari Umar bin Khattab r.a. ia telah berkata: Telah bersabda Rasulullah s.a.w.: Bila malam telah datang dari sebelah sana dan siang telah pergi ke sebelah sana, dan matahari telah terbenam, maka sesungguhnya telah boleh berbuka orang puasa.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. telah berkata: Adalah Rasulullah s.a.w. sebelum beliau sembahyang beliau berbuka dengan buah-buahan yang berair, apabila tak ada maka dengan tamar, apabila tak ada juga, maka dengan air yang berasa sedap.","r":"Abu Daud"},{"y":"h","x":"Dari Anas r.a. telah berkata: Adalah Rasulullah s.a.w. sebelum beliau sembahyang beliau berbuka dengan buah-buahan yang berair, apabila tak ada maka dengan tamar, apabila tak ada juga, maka dengan air yang berasa sedap.” (Diriwayatkan oleh Abu Daud). Ertinya, jika kurma tidak ada, atau tamar pun tak ada pula, maka berbukalah dengan air yang berasa sedap, umpama air yang bergula dan lain-lain. Ketika kita berbuka bacalah doanya iaitu: P Sa a SE SN, 39) PM ols, “Ya Allah! Bagi Engkau (kerana Engkau) aku puasa dan dengan rezeki Engkau aku berbuka.","r":"Abu Daud dan Tirmizi"}],"te":"Meaning of Breaking the Fast"},{"t":"Macam-Macam Uzur yang Membolehkan Meninggalkan Puasa","p":428,"v":1,"d":[{"y":"a","s":2,"a":185,"b":185,"m":"Dan sesiapa yang dalam sakit atau ia dalam perjalanan, maka boleh puasa itu dibayarnya di hari yang lain saja. Allah menghendaki akan kemudahan bagi kamu, dan bukanlah Ia menghendaki kesusahan bagi kamu"},{"y":"a","s":2,"a":195,"b":195,"m":"Dan janganlah kamu jatuhkan dirimu ke dalam jurang kebinasaan"},{"y":"h","x":"Dari Jabir r.a. beliau bersabda: Pernah Rasulullah s.a.w. bertemu dalam suatu perjalanannya dengan seseorang laki-laki terbaring di bawah pokok kayu yang disiram orang kepalanya dengan air. Maka Rasulullah s.a.w. bertanya: Apakah sebabnya ia sampai begini? Mereka menjawab: Ia puasa ya Rasulullah. Maka Rasulullah s.a.w. bersabda: Tidaklah masuk kebaikan puasa dalam perjalanan.","r":"Bukhari dan Muslim"}],"te":"Excuses That Permit Not Fasting"},{"t":"Orang yang Wajib Qada Puasa","p":430,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. telah berkata: Sesiapa yang pernah sakit, kemudian ia sihat kembali, sedang ia belum juga mengerjakan puasanya yang tinggal, hingga telah didapatinya pula Ramadan yang lain, hendaklah dipuasakannya Ramadan yang telah didapatinya itu. Kemudian dipuasakan pula bulan yang dia telah berbuka padanya, dan hendaklah ia memberi makan seorang miskin pada hari-hari puasa yang telah ditinggalkannya itu.","r":"Daruqutni"}],"te":"Who Must Make Up the Fast"},{"t":"Orang yang Diwajibkan Membayar Fidyah Sahaja","p":430,"v":1,"d":[{"y":"a","s":2,"a":184,"b":184,"m":"Dan atas orang-orang yang tidak kuasa mengerjakan puasa, wajiblah ia membayar fidyah, iaitu memberi makan orang miskin"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya ia pernah berkata: Orang tua, biar laki-laki mahupun perempuan, yang keduanya tidak kuasa berpuasa, maka hendaklah keduanya memberi makan orang miskin tiap-tiap hari sebanyak hari puasa yang ditinggalkannya itu.","r":"Bukhari"},{"y":"h","x":"Dari Aisyah r.a. Bahawasanya Nabi s.a.w. bersabda: Sesiapa yang mati, dan di atasnya wajib puasa (Ramadan), boleh walinya mempuasakannya.","r":"Bukhari dan Muslim"}],"te":"Who Must Pay Only Fidyah"},{"t":"Puasa bagi Wanita Hamil atau yang Sedang Menyusukan Anak","p":432,"v":1,"d":[{"y":"h","x":"Dari Abu Qallabah r.a. dari seseorang laki-laki, telah berkata: Telah bersabda Rasulullah s.a.w.: Sesungguhnya Allah telah membolehkan meninggalkan seperdua sembahyang (sembahyang qasar) dan meninggalkan puasa bagi orang-orang yang sedang berjalan jauh (musafir) dan dibolehkan-Nya pula meninggalkan puasa itu bagi perempuan-perempuan hamil dan perempuan-perempuan yang sedang menyusukan.","r":"Abu Daud dan Nasai"}],"te":"Fasting for Pregnant and Breastfeeding Women"},{"t":"Meninggalkan Puasa Tanpa Sebab Syar'i","p":433,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang berbuka satu hari saja di bulan Ramadan dengan tidak ada halangan penting yang dibenarkan oleh Allah kepadanya (kelonggaran) yang tidak dapat diqadanya itu dengan puasa satu masa, andaikata dipuasakannya.","r":"Bukhari dan Tirmizi"}],"te":"Leaving the Fast Without a Valid Reason"},{"t":"Jumlah Hari Bulan Ramadan","p":434,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. telah berkata: Nabi s.a.w. telah bersabda: Sesungguhnya kami hamba yang buta huruf, kami tak pandai menulis dan tak pandai menghitung. Adapun sebulan adalah sekian dan sekian iaitu adakalanya 29 dan adakalanya 30 hari.","r":"Bukhari"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Selama aku berpuasa bersama Rasulullah s.a.w yang 29 hari itu lebih banyak daripada puasaku bersama beliau yang 30 hari.","r":"Daruqutni"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Sesungguhnya selama kami berpuasa bersama dengan Rasulullah s.a.w 29 hari lebih banyak daripada puasa kami yang 30 hari.","r":"Abu Daud"}],"te":"Number of Days in Ramadan"},{"t":"Puasa Tatawwuk","p":435,"v":1,"d":[{"y":"h","x":"Dari Abu Ayyub r.a. ia berkata: Telah bersabda Nabis.a.w.: Sesiapa yang puasa bulan Ramadan, dan diiringinya dengan puasa enam hari di bulan Syawal, maka seolah-olah ia telah memuasakan satu tahun (iaitu pahala puasa satu tahun).","r":"Muslim"},{"y":"h","x":"Dari Usamah bin Zaid r.a. bahawasanya Nabi s.a.w. adalah memuaskan hari Isnin dan hari Khamis. Maka ditanya orang tentang itu, lalu beliau bersabda: Sesungguhnya amal ibadat didatangkan ke hadrat Tuhan pada hari Isnin dan hari Khamis.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Abu Qatadah r.a. bahawasanya Nabi s.a.w. pernah ditanya orang tentang puasa Asyura itu, lalu dijawabnya: Puasa itu gunanya ialah untuk menutup dosa di tahun yang lalu.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Nabi s.a.w. pernah bersabda: Demi jika aku masih hidup sampai tahun yang akan datang, nescaya aku puasakan hari yang ke 9 itu.","r":"Muslim"},{"y":"h","x":"Dari Qatadah r.a. bahawasanya Nabi s.a.w. pernah ditanya orang tentang puasa hari Arafah, maka beliau menjawab: Puasa itu ialah untuk menutup dosa setahun yang lalu dan setahun yang akan datang.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Bersabda Rasulullah s.a.w.: Tidaklah di antara beberapa hari amal yang salih yang lebih disukai Tuhan daripada hari-hari ini, iaitu hari-hari yang sepuluh ini.","r":"Bukhari"},{"y":"h","x":"Dari Qatadah bin Milhan r.a. ia berkata: Adalah Rasulullah s.a.w. menyuruh kami memuasakan hari putih, iaitu hari 13,14, dan hari 15.","r":"Abu Daud"}],"te":"Voluntary Fasting"},{"t":"Hari-Hari yang Diharamkan Berpuasa","p":438,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pn melarang puasa pada dua hari, iaitu hari raya Adha dan hari raya Fitri.","r":"Muslim"},{"y":"h","x":"Dari Nubaisyah Al-Huzalli. r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Hari Tasyrik itu adalah hari makan minum dan menyebut nama Allah Azza Wajalla.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w. Bila telah tinggal separuh dari bulan Syaaban, maka janganlah kamu puasakan juga.","r":"Tirmizi"},{"y":"h","x":"Dari Ammar bin Yasir r.a. ia berkata: Siapa yang memuaskan hari yang disyaki padanya, maka sungguh ia telah menderhakai Abu Qasim, iaitu Nabi Muhammad s.a.w.","r":"Abu Daud dan Tirmizi"}],"te":"Days on Which Fasting Is Forbidden"},{"t":"Hari-Hari yang Dimakruhkan Berpuasa","p":439,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. bersabda: Tidak boleh bagi seseorang berpuasa pada hari Jumaat kecuali apabila dipuasakannya pula hari yang sebelumnya atau sesudahnya.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Rasulullah s.a.w. bersabda: Tidaklah bererti puasa, orang yang puasa terus menerus (selama-lamanya) tidaklah ada ertinya puasa orang yang terus menerus, tidaklah ada ertinya puasa orang yang berpuasa terus menerus.","r":"Muslim"}],"te":"Days on Which Fasting Is Disliked"}],"p":427,"v":1,"te":"Breaking the Fast"},{"t":"Iktikaf","p":440,"v":1,"d":[{"y":"a","s":2,"a":125,"b":125,"m":"Hendaklah engkau berdua (Ibrahim dan Ismail) mensucikan rumah-Ku untuk yang tawaf, orang-orang yang iktikaf dan untuk orang yang rukuk dan yang sujud"},{"y":"h","x":"Dari Aisyah r.a. bahawasanya Rasulullah s.a.w. adalah beriktikaf pada sepuluh yang akhir dari bulan Ramadan hingga beliau meninggal dunia.","r":"Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Rasululllah s.a.w. bila beliau iktikaf, didekatkan kepalanya kepadaku lalu aku selesaikan rambutnya (aku beri minyak wangi) dan beliau tidak masuk ke rumah, kecuali kalau ada keperluan (hajat) manusia.","r":"Abu Daud"},{"y":"a","s":2,"a":186,"b":186,"m":"Dan janganlah kamu campuri mereka (isterimu) sedang kamu melakukan iktikaf dalam masjid"}],"te":"Retreat in the Mosque (Iktikaf)"},{"t":"Malam Qadar","p":442,"v":1,"d":[{"y":"a","s":97,"a":3,"b":5,"m":"Malam qadar itu, lebih baik dari seribu bulan. Pada malam itu turunlah malaikat-malaikat dan Jibril dengan izin Tuhan mereka, supaya mengatur segala pekerjaan. Selamatlah malam itu, hingga terbit fajar"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. bersabda: Sesiapa yang mendirikan (beribadat) pada malam qadar, dengan keimanan dan perhitungan (semata-mata mengharap keredaan Allah) diampuni Tuhan segala dosanya yang terdahulu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. telah berkata: Bersabda Nabi s.a.w.: Jaga-jagalah malam Qadar itu dalam sepuluh yang akhir dari Ramadan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia telah berkata: Telah bersabda Nabi s.a.w.: Jaga-jagalah malam Qadar itu pada malam yang ganjil di antara sepuluh malam yang akhir dari bulan Ramadan.","r":"Bukhari"},{"y":"h","x":"Dari Aisyah r.a. ia telah berkata: Telah bersabda Nabi s.a.w.: Jaga-jagalah malam Qadar itu pada malam yang ganjil di antara sepuluh malam yang akhir dari bulan Ramadan. (Diriwayatkan oleh Bukhari). Keterangan lain mengatakan, bahawa malam Qadar itu adanya sejak tanggal 17 bulan Ramadan. Kerana pada malam itulah turun Al-Quran. Kalau kita ditakdirkan Tuhan bertemu dengan malam Qadar itu maka perbanyaklah membaca doa minta selamat dunia dan akhirat kerana saatnya hanya sebentar. Terutama sekali doa yang diajarkan Nabi kepada Aisyah r.a. ketika Aisyah menanyakan doa apa yang akan dibaca bila bertemu dengan saat itu, maka Rasulullah s.a.w. bersabda kepadanya: La yg. LR se : '- 4. Sg sa 2 Senin Li a? G—-— — SL NI Si Ig) Katakanlah olehmu: Ya Allah! Sesungguhnya Engkau sangat pemaaf dan Engkau suka kepada maaf, oleh kerana itu maafkanlah kesalahanku.","r":"Tirmizi"}],"te":"The Night of Power (Lailatul Qadar)"},{"t":"Keutamaan Bulan Ramadan","p":444,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang berpuasa di bulan Ramadan dengan keimanan dan dengan perhitungan (dengan ikhlas semata-mata mengharapkan keredaan Allah) diampuni Tuhan segala dosanya yang terdahulu.","r":"Bukhari dan Muslim"},{"y":"a","s":2,"a":185,"b":185,"m":"Adapun bulan Ramadan itu padanya diturunkan Quran, akan jadi petunjuk bagi manusia dan jadi kenyataan dari petunjuk serta membezakan antara yang hak dan yang batil"},{"y":"h","x":"Dari Wasilah bin Asqak r.a. Bahawasanya Rasulullah s.a.w. telah bersabda: Diturunkan Suhuf Ibrahim di awal bulan Ramadan, diturunkan Taurat setelah lewat enam Ramadan, Injil diturunkan setelah lewat tiga belas bulan Ramadan, sedang Allah menurunkan Al-Quran setelah lewat hari dua puluh empat bulan Ramadan.","r":"Imam Ahmad"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. bersabda: Bila telah datang bulan Ramadan, terbukalah pintu-pintu syurga, dan terkuncilah pintu-pintu neraka dan terbelenggulah syaitansyaitan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tiap-tiap amalan anak Adam dipergandakan pahalanya antara sepuluh sampai 700 kali, Allah Azza Wajalla telah berfirman: Kecuali puasa, kerana sesungguhnya puasa itu untuk-Ku dan Akulah yang akan membalasnya, ditinggalkannya keinginan hawa nafsunya dan makannya kerana Aku semata-mata.","r":"Muslim"},{"y":"h","x":"Dari Sahal bin Saad r.a. Sesungguhnya Nabi s.a.w. bersabda: Sesungguhnya di dalam syurga ada sebuah pintu yang dinamakan orang Ar-Rayyan yang akan memasukkannya pada hari kiamat oleh orang-orang yang puasa dan tidak seorang juga akan memasukinya selain mereka.","r":"Bukhair dan Muslim"}],"te":"Virtues of the Month of Ramadan"},{"t":"Rahsia dan Hikmat Berpuasa","p":446,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Adapun puasa itu sebagai perisai, dan apabila seseorang puasa, maka janganlah ia mencaci maki orang dan jangan pula menaruh dendam kesumat.","r":"Bukhari"}],"te":"The Inner Meaning and Wisdom of Fasting"}],"p":412,"v":1,"d":[{"y":"a","s":2,"a":183,"b":184,"m":"Hai orang-orang yang beriman. Diwajibkan berpuasa di atasmu, sebagaimana puasa itu telah diwajibkan di atas orang-orang sebelum kamu, mudah-mudahan kamu menjadi orang yang takut (memelihara diri). Lamanya berpuasa itu pada beberapa hari yang dapat dihitung. Maka sesiapa yang sedang sakit di antaramu atau sedang berjalan, maka boleh puasa itu dikerjakan pada hari yang lain. Dan di atas mereka yang tidak kuat berpuasa, boleh membayar fidyah, iaitu memberi makanan orang miskin. Maka sesiapa yang menambah kebajikan maka itu lebih baik baginya. Dan kalau kamu berpuasa, itu lebih baik bagimu, jika kamu mengetahui"}],"te":"Book of Fasting"},{"t":"Kitab Haji","c":[{"t":"Asas Haji","p":450,"v":1,"c":[{"t":"Erti Haji","p":450,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. pernah datang seorang laki-laki kepada Nabi s.a.w. lalu ia bertanya: Ya Rasulullah: apakah yang mewajibkan (syarat wajib) pergi haji? Rasulullah menjawab: Ada bekal dan kenderaan.","r":"Tirmizi"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Dan tidak boleh perempuan berjalan jauh, melainkan berserta dengan muhrimnya.","r":"Muslim"}],"te":"Meaning of Hajj"},{"t":"Seruan Haji dan Keutamaannya","p":452,"v":1,"d":[{"y":"a","s":22,"a":27,"b":27,"m":"Dan beritahukanlah kepada manusia untuk mengerjakan haji, nescaya mereka itu datang kepadamu dengan berjalan kaki, dan dengan berkenderaan dari tiap-tiap negeri yang jauh"},{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Sesiapa yang pergi naik haji, lalu ia tidak mengerjakan dosa, dan tidak pula berbuat kederhakaan (kafir) kepada Tuhan, kembalilah ia seperti pada hari ia dilahirkan oleh ibunya.","r":"Bukhari dan Muslim"}],"te":"The Call to Hajj and Its Virtues"},{"t":"Haji hanya Wajib Sekali Seumur Hidup","p":453,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Aqrak bin Habis pernah bertanya: Ya Rasulullah, apakah haji itu wajib dikerjakan tiap tahun, atau cukup satu kali saja. Rasulullah s.a.w. menjawab: Ya, yang wajib hanyalah satu kali saja, Maka sesiapa yang mahu menambahnya maka itu tatawwuk (sunat).","r":"Abu Daud dan Nasai"}],"te":"Hajj Is Obligatory Only Once in a Lifetime"},{"t":"Mengerjakan Haji untuk Orang Lain","p":453,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya seorang perempuan pernah. bertanya: Ya Rasulullah, sesungguhnya diwajibkan Tuhan atas hamba-Nya pergi menunaikan ibadat haji, aku dapati bapaku telah tua dan tak kuat lagi berkenderaan, bolehkah aku membayarkan haji? Rasulullah s.a.w. menjawab: Ya, boleh.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Nabi s.a.w. pernah mendengar seorang laki-laki berkata: Inilah aku ya Allah untuk Syubrumah. Bertanya Rasulullah: Siapakah Syubrumah itu? Laki-laki itu menjawab: Saudara atau familiku ya Rasulullah. Maka bersabda Rasulullah s.a.w.: Sudah hajikah engkau untuk diri engkau? Ia menjawab: Belum! Bersabda pula Rasulullah s.a.w: Hajilah engkau lebih dahulu untuk diri engkau, kemudian haji pulalah engkau untuk Syubrumah.","r":"Abu Daud dan Ibnu Majah"}],"te":"Performing Hajj for Someone Else"},{"t":"Membawa Anak-Anak Pergi Haji","p":454,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Nabi s.a.w. pernah bertemu dengan sebuah kenderaan di Rauhak, lalu Nabi bertanya: Siapakah kaum ini? Mereka menjawab: Kaum Muslimin. Dan mereka bertanya: Siapakah tuan? Nabi menjawab: Aku Rasulullah. Maka seorang perempuan mengangkatkan seorang anak kecil laki-laki kepadanya, lalu bertanya: Adakah boleh anak ini naik haji? Rasulullah s.a.w. menjawab: Boleh, dan bagi engkaulah pahalanya.","r":"Muslim"}],"te":"Taking Children on Hajj"},{"t":"Naik Haji Sambil Berniaga","p":455,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia telah berkata: Sesungguhnya manusia di mula-mula haji diwajibkan, mereka pernah berjual belidi Mina, di Arafah, di pasar Zil Majaz (satu tempat di dekat Arafah) dan di musim haji, lalu mereka takut berjual beli, lantaran mereka sedang ihram (sedang mengerjakan ibadat haji), maka Allah menurunkan ayat: Tidaklah berdosa kamu, apabila kamu mencari kurnia Tuhanmu di waktu musim haji.","r":"Bukhari dan Muslim"}],"te":"Going on Hajj While Trading"}],"te":"Basics of Hajj"},{"t":"Ihram","c":[{"t":"Ihram dengan Umrah","p":456,"v":1,"d":[{"y":"a","s":2,"a":158,"b":158,"m":"Maka sesiapa yang hendak melakukan haji ke Baitullah atau melakukan umrah, maka tidaklah menjadi halangan baginya bahawa ia berlari-lari antara keduanya"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Rasulullah s.a.w. : telah menjadikan miqat penduduk Madinah di Zul-Hulaifah, miqat penduduk Syam di Juhfah, miqat penduduk Najd Qarnil-Manazil, miqat penduduk yaman di Yalamlam. Lalu Nabi bersabda: Semua tempat itu adalah bagi miqat mereka dan bagi tiap-tiap orang yang datang yang bukan dari tempat itu, iaitu orang-orang yang hendak melakukan haji dan umrah, dan orang-orang lain selain mereka, maka miqatnya ialah sekira-kira dari arah mana ia datang itu, hingga penduduk Mekah miqatnya ialah di Mekah itu.","r":"Muslim"}],"te":"Ihram for Umrah"},{"t":"Mandi sebelum Memakai Kain Ihram","p":457,"v":1,"d":[{"y":"h","x":"Dari Zaid bin Sabit r.a. telah berkata: Pernah aku melihat Nabi s.a.w. melepaskan pakaiannya yang biasa, untuk mengerjakan ihramnya, dan beliau mandi lebih dahulu.","r":"Tirmizi"}],"te":"Bathing Before Putting on Ihram"},{"t":"Kain yang Dipakai untuk Ihram","p":457,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya seorang laki-laki pernah bertanya kepada Rasulullah s.a.w.: Kain apakah yang akan dipakai oleh orang ihram? Maka Rasulullah s.a.w. menjawab: Janganlah kamu pakai baju kurung (gamish) dan jangan pula serban, dan jangan pula seluar dan jangan pula kasut tinggi, dan jangan pula kasut, kecuali seseorang yang tak mempunyai selipar, maka boleh ia memakai kedua kasut (chap), dan hendaklah dikeratnya kedua kasut itu agak di bawah mata kakinya dan jangan pula kamu pakaipakaian yang diberi wangi-wangian.","r":"Muslim"}],"te":"Clothing Worn for Ihram"},{"t":"Orang yang tidak Mempunyai Cadar, boleh Memakai Seluar","p":458,"v":1,"d":[{"y":"h","x":"Dari Jabirr. a. ia telah berkata: Rasulullah s.a.w bersabda: Sesiapa yang tidak mempunyai selipar maka bolehlah memakai kasut, dan sesiapa yang tidak mempunyai kain lepas, maka bolehlah memakai seluar.","r":"Muslim"}],"te":"One Without a Waist Wrap May Wear Trousers"},{"t":"Haram Menutup Kepala bagi Kaum Laki-Laki dan Wajib bagi Kaum Wanita","p":459,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. Sesungguhnya Nabi s.a.w. pernah bersabda tentang seorang yang ihram yang jatuh dari untanya lalu mati: Janganlah kamu tutup kepadalanya, kerana kepala itu di hari kiamat dibangkitkan Allah dalam keadaan membaca Talbiyah.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah aku dengar Rasulullah s.a.w. melarang perempuan-perempuan memakai sarung tangan, dan tutup muka ketika ihram.","r":"Abu Daud, Tirmizi dan lain-lain"}],"te":"Covering the Head Is Forbidden for Men and Required for Women"},{"t":"Melafazkan Niat untuk Umrah","p":460,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. Telah tahallul (ihram) Nabi s.a.w. dengan umrah, dan telah tahallul (ihram) pula sahabat-sahabatnya dengan haji. ?","r":"Muslim"},{"y":"h","x":"Dari Jabir r.a. telah berkata: Pernah kami datang (ke Mekah) berserta dengan Rasulullah s.a.w. sedang kami membaca talbiyah haji, lalu kami disuruh oleh Rasulullah s.a.w. supaya talbiyah itu dijadikan untuk umrah.","r":"Muslim"}],"te":"Stating the Intention for Umrah"},{"t":"Membaca Kalimat Talbiyah","p":460,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. Sesungguhnya Talbiyah Rasulullah s.a.w. ialah: Aku sambut panggilan-Mu ya Allah, aku sambut panggilan-Mu. Aku sambut panggilan-Mu, tidak ada sekutu bagi-Mu. Aku sambut panggilanmu, sesungguhnya bagi-Mulah segala puji dan segala kenikmatan serta kerajaan. Tidak ada sekutu bagiMu.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Hendaklah dibaca talbiyah itu oleh orang umrah, sampai ia meraba Hajar Aswad.","r":"Abu Daud dan Tirmizi"}],"te":"Reciting the Talbiyah"}],"p":456,"v":1,"te":"Ihram"},{"t":"Tawaf","c":[{"t":"Tawaf Qudum dan Ertinya","p":461,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia telah berkata: Sesungguhnya mula-mula sesuatu yang dimulai oleh Rasulullah s.a.w. ketika beliau sampai di Mekah, ialah beliau berwuduk kemudian beliau tawaf ke Kaabah (mengelilingi Kaabah.)","r":"Bukhari dan Muslim"}],"te":"Arrival Tawaf (Qudum) and Its Meaning"},{"t":"Cara Mengerjakan Tawaf","p":462,"v":1,"d":[{"y":"h","x":"Dari Abdullah bin Saib r.a. ia telah berkata: Pernah aku dengar Rasulullah s.a.w. membaca antara tiang Yamani dan Hajar Aswad: Hai Tuhan kami, datangkanlah kepada kami kebahagiaan di dunia, dan kebaikan di akhirat dan peliharalah kami dari api neraka.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Telah tawaf Rasulullah s.a.w. ketika sampai di Mekah, lalu dirabanya tiang (Hajar) pada permulaan melakukan sesuatu perbuatan, kemudian beliau berlarilari berkeliling tiga kali dari yang tujuh, dan beliau berjalan berkeliling empat kali.","r":"Bukhari dan Muslim"}],"te":"How to Perform Tawaf"},{"t":"Sembahyang Dua Rakaat Tawaf","p":464,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. bahawasanya Nabi s.a.w. tatkala sampai ke makam Ibrahim, dibaca: Dan mereka jadikan makam Ibrahim akan tempat sembahyang. Lalu beliau sembahyang dua rakaat, maka dibacanya Fatihah dan surah Al-Kafirun dan surah Al-Ikhlas. Kemudian beliau kembali ke rukuk (tiang Hajar Aswad) lalu beliau meraba tiang itu.","r":"Muslim"}],"te":"Two Rakaat After Tawaf"},{"t":"Perempuan yang Haid tidak boleh Tawaf","p":464,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia telah berkata: Telah bersabda Rasulullah s.a.w.: Orang haid itu boleh menunaikan rukun semua hajinya, kecuali tawaf di Kaabah.","r":"Ahmad"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Umar telah mencium Hajar Aswad dan ia berkata: Bahawasanya aku mencium engkau dan aku sungguh mengetahui, bahawa engkau batu, akan tetapi telah aku lihat Rasulullah mencium engkau.","r":"Muslim"}],"te":"A Menstruating Woman May Not Perform Tawaf"},{"t":"Sai antara Bukit Safa dan Marwa","p":465,"v":1,"d":[{"y":"a","s":2,"a":158,"b":158,"m":"Sesungguhnya bukit Safa dan bukit Marwa itu adalah dari syiar Allah, maka sesiapa yang haji atau umrah, maka tidaklah dosa atasnya bahawa ia tawaf (berlari-lari pergi balik) antara kedua tempat itu, dan sesiapa yang menambah kebaikan (melakukan amal sunat) maka sesungguhnya Allah Maha bersyukur lagi Maha mengetahui"},{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Pernah datang Nabi s.a.w. ke Mekah, lalu beliau tawaf di Kaabah tujuh kali dan sembahyang dua rakaat di belakang makam Ibrahim dan tawaf (sai) antara bukit Safa dan Marwa tujuh kali (pergi balik), dan sungguh adalah perbuatan Rasulullah s.a.w. akan jadi ikutan yang baik bagimu.","r":"Bukhari dan Muslim"}],"te":"Sa'i Between Safa and Marwah"},{"t":"Sai Dimulai dari Bukit Safa","p":466,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. bahawasanya ia telah menceritakan tentang sifat haji Rasulullah s.a.w. sesudah ia sembahyang di belakang makam Nabi Ibrahim, lalu ia bersabda: Kemudian keluar Rasulullah s.a.w. dari pintu Kaabah itu ke bukit Safa, maka apabila beliau telah dekat di Safa beliau berdoa: Sesungguhnya Safa dan Marwa adalah dari Syiar Allah. Mulailah olehmu dengan apa yang telah dimulai oleh Allah. Maka beliau memulakan di bukit Safa lalu naik ke atasnya hingga beliau melihat Kaabah, kemudian beliau menghadap 'ke Kiblat, lalu beliau mentauhidkan Allah dan membesarkan-Nya. Kemudian beliau bersabda: Tidak ada tuhan melainkan Allah Yang Esa, tidak ada sekutu bagi-Nya. Bagi-Nya kerajaan dan bagi-Nya segala puji. Dan Allah berkuasa atas segala sesuatu. Tidak ada tuhan selain Allah yang telah menunaikan janji-Nya, telah menolong hamba-Nya dan telah memburu tentera kaum yang bersekutu memusihi Islam dengan sendiri-Nya.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Jabirr.a. Sesungguhnya Nabi s.a.w. apabila mengerjakan haji Wadak beliau datang ke bukit Marwa, beliau mengerjakan di situ seperti yang dikerjakan di bukit Safa.","r":"Muslim dan Abu Daud"}],"te":"Sa'i Begins at Safa"},{"t":"Bercukur sesudah Sai","p":466,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah bersabda Rasulullah s.a.w. di waktu haji Wadak. Maka hendaklah mengerjakan tawaf di rumah Allah dan bukit Safa dan Marwa, dan hendaklah ia bercukur dan bertahallul, kemudian hendaklah ia membaca talbiah haji.","r":"Bukhari dan Muslim"}],"te":"Shaving After Sa'i"}],"p":461,"v":1,"te":"Tawaf"},{"t":"Wuquf","c":[{"t":"Ihram dengan Haji dan Erti Wukuf","p":468,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Inilah aku ya Allah, aku hendak mengerjakan umrah dan haji.","r":"Muslim"}],"te":"Ihram for Hajj and the Meaning of Wuquf"},{"t":"Membaca Takbir, Zikir, Talbiyah dan Doa","p":469,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah kami berjalan pagipagi hari bersama dengan Rasulullah s.a.w. dari Mina ke Arafah, sebahagian kami membaca talbiyah dan sebahagian lagi membaca takbir.","r":"Muslim"},{"y":"h","x":"Dari Umar bin Syuaib, dari bapanya, dari datuknya dari Nabi s.a.w. beliau bersabda: Sebaik-baik doa ialah pada hari Arafah.","r":"Tirmizi"}],"te":"Reciting Takbir, Zikir, Talbiyah and Supplication"},{"t":"Waktu Mulai Wukuf","p":469,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Raulullah s.a.w. pernah berjalan dari Mina pagi-pagi hari ketika telah sembahyang Subuh pada hari Arafah, sehingga beliau sampai ke Arafah. Lalu beliau turun di Namrah, sehingga sampai pada waktu sembahyang Zuhur. Maka Raulullah s.a.w. berjalan waktu tengahari panas itu, maka dijamakkan sembahyang Zuhur dengan Asar, kemudian beliau berkhutbah kepada orang ramai, kemudian beliau berjalan lagi sehingga tiba di tempat wukuf, iaitu padang Arafah.","r":"Ahmad dan Abu Daud"}],"te":"When Wuquf Begins"},{"t":"Bertolak dari Arafah ke Muzdalifah","p":470,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. bahawasanya Nabi s.a.w. telah datang ke Muzdalifah, maka dikerjakannya sembahyang Isyak dan Maghrib di sana dengan satu azan dan dua iqamat, serta tidak mengucapkan tasbih sama sekali antara keduanya, kemudian Nabi berbaring hingga terbit fajar, maka dikerjakannya sembahyang Subuh (di awal waktunya) hingga telah nyata kepadanya waktu Subuh dengan azan dan iqamat.","r":"Muslim"},{"y":"a","s":2,"a":198,"b":198,"m":"Maka apabila kamu bertolak dari Arafah, maka ingatlah Allah di dekat Masy'aril Haram, dan sebutlah nama-Nya sebagaimana Ia telah menunjukkan engkau"}],"te":"Leaving Arafah for Muzdalifah"}],"p":468,"v":1,"te":"Standing at Arafah (Wuquf)"},{"t":"Melempar Jumrah","c":[{"t":"Erti Melempar Jumrah","p":471,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas dan Usamah bin Zaid r.a. keduanya berkata: Nabi s.a.w. sentiasa membaca talbiah sehingga beliau melempar Jumrah Aqabah. :","r":"Bukhari"}],"te":"Meaning of Stoning the Jamarat"},{"t":"Berkorban sesudah Melempar","p":472,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. bahawa Nabi s.a.w. telah datang ke Mina, di situ beliau datang untuk melempar Jumrah (Aqabah), lalu dilemparnya Jumrah itu. Kemudian setelah beliau kembali ke tempatnya di Mina beliau berkorban, kemudian bersabda kepada tukang cukur: Ambillah (cukurlah). Beliau mengisyaratkan ke bahagian yang kanan kemudian ke bahagian kiri, kemudian rambutnya itu dibagi-bagikan kepada orang-orang (untuk mengambil berkat).","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia telah berkata: Pernah kami berkorban dengan seekor unta betina bersama dengan Rasulullah s.a.w. pada tahun Hudaibiah, untuk kami tujuh orang, dan seekor sapi untuk kami tujuh orang.","r":"Muslim dan Abu Daud"}],"te":"Sacrifice After Stoning"},{"t":"Boleh Memakai Kain Biasa sesudah Melempar Jumrah","p":473,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Rasulullah s.a.w. bersabda: Bila kamu telah melempar Jumrah, maka sesungguhnya telah halal bagimu segala sesuatu selain perempuan (maksudnya bersetubuh).","r":"Ahmad dan Abu Daud"}],"te":"Wearing Ordinary Clothes After Stoning"},{"t":"Bermalam di Mina Selama Hari Tasyrik","p":473,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. sesungguhnya ia telah melempar Jumrah dunia dengan tujuh buah batu, dibacanya takbir sesudah melemparkan tiap-tiap batu itu, kemudian ia maju ke depan, lalu ia mendatar (berjalan di tempat yang datar) lalu ia berdiri menghadap ke kiblat, dan berdiri agak lama, lalu ia berdoa dan diangkatnya kedua tangannya, kemudian dilemparnya Jumrah Wusta. Seperti demikian pula, maka diambilnya arah sebelah kiri, lalu ia mendatar pula, dan berdiri menghadap ke kiblat berdiri yang agak lama, lalu berdoa pula dan diangkatnya dua tangannya, kemudian dilemparnya Jumrah Aqabah dari dalam lembah (mahsar) tetapi ia tidak berdiri di dekatnya. Dan ia berkata: Beginilah aku lihat Nabi s.a.w. melakukannya.","r":"Bukhari"}],"te":"Staying the Nights at Mina on the Days of Tasyrik"},{"t":"Permulaan Waktu Melempar","p":475,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. bahawasanya Nabi s.a.w. tinggal di Mekah, hingga beliau sembahyang Zuhur, kemudian kembali ke Mina, lalu beliau tinggal pula di sana selama hari tasyrik yang tiga, beliau melempar Jumrah Pertama (Jumrah Kubra), dengan tujuh buah batu. Apabila matahari telah tergelincir pada tiap-tiap melempar itu beliau membaca takbir.","r":"Abu Daud dan Baihaqi"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Rasulullah s.a.w. telah melempar jumrah di hari nahar di waktu matahari naik. Dan yang sesudah itu, apabila matahari telah tergelincir.","r":"Muslim dan Abu Daud"}],"te":"When Stoning Begins"},{"t":"Tawaf Ifadah","p":476,"v":1,"d":[{"y":"h","x":"Dari Ibni Umar bahawasanya Nabi s.a.w. telah melakukan tawaf ifadah di hari Nahar, kemudian beliau kembali lalu sembahyang Zuhur di Mina pada hari Nahar.","r":"Bukhari dan Muslim"},{"y":"a","s":22,"a":29,"b":29,"m":"Dan hendaklah mereka tawaf di rumah Allah (Kaabah)"}],"te":"Tawaf al-Ifadah"},{"t":"Minum Air Zamzam dan Keberkatannya","p":476,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. bahawasanya Nabi s.a.w. sesudah tawaf ifadah, beliau datang kepada mereka (sahabat-sahabat) dan mereka sedang menyauk air telaga zamzam, lalu mereka saukkan pula untuk Rasulullah s.a.w. setimba, lalu diminumnya air itu.","r":"Muslim"},{"y":"h","x":"Dari Abu Zar r.a. bahawasanya Rasulullah s.a.w. bersabda tentang air zam-zam: Sesungguhnya air itu ialah makanan dan ubat demam.","r":"Muslim"}],"te":"Drinking Zamzam Water and Its Blessing"}],"p":471,"v":1,"te":"Stoning the Jamarat"},{"t":"Pembahagian Ihram","c":[{"t":"Waktu Memulai Mengerjakan Haji dan Umrah","p":478,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bulan-bulan haji itu ialah Syawal, Zulkaedah dan sepuluh hari dari Zulhijah.","r":"Bukhari"},{"y":"a","s":2,"a":197,"b":197,"m":"Haji itu ialah pada bulan-bulan yang ditentukan"}],"te":"When to Begin Hajj and Umrah"},{"t":"Cara Mengerjakan Fardu Haji","p":478,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Sebahagian dari kami mengerjakan haji secara ifrad, dan sebahagian mengerjakan haji secara qaran dan sebahagian dengan cara bertamattuk.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesiapa yang telah ihram haji dan umrah bersama-sama, cukuplah baginya satu kali tawaf dan satu kali sai saja.","r":"Tirmizi dan Ibnu Majah"}],"te":"How to Perform the Obligatory Acts of Hajj"},{"t":"Keutamaan Haji dan Umrah","p":480,"v":1,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. berkata: Nabi s.a.w. bersabda: Ikutkanlah olehmu antara haji dan umrah, kerana sesungguhnya keduanya menghilangkan dosa, sebagaimana tukang tempa menghilangkan karat besi, karat emas dan perak, dan tidak ada pahala bagi haji yang baik itu melainkan syurga.","r":"Nasai dan Tirmizi"}],"te":"Virtues of Hajj and Umrah"},{"t":"Mengerjakan Umrah sesudah Haji","p":480,"v":1,"d":[{"y":"h","x":"Dari Aisyahr.a. bahawasanya tatkala ia keluar bersama Rasulullah s.a.w. pada haji wadak, ia sedang haid, maka ia mengerjakan seperti apa yang dikerjakan oleh orang haji, kecuali tawaf, kemudian ia berkata: Tatkala kami menunaikan ibadat haji, aku disuruh oleh Rasulullah s.a.w. bersama Abdur Rahman bin Abu Bakar ke Tawim, maka akupun umrah. Lalu Abdur Rahman berkata: Inilah tempat umrah kamu.","r":"Bukhari dan Muslim"}],"te":"Performing Umrah After Hajj"},{"t":"Denda yang Wajib Waktu Ihram","p":481,"v":1,"d":[{"y":"a","s":2,"a":196,"b":196,"m":"Maka sempurnakanlah olehmu haji dan umrah kerana Allah. Maka apabila kamu terkepung oleh musuh (terhalang), maka sembelihlah binatang korban yang mudah didapati"},{"y":"a","s":2,"a":196,"b":196,"m":"Dan janganlah kamu cukur kepalamu, hingga telah sampai hadiah itu ke tempatnya, maka sesiapa di antaramu yang sakit atau ada penyakit di kepalanya, wajiblah ia membayar denda, iaitu berpuasa (tiga hari), atau memberi sedekah (tiga gantang untuk enam orang fakir miskin) atau pengorbanan yang lain memotong binatang"},{"y":"a","s":2,"a":196,"b":196,"m":"Maka sesiapa yang telah bertamattuk dengan umrah hingga haji, maka hendaklah diberikannya hadiah yang mudah diperolehnya, maka siapa yang tidak dapat berhadiah, maka puasalah ia tiga hari pada waktu haji dan tujuh hari bila ia telah kembali, jumlah semuanya itu ialah genap sepuluh hari. Ke1. Keterangan mengenai puasa tiga hari, atau memberi makan 6 orang fakir miskin berasal daripada Hadis Bukhari Muslim, dari Kaab bin Ujrah: wajipan itu ialah bagi orang-orang yang keluarganya tidak tinggal di Masjidilharam. |"},{"y":"a","s":5,"a":95,"b":95,"m":"Hai orang-orang yang beriman, janganlah kamu bunuh binatang buruan itu ketika kamu sedang dalam ihram. Sesiapa di antaramu yang membunuhnya dengan sengaja, adalah balasannya seekor binatang yang dibunuh itu, menurut ketetapan dua orang yang adil di antara kamu. Binatang yang disembelih itu sebagai hadiah yang disampaikan kepada penduduk Mekah dan disedekahkan kepada orang-orang miskin. Boleh juga gantinya memberi makanan beberapa orang miskin atau puasa beberapa hari, supaya dirasakannya keberatan perbuatannya itu"}],"te":"Penalties Owed During Ihram"}],"p":477,"v":1,"te":"Kinds of Ihram"},{"t":"Rukun Haji dan Umrah","c":[{"t":"Yang Diharamkan bagi Orang yang Sedang Ihram","p":484,"v":1,"d":[{"y":"h","x":"Dari Usman bin Affan r.a. bahawasanya Rasulullah s.a.w. telah bersabda: Orang-orang yang sedang ihram itu tak boleh kahwin dan tak boleh pula mengahwinkan dan tak boleh pula meminang.","r":"Muslim"}],"te":"What Is Forbidden in Ihram"},{"t":"Binatang-Binatang yang Halal Dibunuh Waktu Ihram","p":485,"v":1,"d":[{"y":"h","x":"Dari Aisyah r.a. telah berkata: Rasulullah s.a.w. bersabda: Lima macam binatang yang semuanya itu merosakkan, maka binatang itu boleh dibunuh di waktu halal mahupun di waktu ihram, iaitu; kala, burung helang, gagak, tikus dan anjing yang ganas.","r":"Bukhari dan Muslim"}],"te":"Animals That May Be Killed in Ihram"},{"t":"Luput Ibadat Haji Kerana Luput Wukuf di Arafah","p":485,"v":1,"d":[{"y":"h","x":"Dari Abdur Rahman bin Ya'mar Ad-Dili r.a. ia telah berkata: Pernah aku datang kepada Nabi s.a.w. sedang beliau di Arafah, hingga katanya: Maka Nabi s.a.w. menyuruh seorang laki-laki supaya memanggil manusia. Maka ia berseru di kalangan manusia: Haji, haji ialah pada hari wuquf di Arafah.","r":"Abu Daud dan Tirmizi"}],"te":"Missing Hajj by Missing Wuquf at Arafah"}],"p":484,"v":1,"te":"Pillars of Hajj and Umrah"},{"t":"Menziarahi Kuburan Nabi ke Madinah","c":[{"t":"Keutamaan Mekah dan Madinah","p":486,"v":1,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w. tentang Mekah Al-Haram: Tak boleh diburu binatang buruannya, tidak boleh dipotong kayu-kayannya dan tidak halal diambil barang yang tercicir kecuali untuk memberitahukannya, maka sesiapa yang terbunuh keluarganya, maka dia boleh memilih antara dua pilihan; pertama ia boleh menerima tebusan, dan yang kedua ia boleh menuntut balasan supaya yang membunuh itu dibunuh pula.","r":"Muslim"},{"y":"h","x":"Dari Anas bin Malik r.a. ia berkata: Telah berdoa Rasulullah s.a.w.: Ya Allah, jadikanlah keberkatan kota Madinah ini dua kali ganda dari keberkatan kota Mekah.","r":"Muslim"}],"te":"Virtues of Makkah and Madinah"},{"t":"Keutamaan Sembahyang di Masjid Madinah","p":487,"v":1,"te":"Virtue of Praying in the Mosque of Madinah"},{"t":"Tawaf Wadak","p":488,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Adalah manusia berpaling ke tiap-tiap jihat, lalu Rasulullah s.a.w. bersabda: Belum boleh pergi salah seorang di antara kamu hingga ada akhir kewajipannya di rumah Allah.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Diperintah manusia supaya adalah akhir kewajipannya (melakukan pekerjaan wajib) di rumah Allah, kecuali telah diiringkan pekerjaannya. itu dari perempuan yang sedang haid.","r":"Muslim"}],"te":"Farewell Tawaf (Wada')"}],"p":486,"v":1,"d":[{"y":"h","x":"Dari Anas r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang menziarahi aku ke Madinah kerana mengharapkan pahala dari Allah, adalah ia dalam pangkuanku, dan adalah aku akan memberinya syafaat di hari kiamat.","r":"Baihaqi"}],"te":"Visiting the Prophet's Grave in Madinah"},{"t":"Rahsia dan Hikmat Ibadat Haji dan Umrah","c":[{"t":"Rahsia Memakai Kain Ihram","p":489,"v":1,"te":"The Meaning of Wearing Ihram Cloth"},{"t":"Rahsia Tawaf di Kaabah","p":489,"v":1,"te":"The Meaning of Tawaf Around the Kaabah"},{"t":"Rahsia Mengerjakan Sai","p":490,"v":1,"te":"The Meaning of Sa'i"},{"t":"Rahsia Wukuf di Padang Arafah","p":491,"v":1,"te":"The Meaning of Wuquf at Arafah"},{"t":"Rahsia Melontar Jumrah di Mina","p":491,"v":1,"te":"The Meaning of Stoning at Mina"}],"p":489,"v":1,"te":"The Inner Meaning and Wisdom of Hajj and Umrah"},{"t":"Berkorban","c":[{"t":"Erti Berkorban","p":491,"v":1,"d":[{"y":"a","s":22,"a":34,"b":34,"m":"Dan bagi tiap-tiap umat, Kami jadikan tempat berkorban (supaya ia berkorban), agar mereka mengingat nama Allah atas apa direzekikan-Nya kepada mereka, dari binatang-binatang ternak. Maka Tuhanmu itu ialah Tuhan yang Esa, maka hendaklah kepada-Nya kamu berserah diri, dan berilah khabar gembira (hai Muhammad) orang-orang yang tunduk kepada-Nya"},{"y":"h","x":"Dari Abdullah bin Aun ia telah berkata: Bersabda Rasulullah s.a.w.: Hai manusia, sesungguhnya atas tiap-tiap ahli rumah pada tiap tahun disunatkan berkorban.","r":"Abu Daud"}],"te":"Meaning of Sacrifice"},{"t":"Tarikh Berkorban","p":492,"v":1,"d":[{"y":"h","x":"Dari Ummu Salamah r.a. bahawasanya Nabi s.a.w. telah bersabda: Bila telah masuk 10 haribulan Zulhijah dan salah seorang di antara kamu hendak berkorban, maka tidaklah boleh disentuhnya rambut dan kulitnya sedikit pun.","r":"Muslim"},{"y":"h","x":"Dari Barrak bin Azib r.a. berkata: Nabi s.a.w. bersabda: Empat macam binatang yang tak boleh untuk berkorban, iaitu binatang buta yang nyata butanya (rosak matanya sebelah), binatang sakit yang nyata sakitnya, binatang pincang yang nyata kepincangannya dan binatang yang kurus yang tidak ada sumsumnya lagi.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Jubair bin Mut'im r.a. ia berkata: Raulullah s.a.w. bersabda: Tiap-tiap hari tasyrik itu waktu berkorban.","r":"Baihaqi"}],"te":"Dates of the Sacrifice"},{"t":"Tidak Sah Berkorban dengan Binatang yang Bercacat","p":494,"v":1,"d":[{"y":"h","x":"Dari Ali r.a. ia telah berkata: Kami telah diperintah oleh Rasulullah s.a.w. supaya kami muliakan mata dan dua telinga, dan kami tak boleh berkorban dengan binatang yang buta dan tidak pula yang sumbing pinggir telinganya, dan tidak pula yang rosak pangkal telinganya dan tidak pula yang kopek telinganya sebelah bawah dan tidak pula yang belah telinganya sebelah atas.","r":"Abu Daud"},{"y":"a","s":3,"a":92,"b":92,"m":"Sekali-kali kamu takkan mencapai kebaikan, hingga kamu belanjakan (sedekahkan) mana yang paling kamu cintai"},{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Adalah Rasulullah s.a.w. menyembelih dan berkorban di tanah lapang (tempat sembahyang).","r":"Bukhari"}],"te":"A Defective Animal Is Not Valid for Sacrifice"},{"t":"Menyembelih Korban sesudah Selesai Sembahyang Aidiladha","p":495,"v":1,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia telah berkata: Pernah aku hadir bersama dengan Rasulullah s.a.w. mengerjakan sembahyang hari Raya Adha di tanah lapang. Maka tatkala beliau selesai berkhutbah, beliau turun dari mimbar, ada orang membawa seekor kibas kepadanya, lalu disembelih oleh Rasulullah s.a.w. dengan tangannya sendiri kemudian beliau bersabda: Bismillah Allahu Akhbar, ini untukku dan untuk umatku yang tak berkorban.","r":"Abu Daud"},{"y":"h","x":"Dari Barrak bin Azib r.a. ia telah berkata: Bersabda Rasulullah s.a.w.: Sesiapa yang menyembelih sebelum sembahyang, maka ia menyembelih untuk dirinya sendiri, dan sesiapa yang menyembelih sesudah sembahyang, maka sungguh-sungguh ia telah menyempurnakan korbannya dan telah mengikuti sunah kaum Muslimin.","r":"Bukhari"},{"y":"h","x":"Dari Anas r.a. ia telah berkata: Pernah Nabi s.a.w. berkorban dengan dua ekor kibas (domba) yang bagus-bagus, maka aku lihat beliau meletakkan telapak kakinya di atas batang leher dombadomba itu, lalu dibacanya Bismillah dan dibacanya takbir, kemudian disembelihnya kedua ekor domba itu.","r":"Bukhari"}],"te":"Slaughtering After the Eid al-Adha Prayer"},{"t":"Umur Binatang yang Akan Dijadikan Korban","p":496,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah bersabda Nabi s.a.w.: Janganlah kamu sembelih binatang, melainkan yang telah berumur dua tahun, kecuali apabila binatang itu susah engkau dapat, maka potonglah binatang yang berumur satu tahun (dan masuk yang kedua.)","r":"Muslim"}],"te":"Age of the Sacrificial Animal"},{"t":"Seekor Sapi atau Unta boleh untuk Tujuh Orang Berkorban","p":497,"v":1,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah kami haji bersama Rasulullah s.a.w. lalu kami korbankan seekor unta untuk tujuh orang dan seekor sapi untuk tujuh orang.","r":"Muslim"}],"te":"One Cow or Camel Can Be Shared by Seven"},{"t":"Alat untuk Menyembelih Haruslah Alat yang Tajam","p":497,"v":1,"d":[{"y":"h","x":"Dari Syaddad bin Aus r.a. ia berkata: Nabi s.a.w. telah bersabda: Bila kamu hendak membunuh, maka baikkanlah pembunuhanmu itu, dan bila kamu hendak menyembelih, maka baikkanlah penyembelihanmu itu, dan hendaklah kamu menajamkan pisaumu dan menyenangkan sembelihanmu itu.","r":"Muslim"},{"y":"h","x":"Dari Abu Said r.a. ia telah berkata: Pernah kami bertanya: Ya Rasulullah, pernah kami menyembelih unta, sapi dan kambing, maka kami dapati di dalam perutnya ada anak, akan kami buangkah atau boleh kami makan? Rasulullah s.a.w. menjawab: Makanlah, jika kamu mahu memakannya, kerana penyembelihannya terhitung dengan penyembelihan induknya.","r":"Abu Daud"}],"te":"The Slaughtering Tool Must Be Sharp"},{"t":"Sekurang-Kurang Berkorban Seekor Kambing","p":499,"v":1,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya kepada Nabi s.a.w. pernah datang seorang laki-laki, lalu orang itu berkata: Sesungguhnya sudah menjadi kewajipan berkorban seekor unta sedang aku orang kaya, tetapi aku tak dapat unta untuk dibeli. Maka kepadanya diperintahkan oleh Rasulullah s.a.w. supaya membeli tujuh ekor kambing lalu disembelihnya.","r":"Ahmad dan Ibnu Majah"},{"y":"h","x":"Dari Aisyah r.a. ia telah berkata: Pernah manusia penduduk kampung datang berduyun-duyun untuk menghadiri korban di masa Rasulullah s.a.w. Maka Rasulullah s.a.w. bersabda: Simpanlah sepertiga daging itu dan sedekahkanlah yang lainnya.","r":"Abu Daud"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia berkata: Bersabda Rasulullah s.a.w.: Hai penduduk Madinah, janganlah kamu makan daging korban itu lebih dari tiga hari. Maka mereka mengadu kepada Rasulullah s.a.w. bahawasanya mereka ada keluarga, orang pemalu dan pembantu. Lalu beliau s.a.w. bersabda: Makanlah olehmu dan simpanlah dagingnya itu.","r":"Muslim"}],"te":"The Minimum Sacrifice Is One Goat"},{"t":"Keutamaan Berkorban","p":500,"v":1,"d":[{"y":"h","x":"Dari Abu Said Al-Khudri r.a., bahuwasanya Rasulullah s.a.w. pernah bersabda kepada Fatimah r.a.: Bangunlah, saksikanlah korbanmu itu, sesungguhnya titik pertama dari darahnya yang menitis itu diampuni bagimu dosamu yang telah lalu.","r":"Baihaqi"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Berkorbanlah dengan hati yang rela, sesungguhnya tiap-tiap Muslim yang menghadapkan sembelihnya ke arah kiblat, maka darahnya, kotorannya, dan bulunya itu adalah kebajikan dan bakti kepada timbangan pada hari kiamat.","r":"Baihaqi"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata, bersabda Rasulullah s.a.w.: Adapun wang perak yang dibelanjakan pada sesuatu, tak ada yang lebih utama daripada penyembelihan (berkorban) di hari raya.","r":"Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang sudah berkesempatan untuk berkorban, tetapi tidak juga dilakukannya, maka janganlah ia dekati tempat sembahyang kami. :,","r":"Ahmad dan Ibnu Majah"}],"te":"Virtue of Sacrifice"},{"t":"Tukang Sembelih Korban tidak boleh Mengambil Upah dari Binatang Korban","p":502,"v":1,"d":[{"y":"h","x":"Dari Ali r.a. ia berkata: Telah meminta kepadaku Rasulullah s.a.w. supaya aku berdiri di atas untanya, dan supaya aku bagi-bagikan daging, perhiasan di punggungnya dan kulitnya, dan diperintahkannya aku supaya jangan aku memberikan sesuatu upah dari daging korban itu kepada tukang-tukang daging (orang-orang yang mengurus membersihkan dagingnya), kemudian ia berkata: Kami memberikan pula daging-daging korban itu dari korban kami.","r":"Bukhari dan Muslim"}],"te":"The Butcher May Not Be Paid from the Sacrificial Animal"}],"p":491,"v":1,"te":"Sacrifice (Korban)"},{"t":"Akikah","c":[{"t":"Erti Akikah","p":503,"v":1,"d":[{"y":"h","x":"Dari Samurah r.a. dari Nabi s.a.w. beliau bersabda: Tiap-tiap bayi itu tergadai dengan akikahnya, yang harus dipotongkan kambing pada hari yang ketujuh (dari hari lahirnya), dan digunting rambutnya pada hari itu serta diberi nama.","r":"Abu Daud"},{"y":"h","x":"Dari Samurah r.a. dari Nabi s.a.w. beliau bersabda: Tiap-tiap bayi itu tergadai dengan akikahnya, yang harus dipotongkan kambing pada hari yang ketujuh (dari hari lahirnya), dan digunting rambutnya pada hari itu serta diberi nama. (Diriwayatkan oleh Abu Daud). Dalam kitab: SUBULUSSALAM\" dinyatakan: Bahawa berlain-lain faham ulama tentang hukum akikah ini. Menurut Daud dan pengikut-pengikutnya, bahawa akikah ini wajib hukumnya, beralasan hadis di atas. Sedang menurut Jumhur ulama, bahawa akikah itu sunat hukumnya. Mereka beralasan, bahawa hadis di atas itu, dijelaskan (dipalingkan) hukumnya oleh hadis di bawah ini, yang berbunyi: Telah bersabda Rasulullah s.a.w.: Jan an Peni ia Sesiapa yang telah melahirkan seorang anak, jika ia ingin hendak mengakikahinya, maka bolehlah ia perbuat.","r":"Malik dari Amar bin Syuaib"}],"te":"Meaning of Aqiqah"},{"t":"Dua Ekor Kambing untuk Bayi Laki-Laki dan Seekor Kambing untuk Bayi Perempuan","p":504,"v":1,"d":[{"y":"h","x":"Dari Habibah binti Maisarah r.a. telah berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Untuk anak laki-laki dua ekor kambing yang sama besar, dan untuk bayi yang perempuan seekor kambing.","r":"Abu Daud"},{"y":"h","x":"Dari Habibah binti Maisarah r.a. telah berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Untuk anak laki-laki dua ekor kambing yang sama besar, dan untuk bayi yang perempuan seekor kambing. (Diriwayatkan oleh Abu Daud). Adapun kambing yang akan dijadikan akikah itu, ialah kambing yang sudah patut disembelih sebagaimana dinyatakan dalam soal berkorban di atas. Iaitu kambing yang sekurang-kurangnya berumur dua tahun dan masuk ketiga. Adapun bacaan ketika hendak memotong binatang akikah itu adalah seperti bacaan yang dilakukan oleh Nabi s.a.w. ketika mengakikahkan cucunya Hasan dan Kena iaitu: Aa,  a aa Dengan nama Allah, ya Tuhan, kerana Engkau dan kepada Engkau akikah si.....","r":"Baihaqi"},{"y":"h","x":"Dari Aisyah r.a.: Yang sunat dua ekor kambing yang sekupu (sama besar) untuk bayi laki-laki dan untuk bayi perempuan seekor kambing, yang dimasak secara berangkai-rangkai dan jangan dipecah-pecah tulang-tulangnya.","r":"Baihaqi"}],"te":"Two Goats for a Baby Boy and One for a Baby Girl"},{"t":"Memberi Nama Anak dengan Nama yang Sebaik-Baiknya","p":505,"v":1,"d":[{"y":"h","x":"Dari Abu Dardak r.a. ia berkata: Bersabda Nabi s.a.w.: Sesungguhnya kamu akan dipanggil di hari kiamat, dengan namamu dan nama bapamu, oleh sebab itu hendaknya dipakai nama-nama yang baik. dl) MI ols,","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Sesungguhnya nama yang paling disukai Allah ialah Abdullah dan Abdur Rahman.","r":"Muslim"},{"y":"h","x":"Dari Abu Wahab Al-Jasya'ir.a., dari Nabi s.a.w. beliau bersabda: Berilah nama anakmu dengan nama nabi-nabi. Dan nama yang paling disukai Allah ialah Abdullah dan Abdur Rahman. Dan nama yang paling benar (boleh dijadikan nama) ialah Haris dan Hammam. Adapun nama yang paling buruk ialah Harab dan Murrah.","r":"Abu Daud dan Nasai"}],"te":"Giving a Child the Best of Names"}],"p":503,"v":1,"te":"Aqiqah"}],"p":450,"v":1,"d":[{"y":"a","s":3,"a":97,"b":97,"m":"Dan hak bagi Allah, supaya manusia berziarah (naik haji) ke Baitullah (di Mekah), iaitu sesiapa yang kuasa mengunjunginya"}],"te":"Book of Hajj"}],"p":3,"v":1,"te":"Quarter of Worship (Ibadat)"},{"t":"Rubu' Muamalat","c":[{"t":"Kitab Perdagangan dan Jual Beli","c":[{"t":"Asas Perdagangan dan Jual Beli","p":3,"v":2,"c":[{"t":"Erti Perdagangan","p":3,"v":2,"d":[{"y":"a","s":24,"a":37,"b":37,"m":""},{"y":"a","s":2,"a":16,"b":16,"m":""},{"y":"a","s":35,"a":29,"b":29,"m":""}],"te":"Meaning of Trade"},{"t":"Erti Jual Beli","p":3,"v":2,"d":[{"y":"a","s":2,"a":16,"b":16,"m":""},{"y":"a","s":9,"a":111,"b":111,"m":""},{"y":"a","s":62,"a":10,"b":10,"m":""},{"y":"h","x":"Dari Rifa'ah bin Rafi'. Bahawa Rasulullah s.a.w. pernah ditanya orang: Apakah usaha yang paling baik? Rasulullah menjawab: Usaha seseorang dengan tangannya dan tiap-tiap jual beli yang jujur.","r":"Bazar dan Hakim"}],"te":"Meaning of Sale"},{"t":"Mencari yang Halal","p":5,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesungguhnya Allah itu suci, dan Ia tidak akan menerima, melainkan yang suci pula. Dan sesungguhnya Allah, telah menyuruh orang mukmin dengan apa yang diperintahkan kepada rasul-rasul. Lalu Allah Taala berfirman: Hai sekalian Rasul! Makanlah barang yang halal dan kerjakanlah amal salih. Dan firman Allah Taala pula: Hai orang-orang yang beriman! Makanlah barang yang halal, iaitu barang yang Kami jadikan rezeki buat kamu.","r":"Muslim"}],"te":"Seeking What Is Lawful"},{"t":"Rukun Jual Beli","p":5,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Belumlah boleh dua orang yang berjual beli berpisahan, sebelum mereka berkerelaan.","r":"Abu Daud dan Tirmizi"},{"y":"a","s":4,"a":28,"b":28,"m":"Dalil yang menyatakan tentang mensyaratkan ijab kabul itu ialah firman Alah yang berbunyi:  P) Ks DA a aa a SI Melainkan yang halal (kamu makan), bahawa harta benda perdagangan itu, dilakukan rela sama rela antara sesamamu"},{"y":"h","x":"Dari Abu Said r.a. ia berkata: A Raj Ga a JG ak Rah Rare Ra ol, Telah bersabda Rasulullah s.a.w.: Baru sah jual beli, kalau sudah berkerelaan.","r":"Ibnu Hibban dan Ibnu Majah"},{"y":"a","s":4,"a":5,"b":5,"m":""},{"y":"a","s":4,"a":141,"b":141,"m":""},{"y":"h","x":"Dari Jabirr.a. bahawa Rasulullah s.a.w. pernah bersabda: Sesungguhnya Allah dan Rasul-Nya telah mengharamkan menjual arak, bangkai, babi dan berhala.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah melarang Rasulullah s.a.w. menjual anjing dan kucing.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Ibnu Mas'ud Al-Ansarir.a. bahawa Rasulullah s.a.w. telah melarang menerima wang hasil penjualan anjing, wang zina, dan tukang tenung.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Umar bin Syuaib dari bapanya, dari datuknya dari Nabi s.a.w. beliau bersabda: Tidak ada ertinya talak (tidak sah) melainkan pada perempuan yang engkau miliki, dan tidak ada ertinya memerdekakan melainkan pada hamba yang engkau miliki dan tidaklah ada ertinya (tidak sah) berjual beli melainkan pada barang yang engkau miliki.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. beliau berkata: Rasulullah s.a.w. telah melarang jual beli secara melempar dengan batu (lempar-lemparan) dan jual beli yang mengandungi penipuan.","r":"Muslim"}],"te":"Pillars of Sale"},{"t":"Jual Beli yang Dilarang dan tidak Sah","p":14,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: 1 etah melarang Rasulullah s.a.w. menjual mani binatang.","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Umar r.a. beliau berkata: Rasulullah s.a.w. telah melarang menjual anak yang akan dikandung oleh anak yang masih di dalam kandungan (induknya). Penjualan seperti itu adalah penjualan yang dilakukan oleh orang-orang Jahiliah, yang pernah seseorang menjual unta hingga melahirkan anak, kemudian lahir pula anak yang di dalam perutnya itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. ia berkata: Telah melarang Rasulullah s.a.w. tentang melakukan Bai' Muhaqalah, Bai' Mukhadarah, Bai' Mulamasah, Bai' Munabazah dan Bai' Muzabanah.","r":"Bukhari"},{"y":"h","x":"Dari Anas r.a. ia berkata: Telah melarang Rasulullah s.a.w. tentang melakukan Bai' Muhaqalah, Bai' Mukhadarah, Bai' Mulamasah, Bai' Munabazah dan Bai' Muzabanah. (Riwayat Bukhari). Kesembilan: Menentukan dua harga untuk satu barang yang diperjualbelikan. Berkata Syafii: Jual beli seperti ini mengandung dua takwil (erti). Pertama, bahawa seseorang berkata: Aku jual kepada engkau barangku ini dengan harga $1000 secara tunai, dan berharga $2000 secara berhutang. Kedua, bahawa seseorang berkata: Aku jual barangku ini kepadamu, dengan syarat agar kamu jual pula barangmu kepadaku. (Demikian Subulussalam). Sabda Rasulullah s.a.w.: Ra 1 4 di en - 1 a £ Sea a D A UA neg eg Adan Baa gn Tera an ols, Dan Abu Hurairah r.a. beliau berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang menjual dua penjualan dalam satu barang maka baginya ada kerugian atau riba.","r":"Abu Daud"},{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya dari datuknya r.a. ia berkata: Bersabda Rasulullah s.a.w.: “Tidak halal menguntungkan (meminjamkan) serta menjual, tidak halal dua syarat dalam satu penjual an, tidak halal mencari keuntungan dalam barang yang tidak dapat dijamin dan tidak pula halal menjual barang yang tidak ada di sisi- ” mu.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ibnu Mus'udr.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Janganlah kamu membeli ikan di dalam air, kerana jual beli semacam itu mengandungi penipuan.","r":"Ahmad"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawa Rasulullah s.a.w. pernah lewat dekat selonggok barang makanan, lalu Nabi masukkan tangan beliau ke dalamnya, lantas terasa oleh jari beliau basah di dalamnya lalu Nabi bersabda: Apakah ini, hai yang punya makanan?' Orang yang empunya makanan itu menyahut: Kena hujan, ya Rasulullah. Beliau bersabda lagi: Mengapa tidak engkau letakkan saja yang basah itu di atas makanan itu supaya dilihat orang? Sesiapa yang menipu, tidaklah ia masuk ke dalam golongan kami.","r":"Muslim"}],"te":"Forbidden and Invalid Sales"},{"t":"Jual Beli yang Terlarang tetapi Sah","p":19,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. berkata ia: bersabda Rasulullah s.a.w.: Janganlah kamu temui orang yang berkenderaan itu (orang yang membawa bahan-bahan penting ke bandar), dan tidak boleh menjualkan orang yang hadir (orang di bandar) menjualkan barang orang dusun (baru datang).","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tidak boleh seseorang menawar di atas tawaran saudaranya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah melarang Rasulullah s.a.w. melakukan bai' najasyi.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. berkata: Bersabda Rasulullah s.a.w.: Dan tidaklah boleh seseorang menjual di atas penjualan saudaranya, dan tidak pula ia boleh meminang di atas pinangan saudaranya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Rasulullah s.a.w. pernah bersabda: Sesungguhnya kamu akan memberikan (mengembalikan) segala hak kepada yang empunya pada hari kiamat, hingga kambing yang tidak bertanduk, akan diperbalaskan dengan kambing yang bertanduk,","r":"Muslim"}],"te":"Sales That Are Forbidden but Valid"},{"t":"Ikhtikar (Spekulasi)","p":21,"v":2,"d":[{"y":"h","x":"Dari Ma'mar r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang menyimpan barang yang dapat menimbulkan kemelaratan atas kaum Muslimin, Allah akan memukulnya dengan penyakit canggu dan kemiskinan.","r":"Ibnu Majah"},{"y":"h","x":"Dari Ma'mar r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang menyimpan barang (dengan sengaja supaya mahal harganya) maka orang itu telah berdosa.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Anas r.a. ia berkata: Telah mengadu manusia kepada Nabi: “Ya Rasulullah, harga barang-barang telah naik, sebab itu berikanlah harga untuk kami (murahkan)” Maka Rasulullah s.a.w. menjawab: Sesungguhnya Allah yang menentukan harga, yang Maha Kuasa menyempitkan, yang Maha Kuasa menyederhanakan penghidupan, yang Maha Kuasa melapangkan, yang Maha Kuasa memberi rezeki, dan aku sesungguhnya sangat mengharap, bahawa aku akan menemui Allah, dan tiadalah jalan berbuat kezaliman dalam urusan penumpahan darah dan tidak seorang juga di antara kamu yang dapat menuntutku dengan harta benda.","r":"Abu Daud dan Tirmizi"}],"te":"Hoarding (Ikhtikar)"},{"t":"Khiar dalam Jual Beli","p":22,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: “Bila dua orang berjual beli, maka masing-masing boleh khiar (jadi atau tidak jual beli), selama keduanya belum bercerai.” |.","r":"Muslim"},{"y":"h","x":"Dari Jabir r.a. bahawa ia pernah menjual seekor unta kepada Nabi s.a.w. dan disyaratkannya, supaya ia boleh menunggang unta itu untuk pulang ke rumahnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Faedah yang lahir dari barang yang diperjualbelikan itu adalah dengan sebab jaminan.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Jangan kamu suka mentasiriyakan unta dan kambing (mengikutnya di sebelah belakangnya, sedang susunya tak diperah hingga penuh kelihatannya). Sesiapa yang membelinya sesudah itu, maka ia boleh memilih salah satu dua pertimbangan sesudah ia memerahnya. Jika ia kehendaki, ia tahan (ia teruskan jual beli) dan jika ia kehendaki, ia boleh mengembalikan binatang itu serta segantang tamar.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Jangan kamu suka mentasiriyakan unta dan kambing (mengikutnya di sebelah belakangnya, sedang susunya tak diperah hingga penuh kelihatannya). Sesiapa yang membelinya sesudah itu, maka ia boleh memilih salah satu dua pertimbangan sesudah ia memerahnya. Jika ia kehendaki, ia tahan (ia teruskan jual beli) dan jika ia kehendaki, ia boleh mengembalikan binatang itu serta segantang tamar. (Riwayat Bukhari dan Muslim). Dan pada satu riwayat: Maka ia boleh khiar selama tiga hari.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah seseorang mengatakan kepada Rasulullah s.a.w. bahawa ia telah menipu dalam jual beli, maka Rasulullah s.a.w. bersabda kepadanya: Bila engkau berjual beli maka katakanlah (berterus terang) kepada pembeli, tak boleh tipu menipu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. bahawa seorang laki-laki pernah membeli seorang hamba lalu disuruhnya hamba itu berdiri di dekatnya, kemudian didapatinya pada hamba itu ada cacat, lalu diadukannya hal itu kepada Rasulullah s.a.w. maka dikembalikannyalah hamba itu kepadanya (si penjual).","r":"Ahmad dan Abu Daud"}],"te":"Option to Cancel (Khiar) in Sale"},{"t":"Berselisih dan Jujur dalam Jual Beli","p":26,"v":2,"d":[{"y":"h","x":"Dari Abdullah r.a. dari Nabi s.a.w. beliau bersabda: “Bila dua orang yang berjual beli berselisih dan antara keduanya tidak ada saksi maka yang dibenarkan ialah perkataan yang empunya barang, atau keduanya membatalkan jual beli itu.” Aa","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Bersumpah-sumpah itu mencepatkan lakunya barang (tetapi) menghilangkan berkat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tinggalkanlah banyak bersumpah-sumpah dalam jual beli, kerana sesungguhnya bersumpah-sumpah itu mencepatkan laku barang kemudian cepat pula menghilangkan berkatnya.","r":"Muslim"},{"y":"h","x":"Dari Hasan, dari Abu Said, dari Nabi s.a.w. beliau bersabda: Kaum saudagar yang benar dan jujur itu, dikumpulkan nanti di hari kiamat bersama dengan nabi-nabi dan sahabat-sahabat serta orang yang mati syahid.","r":"Tirmizi"}],"te":"Disputes and Honesty in Sale"},{"t":"Perjudian","p":28,"v":2,"d":[{"y":"a","s":5,"a":90,"b":90,"m":"pembayaran lebih dahulu. Kalau kena yang diteka, maka beruntunglah orang yang membayar itu. Tetapi kalau tidak kena, maka hilanglah wang pembayaran itu. Maka perbuatan judi ini adalah haram atau terlarang sekali, sedang hasil yang didapati dengan jalan judi itu terlarang pula memakan atau memakainya untuk yang bersangkutan. Allah berfirman: ve MA P) ve AA a A Ke Pa SA pa an. Ba Se a Ji Hai orang-orang yang beriman! Sesungguhnya arak, judi, patung dan menguji nasib itu adalah perbuatan keji, termasuk perbuatan syaitan, oleh itu jauhilah ia, mudah-mudahan kamu menang"}],"te":"Gambling"},{"t":"Simsar (Badan Perantaraan)","p":29,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. Dalam perkara pengertian simsar ia berkata: Tidaklah mengapa kalau seseorang berkata: Juallah kain ini dengan harga sekian, berapa lebihnya dari penjualan itu, maka yang lebih itu untuk engkau.","r":"Bukhari"}],"te":"Brokers (Simsar)"},{"t":"Berlapang Dada dalam Berjual Beli","p":30,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah dirahmati Tuhan orang yang berlapang dada bila ia berjual beli dan bila minta atau menagih hutang.","r":"Bukhari dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. berkata 1a: Pernah seorang laki-laki mempunyai hak atas Nabi s.a.w. (seekor unta jantan) maka lakilaki itu marah kepada beliau (kerana belum juga dibayar), lalu sahabat-sahabat hendak memukulnya, maka bersabdalah Nabi s.a.w.: Biarkanlah dia kerana orang yang empunya hak sesungguhnya berhak pula ia mengeluarkan kata-kata, maka belikanlah olehmu baginya seekor unta jantan (4 tahun). Mereka lalu menjawab: Tidak ada ya Rasulullah, melainkan ada unta yang lebih baik dari untanya. Maka bersabda Rasulullah: Belilah, lalu berikan kepadanya, kerana sesungguhnya sebaik-baik kamu ialah orang yang dapat berbakti (melebihi) dalam membayar hutangnya.","r":"Bukhari dan Muslim"}],"te":"Being Generous in Buying and Selling"},{"t":"Jual Beli Araya dan Muzayadah (Lelong)","p":31,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah melarang Nabi s.a.w. menjual buah hingga masak lebih dulu, dan tak boleh dijual sesuatu pun melainkan dengan dinar dan dirham (mata wang); kecuali penjualan araya.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Sahal bin Abu Hasmah r.a. bahawa Rasulullah s.a.w. telah melarang menjual buah dengan buah, dan beliau bersabda: Penjualan seperti itu riba, perbuatan itu adalah muzabanah (menjual buahbuahan yang masih di pokok dengan buah yang sudah kering), dikecualikan pada bai' araya (penjualan buah kurma yang masih muda) yang akan diambil (dimakan) oleh ahli rumah sekeluarga, menurut ukuran buah tamar (takarannya) yang akan mereka makan di waktu masih basah.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawa Nabi s.a.w. telah membolehkan melakukan bai'araya, sebanyak lima wasq atau kurang lima wasq.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. ia berkata: Nabi s.a.w. pernah menjual sebuah pelana dan sebuah mangkuk air, dengan mengatakan: Siapa mahu membeli pelana dan mangkuk ini? Menyahut seorang lakilaki: Aku bersedia mengambilnya seharga satu dirham. Lalu Nabi s.a.w. bersabda pula: Siapa yang berani menambahi? Maka diberi dua dirham oleh seorang laki-laki kepada beliau, lalu dijuallah keduanya kepada laki-laki itu.","r":"Tirmizi"}],"te":"Araya Sales and Auctions (Muzayadah)"},{"t":"Menjual Tanah Termasuk Pokokpokok yang Ada di Dalamnya","p":33,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Siapa yang membeli sepokok nakhal (kurma) sesudah dikahwinkan, maka buahnya adalah buat yang menjual, kecuali bila si pembeli mensyaratkan (buat dia). Dan siapa yang membeli seorang hamba, maka harta kekayaan si hamba itu adalah untuk yang menjual, kecuali kalau si pembeli mensyaratkan untuknya.","r":"Bukhari dan Muslim"}],"te":"Selling Land Including Its Trees"},{"t":"Menjual Buah-Buahan yang Telah Nyata Baiknya","p":35,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. telah bersabda: Janganlah kamu memperjualbelikan buah-buahan, hingga sudah nyata baik untuk diambil dan janganlah kamu jual buah muda dengan tamar.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. telah melarang menjual nakhal hingga telah masak buahnya, menjual buah di ranting hingga ia kelihatan memutih dan hingga telah aman bahayanya.","r":"Muslim dan Abu Daud"}],"te":"Selling Fruit Once Clearly Ripe"},{"t":"Buah-Buahan yang Rosak Setelah Dijual","p":36,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Jika engkau telah menjual buah-buahan kepada saudaramu, lalu buahbuahan itu busuk (rosak), maka tidak halal bagimu mengambil sesuatu daripadanya. Apakah sebabnya engkau mahu mengambil harta saudaramu dengan tidak hak (sah).","r":"Muslim"}],"te":"Fruit Damaged After Sale"},{"t":"Mengandam Ternak yang Akan Dijual","p":37,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: “Siapa yang membeli seekor kambing yang ditasriyakan, maka dia boleh memilih sesudah kambing itu diperahnya, jika ia mahu, ia boleh menahan (boleh teruskan jual beli) dan jika ia kehendaki (menggagalkan), maka ia boleh memulangkan kambing itu bersama segantang tamar, bukan gandum.”. |","r":"Bukhari dan Muslim"}],"te":"Holding Back Milk in Livestock for Sale"},{"t":"Murabahah","p":38,"v":2,"d":[{"y":"h","x":"Dari Zaid bin Sabit r.a. bahawa Nabi s.a.w. telah melarang menjual barang-barang ketika berlaku jual beli sebelum barang-barang itu dipindahkan oleh pedagang-pedagang ke kenderaan mereka lebih dahulu.","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawa mereka pernah membeli makanan sebanyak satu jazaf* di hujung pasar (Madinah), maka Rasulullah *tidak ditimbang dan tidak pula ditakar. s.a.w. melarang mereka menjualnya, sebelum mereka memindahkannya dari tempatnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. telah melarang menjual hutang dengan hutang.","r":"Hakim dan Bazar"}],"te":"Cost-Plus Sale (Murabahah)"},{"t":"Memesan Barang (Salam/salaf)","p":40,"v":2,"d":[{"y":"a","s":2,"a":282,"b":282,"m":""},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah Rasulullah s.a.w. datang ke Madinah sedang mereka (penduduk Madinah) memesan buah tamar untuk satu tahun dan dua tahun. Maka Rasulullah bersabda kepada mereka: Sesiapa yang memesan buah tamar, mestilah ditentukan timbangannya pada waktu yang tertentu pula.","r":"Bukhari dan Muslim"}],"te":"Advance Purchase (Salam/Salaf)"}],"te":"Basics of Trade and Sale"},{"t":"Hutang Piutang","c":[{"t":"Mengambil Manfaat Hutang","p":44,"v":2,"d":[{"y":"h","x":"Dari Abu Rafi' r.a. bahawa Rasulullah s.a.w. pernah berhutang seekor unta gadis (umur 3 tahun) kepada seorang laki-laki, lalu dibawa kepada beliau seekor unta yang biasa untuk berzakat, maka aku disuruh Rasulullah supaya membayar untuk laki-laki itu (yang telah memberi hutang tadi), dengan unta gadis pula, aku menjawab: Tidak aku peroleh waktu itu melainkan unta yang lebih baik yang berumur empat tahun, maka bersabda Rasulullah: Berikanlah kepadanya unta itu, sesungguhnya sebaik-baik manusia, ialah orang yang lebih dalam membayar hutang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdullah bin Abu Rabi'ah ia berkata: Pernah Rasulullah s.a.w. berhutang dengan aku sebanyak empat puluh ribu (dinar atau dirham). Lalu datang kepadanya (orang memberikan) wang. maka diberikannya wang itu kepadaku, dan ia berkata: Mudah-mudahan Allah memberi berkat pada keluarga dan harta engkau. Hanya balasan pinjaman ialah puji-pujian (terima kasih) dan mengembalikannya.","r":"Nasai"},{"y":"h","x":"Dari Ali r.a. ia berkata: Bersabda Rasulullah s.a.w.: Tiap-tiap hutang yang sengaja untuk mencari manfaat, maka hukumnya riba.","r":"Al-Haris bin Abi Usamah"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Orang kaya yang melalaikan kewajipan bayar hutang itu aniaya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Siapa siapa yang meminjam harta orang dan ia bermaksud hendak membayarnya, maka Allah akan membayarkannya, dan sesiapa yang meminjam harta orang, dan ia sengaja hendak melenyapkannya (tidak mahu membayar) lebih dahulu Allah akan melenyapkan hartanya itu.","r":"Bukhari"}],"te":"Taking Benefit from a Loan"},{"t":"Al-Hiwalah","p":47,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Orang kaya (orang yang mampu) yang melalaikan kewajipannya adalah aniaya dan apabila menghiwalahkan (memindahkan) seseorang akan hutangnya atas orang yang mampu maka terimalah.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Ada seorang laki-laki yang selalu menurutkan gharimnya (orang yang berhutang kepadanya), sebab ia berhutang sepuluh dinar, lalu ia berkata: Demi Allah, aku belum akan berpisah dengan engkau, sebelum engkau bayar hutang itu kepadaku, atau engkau tunjukkan orang yang akan menjamin. Berkata Ibnu Abbas: Lalu hutang itu dijamin oleh Nabi s.a.w. Kemudian berkata Ibnu Abbas: Lalu diberikannyalah kepada Rasulullah sekadar apa yang telah dijanjikannya.","r":"Abu Daud dan Ibnu Majah"}],"te":"Transfer of Debt (Hiwalah)"},{"t":"Gadai Menggadai","p":49,"v":2,"d":[{"y":"a","s":2,"a":283,"b":283,"m":""},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Telah meninggal Nabi s.a.w. sedang baju besi beliau tergadai, sebab berhutang 20 gantang makanan, yang telah diambilnya (dihutangnya) makanan itu untuk belanja keluarganya.","r":"Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. bahawa Nabi s.a.w. pernah membeli makanan dari seorang Yahudi dengan cara berjanji, dan dirungguhkannya igadaik sehelai baju besi. medan,","r":"Bukhari dan Muslim"},{"y":"a","s":2,"a":279,"b":279,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Belakang binatang boleh ditunggangi bila ia digadaikan, dan susu binatangbinatang ternak itu boleh diminum bila ia digadaikan, dan orang yang menunggang dan yang meminum itu wajib nafkah (belanja) binatang-binatang yang digadaikan itu.","r":"Bukhari dan Abu Daud"}],"te":"Pawning"}],"p":43,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Kang yang melepaskan orang mukmin dari sesuatu kesengsaraan daripada kesengsaraan dunia nescaya Allah akan melepaskan daripadanya kesengsaraan pada hari kiamat, dan sesiapa yang memudahkan orang yang sedang dalam kesulitan nescaya Allah akan memberi kemudahan kepadanya di dunia dan akhirat.","r":"Muslim"},{"y":"a","s":2,"a":282,"b":282,"m":""}],"te":"Debts"},{"t":"Riba Modal","c":[{"t":"Takrif Riba","p":52,"v":2,"d":[{"y":"a","s":22,"a":5,"b":5,"m":""},{"y":"a","s":2,"a":275,"b":275,"m":"un YYo alan Pekerjaan berjual beli itu seperti riba, tetapi Allah menghalalkan berjual beli dan mengharamkan riba"}],"te":"Definition of Riba"},{"t":"Terkutuk Orang yang Makan Riba, Pekerja dan yang Menyaksikannya","p":54,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah dilaknati oleh Rasulullah s.a.w. orang-orang yang suka makan riba, orang yang jadi wakilnya, jurutulisnya, orang-orang yang menyaksikannya, dan seterusnya Rasulullah s.a.w. bersabda: Mereka itu semuanya sama.","r":"Muslim"}],"te":"Cursed Are Those Who Consume Riba, Record It and Witness It"},{"t":"Riba Termasuk Dosa Besar","p":55,"v":2,"d":[{"y":"h","x":"Dari Nabi s.a.w. beliau bersabda: Jauhilah olehmu, tujuh macam yang membahayakan (dosa besar). Mereka bertanya: Apakah itu semua ya Rasulullah? Beliau menjawab: Iaitu; syirik dengan Allah, mengerjakan sihir (teluh dan lain-lainnya), membunuh diri yang diharamkan Allah melainkan dengan yang hak, memakan harta riba, memakan harta anak yatim, lari daripada hari pertempuran dan menuduh wanita-wanita yang terpelihara lagi mukmin terlalai.","r":"Bukhari dan Muslim"}],"te":"Riba Is a Major Sin"},{"t":"Macam-Macam Riba","p":56,"v":2,"d":[{"y":"a","s":3,"a":130,"b":130,"m":""},{"y":"h","x":"Dari Jabir r.a. berkata: Telah bersabda Rasulullah s.a.w.: Riba kaum Jahiliah itu hendaklah dibuang. Dan mula-mula riba yang aku buang di antara riba kita (riba yang dilakukan oleh sebahagian kaum Muslimin ketika itu) ialah riba Abbas bin Abdul Muttalib kerana sesungguhnya riba itu seluruhnya tidak boleh lagi dilakuka","r":"Muslim dan Abu Daud"},{"y":"a","s":2,"a":278,"b":278,"m":"Jika engkau berdua mengambil hak engkau, nescaya tidak akan tinggal lagi yang akan dimakan oleh keluargaku. Alangkah baiknya kalau engkau keduanya mengambil seperdua hak engkau lebih dahulu, dan yang seperdua lagi aku lebihkan membayarnya kepada engkau nanti. Lalu keduanya menerima permohonan itu. Tatkala sampai waktunya, keduanya datang meminta haknya sebagaimana dijanjikan dahulu. Hal ini sampailah kepada Rasulullah s.a.w. lalu Rasulullah s.a.w. melarang keduanya melakukan perbuatan yang begitu. Maka ketika itu turunlah ayat yang berbunyi: PS P PEN AA A YYA Al sal Sy Hai orang-orang yang beriman! Takutlah kamu kepada Allah dan tinggalkanlah apa-apa yang termasuk riba"},{"y":"a","s":2,"a":279,"b":279,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: “Telah bersabda Rasulullah s.a.w. : “Menjual (menukar) emas dengan emas mesti sama timbangannya, sama nilainya (kualitinya), dan menjual perak dengan perak mesti sama timbangannya, sama nilainya, dan sesiapa yang menambah dan meminta lebih sesungguhnya itu telah menjadi riba. Dan pada riwayat lain berbunyi: Menjual tamar dengan tamar, dan menjual gandum dengan gandum, dan syair dengan syair, dan garam dengan garam, mesti sama nilainya, sama timbang terima, maka sesiapa yang menambah dan minta tambah, maka sesungguhnya telah jadi riba, melainkan barang-barang yang berlainan jenisnya.” A ” Sah Sh S5 o","r":"Muslim"}],"te":"Kinds of Riba"},{"t":"Barang-Barang yang boleh Mendatangkan Riba","p":61,"v":2,"te":"Goods That Can Lead to Riba"},{"t":"Soal Bank dan Koperasi Simpan-Pinjam serta yang Dinamakan Mata Wang","p":63,"v":2,"te":"Banks, Savings Co-operatives and Currency"},{"t":"Cara Menjual Barang-Barang Ribawi","p":64,"v":2,"d":[{"y":"h","x":"Dari Ubadah bin Shamit ia berkata: Bersabda pula Rasulullah s.a.w.: Menjual emas dengan emas, menjual perak dengan perak, atau menjual gandum dengan gandum, menjual syair dengan syair, menjual tamar dengan tamar dan menjual garam dengan garam, mesti sama nilainya (kualitinya), sama banyaknya, timbang terima. Maka jika berlainan macamnya, maka boleh kamu menjual bagaimana yang kamu kehendaki, asal saja timbang terima dan tunai sama tunai.","r":"Muslim"}],"te":"How to Sell Ribawi Goods"},{"t":"Pembayaran Hutang yang Dilebihkan","p":66,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. berkata: Telah bersabda Rasulullah s.a.w.: Sesungguhnya yang sebaik-baiknya kamu, ialah orang yang suka berbudi (melebihi) dalam membayar hutangnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Mujahid r.a. bahawa Ibnu Umar r.a. pernah meminjam wang (kepada orang lain), lalu dibayar hutangnya itu kepada yang empunya wang dengan melebihi dari jumlah yang ia pinjam dahulu, maka enggan (tidak mahu) orang itu menerimanya, dan beliau berkata: Ini adalah lebih dari jumlah wang yang telah aku pinjamkan. Maka berkata Ibnu Umar: Ya, sungguh aku tahu, tetapi diriku suka dengan menambahi yang demikian itu.","r":"Malik dalam Al-Muwattak"},{"y":"h","x":"Dari Malik r.a. ia berkata: Pernah disampaikan orang kepadaku, bahawa ada seorang laki-laki datang kepada Abdullah bin Umar, lalu dia berkata: Sesungguhnya aku telah menghutangkan kepada seseorang dan aku mensyaratkan ke atasnya supaya melebihkan bayarannya dari jumlah yang telah aku hutangkan kepadanya? Maka Abdullah bin Umar berkata: Yang demikian itu adalah riba.","r":"Malik dalam Muwatthak"},{"y":"h","x":"Dari 1bu Yasar r.a. ia berkata: Pernah aku mendengar Rasulullah s.a.w. bersabda: Sesiapa yang menunggu (melapangkan) orang yang sedang kemiskinan, atau ia relakan saja hutang itu daripadanya (dianggapnya tidak jadi hutang lagi), nanti Allah akan memberi perlindungan kepadanya dengan perlindungan pada hari yang tidak ada perlindungan baginya, kecuali perlindungan itulah.","r":"Muslim"}],"te":"Repaying a Debt with Extra"},{"t":"Sebab-Sebab Timbulnya Riba","p":69,"v":2,"d":[{"y":"h","x":"Dari Malik Aus r.a. ia berkata: Pernah aku hendak menukarkan wang dirham dengan seratus dinar lalu aku dipanggil oleh Talhah bin Ubaidillah, lantas kami bercakap-cakap tentang hal emas (dinar)ku itu dan dibalik-baliknya wang emas di tangannya itu, hingga ia mahu menukar dirhamku, maka diambilnya wang kemudian ia berkata: Tunggulah juruwang saya dari dusun. Dan Umar r.a. mendengar persoalan itu, lalu ia berkata: Demi Allah, jangan engkau bercerai lebih dahulu sebelum engkau ambil pula tukarannya daripadanya. Telah bersabda Rasulullah s.a.w.: Menukar emas dengan emas itu riba kecuali tunai dengan tunai, dan menukar gandum dengan gandum itu riba kecuali tunai dengan tunai, dan menukar syair dengan syair itu riba kecuali tunai dengan tunai, dan menukar tamar dengan tamar itu riba kecuali tunai dengan tunai.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Minhal r.a. ia berkata: Pernah aku bertanya kepada Al-Bara' tentang penukaran wang, lalu ia berkata: Tanyakanlah kepada Zaid bin Arqam sebab dia yang lebih tahu, lantas aku tanyakan kepada Zaid, maka ia berkata, tanyakanlah kepada Al-Bara' sebab dia yang lebih tahu, kemudian keduanya berkata: Telah melarang Rasulullah s.a.w. menukari perak dengan emas secara hutang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah aku menjual unta di suatu tempat dengan harga dinar, lalu aku terima harganya menurut harga perak, dan aku jual dengan perak, lalu aku terima harganya menurut harga wang emas, kemudian aku datang kepada Rasulullah s.a.w. kudapati beliau sedang di luar rumah Hafshah, maka aku tanyakan kepada beliau hal itu. Lalu Rasulullah menjawab: Tidak mengapa dengan cara begitu menurut harganya pada hari itu juga.","r":"Abu Daud dan Tirmizi"}],"te":"Causes of Riba"},{"t":"Sogokan atau Wang Suap","p":71,"v":2,"d":[{"y":"a","s":5,"a":42,"b":42,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. ia telah berkata: Rasulullah s.a.w. telah mengutuk orang yang suka memberi rasuah, dan orang yang suka menerima rasuah dalam soal hukum menghukum.","r":"Abu Daud dan Tirmizi"}],"te":"Bribery"}],"p":52,"v":2,"te":"Riba"},{"t":"Mahjur","c":[{"t":"Erti Mahjur dan Sebab-Sebabnya","p":73,"v":2,"d":[{"y":"a","s":4,"a":6,"b":6,"m":""}],"te":"Meaning and Causes of Restriction"},{"t":"Kerana di Bawah Umur","p":10,"v":2,"d":[{"y":"a","s":4,"a":10,"b":10,"m":""},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah aku dibawa kepada Nabi s.a.w. (untuk turut perang) pada hari perang Uhud, sedang aku masih berumur 14 tahun, maka aku tidak dibolehkannya. Dan akupun pernah pula dibawa (untuk turut perang) pada hari perang Khandak, dan aku telah berumur 15 tahun, maka dibolehkannya aku.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Athiyah Al-Qurzy r.a. ia berkata: Pernah aku dibawa kepada Nabi s.a.w. pada hari (perang) Khandak. Ketika itu, sesiapa yang telah ada tumbuh bulu (di kemaluannya), setelah ditangkap terus dihukum mati, dan sesiapa yang belum tumbuh bulu, dilepaskannya. Maka aku adalah termasuk orang yang belum tumbuh bulu (di kemaluan), maka ia lepaskan aku.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ali r.a. ia berkata: Pernah aku menghafaz hadis dari Rasulullah s.a.w. yang mengatakan: “Tidak dianggap anak kecil lagi sesudah bermimpi.” g","r":"Abu Daud"}],"te":"Because of Being Under Age"},{"t":"Kerana Bodoh","p":76,"v":2,"d":[{"y":"a","s":4,"a":5,"b":5,"m":""}],"te":"Because of Foolishness"},{"t":"Kerana Lemah Rohani dan Jasmani","p":77,"v":2,"d":[{"y":"a","s":2,"a":282,"b":282,"m":""}],"te":"Because of Mental or Physical Weakness"},{"t":"Kerana Hamba","p":77,"v":2,"d":[{"y":"a","s":16,"a":75,"b":75,"m":""}],"te":"Because of Being a Slave"},{"t":"Kerana Sedang Sakit Kuat","p":77,"v":2,"d":[{"y":"a","s":2,"a":180,"b":180,"m":""}],"te":"Because of Serious Illness"},{"t":"Kerana Sedang Menggadai","p":79,"v":2,"d":[{"y":"a","s":2,"a":283,"b":283,"m":""}],"te":"Because of a Pledge"},{"t":"Kerana Bersuami, bagi Wanita","p":79,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya: Bahawasanya Rasulullah s.a.w. telah bersabda: Tidak boleh bagi seseorang wanita memberikan sesuatu apa, melainkan dengan izin suaminya. Dan dalam satu riwayat berbunyi: Tidak boleh bagi seseorang wanita mengurus dalam perkara harta bendanya, bila suaminya telah memiliki tanggungjawabnya.","r":"Ash-habussunan"}],"te":"Because of Marriage, for Women"},{"t":"Kerana Murtad","p":80,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang telah menukar agamanya, maka bunuhlah ia.","r":"Bukhari"}],"te":"Because of Apostasy"},{"t":"Kerana Jatuh Bankrap (Muflis)","p":81,"v":2,"te":"Because of Bankruptcy (Muflis)"}],"p":73,"v":2,"te":"Legal Restriction (Mahjur)"},{"t":"Muflis (Bankrap)","c":[{"t":"Merampas dan Menjual Barang Muflis","p":82,"v":2,"d":[{"y":"h","x":"Dari Kaab bin Malik dari bapanya r.a. bahawa Rasulullah s.a.w. pernah merampas harta Mu'az, dan Rasulullah telah menjual harta itu untuk membayar hutangnya yang ada.","r":"Daruqutni dan Hakim"}],"te":"Seizing and Selling a Bankrupt's Goods"},{"t":"Meminta Ganti dari Muflis","p":82,"v":2,"d":[{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia berkata: Pernah seorang laki-laki dapat musibat pada masa Rasulullah s.a.w. iaitu buah-buahan yang telah dibelinya busuk. Oleh sebab itu banyaklah hutangnya, maka bersabda Rasulullah s.a.w.: Bersedekahlah kepadanya, maka bersedekahlah orang-orang kepadanya. Tetapi wang yang diterimanya itu belum juga cukup untuk membayar hutangnya, maka bersabdalah Rasulullah s.a.w. kepada orang-orang yang empunya hutang: Ambillah apa yang kamu peroleh, dan tidak ada yang lain bagimu hanya itulah.","r":"Muslim"}],"te":"Claiming Compensation from a Bankrupt"},{"t":"Orang yang tidak Mahu Bayar Hutang boleh Dihukum","p":83,"v":2,"d":[{"y":"h","x":"Dari Amr bin Said, dari bapanya r.a. ia berkata: Bersabda Rasulullah s.a.w.: Orang-orang yang telah sanggup untuk membayar kewajipannya, tetapi dilalaikannya juga bolehlah orang merampas hartanya dan menyeksanya (memasukkannya ke penjara).","r":"Abu Daud dan Nasai"}],"te":"One Who Refuses to Pay a Debt May Be Punished"}],"p":81,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Kami telah mendengar Rasulullah s.a.w. bersabda: Sesiapa yang mendapati harta bendanya menurut aslinya (belum berubah sifatnya) di sisi seseorang yang sudah bankrap, maka dia lebih berhak dengan barang itu daripada lainnya.","r":"Bukhari dan Muslim"}],"te":"Bankruptcy (Muflis)"},{"t":"Jaminan dan Pinjam Meminjam","c":[{"t":"Erti Jaminan dan Syarat-Syaratnya","p":83,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah meninggal seorang laki-laki dari keluarga kami, lalu kami mandikan dia dan kami beri kapur barus kemudian kami kafani. Setelah selesai, kami bawa kepada Rasulullah s.a.w. lalu kami katakan: Sembahyangkanlah dia, ya Rasulullah! Maka Rasulullah s.a.w. membuat sebuah garis, kemudian bertanya: Adakah ia berhutang? Kami jawab: Ada, dua dinar. Nabi lalu berpaling (tidak mahu menyembahyangkan). Kemudian hutang yang dua dinar itu ditanggung oleh Abu Qatadah. Maka kami daiang kepada beliau kembali, lalu Abu Qatadah berkata: Dua dinar itu aku yang tanggung. Maka Rasulullah s.a.w. bersabda: Sekarang engkau yang berhutang dan lepaslah mayat ini dari hutang yang dua dinar itu. Jawab Abu Qatadah, Ya.' Barulah Rasulullah s.a.w. menyenbahyangkan mayat itu.","r":"Ahmad dan Abu Daud"}],"te":"Meaning and Conditions of a Guarantee"},{"t":"Erti Pinjaman dan Syaratnya","p":85,"v":2,"d":[{"y":"a","s":5,"a":3,"b":3,"m":""},{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah terjadi keributan di kota Madinah, lalu Nabi s.a.w. meminjam seekor kuda kepada Abu Talhah, yang dinamakan Al-Mundub, lalu ditunggangi beliau kuda itu. Maka apabila beliau kembali, beliau berkata: Tidak ada kami lihat sesuatu juga di sana, dan tak salah kalau kami katakan, bahawa kuda ini sangat kencang larinya.","r":"Bukhari"},{"y":"h","x":"Dari Samurah r.a. dari Nabi s.a.w. beliau bersabda: Wajib atas tangan menjaga apa yang telah dipinjam sampai barang itu dikembalikan.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Umamah r.a. dari Nabi s.a.w. beliau bersabda: Pinjaman itu mesti dikembalikan, dan orang yang menjamin dialah yang berhutang, dan hutang itu mesti dibayar.","r":"Tirmizi"}],"te":"Meaning and Conditions of a Loan"}],"p":83,"v":2,"te":"Guarantees and Loans"},{"t":"Syarikat Perniagaan (Syirkah)","c":[{"t":"Erti Syarikat Perniagaan","p":88,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Berfirman Allah Taala: Aku jadi yang ketiga antara dua orang yang bersyarikat selama salah seorang antara keduanya tidak khianat terhadap saudaranya (temannya), maka bila ia khianat, keluarlah Aku dari antara keduanya.","r":"Abu Daud"}],"te":"Meaning of Business Partnership"},{"t":"Macam-Macam Cara Syarikat","p":88,"v":2,"d":[{"y":"h","x":"Dari Saib Al-Mahzumi r.a. bahawa ia adalah, syarikat (kawan syarikat) Nabi s.a.w. sebelum beliau diangkat menjadi Rasul, maka ia datang pada hari Fatah (waktu Mekah direbut oleh kaum Muslimin), dan bersabda Rasulullah: Selamat datang saudara dan teman syarikatku.","r":"Ahmad dan Abu Daud"}],"te":"Kinds of Partnership"},{"t":"Cara Membahagi Keuntungan dan Kerugian","p":90,"v":2,"te":"Sharing Profit and Loss"}],"p":88,"v":2,"te":"Business Partnership (Syirkah)"},{"t":"Berwakil","c":[{"t":"Erti Berwakil","p":90,"v":2,"d":[{"y":"a","s":4,"a":35,"b":35,"m":""}],"te":"Meaning of Agency"},{"t":"Rukun dan Syarat Berwakil","p":92,"v":2,"te":"Pillars and Conditions of Agency"},{"t":"Yang Menerima Wakil Adalah Dipercayai","p":92,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah aku keluar pergi ke Khaibar (nama satu tempat), lalu aku datang kepada Nabi s.a.w. Maka beliau bersabda: Jika engkau datang kepada wakilku di Khaibar, maka ambillah daripadanya lima belas wasq (bahan makanan).","r":"Abu Daud"},{"y":"h","x":"Dari Jabir r.a. bahawa Nabi s.a.w. pernah menyembelih korban sebanyak 60 (enam puluh) ekor haiwan, dan disuruhnya Ali, supaya menyembelih binatang yang tinggal.","r":"Muslimin"}],"te":"The Agent Is Trusted"}],"p":90,"v":2,"te":"Agency (Wakalah)"},{"t":"Ikrar","c":[{"t":"Erti Ikrar","p":93,"v":2,"d":[{"y":"a","s":4,"a":134,"b":134,"m":""},{"y":"h","x":"Dari Abu Zarr r.a. ia berkata: Nabi s.a.w. telah bersabda kepadaku: Katakanlah yang benar itu, sekalipun pahit.","r":"Ibnu Hibban"}],"te":"Meaning of Acknowledgement"},{"t":"Syarat-Syarat Ikrar","p":95,"v":2,"d":[{"y":"a","s":16,"a":106,"b":106,"m":""}],"te":"Conditions of Acknowledgement"},{"t":"Erti Merampas","p":95,"v":2,"d":[{"y":"a","s":4,"a":29,"b":29,"m":""}],"te":"Meaning of Usurpation"},{"t":"Barang yang Dirampas Wajib Dikembalikan atau Diganti","p":96,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah salah seorang di antara isteri Nabi s.a.w. mengirimkan makanan kepada Nabi s.a.w. dalam sebuah mangkuk, maka oleh Aisyah dihempaskannya mangkuk itu, maka terbuanglah apa yang ada di dalamnya. Lalu Nabi s.a.w. bersabda: Makanan mesti diganti dengan makanan dan mangkuk juga diganti dengan mangkuk.","r":"Tirmizi dan Bukhari"}],"te":"Usurped Property Must Be Returned or Replaced"},{"t":"Merampas Tanah","p":97,"v":2,"d":[{"y":"h","x":"Dari Said bin Zaidr.a. bahawa Rasulullah s.a.w. pernah bersabda: Sesiapa yang merampas sejengkal tanah di bumi ini dengan cara aniaya, Allah akan mengalungkan tanah yang dirampasnya itu ke lehernya di hari kiamat, mulai dari ketujuh petala bumi.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Said bin Zaid r.a. ia berkata: Bersabda Rasulullah s.a.w.: “Sesiapa yang terbunuh dalam mempertahankan hartanya maka dia termasuk syahid, dan sesiapa yang terbunuh dalam mempertahankan dirinya maka dia termasuk syahid, dan sesiapa yang terbunuh dalam mempertahankan agamanya maka dia termasuk syahid, dan sesiapa yang terbunuh dalam mempertahankan keluarganya maka dia termasuk syahid.” aa","r":"Tirmizi"}],"te":"Usurping Land"},{"t":"Tanggal Iman Orang yang Merampas","p":98,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. bersabda: Seorang penzina tidak akan berzina ketika dia beriman. Dan seorang peminum arak tidak akan meminumnya ketika dia beriman. Dan seorang pencuri tidak akan mencuri ketika dia beriman. Dan seorang perompak tidak akan merompak di kala orang ramai sedang memperhatikannya, yang dia beriman.","r":"Bukhari dan Muslim"}],"te":"The Usurper's Faith Departs"},{"t":"Menanam Tanam-Tanaman di Tanah Orang Lain","p":99,"v":2,"d":[{"y":"h","x":"Dari Rafi' bin Khadij r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang menanam (tanam-tanaman) di sebidang tanah sesuatu kaum tanpa izin mereka, maka tanam-tanaman itu bukanlah menjadi kepunyaannya sedikit juga, tetapi ia berhak menerima nafkahnya (kerugiannya).","r":"Ahmad dan Abu Daud"}],"te":"Planting on Another Person's Land"}],"p":93,"v":2,"te":"Acknowledgement (Ikrar)"},{"t":"Syuf'ah","c":[{"t":"Erti Syuf'ah","p":99,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah menghukum Rasulullah s.a.w. dengan jalan melakukan syuf'ah, pada tiap-tiap barang yang belum dibahagi, maka apabila sudah ada perbatasan, dan jalan pun telah dipisahkan (masing-masing sudah ada tempat lalu sendiri), maka ketika itu tak perlu syuf ah pada barang yang dapat dipindah-pindahkan.","r":"Bukhari dan Muslim"}],"te":"Meaning of Pre-emption"},{"t":"Syufpah tidak Sah pada Barang yang Dapat Dibahagi","p":100,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah menghukum Rasulullah s.a.w. dengan syuf'ah, pada tiap-tiap syarikat yang belum dibahagi, iaitu pada rumah atau kebun yang tidak halal seseorang menjualnya, sehingga mendapat izin dari rakan kongsinya, maka jika dia mahu, dia boleh mengambilnya (membelinya) dan jika dia (tidak) mahu, dia boleh tinggalkan (membiarkan).","r":"Muslim"}],"te":"No Pre-emption in Divisible Property"},{"t":"Barang yang Dibahagi yang tidak Dapat Dipergunakan tidak Sah Padanya Syuf'ah","p":101,"v":2,"d":[{"y":"h","x":"Dari Nabi s.a.w. beliau bersabda: Orang yang sejiran lebih berhak dengan syuf ahjirannya, ia boleh menunggu (mengharapkkan) syuf'ah itu, sekalipun jiran jauh. Syaratnya, bila ada jalan yang dilalui oleh keduanya hanya satu.","r":"Abu Daud dan Tirmizi"}],"te":"No Pre-emption in Property Unusable Once Divided"},{"t":"Rukun dan Syarat Syuf'ah","p":102,"v":2,"te":"Pillars and Conditions of Pre-emption"}],"p":99,"v":2,"te":"Pre-emption (Syuf'ah)"},{"t":"Qiradh","c":[{"t":"Erti Qiradh","p":102,"v":2,"d":[{"y":"a","s":73,"a":20,"b":20,"m":"dharab, yang ertinya dalam ayat, ialah berjalan di bumi guna mencari kurnia Allah, iaitu rezeki, bukan bererti memukul. Firman Allah s.w.t.: Sesat Ta Aa a 3 Dn a Ja San Y * dl Ja DE Allah mengetahui, akan ada sebahagianmu orang sakit dan yang lain berjalan di muka bumi untuk mencari kurnia Allah dan yang lain akan berperang di jalan Allah"}],"te":"Meaning of Qiradh"},{"t":"Rukun dan Syarat Qiradh","p":103,"v":2,"te":"Pillars and Conditions of Qiradh"},{"t":"Minta Kembali Sebahagian Modal","p":104,"v":2,"te":"Asking for Part of the Capital Back"},{"t":"Yang Membawa Modal Dibenarkan dengan Sumpahnya Tentang Rugi atau Untung","p":105,"v":2,"d":[{"y":"h","x":"Dari Shuhaib r.a. bahawasanya Nabi s.a.w. bersabda: Tiga macam yang padanya ada keberkatan, iaitu jual beli hingga janjinya, melepaskan orang berdagang dan mencampurkan gandum dengan syair untuk dimakan bukan untuk dijual.","r":"Ibnu Majah"}],"te":"The Working Partner Is Believed on Oath About Loss or Profit"}],"p":102,"v":2,"te":"Silent Partnership (Qiradh)"},{"t":"Menyewa dan Mengupahkan Tanah","c":[{"t":"Erti Menyewa dan Mengupahkan Tanah","p":106,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Rasulullah s.a.w. pernah mengambil pekerja dari seorang penduduk Khaibar, pada sebidang tanah dengan memberikan sebahagian apa yang dihasilkannya, buah-buahan atau tanaman. |","r":"Bukhari dan Muslim"}],"te":"Meaning of Renting and Sharecropping Land"},{"t":"Rukun dan Syarat Sewa dan Mengupahkan Tanah","p":107,"v":2,"te":"Pillars and Conditions of Renting Land"},{"t":"Muzara'ah","p":107,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Sesungguhnya Nabi s.a.w. tidakmengharamkan bermuzara'ah, bahkan beliau menyuruh supaya yang sebahagian menyayangi yang sebahagian, dengan katanya: Sesiapa yang empunya tanah, maka hendaklah ditanaminya, atau diberikan faedahnya kepada saudaranya, dan jika ia tidak mahu, maka bolehlah ditahan saja tanahnya itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Rafi' r.a. dari Nabi s.a.w. beliau bersabda: Yang boleh bercucuk tanam hanya tiga macam orang, laki-laki yang ada tanah, maka dialah yang berhak mananamnya dan laki-laki yang diserah manfaat tanah kepadanya, maka dialah yang akan menanaminya, dan laki-laki yang menyewa bumi dengan emas atau perak.","r":"Abu Daud"},{"y":"h","x":"Dari Sabit bin Dhahak r.a. ia berkata, bahawa Rasulullah s.a.w. telah melarang muzara'ah dan menyuruh sewa menyewa saja, dan Rasulullah s.a.w. bersabda: Itu tidak mengapa.","r":"Muslim"}],"te":"Sharecropping (Muzara'ah)"},{"t":"Mukhabarah","p":110,"v":2,"d":[{"y":"h","x":"Dari Thaus r.a. bahawa ia suka bermukhabarah. Berkata Umar: Lalu aku katakan kepadanya: Ya Abdurrahman! Kalau engkau tinggalkan mukharabah ini, nanti mereka mengatakan, bahawa Nabi s.a.w. telah melarang mukharabah. Lantas Thaus berkata: Telah menceritakan kepadaku orang yang sungguh-sungguh mengetahui akan hal itu, iaitu Ibnu Abbas, bahawa Nabi s.a.w. tidak melarang mukhabarah itu, hanya beliau bersabda: Bila seseorang memberi manfaat kepada saudaranya lebih baik baginya daripada ia mengambil manfaat dari saudaranya itu, dengan upah yang dimaklumi.","r":"Muslim"}],"te":"Sharecropping (Mukhabarah)"},{"t":"Memelihara Anjing untuk Penjaga","p":111,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang membela anjing, yang bukan anjing untuk pemburu dan bukan pula untuk berjalan dan bukan pula untuk penjaga tanah (sawah-ladang), maka sesungguhnya kuranglah dua bahagian dari pahala amalannya tiap-tiap hari.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang menyimpan anjing, maka sesungguhnya kuranglah tiap-tiap hari satu bahagian dari amalnya, kecuali anjing untuk penjaga kambing atau untuk penjaga kebun, atau untuk berburu.","r":"Bukhari"}],"te":"Keeping a Dog as a Guard"},{"t":"Penjagaan Binatang Ternakan dan Tanam-Tanaman","p":112,"v":2,"d":[{"y":"h","x":"Dari Hiram bin Muhayyishah, ia berkata: Adalah Bara' bin Azib r.a. mempunyai seekor unta betina yang sering memakan tanamtanaman, lalu ia masuk ke dalam pagar, lantas membuat kerosakan di dalamnya (dimakannya tanam-tanaman), lantas soal itu dikatakan orang kepada Rasulullah s.a.w. maka Rasulullah menghukumkan bahawasanya menjaga kebun wajib atas yang empunya di waktu siang dan sesungguhnya menjaga binatang wajib atas yang empunya di waktu malam, dan wajib atas yang empunya binatang mengganti apa yang dirosakkan oleh binatang mereka di waktu malam.","r":"Abu Daud dan Nasai"}],"te":"Looking After Livestock and Crops"}],"p":106,"v":2,"te":"Renting and Sharecropping Land"},{"t":"Upah Mengupah (Ijarah)","c":[{"t":"Erti Upah Mengupah","p":113,"v":2,"d":[{"y":"a","s":65,"a":6,"b":6,"m":""}],"te":"Meaning of Hiring"},{"t":"Rukun dan Syarat Upah Mengupah","p":115,"v":2,"te":"Pillars and Conditions of Hiring"},{"t":"Orang yang Jujur, serta Soal Menerima Upah Berbekam","p":116,"v":2,"d":[{"y":"h","x":"Dari Abu Musa Al-Asy'ari r.a. dari Nabi s.a.w. beliau bersabda: Kasir (juruwang) yang jujur, yang melakukan pekerjaan yang diserahkan kepadanya secara senang hati, adalah ia masuk salah seorang orang yang bersedekah.","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah Rasulullah s.a.w. berbekam dan beliau memberikan upahnya kepada orang yang telah membekam beliau itu. Andaikata itu haram, tentu tidak diberi beliau upah.","r":"Bukhari"}],"te":"Honest Workers, and Payment for Cupping"},{"t":"Memberikan Upah atau Gaji Pegawai atau Buruh","p":117,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: Berilah upah orang yang bekerja sebelum kering peluhnya.","r":"Ibnu Majah"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. bahawa Nabi s.a.w. pernah bersabda: Sesiapa mencari orang yang akan makan upah, maka hendaklah dinyatakan kepadanya berapa upahnya.","r":"Abdurrazak"}],"te":"Paying Wages to Employees and Workers"},{"t":"Mengambil Upah Mengajar Al-Quran","p":117,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Pekerjaan yang lebih berhak kamu menerima upahnya, ialah mengajarkan kitab Allah Taala.","r":"Bukhari dan Muslim"}],"te":"Taking Payment for Teaching the Quran"}],"p":113,"v":2,"te":"Hiring and Wages (Ijarah)"},{"t":"Ihya Ul Mawat (Mengusahakan Tanah Terbiar)","c":[{"t":"Erti Mengusahakan Tanah Terbiar","p":119,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. bahawa Nabi s.a.w. bersabda: “Sesiapa yang membangun sebidang tanah yang bukan jadi hak seseorang, maka dialah yang berhak atas tanah itu.” |","r":"Bukhari"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Harim perigi yang baru digali ialah 25 hasta (sekelilingnya) dan harim perigi yang sudah digali (lama) ialah 50 hasta.","r":"Ahmad"}],"te":"Meaning of Reviving Unused Land"},{"t":"Yang Jadi Milik Bersama dalam Tanah Terbiar","p":120,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Orang Islam itu bersyarikat pada tiga macam, pada air, pada rumput dan pada api.","r":"Abu Daud dan Ibnu Majah"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Janganlah kamu melarang pada kelebihan air, dan dengan melarang kelebihan air itu kamu melarang pula pada kelebihan rumput.","r":"Bukhari dan Muslim"}],"te":"What Is Common Property in Unused Land"},{"t":"Daerah Larangan dan Cara Membuat Jalan","p":121,"v":2,"d":[{"y":"h","x":"Dari As-Shd'ab bin Jasamah r.a. dari Nabi s.a.w. beliau bersabda: Tidak ada daerah larangan, melainkan kerana Allah dan kerana Rasul-Nya, dan telah melarang Nabi s.a.w. (kata As-Sha'ab) akan Naqi' (satu tempat 80 batu dari Madinah), dan telah melarang Umar akan Sarif (satu tempat dekat Tanwin), dan Rabazah (satu tempat antara Mekah dan Madinah).","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah memutuskan Nabi s.a.w. bila mereka berselisih lalu di jalan supaya jalan itu dibuat 7 (tujuh) hasta.","r":"Bukhari dan Muslim"}],"te":"Protected Areas and Making Roads"},{"t":"Menanam Pokok di Pinggir Jalan","p":122,"v":2,"d":[{"y":"h","x":"Dari Nabi s.a.w. beliau bersabda: Tidaklah dari seseorang muslim yang menanam sepokok kayu, lalu buahnya dimakan burung atau manusia, atau binatang, melainkan adalah baginya dengan yang dimakan burung, binatang atau orang itu menjadi sedekah baginya.","r":"Bukhari dan Muslim"}],"te":"Planting Trees by the Roadside"},{"t":"Membahagi-Bahagi Tanah","p":123,"v":2,"d":[{"y":"h","x":"Dari Wail bin Hajar: Bahawasanya Nabi s.a.w. telah membahagibahagikan tanah di Hadramaut untuk peribadinya, dan diutusnya pula Muawiyah untuk dibahagikan pula tanah itu kepadanya.","r":"Abu Daud dan Tirmizi"}],"te":"Dividing Land"},{"t":"Tidak boleh Merosak dan Dirosakkan Orang","p":124,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Bersabda Rasulullah s.a.w.: Jangan kamu merosakkan dan jangan pula kamu dirosakkan orang.","r":"Ahmad dan Ibnu Majah"},{"y":"h","x":"Dari Samurah bin Jundab r.a. ia berkata: Bersabda Rasulullah s.a.w. Sesiapa yang telah membuat suatu dinding di bumi, maka bumi itu bererti telah menjadi haknya.","r":"Abu Daud"}],"te":"No Harm and No Harming"}],"p":119,"v":2,"te":"Reviving Dead Land (Ihya al-Mawat)"},{"t":"Shuluh (Perdamaian)","c":[{"t":"Erti Perdamaian","p":125,"v":2,"d":[{"y":"a","s":4,"a":128,"b":128,"m":""}],"te":"Meaning of Settlement"},{"t":"Perdamaian tidak boleh Menghalalkan Barang yang Haram, dan tidak Pula boleh Mengharamkan Barang yang Halal","p":126,"v":2,"d":[{"y":"h","x":"Dari Amr bin Auf Al-Muzanni r.a., bahawa Rasulullah s.a.w. bersabda: Perdamaian itu boleh berlaku antara kaum Muslimin, kecuali perdamaian yang bersifat mengharamkan sesuatu yang halal atau menghalalkan sesuatu yang haram, dan kaum Muslimin semuanya berdiri atas syarat-syarat mereka, kecuali syarat-syarat yang bersifat mengharamkan sesuatu yang halal atau menghalalkan sesuatu yang haram.","r":"Abu Daud dan Tirmizi"}],"te":"A Settlement Cannot Make the Forbidden Lawful or the Lawful Forbidden"},{"t":"Syarat-Syarat Ada Perdamaian","p":126,"v":2,"te":"Conditions of a Settlement"},{"t":"Perdamaian dalam Pembayaran","p":128,"v":2,"d":[{"y":"h","x":"Dari Kaab bin Malik, bahawa ia pernah bertengkar dengan Hadrad dalam perkara hutang-piutang di dalam masjid, iaitu Ibnu Kaab berhutang pada Abu Hadrad, keduanya sama-sama bersuara lantang, hingga didengar oleh Rasulullah s.a.w. sedang beliau di dalam rumahnya, maka melihatlah Rasulullah kepada keduanya, maka dibukanya kain tutup jendela kamarnya, lalu beliau berseru: Hai Kaab. Kaab menjawab: Aku ya Rasulullah. Rasulullah bersabda: Damaikanlah dari sebahagian hutangmu itu. Kaab berkata: Sesungguhnya telah aku lakukan, ya Rasulullah, Rasulullah bersabda: Bangunlah, maka bayarlah hutangnya (hutangmu itu).","r":"Bukhari dan Muslim"}],"te":"Settlement in Payment"}],"p":125,"v":2,"te":"Settlement (Sulh)"},{"t":"Wakaf","c":[{"t":"Erti Wakaf","p":128,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Bila telah mati anak Adam (manusia) putuslah amalnya, kecuali tiga macam: Sedekah jariah (wakaf), atau ilmu yang dapat diambil orang manFfaatnya, atau anak yang salih yang selalu mendoakannya.","r":"Muslim"}],"te":"Meaning of Wakaf"},{"t":"Rukun dan Syarat serta Mengambil Manfaat Barang Wakaf","p":129,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. bersabda tentang sebidang tanah di Khaibar yang telah diperolehi oleh Umar: Jika engkau kehendaki, engkau tahan tanah itu, dan engkau sedekahkanlah manfaatnya. Berkata Ibnu Umar: Bersedekahlah Umar dengan manfaatnya. Sesungguhnya tanah itu tidak boleh dijual pokoknya dan tidak pula boleh diwariskan, dan tidak pula diberikan kepada orang lain.","r":"Bukhari dan Muslim"}],"te":"Pillars and Conditions of Wakaf, and Using Its Benefit"},{"t":"Mewakafkan Masjid dan Perigi","p":131,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Tatkala datang Rasulullah s.a.w. ke Madinah, lalu diperintahkan beliau membuat masjid, beliau bersabda: Hai Bani Najjar (tukang kayu), juallah kepadaku perkaranganmu! Lalu mereka menjawab: Tidak, demi Allah kami tidak akan meminta wangnya kecuali (meminta pahalanya) kepada Allah. Lalu diambil Nabi tanah perkarangan itu, maka didirikannyalah di sana sebuah masjid.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Usman r.a. bahawa Rasulullah s.a.w. telah bersabda: “Sesiapa yang mahu menggali (mendalamkan) telaga di Raumah (satu tempat) maka baginya syurga.” Lalu aku gali telaga itu.","r":"Bukhari dan Tirmizi"},{"y":"h","x":"Dari Saad bin Ubadah r.a. ia bertanya: “Ya Rasulullah?” Sesungguhnya ibu Saad telah meninggal, maka apakah sedekahnya yang lebih utama?” Rasulullah menjawab: “Air.” Lalu digalinya sebuah perigi, kemudian ia berkata: “Ini untuk ibu Saad.","r":"Abu Daud dan Nasai"}],"te":"Endowing Mosques and Wells"}],"p":128,"v":2,"te":"Endowment (Wakaf)"},{"t":"Hibbah","c":[{"t":"Erti Hibbah","p":132,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Pernah Nabi s.a.w. menerima hadiah, dan dibalasnya hadiah itu.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau Basah Kalau aku dipanggil untuk memakan siku atau kaki kambing, nescaya akan aku terima dan kalau dihadiahkan kepadaku siku atau kaki kambing nescaya aku terima.","r":"Bukhari dan Tirmizi"}],"te":"Meaning of Hibah"},{"t":"Beri Memberi Dapat Menghilangkan Dengki","p":133,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah, dari Nabi s.a.w. beliau bersabda: Beri-memberilah kamu, kerana sesungguhnya pemberian itu menghilangkan sakit hati (dengki), dan janganlah satu keluarga menghinakan keluarga yang lain, walaupun yang diberikan itu sebelah kuku kambing.","r":"Bukhari dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Berimemberilah kamu, nanti kamu akan berkasih-kasihan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Nw man bin Basyir r.a. bahawasanya Nabi s.a.w. bersabda: Takutlah kamu kepada Allah, dan hendaklah kamu melakukan keadilan antara anak-anakmu.","r":"Bukhari dan Muslim"}],"te":"Giving Gifts Removes Envy"},{"t":"Hukum Haram Meminta Balik Pemberian, Kecuali Pemberian Bapa kepada Anak","p":135,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Nabi s.a.w. bersabda: Orang yang meminta kembali barang yang diberikannya, adalah seperti anjing yang muntah kemudian dijilatnya kembali muntahnya itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w beliau bersabda: Tidak halal bagi orang Islam apabila ia telah memberikan sesuatu, kemudian dimintanya kembali pemberiannya itu, kecuali pemberian orang tua kepada anaknya.","r":"Ahmad dan Abu Daud dan lain-lain"}],"te":"Taking Back a Gift Is Forbidden, Except a Father's Gift to His Child"},{"t":"Pemberian yang Meminta Balasan","p":136,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah seorang laki-laki memberikan kepada Rasulullah s.a.w. seekor unta betina lalu dibalas beliau pemberian itu dan beliau bersabda: Telah relakah engkau? Lakilaki itu menjawab: Belum.' Rasulullah lalu menambah balasannya itu dan bersabda: Telah relakah engkau? Laki-laki itu menjawab: Belum. Lalu beliau menambah pula pemberian itu, kemudian beliau bersabda: Telah relakah engkau? Laki-laki itu menjawab Ya, pp sudah!","r":"Ahmad dan Ibnu Hibban"}],"te":"Gifts That Expect Something in Return"},{"t":"Pemberian dengan Umraa dan Ruqbaa","p":137,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Nabi s.a.w. telah menetapkan dengan umraa bahawa umraa itu bagi orang yang telah diberikan kepadama:","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Bersabda Rasulullah s.a.w.: Peganglah hartamu di tanganmu dan janganlah kamu rosakkan, kerana sesungguhnya sesiapa yang melakukan pemberian secara menentukan umur, maka pemberian itu bagi orang yang telah disebutkan umurnya, baik ketika ia masih hidup ataupun ketika ia telah mati, dan bagi orang yang ditinggalkannya (warisnya).","r":"Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Sesungguhnya umraa yang dibolehkan oleh Rasulullah s.a.w. ialah bahawa seseorang berkata, Barang ini pemberian bagi engkau dan bagi ahli waris engkau, maka apabila ia berkata, Pemberian itu bagi engkau selama engkau hidup.' Maka sesungguhnya pemberian itu kembali kepada yang empunya barang.","r":"Muslim"},{"y":"h","x":"Dari Jabir r.a. bersabda Rasulullah s.a.w.: Janganlah kamu mengatakan ruqbaa, dan jangan pula kamu mengatakan umraa, maka sesiapa yang meruqbaakan sesuatu, atau mengumraakannya, maka barang yang di umraakan itu untuk ahli warisnya.","r":"Abu Daud Dan Nasai"}],"te":"Lifetime Gifts (Umra and Ruqba)"}],"p":132,"v":2,"te":"Gifts (Hibah)"},{"t":"Luqatah (Barang Terdapat)","c":[{"t":"Erti Luqatah","p":139,"v":2,"d":[{"y":"a","s":28,"a":8,"b":8,"m":""},{"y":"h","x":"Dari Zaid bin Khalid Al-Juhanni r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang mengambil barang orang yang tercicir, maka dia dalam kesesatan selama belum diberitahukannya.","r":"Muslim dan Ahmad"},{"y":"h","x":"Dari Zaid bin Khalid Al-Juhanni r.a. ia berkata: Pernah seorang laki-laki datang kepada Nabi s.a.w. lalu ia bertanya tentang barang yang tercicir, lantas beliau menjawab: Perhatikan bungkusan dan ikatannya (kalau barang itu dibungkus atau diikat), kemudian beritahukanlah selama setahun, barangkali datang orang yang empunya. Dan jika ia tidak juga datang, maka urusan engkaulah barang itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Zaid bin Khalid Al-Juhanni r.a. bahawa Nabi s.a.w. pernah ditanya tentang luqatah emas dan perak, lalu beliau jawab: “Perhatikanlah bungkusannya dan ikatannya, kemudian beritahukanlah selama setahun, jika tidak engkau ketahui yang empunya, belanjakanlah barang itu dan hendaklah barang itu dipandang sebagai pertaruhan pada engkau. Maka apabila datang orang yang meminta pada suatu hari sesudah masa memberitahukan itu, berikanlah kepadanya.” Penan","r":"Muslim"}],"te":"Meaning of Luqatah"},{"t":"Macam-Macam Barang yang Didapati","p":141,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. iaberkata: Pernah Rasulullah berlalu dan bertemu dengan sebuah tamar di tengah jalan, lalu beliau bersabda: Kalau tidaklah aku khuatir, bahawa tamar itu sebahagian dari sedekah orang, nescaya aku makan tamar itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Zaid bin Khalid Al-Juhanni r.a. bahawa seorang lelaki bertanya kepada Rasulullah s.a.w.: Ya Rasulullah! Bagaimana sebaiknya kambing yang sesat? Beliau menjawab: Ambillah, kerana dia boleh untuk engkau, atau saudara engkau, atau buat serigala (kalau engkau tinggalkan). Ia bertanya lagi: Lalu bagaimana pula unta yang sesat? Beliau menjawab: Tidak boleh engkau miliki, kerana dia dapat memiliki dirinya sendiri dapat mencari semuanya, dan makanannya. Ia cari air dan ia sanggup memakan buah-buahan hingga dijumpai oleh yang empunya.","r":"Bukhari dan Muslim"}],"te":"Kinds of Found Property"},{"t":"Tempat dan Cara-Cara Memberitahu","p":143,"v":2,"d":[{"y":"h","x":"Dari Yo'la bin Murrah ic berkata, bersabda Rasulullah: Sesiapa yang memungut suatu barang tercicir yang sedikit, misalnya seutas tali atau satu dirham, atau yang sama dengan itu, maka hendaklah ia beritahukan selama tiga hari. Jika lebih dari itu, maka hendaklah ia beritahukan enam hari, barangkali datang yang empunya, dan jika tidak datang, hendaklah ia sedekahkan saja barang yang didapatinya itu.","r":"Ahmad dan Tabrani"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Telah dibolehkan bagi kami oleh Rasulullah s.a.w., pada tongkat, cambuk, tali dan sebagainya yang dipungut oleh seorang lelaki untuk dipergunakan.","r":"Ahmad dan Abu Daud"}],"te":"Where and How to Announce It"},{"t":"Boleh Memerah Ternakan Orang Lain Kalau Terpaksa, bila Terdapat di Sesuatu Tempat","p":144,"v":2,"te":"Milking Someone Else's Livestock When in Need"},{"t":"Anak Pungut","p":145,"v":2,"d":[{"y":"a","s":52,"a":21,"b":21,"m":""}],"te":"A Foundling Child"},{"t":"Luqatah di Negeri Mekah dan Orang Haji","p":146,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. sesungguhnya beliau bersabda di dalam khutbahnya ketika negeri Mekah direbut: Dan tidaklah halal luqathahnya, kecuali untuk diberitahukan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdul Rahman bin Usman At-Taimi r.a., bahawa Raulullah s.a.w. telah melarang memungut luqatah orang haji.","r":"Muslim"}],"te":"Lost Property in Makkah and Pilgrims' Property"},{"t":"Hukum Memiliki Luqatah Jika yang Empunya tidak Juga Datang","p":147,"v":2,"d":[{"y":"h","x":"Dari Iyadh bin Himar r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang mendapat barang tercicir maka hendaklah saksikan kepada orang-orang yang dipandang adil, jaga ikatannya dan bungkusannya (kalau ada bungkus). Kemudian ia tidak boleh menyembunyikan dan tidak boleh pula menghilangkannya. Bila yang empunya datang meminta, maka ia lebih berhak dengan dia. Kalau tidak, maka barang itu adalah hak Allah, diberikannya kepada orang yang dikehendakinya.","r":"Imam Ahmad dan Al-Arba'ah"}],"te":"Owning Lost Property When the Owner Never Comes"}],"p":139,"v":2,"te":"Lost Property (Luqatah)"},{"t":"Ja'alah (Penawaran)","c":[{"t":"Erti Jaalah","p":147,"v":2,"te":"Meaning of Ja'alah"},{"t":"Upah Pengubatan","p":148,"v":2,"d":[{"y":"h","x":"Dari Abu Said Al-Khudrir.a. tentang orang disengat kala pada suatu kaum dari kaum Arab, ia berkata: “Demi Allah sesungguhnya aku sanggup mengubatinya tetapi demi Allah, sesungguhnya kami meminta makanan kepadamu, jika kamu tidak mahu menjamu kami, aku tidak akan mengubati kamu hingga kamu janjikan untuk kami suatu hadiah,” lalu mereka janjikan 30 ekor biri-biri, maka berjalanlah ia, lalu dicubanya mengubati yang digigit kala itu, dan dibacanya Al-Fatihah (dari awal sampai akhir), lalu yang sakit itu seolah-olah terlepas dari ikatan (sembuh). Hadis selanjutnya - kemudian mereka datang kepada Rasulullah s.a.w. lantas menceritakan kepada beliau, dan bersabdalah Rasulullah s.a.w.: Di mana engkau tahu, bahawa Al-Fatihah itu ubat? Betul perbuatanmu!","r":"Bukhari dan Muslim"}],"te":"Payment for Medical Treatment"}],"p":147,"v":2,"te":"Reward Contract (Ja'alah)"},{"t":"Wadiah","c":[{"t":"Erti Wadiah dan Syarat-Syaratnya","p":149,"v":2,"d":[{"y":"a","s":4,"a":57,"b":57,"m":""}],"te":"Meaning and Conditions of Wadiah"},{"t":"Orang yang Memegang Barang Amanat tidak Wajib Mengganti","p":150,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya, dari Nabi s.a.w. beliau bersabda: Sesiapa diserahkan suatu pertaruhan, maka tidaklah wajib atasnya menganti.","r":"Ibnu Majah"}],"te":"A Trustee Need Not Compensate for a Trust"},{"t":"Wajib Memulangkan Amanat kepada yang Empunya","p":150,"v":2,"d":[{"y":"h","x":"Dari Abu dlurairah r.a. ia berkata: Telah bersabda Nabi s.a.w.: Bayarkanlah amanat itu kepada orang yang telah bertaruhan kepada engkau, dan janganlah engkau berkhianat pada sesuatu yang dipertaruhkan orang kepada engkau.","r":"Abu Daud dan Tirmizi"}],"te":"Returning a Trust to Its Owner Is Obligatory"}],"p":149,"v":2,"te":"Safekeeping (Wadiah)"},{"t":"Wasiat","c":[{"t":"Erti Wasiat","p":151,"v":2,"d":[{"y":"a","s":4,"a":11,"b":11,"m":"Sesudah wasiat yang telah diwasiatkan oleh seseorang atau sesudah hutang dibayar"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawasanya Rasulullah s.a.w. telah bersab. da: Tidaklah yang menjadi hak orang Islam, yang ada padanya sesuatu yang hendak diwasiatkannya, dan ia akan bermalam dua malam, melainkan hendaklah wasiatnya itu dituliskan di dekatnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Saad bin Abu Waqash r.a. bahawa ia pernah berkata dalam sakitnya: Ya Rasulullah, sesungguhnya hartaku banyak dan tidak ada yang akan mewarisi harta itu selain seorang anakku yang perempuan, bolehkah aku wasiatkan hartaku itu semuanya? Rasulullah menjawab: Jangan! Dia bertanya lagi: Kalau dua pertiganya bagaimana? Beliau menjawab: Jangan! Aku bertanya lagi: Bagaimana kalau seperdua. Beliau menjawab: Jangan! Aku bertanya lagi: Kalau sepertiganya? Rasulullah menjawab: Ya, boleh dan sepertiga itu telah banyak. Sesungguhnya apabila engkau tinggalkar ahli waris engkau itu kaya lebih baik daripada engkau tinggalkan mereka dalam kemiskinan, meminta-minta kepada manusia.","r":"Bukhari dan Muslim"}],"te":"Meaning of a Bequest"},{"t":"Isi Wasiat tidak boleh Merugikan Ahli Waris","p":153,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesungguhnya lelaki atau perempuan yang hendak beramal dengan mentaati Allah Taala selama enam puluh tahun, kemudian ketika datang ajalnya, lalu keduanya membuat kemelaratan dalam wasiat (mewasiatkan hak ahli waris) wajiblah neraka bagi keduanya.","r":"Abu Daud dan Tirmizi"}],"te":"A Bequest May Not Harm the Heirs"},{"t":"Tidak Sah Berwasiat untuk Ahli Waris","p":153,"v":2,"d":[{"y":"h","x":"Dari Abu Umamah r.a. ia berkata: Telah bersabda Rasulullah s.a.w. dalam ceramahnya di tahun Haji wadak: Sesungguhnya Allah telah memberikan tiap-tiap orang empunya hak akan haknya, oleh sebab itu tidak boleh berwasiat untuk ahli waris. Anak zina itu semata-mata hak ibunya dan bagi orang yang berzina ada halangan (tidak ada hubungan apa-apa) dan perhitungan mereka terserah kepada Allah.","r":"Tirmizi"}],"te":"No Bequest to an Heir"},{"t":"Boleh Wasiat kepada Kerabat Karib selain Ahli Waris","p":154,"v":2,"d":[{"y":"a","s":2,"a":180,"b":180,"m":""}],"te":"A Bequest May Go to Close Relatives Who Are Not Heirs"}],"p":151,"v":2,"te":"Bequests (Wasiat)"},{"t":"Faraidh (Perwarisan)","c":[{"t":"Erti Faraidh","p":155,"v":2,"d":[{"y":"a","s":4,"a":7,"b":7,"m":""},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Bahagibahagilah harta benda antara ahli faraidh, menurut kitab Allah.","r":"Muslim dan Abu Daud"}],"te":"Meaning of Faraidh"},{"t":"Yang Bersangkutan dengan Peninggalan Mayat","p":156,"v":2,"te":"What Relates to the Estate of the Deceased"},{"t":"Rukun, Syarat dan Sebab-Sebab Menjadi Ahli Waris","p":157,"v":2,"te":"Pillars, Conditions and Causes of Inheritance"},{"t":"Yang Menghalangi Menjadi Ahli Waris","p":157,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a..w. beliau bersabda: Orang yang membunuh tidak dapat mewarisi.'","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Usamah bin Zaid r.a. dari Nabi s.a.w. beliau bersabda: Tidak boleh orang Islam mewarisi orang kafir, dan tidak pula orang kafir mewarisi orang Islam.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdullah Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Tidak dapat waris-mewarisi orang-orang yang berlainan agama.","r":"Abu Daud dan Tirmizi"},{"y":"a","s":16,"a":75,"b":75,"m":"Tidak dapat waris-mewarisi orang-orang yang berlainan agama. (Riwayat Abu Daud dan Tirmizi). Hal ini mengenai orang-orang yang memeluk agama apa saja, asal berlainan agama, yang seorang tidak dapat mempusakai yang lain, umpamanya yang seorang Yahudi dan yang seorang lagi Nasrani, apalagi yang satu Islam sedang yang lain kafir. Ketiga: Hamba abdi, sebab hamba abdi itu belum ada hubungannya dengan tuannya, sebelum dimerdekakan. Selama ia masih hamba abdi selama itu pula ia belum dapat berkuasa atas harta bendanya. Firman Allah s.w.t.: Ti SI SA Ka Yea jai Allah telah memperlihatkan satu contoh, iaitu hamba yang dimiliki tidak berkuasa di atas sesuatu juga"}],"te":"What Prevents Someone from Inheriting"},{"t":"Ahli Waris dari Pihak Laki-Laki dan Pihak Perempuan","p":159,"v":2,"te":"Heirs on the Male and Female Sides"},{"t":"Kalau Semua Ahli Waris Ada Semuanya","p":159,"v":2,"te":"When All the Heirs Are Present"},{"t":"Golongan Ahli Waris","p":160,"v":2,"te":"Groups of Heirs"}],"p":155,"v":2,"te":"Inheritance (Faraidh)"},{"t":"Macam-Macam Furudh di dalam Al-Quran","c":[{"t":"Contoh-Contoh Pembahagian","p":169,"v":2,"d":[{"y":"h","x":"Dari Abu Huarairah r.a. dari Nabi s.a.w. beliau bersabda: Jika anak bayi yang lahir itu menangis (lalu meninggal) ia mendapat pusaka.","r":"Abu Daud, Nasai dan lain-lain"}],"te":"Examples of Division"},{"t":"Hijab (Soal Orang yang Terdinding) dari Mendapat Waris","p":171,"v":2,"te":"Exclusion (Hijab) from Inheriting"},{"t":"Asobah dan Pembahagiannya","p":175,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Bersabda Rasulullah s.a.w.: Bahagi-bahagikanlah harta pusaka itu kepada ahlinya (orang-orang yang mempunyai bahagian), dan barang-barang yang masih berbaki itu hak bagi kerabat (keluarga) yang laki-laki, yang paling dekat kepada mayat.","r":"Bukhari dan Muslim"},{"y":"a","s":4,"a":175,"b":175,"m":""},{"y":"a","s":4,"a":176,"b":176,"m":"LA) o aan. 0,0 A e Z * PANDA z lag Sg z Lan Ku I Ss Ya Beg MELAKA a Dan apabila sesaudara, laki-laki dan perempuan, maka laki-laki mendapat bahagian sebanyak 2 orang perempuan"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: “Orang yang telah dimerdekakan itu hak bagi orang yang telah mengeluarkan wang (orang yang dahulu membelinya) dan ia menguasai nikmat kemerdekaannya itu.” |. |","r":"Bukhari dan Muslim"}],"te":"Residuary Heirs (Asabah) and Their Shares"},{"t":"Menyatakan Asal Masalah","p":180,"v":2,"d":[{"y":"a","s":4,"a":11,"b":11,"m":"bs ke SA Se G Ag Kena Ta Allah berpesan kepadamu tentang anak-anakmu, iaitu bagi seorang laki-laki seperti bahagian dua orang perempuan"}],"te":"Stating the Base of the Problem"},{"t":"Cara Mencari Pokok Masalah","p":181,"v":2,"te":"Finding the Base Number"},{"t":"Aul dan Contohnya","p":182,"v":2,"te":"Proportional Reduction ('Aul) and Examples"}],"p":162,"v":2,"d":[{"y":"a","s":4,"a":12,"b":12,"m":""},{"y":"a","s":4,"a":11,"b":11,"m":""},{"y":"a","s":4,"a":12,"b":12,"m":""},{"y":"a","s":4,"a":12,"b":12,"m":""},{"y":"a","s":4,"a":12,"b":12,"m":""},{"y":"a","s":4,"a":11,"b":11,"m":""},{"y":"a","s":4,"a":176,"b":176,"m":""},{"y":"a","s":4,"a":11,"b":11,"m":"PA Pa - Ku Os AM P N3 a) IK A KAH Pe Bila tidak ada baginya anak dan ia diwarisi oleh dua orang ibu bapanya, maka bagi ibunya sepertiga dari hartanya"},{"y":"a","s":4,"a":12,"b":12,"m":"PA Pa - Ku Os AM P N3 a) IK A KAH Pe Bila tidak ada baginya anak dan ia diwarisi oleh dua orang ibu bapanya, maka bagi ibunya sepertiga dari hartanya. (Surah An-Nisa' ayat 11). 2. Dua orang saudara seibu atau lebih, baik laki-laki mahupun perempuan. Dengan syarat: a. Tidak ada anak yang mewarisi dari mayat, b. Tidak ada bapa atau datuk. Firman Allah s.w.t.: SA AAA PER : a Ae IDA Naa Jika ada saudara seibu itu lebih dari seorang, maka mereka bersyarikat pada yang sepertiga itu"},{"y":"a","s":4,"a":11,"b":11,"m":""},{"y":"a","s":4,"a":11,"b":11,"m":""},{"y":"a","s":4,"a":12,"b":12,"m":""},{"y":"h","x":"Dari Imran bin Husseinr.a. bahawasanya seorang laki-laki pernah datang kepada Nabi s.a.w. lalu ia berkata: Sesungguhnya anak laki-laki dari anakku yang laki-laki telah meninggal, maka berapakah bahagianku dari harta warisannya? Rasulullah s.a.w. menjawab: Bagi engkau seperenam.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Buraidah r.a. bahawasanya Nabi s.a.w. telah menjadikan (memberikan untuk nenek perempuan seperenam, bila tidak ada berserta ibunya.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Ibnu Masud r.a. tentang anak perempuan, dan anak perempuan dari anak laki-laki berserta saudara perempuan, ia berkata: Sesungguhnya aku hukumkan kepadanya, seperti yang dihukumkan oleh Nabi s.a.w. iaitu bagi anak perempuan seperdua harta, dan bagi anak perempuan dari anak laki-laki seperenam untuk menyempurnakan dua pertiga, dan mana yang tinggal (setelah dibahagi) maka bagi saudara yang perempuanlah.","r":"Bukhari dan Abu Daud"}],"te":"Fixed Shares in the Quran"},{"t":"Ahli Waris yang Mendapat Furudh","c":[{"t":"Pembahagian Ahli Waris yang tidak Terhijab","p":197,"v":2,"d":[{"y":"a","s":8,"a":75,"b":75,"m":""}],"te":"Division Among Heirs Who Are Not Excluded"},{"t":"Zawil-Arham dan Soal Rad","p":199,"v":2,"d":[{"y":"h","x":"Dari Al-Miqdam bin Ma'dikariba r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Pak cik sebelah ibu adalah menjadi waris yang tidak ada waris.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Nabi s.a.w. beliau bersabda: Anak lelaki oleh saudara perempuan sesuatu kaum, adalah masuk golongan mereka atau diri mereka.","r":"Bukhari dan Muslim"}],"te":"Distant Kindred (Zawil Arham) and Return (Radd)"},{"t":"Bila Berkumpul Datuk-Datuk dengan Saudara Laki-Laki atau Perempuan","p":203,"v":2,"te":"When Grandfathers Inherit with Brothers or Sisters"},{"t":"Ahli Waris yang Dibuat dengan Perjanjian","p":211,"v":2,"d":[{"y":"a","s":4,"a":33,"b":33,"m":""}],"te":"Heirs by Agreement"},{"t":"Kesimpulan Ahli Waris yang Mengambil Harta Pusaka Menurut Al-Quran dan Hadis","p":212,"v":2,"te":"Summary of Heirs According to the Quran and Hadith"},{"t":"Al-Akdar","p":213,"v":2,"te":"Al-Akdariyyah"},{"t":"Bahagian yang Terpecah-Pecah","p":214,"v":2,"te":"Fractional Shares"}],"p":186,"v":2,"d":[{"y":"a","s":4,"a":12,"b":12,"m":"Maka apabila mereka (anak-anak yang seibu) lebih dari itu, maka mereka bersyarikat dalam sepertiga harta pusaka. perug"}],"te":"Heirs Who Receive Fixed Shares"}],"p":3,"v":2,"te":"Book of Trade and Sale"}],"p":1,"v":2,"d":[{"y":"a","s":28,"a":77,"b":77,"m":""},{"y":"h","x":"Dari Ibnu Umar r.a. beliau berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang melepaskan hajat saudaranya, Allah akan melepaskan pula hajatnya. Dan sesiapa yang suka melapangkan kesempitan orang Islam, Allah akan melapangkan pula kesempitannya dari beberapa kesempitannya di hari kiamat.","r":"Bukhari dan Muslim"}],"te":"Quarter of Transactions (Muamalat)"},{"t":"Rubu' Munakahat","c":[{"t":"Kitab Munakahat","c":[{"t":"Asas Munakahat","p":220,"v":2,"c":[{"t":"Erti Nikah atau Pernikahan","p":220,"v":2,"d":[{"y":"a","s":4,"a":3,"b":3,"m":""},{"y":"a","s":24,"a":32,"b":32,"m":""}],"te":"Meaning of Nikah and Marriage"},{"t":"Hikmat Nikah","p":221,"v":2,"d":[{"y":"a","s":30,"a":21,"b":21,"m":""},{"y":"h","x":"Dari Abdullah bin Mas'ud r.a. ia berkata: bersabda Rasulullah s.a.w.: Hai pemuda-pemuda sekalian, sesiapa yang sudah sanggup di antara kamu untuk kahwin, hendaklah ia kahwin, kerana sesungguhnya perkahwinan itu lebih menjaga bagi penglihatan dan lebih memelihara bagi kehormatan. Dan sesiapa yang belum sanggup untuk kahwin, maka berpuasalah, kerana sesungguhnya puasa itu gunanya untuk mengekang syahwat.","r":"Bukhari dan Muslim"}],"te":"Wisdom of Marriage"},{"t":"Hukum Nikah","p":222,"v":2,"d":[{"y":"h","x":"Dari Abu Ayub r.a. dari Nabi s.a.w. beliau bersabda: “Empat macam yang masuk bahagian sunah rasul-rasul: pemalu, suka berharum-haruman, bersiwak (bersugi atau menggosok gigi) dan ikah.” Na dian","r":"Ahmad dan Tirmizi"},{"y":"h","x":"Dari Anas r.a. ia berkata: Bersabda Nabi s.a.w.: Maka sesiapa yang membenci akan sunahku maka ia tidak masuk umatku.","r":"Bukhari dan Muslim"}],"te":"Ruling on Marriage"},{"t":"Dasar Pernikahan yang Dituntut oleh Syarak","p":222,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Dikahwini perempuan itu kerana empat macam, kerana hartanya, kerana baik kelakuannya, kerana kecantikannya dan kerana agamanya, maka ambillah perempuan yang taat kepada agama nanti engkau akan beruntung.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Nabi s.a.w.: Sesungguhnya dunia itu ialah harta benda, dan yang sebaik-baik harta benda dunia ialah perempuan yang salih.","r":"Nisai dan Muslim"},{"y":"h","x":"Dari Abdullah bin Umar r.a. ia berkata: Telah bersabda Rasululah s.a.w.: Janganlah kamu nikahi perempuan itu kerana kecantikannya, sebab barangkali kecantikannya dapat merosakkannya, dan jangan pula kerana hartanya, sebab barangkali hartanya dapat menjadikan derhaka, dan nikahilah perempuan itu kerana agamanya dan sesungguhnya hamba abdi yang hitam dan rosak telinganya tetapi yang beragama adalah lebih baik.","r":"Ibnu Majah dan Al-Bazzar"},{"y":"h","x":"Dari Anas r.a. ia berkata: Adalah Rasulullah s.a.w. menyuruh kami kahwin, dan melarang kami membujang, dengan larangan yang keras, lantas beliau bersabda: Kahwinilah perempuan yang banyak keturunannya (ramai anak) lagi dicintai, kerana sesungguhnya aku akan bermegah-megah dengan ramainya umatku di hari kiamat kelak.","r":"Ahmad dan Ibnu Hibban"},{"y":"h","x":"Dari Jabir r.a. sesungguhnya ia pernah kahwin, lalu Rasulullah s.a.w. bertanya: “Ya Jabir, engkau telah kahwin?” Aku jawab: ya”. Beliau bertanya: “Perawankah atau sudah janda (saib)?” Aku jawab: “Sudah janda”. Beliau bersabda: “Alangkah baiknya bila engkau kahwini yang masih perawan, akan lawan engkau bersenda Surau.","r":"Muslim dan Bukhari"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Bersabda Rasulullah s.a.w. : Kahwinilah gadis yang perawan, kerana sesungguhnya mereka lebih sedap mulutnya, dan lebih bersih rahimnya, dan lebih suka dengan segala sesuatu yang serba sederhana.","r":"Tabrani dan Baihaqi"},{"y":"a","s":49,"a":13,"b":13,"m":"Kahwinilah gadis yang perawan, kerana sesungguhnya mereka lebih sedap mulutnya, dan lebih bersih rahimnya, dan lebih suka dengan segala sesuatu yang serba sederhana. (Riwayat Tabrani dan Baihaqi). Keempat: Bahawa ada kedua-duanya hendaknya orang yang taat kepada Tuhan. Firman Allah s.w.t.: P) P P) o. ore D KE. | 2 | aaa *s a Sa U, Sesungguhnya yang semulia-mulia kamu di sisi Tuhan, ialah orang yang paling berbakti kepada-Nya"}],"te":"The Basis of Marriage Required by the Shariah"}],"te":"Basics of Marriage"},{"t":"Melamar atau Meminang","c":[{"t":"Melihat sebelum Melamar","p":226,"v":2,"d":[{"y":"h","x":"Dari Mughirah r.a. sesungguhnya ia pernah meminang seorang perempuan, lalu Nabi s.a.w. bersabda kepadanya: Lihatlah perempuan itu lebih dahulu kerana sesungguhnya melihat itu lebih cepat membawa kekekalan kecintaan antara keduanya.","r":"Nasai dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. berkata ia: Aku pernah duduk dekat Nabi s.a.w. lalu datang kepada beliau seorang lelaki maka diceritakan bahawa ia akan mengahwini seorang perempuan dari kaum Ansar. Rasulullah lalu bersabda: Sudahkah engkau melihat rupanya? Laki-laki itu menjawab: Belum. Rasulullah bersabda pula: Pergilah lihat, kerana sesungguhnya pada muka kaum Ansar itu mungkin ada sesuatu yang jadi cacat.","r":"Muslim dan Nasai"}],"te":"Seeing Before Proposing"},{"t":"Hal-Hal yang boleh Dilihat","p":227,"v":2,"d":[{"y":"a","s":24,"a":30,"b":31,"m":""},{"y":"a","s":24,"a":31,"b":31,"m":""}],"te":"What May Be Seen"},{"t":"Wanita-Wanita yang boleh Dilamar","p":228,"v":2,"d":[{"y":"a","s":2,"a":228,"b":228,"m":""},{"y":"a","s":2,"a":235,"b":235,"m":""},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: Tidak boleh meminang seseorang atas pinangan saudaranya, hingga yang meminang sebelumnya itu meninggalkan pinangannya, nd ankanya bagan.","r":"Bukhari dan Muslim"}],"te":"Women Who May Be Proposed To"}],"p":226,"v":2,"te":"Proposing Marriage"},{"t":"Kafaah","c":[{"t":"Erti Kafaah","p":229,"v":2,"d":[{"y":"a","s":2,"a":221,"b":221,"m":""},{"y":"h","x":"Dari Aisyah r.a. dalam perkara kisah Barirah ketika ia telah dimerdekakan, ia berkata: Adalah suami Barirah itu seorang hamba, lalu kepadanya diberi oleh Rasulullah s.a.w. kesempatan memilih, maka dengan sendirinya dipilihnyalah pernikahan itu. Andaikata suaminya itu seorang yang merdeka, tentu ia tidak melakukan pemilihan.","r":"Bukhari dan Muslim"},{"y":"a","s":24,"a":3,"b":3,"m":""},{"y":"a","s":24,"a":26,"b":26,"m":""},{"y":"a","s":39,"a":9,"b":9,"m":""},{"y":"h","x":"Dari Buraidah r.a. ia berkata: Pernah Abu Bakar dan Umar r.a. meminang Siti Fatimah (anak perempuan Nabi s.a.w.), maka bersabda Rasulullah s.a.w.: Sesungguhnya ia masih kecil. Kemudian dipinang oleh Ali r.a. maka beliau kahwinkanlah dengan Ali.","r":"Nasai"}],"te":"Meaning of Kafaah"},{"t":"Kafaah Menurut Agama","p":234,"v":2,"d":[{"y":"h","x":"Dari Abu Nadhrah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Hai manusia! Ketahuilah! Sesungguhnya Tuhanmu itu satu, bapamu satu. Ketahuilah! Tidak ada kelebihan orang Arab dari orang Ajam (bangsa selain bangsa Arab), dan tidak ada pula kelebihan orang Ajam dari orang Arab. Tidak ada kelebihan orang merah dari orang hitam dan tidak ada pula kelebihan orang hitam itu dari orang merah, melainkan dengan bertakwa kepada Allah.","r":"Ahmad"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawa Nabi s.a.w. bersabda: Hai Bani Bayadhah (nama suku), kahwinkanlah Abu Hindun, dan nikahkanlah dia, adalah Abu Hindun itu tukang bekam.","r":"Abu Daud dan Hakim"}],"te":"Compatibility in Religion"},{"t":"Nikah Tanpa Kemahuan Sendiri","p":235,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah datang seorang perempuan muda kepada Nabi s.a.w. lalu ia berkata: Sesungguhnya bapaku telah mengahwinkan aku dengan anak laki-laki saudaranya, dengan demikian supaya keburukan dirinya dapat diangkatnya. Rasulullah lalu menyerahkan urusan itu kepadanya sendiri, maka ia berkata: Sesungguhnya aku membolehkan apa yang telah diperbuat oleh bapaku, tetapi aku hendak memberitahukan kepada perempuan-perempuan lain, supaya kaum bapa sekali-kali tidak boleh lagi menjalankan urusan seperii itu.","r":"Ahmad dan Nasai"}],"te":"Marriage Without One's Own Consent"}],"p":229,"v":2,"te":"Compatibility (Kafaah)"},{"t":"Rukun Nikah","c":[{"t":"Tidak Sah Nikah Melainkan dengan Wali","p":236,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tidak boleh perempuan mengahwinkan perempuan, dan tidak boleh pula perempuan mengahwinkan dirinya sendiri.","r":"Ibnu Majah dan Daruqutni"},{"y":"a","s":2,"a":232,"b":232,"m":"Jumhur ulama mengambil alasan dengan hadis tersebut di atas, bahawa perkahwinan itu harus dengan wali. Dan juga beralasan dengan firman Allah yang berbunyi: Ja OT | BAKI ANA AT SANA aj Peri Sr di aa YAN al a Karan Maka janganlah kamu larang perempuan-perempuan itu mengahwini suaminya kembali, bila mereka telah suka sama suka dengan baik. yang Dai"},{"y":"h","x":"Dari Aisyahr.a. dari Nabi s.a.w. beliau bersabda: Tidak sahnikah, melainkan dengan berwali dan dua orang saksi yang adil.","r":"Ahmad dan Baihaqi"}],"te":"No Marriage Without a Guardian (Wali)"},{"t":"Syarat-Syarat Jadi Wali","p":238,"v":2,"d":[{"y":"a","s":3,"a":28,"b":28,"m":""},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Bersabda Rasulullah s.a.w.: Tidak sah nikah melainkan dengan wali yang cerdas atau dengan Sultan.","r":"Tabrani"}],"te":"Conditions of a Guardian"},{"t":"Wali yang tidak Mahu Menikahkan","p":239,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Perempuan yang kahwin dengan tidak seizin walinya, maka nikahnya itu batal, tiga kali diucapkan oleh Nabi kata-kata itu. Dan apabila ia telah dukhul (bersetubuh) dengan perempuan itu, maka yang wajib ialah mahar misil (sekadar pemberian) sebab ia telah mencampuri perempuan itu. Jika mereka berselisih, maka sultanlah wali oran yang tidak ada walinya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Samurah r.a. dari Nabi s.a.w. beliau bersabda: Perempuanperempuan yang dikahwinkan oleh dua orang walinya, maka perempuan itu jadi hak yang pertama.","r":"Abu Daud dan Ibnu Maja"}],"te":"A Guardian Who Refuses to Marry Her Off"},{"t":"Macam-Macam Wali","p":240,"v":2,"te":"Kinds of Guardian"},{"t":"Muhakkam","p":242,"v":2,"te":"An Appointed Arbiter as Guardian (Muhakkam)"},{"t":"Khutbah Nikah","p":242,"v":2,"d":[{"y":"h","x":"Dari Abdullah bin Mas'ud r.a. ia berkata: Telah diajarkan khutbah hajat kepada kami oleh Rasulullah s.a.w. di waktu nikah dan lainnya, iaitu: Puji-pujian bagi Allah, dan kepada-Nya kita minta tolong dan minta ampun. Dan kita berlindung pada Allah dari kejahatan-kejahatan diri kita. Sesiapa yang ditunjuki-Nya tidaklah ia akan sesat. Sesiapa yang disesatkan-Nya tidaklah ia akan dapat petunjuk. Aku bersaksi bahawa Muhammad adalah hamba dan utusan-Nya. Hai orang-orang yang beriman, takutlah kamu kepada Allah sebenar-benarnya takut, dan janganlah kamu mati melainkan kamu dalam memeluk agama Islam. Dan takutlah kamu kepada Allah yang kamu meminta-minta dengan Dia (nama-Nya) dan dengan perhubungan silaturrahim. Sesungguhnya Allah selalu melihat perbuatanmu. Hai orang-orang yang beriman, takutlah kamu kepada Allah dan ucapkanlah kata yang lemah-lembut. DiperbaikiNya bagimu segala amal pekerjaanmu, dan akan diampuni-Nya segala dosamu. Dan sesiapa yang mengikuti Allah dan rasul-Nya, maka sesungguhnya beruntunglah ia mendapat kemenangan yang sebearbaamya.","r":"Abu Daud dan Tirmizi"}],"te":"The Marriage Sermon"},{"t":"Erti Maskahwin dan yang Dapat Dijadikan Maskahwin","p":243,"v":2,"d":[{"y":"a","s":4,"a":4,"b":4,"m":""},{"y":"h","x":"Dari Abu Salmah r.a. pernah aku bertanya kepada Aisyah: Berapa maskahwin Rasulullah s.a.w. Aisyah menjawab: “Adalah maskahwin yang diberikan beliau kepada isteri-isteri beliau 12 (dua belas) auqiyah dan senasysya.” Ia berkata lagi: “Tahukah engkau, apakah nasysya itu?” Aku menjawab: “Tidak.” Lantas ia katakan, bahawa satu nasysya itu ialah setengah auqiyah, maka jumlah semuanya itu dalah 500 dirh adala irham.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Abdullah bin Amir bin Rabiah, dari bapanya bahawa seorang perempuan Bani Fazarah telah kahwin dengan maskahwin dua terompah, lalu Rasulullah s.a.w. bersabda: “Adakah engkau suka menukar diri engkau dan harta engkau dengan dua terompah?” Ia menjawab: “Aku rela.” Maka perkahwinan itu dibolehkan oleh Rasulullah s.a.w.","r":"Tirmizi"},{"y":"h","x":"Dari Shala bin Saad r.a. bahawa dalam kisah seorang laki-laki yang akan mengahwini seorang perempuan dan tidak ada padanya sesuatu pun yang dapat dijadikannya maskahwin. Ia berkata: Rasululah s.a.w. telah bersabda: Adakah engkau hafaz Al-Quran? Ia menjawab: Aku ada menghafaz surah itu dan surah ini. Lalu Rasulullah s.a.w. bersabda: Dapatkah engkau membacakannya di luar kepala (secara hafazan)? Ia menjawab: Ya. Rasulullah s.a.w. bersobda: Pergilah, sesungguhnya telah aku jadikan dia milikmu dengan apa yang ada serta engkau dari Al-Quran. Pergilah, sesungguhnya telah aku kahwinkan engkau dengannya, maka ajarkaniah kepadanya ayat Al-Quran itu.","r":"Muslim"},{"y":"h","x":"Dari Jabir bin Abdullah r.a. bahawa Nabi s.a.w. telah bersabda: Orang yang memberikan tepung atau tamar untuk maskahwin perempuan, maka halallah perempuan itu baginya.","r":"Abu Daud"},{"y":"h","x":"Dari Anas r.a. bahawa Nabi s.a.w.: Telah memerdekakan Shafiah (isterinya) dan beliau jadikan kemerdekaan itu sebagai maskahwinD","r":"Bukhari dan Muslim"}],"te":"Meaning of the Dowry and What May Be Given as Dowry"},{"t":"Yang Mewajibkan Maskahwin","p":246,"v":2,"d":[{"y":"h","x":"Dari Alqamah r.a. bahawa Ibnu Mas'ud pernah ditanya orang tentang seorang laki-laki yang telah mengahwini seorang perempuan, dan suami itu belum membayar maskahwin perempuannya dan belum pula ia dukhul (bersetubuh) dengan perempuan itu, lalu ia mati. Jawab Ibnu Mas'ud: “Hak baginya seperti maskahwin wanitawanita sebangsanya, tidak kurang dan tidak pula lebih, dan hak pula baginya harta pusaka, dan wajib atasnya idah (idah wafat).” Lalu berdiri Ma'qil bin Sanan Al-Asyja'i, lantas ia berkata: “Telah menghukumkan pula Rasulullah s.a.w. dalam perkara Barwa' anak perempuan Wasyiq, seumpama yang telah engkau hukumkan itu.” Maka gembiralah Ibnu Mas'ud setelah mendengar kejadian Barwa' itu.","r":"Abu Daud dan Tirmizi"},{"y":"a","s":2,"a":237,"b":237,"m":"Dan jika kamu menceraikan perempuan-perempuan itu sebelum kamu menyentuhnya, dan sesungguhnya kamu telah menentukan maskahwin bagi mereka, maka yang wajib dibayar ialah seperdua dari yang telah kamu tentukan itu. Kecuali apabila mereka atau orang-orang yang memegang akad nikah (wali) mahu memaafkan"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Perempuan yang mana juga kahwin dengan tidak setahu walinya maka nikahnya itu batal. Apabila yang mengahwinnya itu telah dukhul (bersetubuh) dengan dia maka hak baginya maskahwinnya sebab sesuatu yang telah dirasainya dari farajnya.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Bashrah bin Aksam Al-Ansari r.a. bahawa ia bertanya kepada Nabi s.a.w.: Aku telah mengahwini seorang perawan menurut keterangannya, lalu aku dukhul (bersetubuh) dengan dia maka tibatiba aku ketahui ia sudah mengandung. Nabi s.a.w. menjawab: Hak baginya maskahwinnya, sebab apa yang telah engkau lakukan pada farajnya.","r":"Abu Daud"}],"te":"What Makes the Dowry Due"},{"t":"Lafaz Nikah dan Menyempurnakan Maskahwin","p":249,"v":2,"d":[{"y":"a","s":33,"a":37,"b":37,"m":""},{"y":"h","x":"Dari Uqbah bin Amir r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Syarat-syarat yang lebih hak kamu sempurnakan, ialah syarat yang dengan syarat-syarat itu kamu telah merasakan faraj perempuan:","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah bersabda Nabi s.a.w.: Adapun syarat-syarat yang tidak ada bertemu di dalam kitab Allah bertentangan dengan agama maka syarat-syarat itu batal, sekalipun syaratsyarat itu diucapkan seratus kali.","r":"Bukhari dan Muslim"}],"te":"The Words of Marriage and Completing the Dowry"},{"t":"Syarat (Taklik) serta Menyerahkan Maskahwin","p":250,"v":2,"d":[{"y":"a","s":2,"a":236,"b":236,"m":""}],"te":"Conditions (Taklik) and Handing Over the Dowry"}],"p":236,"v":2,"te":"Pillars of Marriage"},{"t":"Menikahkan Wanita Perawan dan Wanita Janda","c":[{"t":"Minta Izin untuk Mengahwinkan Wanita Perawan","p":252,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Tidak boleh dinikahkan perempuan janda itu hingga diminta perintahnya, dan tidak boleh pula dikahwinkan anak perawan itu. hingga diminta izinnya. Mereka bertanya: Ya Rasulullah! Bagaimana izin anak perawan itu? Nabi menjawab: Apabila ia diam.","r":"Bukhari dan Muslim"}],"te":"Asking a Virgin's Permission Before Marrying Her Off"},{"t":"Wanita Janda Lebih Berhak dengan Dirinya untuk Kahwin","p":253,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa Nabi s.a.w. bersabda: Perempuan janda itu lebih berhak atas dirinya daripada walinya. Anak perawan itu diminta izinnya dan izinnya ialah diamnya.","r":"Muslim"}],"te":"A Previously Married Woman Has More Right over Herself"},{"t":"Mengahwinkan Anak di Bawah Umur","p":253,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah dikahwini aku oleh Rasulullah s.a.w. ketika aku anak perawan berumur epam tahun, dan beliau mencampuri aku ketika aku berumur sembilan tahun.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Anak perempuan yang masih di bawah umur (anak perempuan perawan) harus diminta perintahnya dalam perkara mengahwinkan dirinya. Jika ia diam, itulah tanda izinnya. Dan jika ia enggan maka tidaklah boleh dilakukan paksaan.","r":"Abu Daud dan Ibnu Majah"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah dikahwini aku oleh Rasulullah s.a.w. di bulan Syawal dan beliau campur dengan aku di bulan Syawal. Mana saja perempuan Rasulullah s.a.w. yang ada lebih beruntung di dekat beliau daripada aku. G  $-","r":"Muslim"}],"te":"Marrying Off a Child Under Age"}],"p":252,"v":2,"te":"Marrying a Virgin and a Previously Married Woman"},{"t":"Macam-Macam Wanita yang Akan Dinikahi","c":[{"t":"Wanita yang Sah Dinikahi","p":255,"v":2,"d":[{"y":"a","s":4,"a":24,"b":24,"m":"Dan diharamkan atasmu perempuan-perempuan yang sedang bersuami, kecuali perempuan-perempuan yang dimiliki tangan kananmu (hamba, iaitu perempuan yang dirampas di medan.perang), yang demikian itu telah dituliskan Allah atasmu"}],"te":"Women Who May Be Married"},{"t":"Wanita yang tidak Sah Dinikahi","p":256,"v":2,"d":[{"y":"a","s":4,"a":23,"b":23,"m":"Diharamkan atasmu ibumu, anak perempuanmu, saudara perempuanmu, makcik (saudara perempuan dari bapa), makcikmu (saudara perempuan dari ibu), anak perempuan dari saudara lakilaki dan anak perempuan dari saudara perempuan"},{"y":"a","s":4,"a":23,"b":23,"m":"Diharamkan atasmu ibumu, anak perempuanmu, saudara perempuanmu, makcik (saudara perempuan dari bapa), makcikmu (saudara perempuan dari ibu), anak perempuan dari saudara lakilaki dan anak perempuan dari saudara perempuan. (Surah An-Nisa' ayat 23). Dari sebab sepersusuan. Pertama: Ibu yang menyusukan (ibu susuan). Kedua: Saudara yang sesusuan (saudara susuan). Firman Allah s.w.t.: Ra A. Di Se Anis A, LAA A An g Dan diharamkan juga ke atasmu mengahwini ibu yang menyusukanmu dan saudaramu yang sesusuan"},{"y":"a","s":4,"a":23,"b":23,"m":""},{"y":"a","s":4,"a":22,"b":22,"m":"di PE oz w ea a a Ken a D an Ss Dan janganlah kamu nikah perempuan-perempuan yang telah dinikahi oleh bapa-bapamu, kecuali yang telah terdahulu (orang sebelum ayat ini diturunkan). Sesungguhnya perbuatan itu adalah sangat keji dan berdosa dan jalan yang sejahat-jahatnya"}],"te":"Women Who May Not Be Married"},{"t":"Tidak Sah Menikahi Dua Orang Bersaudara Sekaligus","p":258,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Tidak boleh dikumpulkan antara perempuan dan saudara perempuan dari bapanya dan tidak pula antara perempuan dan saudara perempuan dari ibunya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Yang haram oleh kerana sesusuan sebagaimana haram oleh sebab keturunan.","r":"Bukhari dan Muslim"}],"te":"Marrying Two Sisters at Once Is Invalid"},{"t":"Susuan yang Menyebabkan Mahram","p":259,"v":2,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia D Telah bersabda Rasulullah s.a.w.: Tidaklah dinamakan menyusu melainkan air susu yang telah menguatkan tulang dan menumbuhkan daging.","r":"Abu Daud"},{"y":"h","x":"Dari Ummu Fadhal r.a. dari Nabi s.a.w. beliau bersabda: “Tidaklah memahramkan sekali dua kali menyusu, sekali atau dua kali hi cucup).” paun)","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah pada barang yang diturunkan dari ayat Al-Quran iaitu sepuluh kali menyusu yang nyata boleh memahramkannya, kemudian ayat itu dimansuhkan (diubah hukumnya) dengan lima kali susu yang nyata.","r":"Muslim dan Abu Daud"}],"te":"Breastfeeding That Creates Mahram Ties"},{"t":"Menikahi Wanita Ahli Kitab","p":260,"v":2,"d":[{"y":"a","s":5,"a":5,"b":5,"m":""},{"y":"a","s":2,"a":221,"b":221,"m":"* Ss o PER) Ha s0 4 Sa da BMA In YG a Sa a Dan janganlah kamu kahwin dengan laki-laki musyrik itu sehingga mereka beriman. Dan sesungguhnya hamba yang mukmin lebih baik dari orang musyrik, sekalipun rupanya mengagumkan kamu"}],"te":"Marrying Women of the People of the Book"},{"t":"Suami atau Isteri yang Masuk Islam","p":261,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa seorang laki-laki pernah datang sesudah ia memeluk Islam di masa Rasulullah s.a.w. kemudian datang pula isterinya sesudah ia masuk Islam pula, maka ia berkata: Ya Rasulullah, sesungguhnya isteriku telah masuk Islam bersertaku, maka kembalikanlah dia kepadaku, maka dikembalikanlah isterinya itu oleh Rasulullah kepadanya.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah seorang wanita memeluk agama Islam di masa Rasulullah s.a.w. lalu wanita itu telah kahwin - Maka datang suaminya yang pertama kepada Nabi s.a.w. lantas ia berkata: Ya Rasulullah! Sesungguhnya aku telah masuk Islam, dan ia telah tahu dengan keislamanku — Lalu wanita itu ditarik kembali oleh Nabi s.a.w. dari suaminya yang kedua dan dikembalikannya kepada suami yang pertama.","r":"Abu Daud dan Ibnu Majah"}],"te":"When a Husband or Wife Becomes Muslim"},{"t":"Pernikahan yang Terlarang","p":262,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. telah melarang “syighar” dalam berakad. Dan yang dimaksudkan syighar ialah bahawa mengahwinkan seseorang akan anak perempuannya, dengan perjanjian bahawa dikahwininya pula anak perempuan laki-laki yang mengahwini anaknya, dan tiadalah antara keduanya maskahwin.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Salmah bin Al-Akwa' r.a. ia berkata: Pernah Rasulullah s.a.w. membolehkan perkahwinan mut'ah pada hari (peperangan) Authas selama tiga hari, kemudian sesudah itu beliau melarangnya.","r":"Muslim"},{"y":"h","x":"Dari Usman r.a. dari Nabi s.a.w., beliau bersabda: Orang yang sedang ihram tidak boleh menikah, tidak boleh menikahkan dan tidak boleh pula meminang.","r":"Muslim"},{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Telah mengutuki Rasulullah s.a.w. terhadap orang laki-laki yang menghalalkan, dan yang dihalalkan.","r":"Tirmizi dan Nasai"},{"y":"h","x":"Dari Uqbah bin Amir r.a. ia berkata: Bersabda Rasulullah s.a.w.: Mahukah kamu aku ceritakan tentang kehormatan yang dipinjamkan? Mereka menjawab: Mahu! Dan itulah si muhallil. Telah mengutuki Allah akan si muhallil dan muhallallah.","r":"Ibnu Majah dan Hakim"},{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. beliau bersabda: Hamba abdi mana juga yang kahwin dengan tidak seizin tuannya maka ia dihukum berzina.","r":"Abu Daud dan Tirmizi"}],"te":"Forbidden Marriages"}],"p":255,"v":2,"te":"Kinds of Women for Marriage"},{"t":"Walimatul Urus","c":[{"t":"Persiapan sebelum Pesta dan Memakai Genderang (Bunyi-Bunyian)","p":266,"v":2,"d":[{"y":"h","x":"Dari Ali r.a. ia berkata: Rasulullah telah menyediakan kain bulu tebal, gelas besar, dan bantal yang disirami dengan bau-bauan untuk Fatimah.","r":"Nasai"},{"y":"h","x":"Dari Aisyah r.a. bahawa ia pernah mengirimkan seorang perempuan kepada seorang laki-laki kaum Ansar, maka Nabi s.a.w. bersabda: Hai Aisyah, tidak adakah bersamamu alat penghibur? kerana kaum Ansar suka sekali kepada hiburan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Rabi' bin Mw'awwiz r.a. berkata: Telah Nabi s.a.w. datang lalu beliau masuk ketika aku menjadi pengantin. Lantas beliau duduk di atas tilamku, seperti tempat duduk engkau ini, maka masuklah pelayan-pelayan remaja perempuan (hamba-hamba abdi yang masih perawan) kepada kami, sambil memukul rebana dan mendendangkan orang-orang yang mati terbunuh, iaitu bapa-bapaku di haru perang Badar. Tiba-tiba berkata salah seorang di antara mereka (hamba-hamba): Di sini ada Nabi, yang mengetahui apa yang terjadi esok pagi. Maka Rasululah bersabda: Tinggalkan yang begini (berdendang, menyebut nama-nama orang yang telah tewas) dan nyanyikanlah menurut yang telah kamu katakan semula (mengagungagungkan jasa pahlawan, dengan tidak menyebut nama mereka.","r":"Bukhari dan Abu Daud"}],"te":"Preparing for the Feast and Using Drums (Music)"},{"t":"Rebana dalam Pesta Perkahwinan","p":268,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. dari Nabi s. a w. beliau bersabda: Beritahukanlah perkahwinan dan jadikanlah perkahwinan di masjid dan tepuklah rebana dalam perkahwinan itu.","r":"Ahmad dan Tirmizi"},{"y":"h","x":"Dari Muhammad bin Hatib r.a. dari Nabi s.a.w. beliau bersabda: Yang memisahkan antara yang haram dan yang halal ialah rebana dan suara nyanyian dalam perkahwinan.","r":"Nasai dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Adalah Nabi, s.a.w. Apabila beliau telah menyetujui seseorang kahwin dan apabila telah selesai perkahwinan itu, beliau ucapkan: Mudah-mudahan Allah memberi engkau berkat, dan didatangkan-Nya keselamatan atas engkau, dan mudah-mudahan dikumpulkan-Nya kamu keduanya dalam kebajikan.","r":"Abu Daud dan Nasai"}],"te":"The Tambourine at Weddings"},{"t":"Pesta Perkahwinan dengan Menyembelih Binatang Ternak","p":269,"v":2,"d":[{"y":"a","s":33,"a":53,"b":53,"m":"Walimatul Urus ertinya pesta pengantin. Kalau diundang, wajib mendatanginya. si dab BU SG ZA a Firman Allah s.w.t.: oY al P DE Apabila kamu diundang maka masuklah, dan apabila kamu telah selesai makan maka cepatlah keluar. Keterangan lain:"},{"y":"h","x":"Dari Anas bin Malik r.a. bahawa Nabi s.a.w. telah melihat bekasbekas wangi-wangian pada diri Abdurrahman bin Auf, lalu beliau bertanya: Apa ini? Ia menjawab: Ya Rasulullah, sesungguhnya aku telah mengahwini seorang perempuan, dengan maskahwinnya sebutir emas. Rasulullah bersabda: Mudah-mudahan Allah memberkati engkau, adakanlah pestanya, sekalipun dengan meInorong seekor Kambing,","r":"Bukhari dan Muslim"}],"te":"A Wedding Feast with Slaughtered Livestock"},{"t":"Kewajipan Menghadiri Undangan Walimatul-Urus","p":270,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Bila seseorang mengundang saudaranya, maka hendaklah saudaranya itu memperkenankannya, biar undangan itu untuk pesta mempelai dandanan","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Makanan yang paling kurang berkatnya ialah makanan jamuan (pesta) yang dilarang datang kepadanya orang yang ingin datang (orang-orang miskin). Dan diundang menghadirinya orang-orang yang tidak akan datang (orang-orang yang tak berkehendak sangat). Dan sesiapa yang tidak memperkenankan panggilan, sesungguhnya ia telah derhaka kepada Allah dan Rasul-Nya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Makanan yang paling kurang berkat-Nya, makanan kenduri, yang dipanggil kepadanya orangorang yang mampu saja dan ditinggalkan orang-orang yang miskin.","r":"Bukhari dan Muslim"}],"te":"The Duty to Attend a Wedding Invitation"},{"t":"Pesta yang Wajib Diperkenankan dan yang Dilarang Menghadirinya","p":271,"v":2,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Bersabda Rasulullah s.a.w.: Makanan hari pertama itulah yang hak dikabulkan, dan makanan hari kedua adalah urusan biasa. Adapun makanan hari ketiga menjadi kebanggaan (kesombongan). Dan sesiapa yang sombong, Allah sombong pula terhadapnya.","r":"Tirmizi dan lain-lainnya"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Sesungguhnya Nabi s.a.w. telah melarang memakan makanan orang-orang yang dengan sengaja untuk ditayangkan.","r":"Abu Daud"},{"y":"a","s":3,"a":104,"b":104,"m":"Sesungguhnya Nabi s.a.w. telah melarang memakan makanan orang-orang yang dengan sengaja untuk ditayangkan. (Riwayat Abu Daud). Bila seseorang menghadiri juga jamuan yang terdapat padanya kemungkaran, bererti ia menyetujui adanya kemungkaran itu. Firman Allah s.w.t.: # y o DA. SA pal as Si o :) 4 ; so P Pa ai, 5 al ta ay Dan hendaklah ada segolongan umat deripadamu, yang menyeru kepada kebaikan dan melarang berbuat kemungkaran dan mereka itulah orang-orang yang menang"}],"te":"Feasts That Must Be Attended and Those to Avoid"}],"p":266,"v":2,"te":"Wedding Feast (Walimah)"},{"t":"Hak dan Kewajipan Suami Isteri","c":[{"t":"Erti Hak dan Kewajipan","p":273,"v":2,"d":[{"y":"a","s":2,"a":228,"b":228,"m":""}],"te":"Meaning of Rights and Duties"},{"t":"Hak Isteri di Atas Suami","p":274,"v":2,"d":[{"y":"a","s":4,"a":19,"b":19,"m":""},{"y":"a","s":4,"a":34,"b":34,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. bersabda: Pergaulilah kaum wanita itu dengan pergaulan yang lemahlembut, kerana sesungguhnya kaum wanita itu dijadikan dari tulang rusuk dan sesungguhnya tulang rusuk itulah yang sebengkok-bengkoknya ialah yang paling atas. Maka apabila engkau hendak meluruskannya, engkau pecahlah dia, dan apabila tidak engkau luruskan, ia sentiasa bengkok selama-lamanya. Oleh sebab itu bergaullah dengan kaum wanita dengan pergaulan yang lemahlembut,","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. bersabda: Pergaulilah kaum wanita itu dengan pergaulan yang lemahlembut, kerana sesungguhnya kaum wanita itu dijadikan dari tulang rusuk dan sesungguhnya tulang rusuk itulah yang sebengkok-bengkoknya ialah yang paling atas. Maka apabila engkau hendak meluruskannya, engkau pecahlah dia, dan apabila tidak engkau luruskan, ia sentiasa bengkok selama-lamanya. Oleh sebab itu bergaullah dengan kaum wanita dengan pergaulan yang lemahlembut, (Riwayat Bukhari dan Muslim). Sabda Rasulullah s.a.w. lagi: PA D A DANA. u KARI A AA AA ea pa ols, Ap as aa Sesungguhnya perempuan itu dijadikan dari tulang rusuk yang bengkok. Sekali-kali tidak akan lurus perempuan itu bagi engkau atas satu jalan saja. Apabila engkau hendak bermesra dengan dia, bermesralah. Dan ketahuilah di dalam dirinya ada sifat bengkok, dan cara memecahkannya ialah menceraikannya.","r":"Muslim"},{"y":"h","x":"Dari Muawiyah bin Haidah r.a. ia berkata: Pernah aku bertanya kepada Rasulullah, apakah hak seseorang isteri yang wajib kami bayarkan. Beliau menjawab: Engkau beri makan dia apabila engkau makan, dan engkau beri pakaian apabila engkau berpakaian dan janganlah engkau memukul mukanya, dan jangan pula engkau maki-maki dan jangan engkau renggangi dia kecuali di dalam nanah du juga.","r":"Abu Daud"},{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. pada hadis haji, dalam perkara wanita beliau bersabda: Dan menjadi hak bagi mereka, kewajipan atasmu memberi makan dan pakaian mereka menurut yang sesual.","r":"Muslim"},{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. beliau bersabda: Bila seseorang telah lama hilang (dari isteri), maka janganlah ia masuki isterinya Pada wak malama","r":"Bukhari dan Muslim"}],"te":"The Wife's Rights over the Husband"},{"t":"Hak Suami di Atas Isteri","p":277,"v":2,"d":[{"y":"h","x":"Dari Amr bin Ahwash Al-Jusyammi r.a. bahawa Nabi s.a.w. bersabda: Ketahuilah, bahawa sesungguhnya bagimu atas kaum perempuan ada hak, dan bagi perempuan atas dirimu ada pula haknya.","r":"Tirmizi"},{"y":"a","s":4,"a":34,"b":34,"m":"Ketahuilah, bahawa sesungguhnya bagimu atas kaum perempuan ada hak, dan bagi perempuan atas dirimu ada pula haknya. (Riwayat Tirmizi). Adapun yang jadi kewajipan di atas isteri dan yang berupa hak oleh suami adalah: Pertama: Menjaga kehormatannya zahir dan batin, bila ada datang gangguan dari orang yang bukan mahramnya. Firman Allah s.a.w.!:  Kad A Sa D GG DULG P  Ng al AW DE Wanita-wanita yang baik ialah wanita yang berdiri menjaga kehormatannya dengan apa yang telah dijaga oleh Allah"},{"y":"h","x":"Dari Abdullah bin Amr bin Ash r.a. sesungguhnya Rasulullah s.a.w. pernah bersabda: Dunia ini adalah harta-benda, dan sebaik- 'baik harta-benda ialah perempuan yang salih.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Andaikata boleh aku memerintahkan supaya seseorang sujud kepada seseorang, nescaya akan aku suruh lebih dahulu perempuan sujud kepada suami.","r":"Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Bila seorang laki-laki mengajak isterinya ke tempat tidur, lalu isterinya enggan datang, dikutuki ia (isteri itu) oleh malaikat hingga waktu subuh.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. bahawa Rasulullah s.a.w. bersabda: Tidak halal bagi perempuan berpuasa (puasa sunat) sedang suaminya hadir di rumah, kecuali dengan izinnya. Dan tidak diizinkannya seseorang masuk ke rumahnya, kecuali dengan izin suaminya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Muaz bin Jabalr.a. dari Nabi s.a.w. beliau bersabda: Tidaklah menyakiti seorang perempuan akan suaminya di dunia, melainkan berkata isterinya yang daripada bidadari: Janganlah engkau sakiti dia, nanti engkau dikutuki Allah. Sesungguhnya dia di dekat engkau adalah sebagai tamu saja, yang tidak berapa lama lagi ja akan menceraikan engkau dan ia kembali kepada kami.","r":"Tirmizi"},{"y":"h","x":"Dari Abdullah r.a. dari Nabi s.a.w. beliau bersabda: Perempuan ituialah aurat, maka bila ia keluar, ia sentiasa dihiasi oleh syaitan.","r":"Tirmizi"},{"y":"h","x":"Dari Abdullah bin Amr bin Ash r.a. bahawa Rasulullah s.a.w. bersabda: “Sungguh telah menang (bahagia hidupnya) orang Islam dan adalah penghidupannya mencukupi (berhemat) dan hatinya disenangkan Allah dengan apa yang telah dikurniakan-Nya kepada- ” nya.","r":"Muslim"},{"y":"a","s":14,"a":7,"b":7,"m":"ve Laa a. AP a AA. Men ka a Si Ss A SA P Yaa Apabila kamu bersyukur, nescaya akan Ku-tambahi nikmat-Ku kepadamu dan apabila kamu ingkari, sesungguhnya seksa-Ku lebih sangai-"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Ya Rasulullah! Bagaimana isteri yang lebih baik? Beliau jawab: Iaitu perempuan yang suka menggembirakan suami apabila suami memandang kepadanya, dan mentaati perintahnya (bila suaminya memerintah) dan tidak dilanggar perintahnya itu dalam soal dirinya sendiri dan tidak pula dalam hartanya, yang menyebabkan suami benci.","r":"Nasai"}],"te":"The Husband's Rights over the Wife"}],"p":273,"v":2,"te":"Rights and Duties of Husband and Wife"},{"t":"Beristeri Lebih dari Seorang","c":[{"t":"Seorang Laki-Laki Dibolehkan Beristeri Lebih dari Seorang","p":283,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Ghailan bin Salmah As-Saqafi telah masuk Islam. Di waktu ia masih Jahiliah isterinya ada sepuluh orang. Isteri-isterinya itu Islam semua berserta dia. Lantas ia disuruh oleh Rasulullah s.a.w. memilih empat orang di antara mereka.","r":"Tirmizi dan Ibnu Majah"}],"te":"A Man May Marry More Than One Wife"},{"t":"Isteri Nabi Muhammad ﷺ","p":284,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Adalah Nabi s.a.w. bergiliran datang kepada isteri-isteri beliau satu-satu malam. Dan beliau ketika itu beristeri sembilan orang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Tidaklah diwafatkan Nabi Muhammad s.a.w. hingga Allah telah menghalalkan baginya mengahwini wanita berapa beliau sukai.","r":"Nasai"}],"te":"The Wives of Prophet Muhammad ﷺ"},{"t":"Pembahagian Secara Zahir dan Secara Batin","p":284,"v":2,"d":[{"y":"a","s":4,"a":129,"b":129,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang beristeri dua orang, lalu ia cenderung kepada salah seorang antara keduanya (tidak adil) ia datang di hari kiamat sedang badannya cenderung pula.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Nabi s.a.w. membahagi-bahagikan sesuatu di antara isteri-isternya secara adil dan beliau bersabda: Ya Allah, inilah cara pembahagian (yang dapat) aku lakukan pada barang yang aku miliki (pembahagian nafkah, pakaian dan lainlain), maka janganlah Engkau cela aku pada barang yang engkau miliki (kecintaan di dalam hati), dan itu tidak dapat aku miliki.","r":"Abu Daud dan Tirmizi"}],"te":"Outward and Inward Fairness"},{"t":"Pembahagian Giliran","p":287,"v":2,"d":[{"y":"a","s":10,"a":67,"b":67,"m":""},{"y":"h","x":"Dari Aisyah ia berkata: Adalah Rasulullah s.a.w. tidak melebihkan setengah kami di atas yang lain, dalam pembahagian waktunya memulangi kami, sekalipun sedikit sekali waktu bagi Rasulullah. Tetapi beliau tetap bergilir kepada kami, dan didekatnya tiap-tiap isterinya dengan tidak mencampurinya hingga ia sampai kepada isterinya yang mendapat giliran, lalu beliau bermalam di rumahnya.","r":"Abu Daud dan Ahmad"},{"y":"h","x":"Dari Anas r.a. ia berkata: Adalah Nabi s.a.w. bergilir kepada isteri-isterinya pada suatu malam, dan bagi beliau ketika itu ada senbaaworang Kien,","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah Rasulullah s.a.w. bila beliau hendak berjalan jauh diadakannya undian antara isterinya. Mana di antara mereka yang menang dalam undian itu, dengan dialah ia berjalan. Dan adalah Rasulullah membahagi waktu bagi tiap-tiap isterinya, harinya dan malamnya.","r":"Bukhari dan Muslim"}],"te":"Taking Turns"},{"t":"Giliran Waktu Kahwin dengan Janda atau Perawan","p":289,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. ia berkata: Sebahagian sunah Nabi s.a.w. ialah apabila seorang laki-laki mengahwini seorang perawan sesudah yang janda, bolehlah ia tinggal padanya selama 7 (tujuh) malam, dan apabila ia mengahwini perempuan yang sudah janda, boleh ia Tetap padanya selama 3 (tiga) hari, dan seterusnya diadakan giliran.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Bakar bin Abdurrahman r.a. bahawa Rasulullah s.a.w. setelah mengahwini Ummu Salamah, lalu beliau bermalam padanya. Kemudian Rasulullah hendak keluar, lalu direnggutkannya kain Rasulullah, maka bersabda Rasulullah s.a.w.: Jika aku kehendaki, aku tambahi waktunya untuk engkau, dan aku telah mencuKupkan waktu untuk engkau; bagi perempuan yang perawan tujuh malam dan bagi yang janda tiga malam.","r":"Muslim"}],"te":"Turns After Marrying a Widow or a Virgin"},{"t":"Mengajar Isteri yang Derhaka","p":290,"v":2,"d":[{"y":"a","s":4,"a":34,"b":34,"m":""},{"y":"h","x":"Dari Abdullah bin Zam'ah r.a. dari Nabi s.a.w. beliau bersabda: Tidak boleh seseorang suami memukul isterinya, seperti memukul seorang hamba, kemudian pada hari sesudahnya dicampurinya isterinya itu.","r":"Bukhari dan Tirmizi"},{"y":"h","x":"Dari Umar r.a. dari Nabi s.a.w. beliau bersabda: Tidak boleh seorang suami ditanya tentang sesuatu yang menyebabkan ia naaa saya","r":"Abu Daud dan Nasai"}],"te":"Correcting a Rebellious Wife"}],"p":283,"v":2,"te":"Having More Than One Wife"},{"t":"Bertahkim","p":292,"v":2,"d":[{"y":"a","s":4,"a":35,"b":35,"m":""}],"te":"Arbitration (Tahkim)"},{"t":"Perdamaian antara Suami Isteri","c":[{"t":"Erti Perdamaian antara Suami Isteri","p":293,"v":2,"d":[{"y":"a","s":4,"a":128,"b":128,"m":""},{"y":"h","x":"Dari Aisyah r.a. dalam firman Tuhan yang berbunyi: Dan jika perempuan itu khuatir (melihat) suaminya marah atau memalingkan muka, hingga akhir ayat, ia berkata: Ayat ini turun berhubungan dengan seorang perempuan yang ada di sisi suaminya, yang mana suaminya itu tidak banyak lagi bertempat tidur dengan dia. Lalu suaminya hendak menceraikannya serta hendak mengahwini perempuan lain (isteri muda). Perempuan itu berkata kepada suaminya: Biarkan sajalah aku tidak perlu engkau ceraikan, kemudian kahwinlah engkau dengan perempuan lain dan engkau tidak perlu memberi nafkahku dan juga tidak perlu pembahagian yang adil kepadaku.","r":"Bukhari dan Muslim"}],"te":"Meaning of Reconciliation Between Spouses"},{"t":"Tidak Wajib Mengisi Keadilan bila Telah Ada Perdamaian","p":295,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa Saudah, isteri Nabi s.a.w. pernah khuatir bahawa ia akan diceraikan oleh Nabi s.a.w. lalu ia berkata: “Janganlah engkau ceraikan aku, dan peliharalah aku (sebagai isteri engkau), dan biarlah aku serahkan hari giliranku untuk Aisyah.” Lantas dilaksanakanlah oleh Rasullulah s.a.w., maka turunlah ayat: Maka tidaklah berdosa atas keduanya bahawa keduanya berdamai, sedang perdamaian itulah yang sebaik-baiknya, maka apa yang telah disepakati keduanya dalam sesuatu, adalah boleh (jaiz) hukumnya.","r":"Tirmizi"}],"te":"Equal Division Is Not Required Once Reconciled"}],"p":293,"v":2,"te":"Reconciliation Between Husband and Wife"},{"t":"Pergaulan antara Lelaki dan Wanita","c":[{"t":"Larangan Berkhalwat antara Seorang Lelaki dan Seorang Perempuan","p":296,"v":2,"d":[{"y":"a","s":24,"a":3,"b":3,"m":""},{"y":"h","x":"Dari Jabir r.a. ia berkata: Pernah aku bertanya kepada Nabi s.a.w. tentang pandangan yang mengejutkan hati (yang menyirapkan darah di dada), maka beliau menjawab: Putarkanlah (alihkanleh) pandangan engkau","r":"Muslim dan Tirmizi"}],"te":"A Man and a Woman Alone Together (Khalwat) Is Forbidden"},{"t":"Syaitan Dapat Masuk Melalui Pembuluh Darah","p":297,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. beliau bersabda: “Janganlah kamu masuk atas perempuan ketika suaminya tidak ada, sebab syaitan dapat lalu di pembuluh darah seseorang.” Kami bertanya: “Dan pada engkau juga (ya Rasulullah)!” Beliau menjawab: “Pada pembuluh darahku juga, tetapi Allah selalu menolongku melawannya, hingga aku selamat daripadanya.” '","r":"Tirmizi"}],"te":"Satan Flows Through the Blood Vessels"},{"t":"Yang Dibolehkan hanya Pandangan yang Pertama Terhadap Wanita","p":298,"v":2,"d":[{"y":"h","x":"Dari Ali r.a. dari Nabi s.a.w. beliau bersabda: Ya Ali! Janganlah engkau turutkan pandangan itu, kerana yang boleh bagi engkau, hanyalah pandangan yang pertama dan tidak halal bagi engkau pandangan yang kedua.","r":"Abu Daud dan Tirmizi"}],"te":"Only the First Glance at a Woman Is Allowed"},{"t":"Memakai Tabir","p":299,"v":2,"d":[{"y":"a","s":33,"a":53,"b":53,"m":""},{"y":"h","x":"Dari Anas r.a. ia berkata: Ubay bin Ka'ab pernah bertanya kepadaku tentang perkara hijab dan akulah orang yang lebih mengetahui soal itu. Pernah Nabi s.a.w. masih menjadi pengantin dengan Zainab pada waktu pagi beliau mengahwini Zainab itu di Madinah. Lalu beliau undang orang-orang untuk makan, ketika matahari telah tinggi. Maka duduklah beberapa orang laki-laki berserta Rasulullah s.a.w. (selesai makan), sesudah orang lain bangun dari tempat duduknya, sampai Rasulullah s.a:w. bangun pula (agar mereka bangun dari duduk mereka). Lalu Rasulullah s.a.w. berjalan dan aku pun berjalan pula berserta beliau, hingga beliau sampai ke pintu bilik Aisyah. Kemudian Rasulullah s.a.w. mengira, bahawa mereka yang duduk itu telah keluar semuanya, lantas beliau kembali, dan aku pun kembali pula berserta beliau. Ternyata mereka masih duduk juga di tempat mereka semula. Beliau pun berbalik, lalu aku pun berbalik pula pada kali yang kedua, hingga beliau sampai pula ke pintu bilik Aisyah. Lalu beliau pun balik kembali, aku pun balik pula. Pada waktu itu mereka semuanya telah berdiri dari duduk mereka (keluar). Maka dipasang beliaulah tabir antaraku dan antara beliau, lalu turunlah ayat hijab, iaitu: Hai orang-orang yang beriman, hingga firman Tuhan: Dan bila kamu hendak bertanya sesuatu kepada…","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Bersabda Nabi s.a.w: Sesungguhnya perempuan-perempuan itu bila menghadap, seperti rupa syaitan, dan bila membelakang seperti rupa syaitan, m maka apabila seseorang. telah melihat perempuan, hendaklah ia datang kepada isterinya, kerana sesungguhnya itu dapat menghilangkan apa yang tergambar di dalam hatinya.","r":"Muslim"}],"te":"Using a Screen (Hijab)"},{"t":"Memakai Sifat Cemburu","p":302,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Bahawasanya Allah sangat cemburu dan orang mukmim itu cemburu. Dan yang dicemburui Allah, ialah bahawa orang mukmin mendatangkan (memperbuat) apa yang diharamkan oleh Allah.","r":"Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Tidak ada seseorang yang lebih cemburu daripada Allah apabila melihat hambaNya ber. apa.","r":"Bukhari"},{"y":"h","x":"Dari Saad bin Ubadah r.a. ia berkata: Andaikata aku lihat seseorang laki-laki ada berserta isteriku, nescaya aku parang dia dengan pedang dan bukan dengan belakangnya. Lalu Nabi s.a.w. bersabda: Apakah kamu tidak kagum tentang kecemburuannya (Sa'ad), sesungguhnya aku lebih cemburu daripadanya, dan Allah lebih cemburu pula daripadaku.","r":"Bukhari dan Muslim"}],"te":"Having Protective Jealousy"}],"p":296,"v":2,"te":"Interaction Between Men and Women"},{"t":"Kesopanan dalam Bersetubuh","c":[{"t":"Sang Isteri Adalah Merupakan Kebun dan Pakaian","p":303,"v":2,"d":[{"y":"a","s":2,"a":223,"b":223,"m":""},{"y":"a","s":2,"a":187,"b":187,"m":""}],"te":"The Wife Is a Garden and a Garment"},{"t":"Berlindung dari Godaan Syaitan","p":304,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Sesungguhnya salah seorang di antara kamu apabila hendak mendatangi isterinya (hendak bersetubuh), hendaklah ia membaca: Dengan nama Allah, Ya Allah jauhkanlah kami dari syaitan dan jauhkanlah syaitan itu dari barang yang telah Engkau beri rezeki kepada kami.' Kerana sesungguhnya jika ditakdirkan ada anak antara keduanya di waktu itu, tidak dapat syaitan menyakitinya selama-lamanya.","r":"Bukhari dan Muslim"}],"te":"Seeking Protection from Satan's Temptation"},{"t":"Larangan Mendatangi Isteri dari Sebelah Dubur dan boleh Melakukan Azal","p":304,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w., beliau bersabda: Allah tidak mahu melihat kepada laki-laki yang mendatangi laki-laki atau perempuan di sebelah duburnya.","r":"Tirmizi"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Adalah kami melakukan azal di masa Rasulullah s.a.w. Lalu hal itu sampai kepadanya, tetapi ia tidak melarang kami. Dan pada satu riwayat: Sedang Al-Quran turun ketika itu.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Rasulullah s.a.w. telah bersabda: “Terkutuklah orang-orang yang mendatangi isterinya di sebelah duburnya.” :","r":"Abu Daud dan Nasai"}],"te":"Approaching the Wife from Behind Is Forbidden; Withdrawal (Azal) Is Allowed"},{"t":"Bergurau sebelum Bersetubuh","p":305,"v":2,"d":[{"y":"h","x":"Dari Uqbah bin Amir ia berkata: Bersabda Nabi s.a.w: Tiap-tiap yang dijadikan permainan oleh laki-laki Islam, semuanya batil, melainkan melatih menembak dengan panah dan melatih kudanya untuk perang, dan senda gurau dengan isterinya, maka sesungguhnya semuanya adalah permainan yang hak.","r":"Tirmizi dan lain-lainnya"}],"te":"Affection Before Intimacy"},{"t":"Memakai Tutup","p":305,"v":2,"te":"Covering Oneself"},{"t":"Haram Hukumnya Bersetubuh ketika Isteri dalam Haid dan Nifas","p":305,"v":2,"d":[{"y":"a","s":2,"a":222,"b":222,"m":"Darah haid itu penyakit. Oleh sebab itu jauhilah isteri-isteri itu di waktu haid dan janganlah kamu dekati mereka, hingga mereka suci kembali"}],"te":"Intimacy During Menstruation and Postnatal Bleeding Is Forbidden"},{"t":"Wanita yang Ditawan di Medan Perang, sebelum Disetubuhi Hendaklah Diistibrakkan Lebih Dahulu","p":305,"v":2,"d":[{"y":"h","x":"Dari Ruwaifi' bin Sabit Al-Ansari r.a. dari Nabi s.a.w. beliau bersabda: Tidak halal bagi manusia yang percaya kepada Allah dan hari kiamat, bahawa dicampuri (wathak) perempuan yang ditawan, hingga diistibrakkannya lebih dahulu dengan keluar darah haid satu kali.","r":"Abu Daud dan Tirmizi"}],"te":"Captive Women Must First Wait One Cycle (Istibra')"}],"p":303,"v":2,"te":"Etiquette of Intimacy"},{"t":"Penceraian (Talak)","c":[{"t":"Talak Adalah Perbuatan Halal yang Dimurkai Tuhan","p":308,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Perbuatan halal yang dimurkai Allah ialah talak.","r":"Abu Daud dan Hakim"},{"y":"a","s":4,"a":130,"b":130,"m":"# P) n ya #  PR A ' ea g PAN os A Si Ku ul 4 SIS Aan Sa WS 4 Yu Gan KAI Aa Dan jika keduanya (suami isteri) bercerai, Allah akan melapangkan hidup masing-masing dan adalah Allah itu lapang lagi bijaksana"}],"te":"Divorce Is a Lawful Act Hated by Allah"},{"t":"Hukum Menjatuhkan Talak","p":309,"v":2,"te":"Ruling on Pronouncing Divorce"},{"t":"Syarat Sah Jatuh Talak","p":310,"v":2,"d":[{"y":"h","x":"Dari Alir.a. dari Nabi s.a.w. beliau bersabda: Diangkatkan dosa dari tiga macam orang, dari orang yang tidur hingga ia bangun, dari anak kecil hingga ia baligh dan dari orang gila sampai ia baik/sihat akalnya.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Semua talak itu dibolehkan agama, kecuali talak orang yang sudah berubah akalnya.","r":"Tirmizi hadis Mauquf"},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Sesungguhnya Allah Taala telah membuangkan dari umatku dosa tersalah, lupa dan dosa terpaksa.","r":"Ibnu Majah dan Hakim"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w.: Tidak ada talak itu sah, dan tidak pula kemerdekaan yang dalam keadaan terpaksa.","r":"Abu Daud"}],"te":"Conditions for a Valid Divorce"},{"t":"Lafaz yang Menunjukkan Talak","p":312,"v":2,"d":[{"y":"a","s":65,"a":2,"b":2,"m":"Hari ini engkau telah aku bebaskan. Firman Allah s.w.t.:.o ge, SA Ki & 0, Pan $ yan Kara a 5 Gu en Ya pn Maka rujukilah mereka dengan cara yang baik atau ceraikanlah mereka dengan cara yang baik pula"},{"y":"a","s":2,"a":231,"b":231,"m":"Hari ini engkau telah aku bebaskan. Firman Allah s.w.t.:.o ge, SA Ki & 0, Pan $ yan Kara a 5 Gu en Ya pn Maka rujukilah mereka dengan cara yang baik atau ceraikanlah mereka dengan cara yang baik pula. (Surah At-Talak, ayat 2). Firman Allah s.w.t.:.o K9. Pa Ca.1.o Re. P za UG Kar A pg Ga A YAN al a Maka rujukilah mereka dengan cara yang baik atau lepaslah mereka dengan cara yang baik pula"}],"te":"Words That Mean Divorce"},{"t":"Lafaz Nikah, Talak dan Rujuk tidak boleh Dipermain-Mainkan","p":312,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Tiga perkara, bila yang tiga itu disengaja benar, ia benar, dan kalau disengaja berolok-olok, iapun benar juga, iaitu nikah, talak dan rujuk.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Dimaafkanlah Allah umatku, selama yang terguris-guris di dalam hatinya belum dikatakannya atau belum dilakukannya.","r":"Bukhari dan Muslim"}],"te":"Marriage, Divorce and Return Are Not to Be Joked About"}],"p":308,"v":2,"te":"Divorce (Talak)"},{"t":"Macam-Macam Talak","c":[{"t":"Talak Raj'i","p":314,"v":2,"d":[{"y":"a","s":2,"a":229,"b":229,"m":""},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Adalah kaum laki-laki apabila ia telah menceraikan isterinya, ia beranggapan bahawa ia lebih berhak merujuki isterinya itu, sekalipun isterinya telah diceraikannya sampai tiga kali. Lalu dimansuhkan (ditukar hukumnya) dengan firman Tuhan yang berbunyi: Talak (yang boleh dirujuki) hanya dua kali, kemudian tahanlah secara pergaulan yang baik atau lepaskanlah dengan cara yang baik pula.","r":"Abu Daud dan 'Iirmizi"}],"te":"Revocable Divorce (Raj'i)"},{"t":"Talak Al-Battah","p":316,"v":2,"d":[{"y":"h","x":"Dari Rukanah bin Abdi Yazid r.a. ia berkata: Pernah aku datang kepada Nabi, lalu aku bertanya: Ya, Rasulullah sesungguhnya aku telah menceraikan (mentalak) isteriku secara Al-Battah. Maka Nabi bersabda: Berapa yang engkau kehendaki dengan kata-kata Al-Battah itu? Aku menjawab: Satu kali, beliau bersabda: Wallahi; aku ucapkan: Wallahi! Nabi bersabda: Maka jatuhnya menurut berapa ang engkau kehendaki.","r":"Abu Daud"}],"te":"Absolute Divorce (Al-Battah)"},{"t":"Talak Bain","p":317,"v":2,"d":[{"y":"a","s":2,"a":230,"b":230,"m":""},{"y":"a","s":2,"a":230,"b":230,"m":""},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Sesungguhnya Rifa'ah Al-Qurazhi, pernah datang kepada Nabi s.a.w. lalu ia berkata: Ya Rasulullah, sesungguhnya Rifa'ah telah menceraikan aku. Maka talak itu telah terputus untuk kembali kepadanya (talak tiga) dan sesungguhnya aku telah nikah dengan Abdurrahman bin Zubair Al-Qurazhi sesudah itu, dan percampuranku dengan dia adalah seumpama pergeseran hujung kain. Bersabda Rasulullah s.a.w: Barangkali engkau hendak kembali kepada Rifa'ah jangan, sebelum dirasakannya lazat madu engkau dan engkau rasakan pula madunya lebih dahulu.","r":"Bukhari dan Muslim"}],"te":"Irrevocable Divorce (Bain)"},{"t":"Menjatuhkan Talak Tiga Sekaligus","p":319,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Adalah talak di masa Nabi s.a.w. dan di masa Abu Bakar, dan dua tahun permulaan masa Khalifah Umar, iaitu talak tiga yang dijatuhkan sekaligus dihukumkan satu kali. Berkata Umar bin Khattab: Sesungguhnya manusia itu sangat suka sekali terburu-buru dalam sesuatu pekerjaan, yang sesungguhnya pekerjaan itu yang baik bagi mereka ialah dilambatkan (difikir secara mendalam). Alangkah baiknya kalau kita tetapkan saja hukum talak tiga atas mereka. Lantas diteruskannya hukum atas mereka.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Abu Ash-Shahba' r.a. bahawa ia pernah bertanya kepada Ibnu Abbas: “Adakah engkau tahu, sesungguhnya talck tiga itu ditetapkan satu di masa Nabi s.a.w. dan di masa Abu Bakar, tetapi dijadikan tiga di masa pemerintahan Umar?” Maka berkata Ibnu Abbas: “Ya!”","r":"Muslim dan Abu Daud"}],"te":"Pronouncing Three Divorces at Once"},{"t":"Perselisihan Pendapat Tentang Menjatuhkan Talak Tiga Sekaligus","p":320,"v":2,"te":"Differences of Opinion on Three Divorces at Once"},{"t":"Pengecualian Talak","p":321,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. bahawa Rasulullah s.a.w. bersabda: “Talak itu ialah dua kali talak dan idahnya dua kali haid.” ar Ks SUNI ol,","r":"Tirmizi"}],"te":"Conditional Exceptions in Divorce"},{"t":"Talak Sunni dan Talak Bid'i","p":322,"v":2,"d":[{"y":"a","s":65,"a":1,"b":1,"m":""},{"y":"h","x":"Dari Ibnu Umar r.a. bahawa ia pernah mentalak isterinya di masa Rasulullah s.a.w. sedang isterinya itu dalam haid, lalu Umar (bapanya) bertanya kepada Rasulullah s.a.w. tentang kejadian itu, lalu beliau bersabda: Suruhlah dia merujuki isterinya itu, kemudian hendaklah ia tahan isterinya itu (jangan diceraikan lagi) hingga ia suci, kemudian ia haid, kemudian ia suci, jika ia hendak meneruskan perkahwinan itu ditahannyalah sesudah itu (jangan diceraikan), dan jika ia hendak menceraikannya, ceraikanlah sebelum ia dicampuri, maka itulah idahnya (permulaannya) yang telah diperintahkan Allah dan boleh perempuan-perempuan diceraikan ketika itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Nafi' ia berkata: Adalah Ibnu Umar bila ia ditanya tentang seorang laki-laki menjatuhkan talak kepada isterinya, sedang isterinya itu dalam haid, ia berkata: “Adapun engkau telah mentalaknya sekali atau dua kali. Bahawasanya Rasulullah s.a.w. telah menyuruhnya supaya merujukinya.”..","r":"Muslim"}],"te":"Sunnah and Innovated Divorce"}],"p":314,"v":2,"te":"Kinds of Divorce"},{"t":"Idah","c":[{"t":"Erti Idah","p":325,"v":2,"te":"Meaning of Iddah"},{"t":"Idah Talak","p":325,"v":2,"d":[{"y":"a","s":2,"a":228,"b":228,"m":""},{"y":"a","s":65,"a":4,"b":4,"m":""},{"y":"a","s":33,"a":49,"b":49,"m":""}],"te":"Iddah After Divorce"},{"t":"Idah Hamil","p":326,"v":2,"d":[{"y":"a","s":65,"a":4,"b":4,"m":""},{"y":"h","x":"Dari Miswar bin Makhzamah r.a. bahawa Subai'ah Al-Aslamiah, pernah melahirkan anak sesudah suaminya meninggal dalam beberapa malam berselang. Lantas ia datang kepada Nabi s.a.w. minta izin untuk kahwin, lalu diizinkan oleh Rasulullah s.a.w. maka ia pun kahwinlah.","r":"Bukhari"}],"te":"Iddah of a Pregnant Woman"},{"t":"Idah Wafat","p":327,"v":2,"d":[{"y":"a","s":2,"a":234,"b":234,"m":""}],"te":"Iddah After a Husband's Death"},{"t":"Idah Wanita yang Kehilangan Suami","p":328,"v":2,"d":[{"y":"h","x":"Dari Umar r.a. ia berkata: Mana-mana saja perempuan yang kehilangan suaminya dan ia tidak mengetahui di mana dia, sesungguhnya perempuan itu wajib menunggu empat tahun, kemudian hendaklah ia beridah empat bulan sepuluh hari, barulah ia boleh kahwin.","r":"Malik"},{"y":"a","s":2,"a":231,"b":231,"m":""},{"y":"h","x":"Dari Said Bin Musayyab r.a. berkata: “Apabila seseorang hilang dalam barisan pertempuran hendaklah isterinya menunggu setahun Il y 3” amanya","r":"Bukhari"},{"y":"a","s":2,"a":235,"b":235,"m":"Isterinya itu tidak boleh kahwin, dan hartanya itu belum boleh dibahagi-bahagi, bila telah putus khabar beritanya maka aturannya ialah aturan suaminya yang hilang. (Ri t Bukhari) iwayat Bukhari). Sebelum idah sampai, haram hukumnya bagi perempuan kahwin. Firman Allah s.w.t.: ee a, di Susi a Ba a La a Y; Yo asa sun Ke in a LU Ai Ad 4 Dan janganlah kamu bercita-cita akan a hingga sampai bilangan idahmu terlebih dahulu. Dan ketahuilah bahawa Allah mengetahui segala yang ada dalam diri kamu, maka takutlah kamu kepada-Nya"},{"y":"h","x":"Dari Ummu Athiyah r.a. ia berkata: Adalah kami dilarang memakai perhiasan di waktu kematian lebih dari tiga hari, melainkan di waktu kematian suami iaitu empat bulan sepuluh hari, serta kami tidak boleh bercelak dan tidak boleh pula berharum-harum dan tidak boleh memakai kain yang berwarna.","r":"Bukhari dan Muslim"},{"y":"a","s":2,"a":234,"b":234,"m":""}],"te":"Iddah of a Woman Whose Husband Is Missing"}],"p":325,"v":2,"te":"Waiting Period (Iddah)"},{"t":"Rujuk","c":[{"t":"Erti Rujuk","p":332,"v":2,"d":[{"y":"a","s":2,"a":228,"b":228,"m":""}],"te":"Meaning of Ruju'"},{"t":"Rujuk hanya Dapat Dilakukan dalam Talak yang Raj'i","p":332,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ketika ditanya oleh seseorang ia berkata: Adapun engkau yang telah menceraikan (isteri) sekali atau dua kali maka sesungguhnya Rasulullah s.a.w. telah menyuruh merujuki kembali.","r":"Muslim"},{"y":"a","s":2,"a":231,"b":231,"m":"Adapun engkau yang telah menceraikan (isteri) sekali atau dua kali maka sesungguhnya Rasulullah s.a.w. telah menyuruh merujuki kembali. (Riwayat Muslim). Oleh kerana besarnya hikmat yang terkandung dalam mengikatkan tali perkahwinan itu maka bila seseorang telah menceraikan isterinya, ia disuruh oleh Allah s.w.t. supaya rujuk kembali. Firman Allah s.w.t.: *.o go, sha sl 4A Man AN Pa Ii; P D bae a ga YAN a A a yn KAI Ay Dan bila kamu telah menceraikan isterimu, sebelum idahnya sampai maka tahanlah (rujukilah) mereka kembali menurut yang sebaik-baiknya atau biarkanlah mereka menurut yang sebaik-baikda"}],"te":"Return Is Possible Only After a Revocable Divorce"},{"t":"Rukun Rujuk","p":333,"v":2,"te":"Pillars of Ruju'"},{"t":"Wajib Mengadakan Saksi","p":334,"v":2,"d":[{"y":"a","s":65,"a":2,"b":2,"m":""},{"y":"h","x":"Dari Ibnu Mas'ud r.a. ia berkata: Rasulullah s.a.w. bersabda: Talak itu adalah hak laki-laki, dan idah itu di pihak perempuan.","r":"Daruqutni dan Baihaqi"}],"te":"Witnesses Are Required"}],"p":332,"v":2,"te":"Return to Marriage (Ruju')"},{"t":"Khuluk","c":[{"t":"Erti Khuluk","p":335,"v":2,"d":[{"y":"a","s":2,"a":229,"b":229,"m":""}],"te":"Meaning of Khuluk"},{"t":"Sebab-Sebab Terjadi Khuluk","p":336,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya perempuan Sabit bin Qais, pernah datang kepada Nabi s.a.w. lalu ia berkata: Ya Rasulullah, aku tidak benci kepadanya kerana kelakuannya dan tidak pula dalam soal agama, akan tetapi aku benci sekali kepada kafir dalam Islam. Maka Rasulullah s.a.w. bertanya: Mahukah engkau mengembalikan taman bunganya (maskahwin) kepadanya? ia menjawab: Mahu! Bersabda Rasulullah s.a.w.: Terimalah (hai Sabit) taman bunga itu, dan ceraikanlah dia sekali.","r":"Bukhari dan Muslim"}],"te":"Reasons for Khuluk"},{"t":"Dilarang Keras Wanita Minta Cerai, Kalau tidak Ada Uzur Syar'i","p":337,"v":2,"d":[{"y":"h","x":"Dari Sauban r.a. bahawa Rasulullah s.a.w. bersabda: Mana-mana perempuan yang meminta cerai kepada suaminya, tidak kerana apaapa (tidak kerana uzur syar'i) maka haram atasnya bau syurga.","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa seorang isteri Sabit bin Qais telah mengkhuluknya, lalu Nabi s.a.w. menjadikan idahnya satu kali haid. Zu","r":"Abu Daud dan Tirmizi"}],"te":"A Wife May Not Ask for Divorce Without a Valid Reason"},{"t":"Cerai Khuluk tidak boleh Rujuk","p":338,"v":2,"te":"No Return After Khuluk"}],"p":335,"v":2,"te":"Divorce at the Wife's Request (Khuluk)"},{"t":"Fasah","c":[{"t":"Erti Fasah dan Sebab boleh Fasah","p":339,"v":2,"d":[{"y":"h","x":"Dari Kaab bin Zaid r.a. bahawa Rasulullah s.a.w. pernah mengahwini seorang perempuan Bani Ghafar maka tatkala ia akan dukhul (bersetubuh) dan perempuan itu telah meletakkan kainnya, dan ia duduk di atas katil, kelihatanlah oleh beliau putih (balar) di pinggangnya, lalu beliau berpaling (lari dari katil itu) kemudian berkata: “Ambillah kain engkau, tutupilah badan engkau. Dan tidak beliau ambil kembali barang yang beliau berikan kepada peremitu.” Dea","r":"Ahmad dan Baihaqi"},{"y":"h","x":"Dari Umar r.a. ia berkata: Bila mana seorang laki-laki mengahwini seorang perempuan, dan pada si perempuan itu ada tanda-tanda gila, atau ada kusta, atau balar, lalu disentuhnya perempuan itu, maka hak baginya maskahwinnya dengan sempurna. Dan yang demikian itu hak bagi suaminya hutang atas walinya.","r":"Malik dan Syafii"},{"y":"h","x":"Dari Said bin Musayyab r.a. ia berkata: Mana-mana laki-laki yang kahwin dengan seorang perempuan, dan pada laki-laki itu ada tanda-tanda gila, atau ada tanda-tanda yang dapat membahayakan, sesungguhnya perempuan itu boleh memilih. Jika dikehendakinya ditetapkannyalah perkahwinan itu, dan jika dikehendakinya boleh ia bercerai.","r":"Malik"},{"y":"h","x":"Dari Ali r.a. ia berkata: Mana-mana lelaki yang mengahwini perempuan lalu ia dukhul dengan perempuan itu, didapatinya perempuan itu kena balar atau gila atau penyakit kusta, maka hak baginya maskahwinnya dengan sebab menyentuh (mencampuri) perernpuan, dan maskahwin itu hak bagi suami (supaya dikembalikan) dan hutang di atas orang yang telah menipunya, dari perempuan itu. Dan kalau didapati ada daging tumbuh (difarajnya hingga menghalangi jima') suami itu boleh khiyar. Apabila ia telah menyentuhnya, maka hak baginya maskahwin sebab barang yang telah dilakukannya dengan farajnya.","r":"Said bin Mansur"},{"y":"h","x":"Dari Said bin Musayyabr.a. ia berkata: Telah memutuskan Umar bin Khattab, bahawasanya laki-laki yang Unnah di beri tempoh satu tahun.","r":"Said bin Mansur"},{"y":"a","s":2,"a":213,"b":213,"m":"Telah memutuskan Umar bin Khattab, bahawasanya laki-laki yang Unnah di beri tempoh satu tahun. (Riwayat Said bin Mansur). Guna diberi tempoh satu tanun, supaya jelas apakah betul ia Unnah atau tidak atau mungkin sembuh. Dikiaskan juga dengan aib yang enam macam ini, aib-aib yang lain yang dapat menghalangi maksud perkahwinan, biar dari pihak laki-laki mahupun dari pihak perempuan. Firman Allah s.w.t.: A Lia ng : Lau P a, P P P) 2 os gi 3 kal. a 5, KT Ba Bo KE N;... YAN &l a Ka Dan janganlah kamu rujuki mereka (isteri) untuk memberi kesusahan, kerana kamu hendak membuat aniaya, dan sesiapa yang berbuat demikian, maka sesungguhnya ia telah aniaya akan dirinya"}],"te":"Meaning of Fasakh and Its Grounds"},{"t":"Fasah yang Disebabkan tidak Diberi Belanja (Nafkah)","p":343,"v":2,"d":[{"y":"h","x":"Dari Umar r.a. bahawa ia pernah berkirim surat kepada pembesarpembesar tentera, tentang laki-laki yang telah jauh dari isteri-isteri mereka, supaya pemimpin-pemimpin itu menangkap mereka, agar mereka mengirim nafkah atau menceraikan isterinya. Maka bila mereka telah menceraikannya, hendaklah mereka kirim semua nafkah yang telah mereka tahan.... a","r":"Syafii dan Baihaqi"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w. tentang laki-laki yang tidak memperoleh apa yang akan dinafkahkannya kepada isterinya: Bolehlah keduanya bercerai.","r":"Daruqutni dan Baihaqi"}],"te":"Annulment for Lack of Maintenance"},{"t":"Pendapat Ulama Mengenai Masa Perlaksanaan Fasah","p":343,"v":2,"te":"Scholars' Views on When Annulment Takes Effect"}],"p":339,"v":2,"te":"Annulment (Fasakh)"},{"t":"Ila'","c":[{"t":"Erti Ila'","p":345,"v":2,"d":[{"y":"a","s":2,"a":226,"b":226,"m":""},{"y":"h","x":"Dari Anas r.a. ia berkata: Telah mengila' Rasullullah s.a.w. akan salah seorang isteri beliau, dan adalah kaki isterinya patah sebelah, lalu ia bermalam saja di suatu tempat yang bernama Masyrubah selama dua puluh sembilan malam, kemudian baru didekatinya (isterinya) itu. Mereka berkata: Bukankah Rasul telah mengila' isteri Rasul selama sebulan, maka bersabda Rasulullah s.a.w.: Bulan ini hanya dua puluh sembilan hari.","r":"Bukhari dan Muslim"}],"te":"Meaning of Ila'"},{"t":"Ila' Adalah Mengharamkan Bersetubuh dengan Isteri","p":345,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah mengila' Rasulullah s.a.w. akan sebahagian isterinya dan beliau telah mengharamkan sesuatu lalu dijadikannya yang haram itu menjadi halal, maka diisinyalah denda sumpahnya itu.","r":"Tirmizi"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Apabila seorang laki-laki mengharamkan isterinya atasnya, maka itu ialah sumpah, dan akan diisi denda (bila ia melanggarnya), dan ia berkata: Demi sungguh telah ada bagimu pada perbuatan Rasulullah s.a.w. contoh yang baik sekali.. ; :","r":"Bukhari dan Muslim"}],"te":"Ila' Is Forbidding Oneself Intimacy with One's Wife"},{"t":"Denda atau Kafarat Ila'","p":347,"v":2,"d":[{"y":"a","s":5,"a":89,"b":89,"m":""}],"te":"Penalty (Kafarah) for Ila'"}],"p":345,"v":2,"te":"Oath of Abstinence (Ila')"},{"t":"Zhihar","c":[{"t":"Erti Zhihar","p":348,"v":2,"te":"Meaning of Zihar"},{"t":"Hukum Zhihar","p":348,"v":2,"d":[{"y":"a","s":58,"a":2,"b":2,"m":"zhihar itu haram hukumnya. dan berdosa orang yang memperbuatnya, sebagaimana Allah menyatakan: o o D ati a A. Da a ra PA a Mp D a Sa a D Z sa An A DK Sa 7# Ra Da Ji Oo Ia Sa el Kent NI NI KM Pan A. ga da aa a Pelangan D ols ag - Orang-orang yang menzhihar isterinya di antaramu (padahal) mereka Apara isteri itu) bukan ibu mereka. Tidaklah ibu-ibu mereka, melainkan wanita yang melahirkan mereka. Dan sesungguhnya mereka sungguh-sungguh mengucapkan suatu perkataan yang mungkar dan dusta belaka. Dan sesungguhnya Allah Maha Pemaaf lagi Pengamun"}],"te":"Ruling on Zihar"},{"t":"Denda atau Kafarat Zhihar","p":349,"v":2,"d":[{"y":"a","s":58,"a":3,"b":4,"m":""}],"te":"Penalty (Kafarah) for Zihar"}],"p":348,"v":2,"te":"Zihar"},{"t":"Liu'an","c":[{"t":"Erti Lian","p":350,"v":2,"d":[{"y":"a","s":24,"a":6,"b":7,"m":""}],"te":"Meaning of Li'an"},{"t":"Isteri Bebas dari Hukuman Apabila Mahu Mengucapkan Sumpah Lian","p":352,"v":2,"d":[{"y":"a","s":24,"a":8,"b":9,"m":"Dan terhindarlah isteri itu daripada seksaan bila ia bersumpah empat kali dengan Allah, bahawa suaminya itu orang yang dusta dan yang kelima dibacanya, bahawa kemarahan adalah tertimpa atasnya, apabila suaminya itu yang benar"}],"te":"The Wife Is Freed from Punishment If She Swears the Li'an Oath"},{"t":"Cara Melakukan Sumpah Lian","p":352,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa Rasulullah s.a.w. pernah menyuruh seorang laki-laki meletakkan tangannya tatkala mengucapkan sumpahnya yang kelima di atas mulutnya, dan ia berkata: Sesungguhnya sumpah yang kelima itu memastikan seksaan Tuhan.","r":"Abu Daud dan Nasai"}],"te":"How the Li'an Oath Is Taken"},{"t":"Akibat Sumpah Lian bagi Suami Isteri","p":354,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Rasulullah s.a.w. berkata kepada (dua orang suami isteri) yang telah tuduh menuduh: Perhitungan engkau keduanya terserah kepada Allah; salah seorang di antara kamu berdua mesti ada yang berdusta. Tidak ada jalan lagi bagi engkau untuk kembali kepadanya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa ia telah berkata dalam hadis dua orang yang tuduh menuduh (suami isteri): Dan telah menghukum Rasulullah s.a.w. bahawa tidak ada tempat kediaman yang hak baginya (isteri) yang wajib atasnya (suami), dan tidak pula makanan yang wajib diberikan oleh suami, kerana keduanya telah bercerai, bukan kerana talak dan bukan pula kerana suaminya meninggal.","r":"Abu Daud"}],"te":"Effects of Li'an on the Couple"},{"t":"Akibat Sumpah Lian pada Hukum","p":355,"v":2,"te":"Legal Effects of Li'an"}],"p":350,"v":2,"te":"Mutual Cursing (Li'an)"},{"t":"Keturunan","c":[{"t":"Erti Keturunan","p":356,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairahr.a. ia berkata: Pernah datang seorang laki-laki suku Fazarah kepada Nabi s.a.w. lalu ia berkata: “Sesungguhnya isteriku telah melahirkan seorang anak laki-laki yang hitam warnanya.” Lalu Nabi bertanya: “Apakah bagi engkau ada unta.” Ia menjawab: “Ada.” Rasulullah bertanya: “Apakah warnanya?” Ia menjawab: “Merah.” Rasulullah bertanya lagi: “Adakah padanya warna kelabu?” Ia menjawab: “Sesungguhnya padanya banyak warna kelabu.” Selanjutnya Nabi bersabda: “Bagaimana warna itu datang kepadanya?” Dia menjawab: “Barangkali ditarik oleh peluhnya.” Rasulullah bersabda: “Dan anak engkau ini barangkali warnanya ditarik oleh peluh ibunya.” (menyerupai kulit ibunya).","r":"Bukhari dan Muslim"}],"te":"Meaning of Lineage"},{"t":"Larangan Menuduhkan Anak Kepunyaan Orang Lain","p":357,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Perempuan-perempuan yang menuduhkan seorang anak kepada sesuatu kaum, padahal anak itu bukan anak mereka, maka perempuan itu tidaklah jadi jaminan Allah dalam sesuatu perkara, dan perempuan itu sekali-kali tidak akan dimasukkan ke dalam syurga-Nya. Dan laki-laki yang menyangkal akan anaknya sendiri sedang ia mengetahui, bahawa anak itu memang anaknya, Allah Taala berlepas diri daripadanya, dan ia diberi malu oleh Allah s.w.t. di hadapan Orang-orang yang Kemudian;","r":"Abu Daud dan Nasai"}],"te":"Claiming Another Person's Child Is Forbidden"},{"t":"Mengundi Siapa yang Empunya Anak","p":358,"v":2,"d":[{"y":"h","x":"Dari Zaid bin Arqam r.a. ia berkata: Pernah Alir.a. didatangi tiga orang, iaitu ketika dia berada di Yaman. Mereka yang datang telah mencampuri seorang perempuan dalam masa suci yang bersamaan, maka bertanya Ali kepada dua orang (di antara mereka): “Mahukah kamu keduanya mengaku bahawa anak ini anak yang seorang lagi (orang ketiga)?” Keduanya berkata: “Tidak mahu” hingga mereka ketiganya ditanya oleh Ali. Maka diundilah antara mereka (kerana ketiganya mengakui anaknya), lalu anak itu diberikan oleh Ali kepada orang yang beroleh undian itu dan diwajibkan orang itu membayar dua pertiga tebusan kepada kedua orang sahabatnya. Hal ini kemudian diberitahukannya kepada Nabi s.a.w. maka tertawalah Rasulullah hingga kelihatan semua gigi beliau.","r":"Abu Daud dan Nasai"}],"te":"Drawing Lots over Who Owns a Child"},{"t":"Anak yang Sah Keturunan Bapanya, Sedang Anak yang tidak Sah Keturunan Ibunya","p":359,"v":2,"d":[{"y":"a","s":33,"a":5,"b":5,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. bahawasanya Nabi s.a.w. pernah bersabda: Anak zina itu ialah untuk ibunya, dan laki-laki yang berzina Ia berhak dilempar barat","r":"Bukhari dan Muslim"}],"te":"A Child Lawfully Related to the Father, and One Related Only to the Mother"},{"t":"Penyangkalan Terhadap Anak","p":360,"v":2,"d":[{"y":"a","s":46,"a":15,"b":15,"m":""},{"y":"a","s":31,"a":14,"b":14,"m":""}],"te":"Denying a Child"}],"p":356,"v":2,"te":"Lineage"},{"t":"Muhadhanah (Mengasuh)","c":[{"t":"Erti Muhadhanah dan Orang yang Berhak Melakukan Muhadhanah","p":361,"v":2,"d":[{"y":"h","x":"Dari Abdullah bin Umar r.a. bahawa seorang perempuan pernah berkata: Ya Rasulullah, sesungguhnya anakku ini adalah perutku yang mengandunginya, dan susuku yang jadi minumannya, dan pangkuanku yang memeluknya, sedang bapanya telah menceraikan aku, dan bapanya itu mahu mengambilnya daripadaku. Lalu Rasulullah s.a.w. bersabda kepadanya: Engkau yang lebih berhak dengan anak itu, selama engkau belum kahwin.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Pernah aku bersama-sama dengan Nabi s.a.w. lalu datang seorang perempuan, dan ia berkata: “Ya Rasulullah! Sesungguhnya suamiku hendak pergi membawa anakku, dan sesungguhnya ia telah memberi minum daripada perigi Abu Inabah? dan sungguh ia telah berjasa kepadaku.” Maka bersabda Rasulullah s.a.w.: “Berundinglah kamu perkara anak itu.” Maka berkata suaminya itu: “Siapakah yang berani menghalangi aku dengan anakku ini?” Dan bersabda Nabi s.a.w. (kepada anak itu). Ini bapamu dan ini ibumu. Maka ambillah tangan yang mana antara keduanya yang engkau kehendaki. Lalu diambilnya tangan ibunya, maka berjalanlah perempuan itu dengan anaknya.","r":"Ash-Habussunan"},{"y":"h","x":"Dari Al-Bara' bin Azibr.a. bahawasanya Nabi s.a.w. telah memutuskan dalam perkara anak perempuan oleh Hamzah (dalam perkara mengasuh) untuk makciknya (adik perempuan ibunya), dan ia berkata: Makcik itu adalah mengambil tempat ibu.","r":"Bukhari"}],"te":"Meaning of Custody and Who Has the Right to It"},{"t":"Anak Mengikut kepada Siapa yang Islam dari Kedua Orang Ibu Bapanya","p":364,"v":2,"d":[{"y":"h","x":"Dari Rafi' bin Sinan r.a. bahawa ia telah masuk Islam sedang isterinya enggan masuk Islam. Maka isterinya datang kepada Nabi s.a.w. lalu berkata: (Ini) anakku, sambil disusukan. Dan Rafi' juga berkata: (Ini) anakku! Lalu Nabi s.a.w. bersabda: Duduklah engkau di sebelah sini, dan beliau bersabda pula kepada isterinya: Duduklah engkau di sebelah sana, dan duduklah anak itu di antara keduanya. Kemudian beliau bersabda: Panggillah anakmu. (Setelah masingmasing memanggilnya), maka anak itu menoleh kepada ibunya. Lantas Nabi s.a.w. berdoa: Ya Allah! Tunjukilah anak ini. Lalu anak itu menoleh kepada bapanya, maka diambilnya anaknya itu.","r":"Abu Daud dan Nasai"}],"te":"The Child Follows the Muslim Parent"}],"p":361,"v":2,"te":"Child Custody (Hadhanah)"},{"t":"Radha'ah (Menyusukan)","c":[{"t":"Erti Menyusukan","p":366,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawasanya Nabi s.a.w. telah bersabda: Dan haram hukumnya kerana sepersusuannya apa yang haram sebab seketurunan.","r":"Bukhari dan Muslim"}],"te":"Meaning of Breastfeeding"},{"t":"Susuan yang Mengakibatkan Mahram","p":366,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Maka sesungguhnya susuan itu kerana disebabkan lapar.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Mas'udr.a. ia berkata: Telah bersabda Rasulullah s.a.w: “Tidaklah dinamakan susuan, melainkan susuan yang menguatkan tulang, dan menumbuhkan daging.” :","r":"Abu Daud"},{"y":"a","s":2,"a":233,"b":233,"m":"Tidaklah dinamakan susuan, melainkan susuan yang menguatkan tulang, dan menumbuhkan daging. : (Diriwayatkan oleh Abu Daud). Selain dari itu bahawa menyusukan itu paling lama selama dua tahun. Bila menyusukan itu sesudah lebih dua tahun ke atas, maka antara yang menyusukan dan yang disusukan itu tidak menjadi mahram. Sebab Allah berfirman: Len P ; ? A 07 SS Ke SS AS YAN al a g g Dua tahun yang sempurna, bagi orang yang hendak menyempurnakan masa susuan"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Adalah pada apa yang turun dari AlQuran sepuluh kali susuan yang diketahui (jumlahnya) yang mengharamkan. Kemudian hukum itu dimansuhkan (ditukar) dengan lima kali susuan yang diketahui. Lalu diwafatkan Rasulullah, sedang kalimat 'lima kali susuan yang dimaklumi' itu adalah termasuk pada apa yang dibaca dari Al-Quran.","r":"Muslim"}],"te":"Breastfeeding That Creates Mahram Ties"},{"t":"Perintah Menyusukan Anak Bukanlah Perintah Wajib","p":368,"v":2,"d":[{"y":"a","s":2,"a":233,"b":233,"m":""},{"y":"a","s":65,"a":6,"b":6,"m":""},{"y":"a","s":65,"a":6,"b":6,"m":""}],"te":"Breastfeeding Is Not an Absolute Obligation"},{"t":"Lama Masa Menyusukan","p":368,"v":2,"d":[{"y":"a","s":2,"a":233,"b":233,"m":""},{"y":"a","s":2,"a":233,"b":233,"m":""},{"y":"a","s":46,"a":15,"b":15,"m":"Apabila perempuan melahirkan anak yarig baru saja enam bulan mengandung, hendaklah ia menyusukannya selama dua tahun. Apabila anak itu dilahirkannya setelah tujuh bulan mengandung, hendaklah disusukannya 23 bulan. Dan apabila anak itu dilahirkan sesudah genap sembilan bulan dalam kandungan hendaklah disusukannya selama 21 bulan. Dengan demikian, lama masa mengandung dan menceraikan ada selama 30 bulan. Firman Allah s.w.t.: $ Lana Oo. P Sea Sy CI Sa das AKA Dari mengandungnya dan (sampai) menceraikannya lamanya tiga puluh bulan"}],"te":"Length of Breastfeeding"}],"p":366,"v":2,"te":"Breastfeeding (Radha'ah)"},{"t":"Nafkah","c":[{"t":"Erti Nafkah","p":371,"v":2,"d":[{"y":"a","s":65,"a":7,"b":7,"m":""}],"te":"Meaning of Nafkah"},{"t":"Sebab-Sebab yang Mewajibkan Nafkah","p":372,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. di dalam hadis haji dalam perkara menyebutkan soal perempuan, beliau bersabda: “Dan hak bagi mereka, kewajipan atasmu memberi makan mereka dan pakaian mereka menurut yang kesesuaiannya.”..","r":"Muslim"},{"y":"a","s":65,"a":6,"b":6,"m":""},{"y":"h","x":"Dari Fatimah binti Qais r.a. ia berkata: Aku telah tiga kali diceraikan oleh suamiku, lalu Rasulullah s.a.w. tidak memberi tempat untukku dan tidak pula belanja.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Aisyah r.a. ia berkata tentang seorang perempuan yang tidak pernah diberi nafkah oleh suaminya. Rasulullah s.a.w. telah bersabda: “Ambillah olehmu dari hartanya menurut yang sesuai, iaitu sekadar mencukupi untuk belanjamu dan mencukupi pula untuk anak-anakmu.”, f","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Tharik Al-Muharibi r.a. ia berkata: Rasulullah s.a.w. bersabda di atas mimbar: Tangan yang memberi itu lebih mulia, dan mulailah memberi dengan orang yang wajib bagimu menanggung nafkahnya, iaitu ibu engkau, bapa engkau, saudara-saudara engkau yang perempuan dan saudara engkau yang laki-laki kemudian orang yang dekat hubungannya dengan engkau dan yang dekat pula seterusnya.","r":"Nasai"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Hak bagi yang dimiliki memberi makannya dan pakaiannya dan ia tidak boleh diberati berkerja, melainkan sekadar kesanggupannya.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w.: “Wang yang engkau belanjakan di jalan Allah dan wang yang engkau belanjakan untuk memerdekakan seorang hamba dan wang yang engkau sedekahkan kepada fakir miskin, serta wang yang engkau belanjakan untuk keperluan keluarga engkau, maka yang lebih besar pahalanya ialah wang yang engkau belanjakan untuk keluarga engkau.” Da Kn Pena - ARA, D Ai Ja Ga : AU a (en En","r":"Muslim"},{"y":"h","x":"Dari Abdullah bin Umarr.a. ia berkata: Telah bersabda Rasulullah s.a.w: Besarlah dosa manusia yang mensia-siakan orang-orang yang menjadi tanggungjawabnya.","r":"Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Diseksanya seorang perempuan kerana kucing. Kucing itu dikurungnya hingga mati, maka masuklah perempuan itu ke dalam neraka kerana kucing itu tidak diberinya makan dan tidak pula diberinya minum ketika dikurungnya dan tidak ditinggalkannya rumput-rumputnya yangakandinakannya.","r":"Bukhari dan Muslim"}],"te":"What Makes Maintenance Obligatory"}],"p":371,"v":2,"te":"Maintenance (Nafkah)"}],"p":220,"v":2,"te":"Book of Marriage"},{"t":"Kitab Makanan dan Pakaian","c":[{"t":"Asas Makanan dan Pakaian","p":378,"v":2,"c":[{"t":"Ketentuan Barang yang Akan Dimakan","p":378,"v":2,"d":[{"y":"a","s":5,"a":1,"b":1,"m":""},{"y":"h","x":"Dari Salman Al-Farisi ia berkata: Telah bersabda Rasulullah s.a.w.: Yang halal ialah apa yang telah dihalalkan oleh Allah dalam kitab-Nya, dan haram ialah apa yang telah diharamkan oleh Allah dalam kitab-Nya, dan sesuatu yang didiamkan-Nya hukumnya ialah termasuk barang yang dimaafkan (dibolehkan).","r":"Tirmizi dan Abu Daud"}],"te":"Rules for What May Be Eaten"},{"t":"Binatang-Binatang yang Halal Dimakan","p":379,"v":2,"d":[{"y":"h","x":"Dari Asma' r.a. ia berkata: Pernah kami menyembelih seekor kuda di masa Nabi s.a.w. lalu kami makan dagingnya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Khalid bin Walid r.a. sesungguhnya ia pernah bertanya kepada Nabi s.a.w. tentang binatang tenggiling direbus, katanya: “Apakah binatang itu haram, ya Rasulullah?” Rasulullah menjawab: “Tidak, tetapi binatang itu tidak ada di negeriku, maka oleh sebab itu tak ada nafsuku hendak memakannya.” Berkata Khalid: “Maka kutariklah dia, lantas aku makan, sedang Nabi s.a.w. melihat.” g","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Qatadah r.a. dalam perkara himar liar, ia berkata: Maka telah dimakan oleh Nabi s.a.w.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Musa r.a. ia berkata: Pernah aku melihat Nabi s.a.w. makan (daging) ayam.","r":"Bukhari dan Tirmizi"},{"y":"h","x":"Dari Ibnu Abu Aufar.a. ia berkata: “Pernah kami berperang bersama Nabi s.a.w. sebanyak tujuh atau enam kali, dan kami pernah makan belalang berserta Nabi.”.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. dalam perkara binatang arnab ia berkata: Aku bawa kepada Abu Talhah seekor arnab, lalu disembelihnya. Kemudian dikirimkan orang dua pehanya kepada Rasulullah s.a.w. maka beliau terima pemberian itu.","r":"Bukhari dan Muslim"}],"te":"Animals That Are Lawful to Eat"},{"t":"Binatang Laut, serta Bangkai Ikan dan Belalang","p":382,"v":2,"d":[{"y":"a","s":5,"a":96,"b":96,"m":": SI Le alah pem) k2 IN JI Yi ul DU Bn Dihalalkan bagimu menangkap buruan (binatang) laut dan memakannya, akan jadi kesenangan bagimu dan bagi para musafir"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w. tentang perkara laut, iaitu suci airnya dan halal bangkainya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ibnu Umarr.a. dari Nabi s.a.w. beliau bersabda: Dihalalkan bagi kita dua jenis bangkai dan dua jenis darah. Kedua jenis bangkai itu ialah ikan dan belalang dan dua jenis darah itu ialah hati dan limpa.","r":"Ibnu Majah dan Hakim"}],"te":"Sea Creatures, Dead Fish and Locusts"},{"t":"Binatang-Binatang yang Haram Dimakan","p":383,"v":2,"d":[{"y":"a","s":5,"a":3,"b":3,"m":""},{"y":"h","x":"Dari Jabir r.a. ia berkata: Pada hari Khaibar Rasulullah s.a.w. melarang makan daging himar peliharaan.","r":"Abu Daud dan Muslim"},{"y":"h","x":"Dari Jabir r.a. ia berkata: Nabi s.a.w. telah melarang pada hari Khaibar, memakan daging himar peliharaan.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah berkata seorang tua di dekatnya: Pernah aku dengar Abu Hurairah berkata: Pernah disebut-sebut orang di dekat Nabi s.a.w. tentang binatang landak. Berkata Rasulullah s.a.w.: Sesungguhnya binatang itu keji di antara bermacammacam yang keji.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Abu Waqid Al-Laisi ia berkata: Bersabda Nabi s.a.w.: Apaapa yang dipotong dari binatang-binatang ternak selagi ia hidup maka ia dihukumkan bangkai.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah Nabi s.a.w. melarang memakan semua haiwan yang mempunyai taring dan burung-burung yang mempunyai kuku pencakar.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Tiaptiap yang mempunyai taring dari binatang buas, memakannya haTenaga.","r":"Muslim"},{"y":"a","s":6,"a":145,"b":145,"m":""},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah disuruh oleh Rasulullah s.a.w. membunuh lima jenis binatang yang merosak, di masa halal (biasa) dan di masa ihram, iaitu tikus, kala jengking, gagak, helang dan aa Peraaaai","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Saad r.a. bahawa Nabi s.a.w. telah menyuruh membunuh mengkarung dan dinamakannya binatang itu binatang kecil perosak uwang):","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Telah melarang Nabi s.a.w. membunuh empat jenis binatang, iaitu semut, lebah, burung tegukteguk dan burung suradi.","r":"Abu Daud dan Ahmad"},{"y":"a","s":7,"a":157,"b":157,"m":"a Pn PAN se a OM aloe,,. DN B a Dan mengharamkan Allah atas mereka segala macam yang kejikeji"},{"y":"h","x":"Dari Abdul Rahman bin Usman ia berkata: Pernah seorang tabib menyebut-nyebut ubat di dekat Nabi s.a.w. dan disebutnya binatang katak yang dapat dijadikan ubat itu. Lantas Nabi s.a.w. melarang membunuh katak itu.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah melarang Nabi s.a.w. memakan daging binatang yang memakan tahi dan meminum susunya.","r":"Abu Daud dan Tirmizi"},{"y":"a","s":2,"a":173,"b":173,"m":"Peg D K pen Pn. KA ta Se BA a NASA Sesungguhnya diharamkan atasmu memakan bangkai, darah, daging babi, binatang yang disembelih bukan dengan nama Allah. Maka sesiapa yang terpaksa memakannya dan ia tidak aniaya dan tidak pula melampaui batas, tidaklah ada dosa atasnya"}],"te":"Animals That Are Forbidden to Eat"}],"te":"Basics of Food and Clothing"},{"t":"Berburu","c":[{"t":"Alat-Alat untuk Berburu dan Hukum Binatang Buruan","p":391,"v":2,"d":[{"y":"a","s":5,"a":4,"b":4,"m":"Bismillah ketika melepaskan binatang itu. Firman Allah s.w.t.: AI Su a SAMA PAR A Sa a a Sa a ta a da aa LAN ! ga A Bn Katakanlah hai Muhammad, dihalalkan bagimu segala makanan yang baik rasanya, binatang yang diburu oleh anjing yang terlatih, yang kamu lepaskan buat memburu binatang, sedang kamu telah memberi ajaran kepada anjing itu dengan ajaran yang telah diajarkan Allah kepadamu. Maka bolehlah kamu makan binatang yang ditangkap anjing itu tetapi sebutlah nama Allah ketika melepaskannya. Dan takutlah kamu kepada Allah, sesungguhnya Allah cepat perkangannya"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Ya Rasulullah, sesungguhnya aku pernah melepaskan seekor anjing yang terlatih lalu ditangkapnya buruan itu untukku, dan aku sebut pula nama Allah waktu melepaskannya. Maka bersabda Rasulullah s.a.w.: Apabila engkau telah melepaskan anjing engkau yang terlatih serta engkau telah menyebut nama Allah waktu melepasnya, maka makanlah (boleh dimakan) sekalipun buruan itu telah dibunuhnya, (syaratnya) selama ia tidak disyarikati oleh anjing yang lain, yang tidak dilepaskan bersama-sama dengan anjing itu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Adi bin Hatim r.a. ia berkata: Telah bersabda Rasulullah s.a.w. Bila engkau telah melepaskan anjing engkau, maka sebutlah nama Allah di atasnya. Bila ia telah menangkap untuk engkau, dan engkau dapati binatang itu masih hidup sembelihlah dia. Dan jika engkau dapati dia telah terbunuh, dan anjing itu tidak memakannya, maka boleh engkau makan dia. Dan jika engkau dapati anjingmu berserta anjing-anjing yang lain, sedang binatang itu telah terbunuh, maka janganlah engkau makan. Kerana engkau tidak mengetahui, mana di antara kedua anjing itu membunuhnya. Dan jika engkau telah memanah dengan panah engkau, maka sebutlah nama Allah Taala","r":"Muslim"}],"te":"Hunting Tools and the Ruling on Game"},{"t":"Binatang-Binatang yang Kena Panah atau Peluru","p":393,"v":2,"d":[{"y":"h","x":"Dari Adi bin Hatim r.a. ia berkata: Bersabda Rasulullah s.a.w.: Apabila engkau hendak memanahkan anak panahmu (kepada buruan), maka sebutlah nama Allah Taala, bila ia hilang (dari engkau) selama sehari, lantas tidak engkau dapati padanya melainkan bekas panahmu, maka makanlah jika engkau mahu, dan apabila engkau mendapatinya terbenam di dalam air, maka janganlah engaman","r":"Muslim"},{"y":"h","x":"Dari Adi r.a. ia berkata: Pernah aku a Kepada Rasulullah s.a.w. tentang buruan yang kena sanding panah, lalu beliau jawab: Bila engkau mengenainya dengan panah, dengan hujungnya yang tajam, boleh engkau makan. Tapi bila engkau mengenainya dengan sandingnya (lintangnya) lantas ia mati, sesungguhhya binatang itu buruan yang kena pukul, maka janganlah engkau makan.","r":"Bukhari"}],"te":"Animals Hit by Arrows or Bullets"},{"t":"Macam-Macam Binatang yang Akan Disembelih","p":395,"v":2,"d":[{"y":"h","x":"Dari Usyra', dari bapanya ia berkata: Ditanya orang: Ya Rasulullah, apakah tidak ada penyembelihan itu selain dikerongkongan dan dileher? Beliau menjawab: Kalau engkau cucuk pehanya, nescaya memandailah itu.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Rafi' bin Khadij (di dalam kisah perjalanannya dn Rasulullah s.a.w.) ia berkata: Pernah kami sampai kepada sekumpulan unta dan kambing (rampasan), lantas daripadanya ada seekor unta jantan, maka dilempar oleh seorang laki-laki dengan panah, lalu mati unta itu. Rasulullah s.a.w. bersabda: Sesungguhnya bagi unta ini ada tabiat seperti tabiat binatang liar, maka apabila sesuatu dari unta-unta itu mengalahkan kamu maka perbuatlah dengan dia seperii itu.","r":"Bukhari dan Muslim"}],"te":"Kinds of Animals to Be Slaughtered"},{"t":"Syarat-Syarat Penyembelihan dan Syarat Orang yang Akan Menyembelih","p":396,"v":2,"te":"Conditions of Slaughter and of the Slaughterer"},{"t":"Syarat-Syarat Alat untuk Menyembelih","p":397,"v":2,"d":[{"y":"h","x":"Dari Syaddad bin Aus ia berkata: Bersabda Rasulullah s.a.w.: Bila kamu hendak membunuh, baikkanlah pembunuhanmu itu, dan bila kamu hendak menyembelih baikkanlah penyembelihanmu itu, dan hendaklah kamu tajamkan perkakasmu, dan hendaklah engkau senangkan penyembelihan itu.","r":"Muslim"},{"y":"h","x":"Dari Rafi' bin Khadij dari Nabi s.a.w. beliau bersabda: Apa-apa yang dapat mengalirkan darah serta dibaca nama Allah padanya (waktu menyembelihnya), maka boleh engkau makan kecuali gigi dan kuku. Gigi adalah tulang dan kuku adalah pisau orang Habdan","r":"Bukhari dan Muslim"},{"y":"h","x":"Apa-apa yang dapat mengalirkan darah serta dibaca nama Allah padanya (waktu menyembelihnya), maka boleh engkau makan kecuali gigi dan kuku. Gigi adalah tulang dan kuku adalah pisau orang Habdan (Riwayat Bukhari dan Muslim). Haram memakan daging binatang yang mati terhimpit, mati jatuh atau ditembak dengan peluru (bukan berburu), atau disembelih dengan pisau tumpul yang tidak dapat dikeratkan, melainkan semata-mata dengan kekuatan yang menyembelih. Menurut sebahagian ulama, bahawa dengan pisau tajam itu adalah semata-mata sunat menyembelih, dan bukan wajib. Dalam penyembelihan binatang ternak disunatkan: 1. Memutuskan kedua urat yang ada di kiri kanan leher binatang itu. 2. Binatang yang disembelih itu hendaklah dihadapkan ke Kiblat. 3. Yang menyembelih hendaklah orang laki-laki yang baligh - berakal. Kalau tidak ada laki-laki, sama ada kerana jauh atau sebagainya maka boleh dilakukan oleh perempuan. Bila tidak ada perempuan, bolehlah anak laki-laki yang sudah mumayiz. 4. Membaca nama Allah ketika menyembelih, iaitu: ji a lalu terus membaca selawat kepada Nabi, iaitu: eRAnan AA Penyembelihan Ahli Kitab. Penyembelihan Ahli Kitab, iaitu orang Nasrani dan orang Yahudi boleh (halal) dimakan, seperti corned dan sebagainya. Firman Allah s.w.t.: : DE Dang Pa bi Si Dan makanan…","r":"Bukhari"}],"te":"Conditions of the Slaughtering Tool"},{"t":"Penyembelihan Janin (Anak di dalam Perut), serta Hukum Membaca Bismillah Waktu Menyembelih","p":399,"v":2,"d":[{"y":"h","x":"Dari Abu Said Khudrir.a. ia berkata: Bersabda Rasulullah s.aA.W.: Penyembelihan anak binatang dalam perut, cukuplah dengan penyembelihan induknya.","r":"Ahmad"},{"y":"h","x":"Dari Aisyah r.a. sesungguhnya kaum pernah berkata kepada Nabi s.a.w. bahawa pernah suatu kaum memberikan daging kepada kami, dan kami tidak tahu apakah mereka menyebut nama Allah ketika menyembelihnya atau tidak. Bersabda Nabi: Bacalah Bismillah ketika memakannya dan makanlah,","r":"Bukhari"}],"te":"Slaughter of a Foetus, and Saying Bismillah When Slaughtering"}],"p":391,"v":2,"d":[{"y":"a","s":5,"a":94,"b":94,"m":""}],"te":"Hunting"},{"t":"Kesopanan dalam Makanan dan Minuman","c":[{"t":"Kesopanan dalam Makan","p":400,"v":2,"d":[{"y":"h","x":"Dari Salmanr.a. bahawa Rasulullah s.a.w. bersabda: Keberkatan makanan itu ialah berwuduk sebelumnya dan berwuduk pula sesudahnya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Bila salah seorang di antaramu hendak makan, hendaklah dia menyebut nama Allah. Jika ia terlupa menyebut nama Allah itu di awalnya, hendaklah diucapkannya: Alma","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Bila salah seorang di antaramu hendak makan, hendaklah dia menyebut nama Allah. Jika ia terlupa menyebut nama Allah itu di awalnya, hendaklah diucapkannya: Alma A A (Riwayat Abu Daud dan Tirmizi). 3 Menjamah makanan dengan tangan kanan, jangan dengan tangan kiri, sebab syaitan (iblis) makan dengan tangan kiri dan minum dengan tangan kiri. Sabda Rasulullah s.a.w.: PA  ENT a  a ag N SAN p Sa SERA SB A Dan a Ba JU Si ceh Oo Dada A Sa Na KR AA) Diceritakan oleh Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Apabila salah seorang di antara kamu akan makan, hendaklah ia makan dengan tangan kanannya. Dan apabila ia akan minum, hendaklah ia minum dengan tangan kanannya. Kerana syaitan itu makan dengan tangan kiri dan minum pun dengan tangan kiri juga.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Jabirr.a. bahawasanya Nabi s.a.w. pernah mengambil tangan seseorang yang kena penyakit kusta, lalu beliau masukkan tangan itu berserta tangannya ke dalam bekas air (untuk dibasuh). Kemudian beliau bersabda: ah Su Ai a Pa : Dengan nama Allah, aku percaya kepada Allah dan bertawakal kepada-Nya.","r":"Tirmizi"},{"y":"h","x":"Dari Amr bin Abu Salmah r.a. ia berkata: Telah berkata kepadaku Nabi s.a.w.: Hai anakku, sebutlah nama Allah dan makanlah dengan tangan kanan engkau dan ambillah makanan yang dekat kepada engkau. Sesudah itu selalu aku makan sedemikian.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Sekali-kali tak pernah Nabi s.a.w. mencela makanan, jika beliau suka dimakannya dan jika beliau tidak suka ditinggalkannya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Bila seyang sebelah atas akan tetapi makanlah dari sebelah bawahnya, kerana sesungguhnya berkat itu turun dari atasnya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Kaab bin Malik r.a. ia berkata: Adalah Nabi s.a.w. makan dengan tiga jari, dan beliau jilat jarinya sebelum beliau sapu (basuh).","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. bahawa Rasulullah s.a.w. berkata tentang makanan yang jatuh ke bawah: “Hendaklah diambil yang jatuh itu lalu buangkanlah kotoran yang ada pada makanan itu, kemudian hendaklah dimakan dan janganlah dibiarkan makanan itu untuk syaitan. Dan apabila telah selesai makan, maka hendaklah dijilat anak jari, kerana sesungguhnya tidaklah diketahui yang mana makanan itu yang mengandungi berkat.” (en GN Nu","r":"Muslim"}],"te":"Manners of Eating"},{"t":"Kesopanan dalam Minum","p":405,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: “Janganlah kamu minum sekali teguk saja, seperti unta minum air. Tetapi minumlah dua-dua atau tiga-tiga teguk, dan bacalah Bismillah bila kamu hendak minum, dan bacalah Alhamdulillah bila kamu telah selesai minum.” N !.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah melarang Rasulullah s.a.w. bahawa seseorang minum dari mulut tempat air atau dari geriba.","r":"Tirmizi"},{"y":"h","x":"Dari Anasr.a. ia berkata: Adalah Nabi s.a.w. meniup ketika beliau akan minum tiga kali, dan beliau bersabda: “Sesungguhnya yang semacam itu adalah lebih memuaskan dan lebih meringankan isi t. 2” Pn","r":"Bukhari dan Muslim"}],"te":"Manners of Drinking"},{"t":"Memuji Tuhan sesudah Makan dan Minum","p":406,"v":2,"d":[{"y":"h","x":"Dari Abu Umamah r.a. bahawa Nabi s.a.w. biasanya bila telah mengangkat hidangan, beliau ucapkan: Puji-pujian bagi Allah yang tidak terhingga banyaknya, baik lagi diberkati, tidak menghendaki dicukupi orang, dan tidak pula dititipi orang, dan tidak memerlukan pula ditolong orang, wahai Tuhan kami.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Makanan berdua mencukupi untuk bertiga, dan makanan bertiga mencukupi untuk berempat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Wahsyi bin Harb r.a. bahawasanya sahabat-sahabat Rasulullah s.a.w. pernah mengadu: Ya Rasulullah sesungguhnya kami makan tetapi kami tidak kenyang. Rasulullah menjawab: Barangkali kamu makan berpisah-pisah (berganti-ganti). Mereka menjawab: Ya, memang kami makan berpisah-pisah. Rasulullah s.a.w. bersabda: Maka dari itu berkumpullah kamu menghadapi makananmu dan sebutlah nama Allah, nescaya kamu diberkati Allah padanya.","r":"Abu Daud"}],"te":"Praising Allah After Eating and Drinking"}],"p":400,"v":2,"d":[{"y":"a","s":40,"a":51,"b":51,"m":""},{"y":"a","s":7,"a":31,"b":31,"m":""}],"te":"Manners of Eating and Drinking"},{"t":"Tetamu","p":408,"v":2,"d":[{"y":"h","x":"Dari Abu Syuraih Al-Ka'bi r.a. bahawa Rasulullah s.a.w. telah bersabda: Siapa-siapa yang percaya kepada Allah dan kepada hari kiamat maka hendaklah dimuliakan tamunya, yang seharusnya hanya sehari dan semalam. Yang tamu adalah selama tiga hari. Yang sesudah itu jadi sedekah. Dan tidaklah halal bagi tamu apabila ia terus diam padanya, kalau sekiranya akan menyempitkannya.","r":"Abu Daud"}],"te":"Guests"},{"t":"Bejana","p":409,"v":2,"d":[{"y":"h","x":"Dari Huzaifah r.a. dari Nabi s.a.w. beliau bersabda: Janganlah kamu minum dari bejana emas dan perak. Dan janganlah kamu pakai kain sutera, sebab pakaian itu hanya hak orang kafir di dunia ini, dan akan menjadi hakmu di akhirat nanti.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. beliau bersabda: Ikatlah bejana dan tutuplah minuman itu, kerana sesungguhnya setahun sekali ada suatu malam yang turun padanya penyakit kolera. Tidaklah lalu saja di satu bejana yang tidak bertutup atau gelas yang tidak tertutup, melainkan masuk ke dalamnya penyakit itu.","r":"Muslim"}],"te":"Vessels"},{"t":"Pakaian","c":[{"t":"Jenis-Jenis Pakaian","p":409,"v":2,"d":[{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Adalah pakaian yang paling disukai oleh Rasulullah s.a.w. ialah pakaian gamis.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Asma' binti Yazid Al-Ansari r.a. ia berkata: Adalah lengan baju Rasulullah s.a.w. hingga pergelangannya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Jabir r.a. bahawa Rasulullah s.a.w. ketika masuk pada hari pembukaan Mekah (ketika Mekah direbut), di kepala beliau dipakainya serban hitam.","r":"Muslim"},{"y":"h","x":"Dari Umar bin Khattab r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: “Janganlah kamu pakai pakaian sutera, kerana sesungguhnya sesiapa yang memakainya di dunia, ia tidak dapat lagi memakainya di akhirat.”. ;,","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Musa Al-Asy'ari r.a. bahawa Rasulullah s.a.w. telah bersabda: Diharamkan memakai pakaian sutera dan emas bagi lakilaki umatku dan dihalalkan bagi perempuan-perempuan mereka.","r":"Tirmizi"},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa Nabi s.a.w. pernah melihat sebuah cincin emas di tangan seorang laki-laki lalu dicabutnya, lantas dilemparkannya, dan bersabda: Sengajakah kamu masuk ke dalam api neraka.","r":"Muslim"},{"y":"h","x":"Dari Anas r.a. ia berkata: “Adalah cincin Nabi s.a.w. dari perak, dan adalah hiasannya (tempat meletakkan batu permata) dari perak juga.”,.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Anas r.a. ia berkata: Adalah ukiran cincin Nabi s.a.w. tiga baris. Muhammad di baris yang pertama, Rasul di baris yang kedua dan Allah di baris yang ketiga.","r":"Tirmizi"},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang tidak bersarung maka pakailah seluar. Dan sesiapa yang tidak berselipar maka pakailah kasut.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairahr.a. dari Nabi s.a.w. beliau bersabda:  Apabila seseorang hendak memakai selipar (kasut) hendaklah ia mulai dengan yang kanan. Dan bila hendak menanggalkannya, hendaklah dimulai dengan yang sebelah kiri.","r":"Bukhari dan Muslim"}],"te":"Kinds of Clothing"},{"t":"Pakaian yang Lebih Utama dan Cara Memakai Cincin","p":414,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa Rasulullah s.a.w. pernah bersabda: Pakailah olehmu pakaianmu yang putih, kerana sesungguhnya pakaian yang putih itu adalah sebaik-baik pakaian, dan kafanilah mayatmu dengan kain putih itu.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Anas r.a. ia berkata: “Cincin Nabi s.a.w. di sini, lalu ia tunjuk jari manisnya yang kiri.” Spa a nn","r":"Muslim dan Nasai"},{"y":"h","x":"Dari Abu Said Al-Khudri r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sarung orang Islam ialah hingga seperdua betis, dan tidak berdosa (tidak jadi halangan) sampai antara betis dan kedua buku lali. Dan yang lebih ke baawah dari kedua buku lali, maka dia dalan neraka,","r":"Abu Daud"}],"te":"Preferred Clothing and How to Wear a Ring"},{"t":"Pakaian bagi Kaum Wanita","p":416,"v":2,"d":[{"y":"a","s":33,"a":59,"b":59,"m":""},{"y":"a","s":24,"a":31,"b":31,"m":""},{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Takala turun ayat: AI yy Sek 6N keluarlah wanita Ansar seolah-olah di atas kepala hinggap binatang gagak, kerana pakaian mereka.","r":"Abu Daud"}],"te":"Clothing for Women"},{"t":"Pakaian Wanita Muhajirin","p":417,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Memberi rahmat Allah Taala akan perempuan-perempuan Muhajirin yang dahulu, iaitu ketika turun ayat yang berbunyi Ors IJ Api pi pad, mereka -potonglah bahan pakaian mereka, lalu mereka jadikan sebagai selendang.","r":"Abu Daud dan Bukhari"},{"y":"h","x":"Dari Aisyah r.a. bahawa Asma' binti Abu Bakar r.a. pernah masuk ke tempat Nabi s.a.w. sedang di tubuhnya berpakaian kain tipis, maka berpalinglah Rasulullah s.a.w. daripadanya dan beliau bersabda: Ya Asma' sesungguhnya perempuan-perempuan bila ia telah sampai kepada masa haid (baligh) tidak patut lagi baginya, bahawa dilihat orang anggotanya kecuali ini dan ini.","r":"Abu Daud"}],"te":"Clothing of the Muhajirin Women"},{"t":"Menyambung Rambut dengan Rambut Orang Lain","p":418,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Telah mengutuk Allah akan perempuan-perempuan yang menyambung rambut dan yang minta disambungkannya. Dan orang yang membuat tahi lalat dan yang minta dibuatkan tahi lalat.","r":"Bukhari dan Muslim"}],"te":"Hair Extensions with Another Person's Hair"}],"p":409,"v":2,"d":[{"y":"a","s":7,"a":26,"b":26,"m":""}],"te":"Clothing"}],"p":378,"v":2,"te":"Book of Food and Clothing"}],"p":220,"v":2,"te":"Quarter of Marriage (Munakahat)"},{"t":"Rubu' Jinayat","c":[{"t":"Kitab Jinayat (Bahagian Jenayah dan Hudud)","c":[{"t":"Asas Jinayat","p":420,"v":2,"c":[{"t":"Erti Jenayah dan Hudud","p":420,"v":2,"d":[{"y":"a","s":2,"a":229,"b":229,"m":""}],"te":"Meaning of Crime and Hudud"},{"t":"Hikmat Disyariatkan Jenayah dan Hudud","p":421,"v":2,"te":"Wisdom of Laws on Crime and Hudud"},{"t":"Pembahagian Jarimah (Jenayah) Menurut Syariat Islam","p":421,"v":2,"te":"Categories of Crime in the Shariah"}],"te":"Basics of Criminal Law"},{"t":"Pembunuhan","c":[{"t":"Erti Pembunuhan","p":423,"v":2,"d":[{"y":"a","s":4,"a":93,"b":93,"m":""},{"y":"h","x":"Dari Abdullah bin Mas'ud r.a. dari Nabi s.a.w. beliau bersabda: Tidaklah terbunuh seseorang secara aniaya, melainkan adalah pertanggungjawapan darahnya yang mengalir itu atas anak Adam pertama, kerana sesungguhnya dialah orang yang mula-mula melakukan pembunuhan.","r":"Bukhari dan Muslim"}],"te":"Meaning of Homicide"},{"t":"Pembunuhan Termasuk Salah Satu Dosa Besar","p":424,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w beliau bersabda: Jauhilah olehmu tujuh macam dosa besar yang sangat membahayakan. Mereka bertanya: Ya Rasulullah, apakah yang tujuh macam itu? Rasulullah s.a.w berkata: Iaitu syirik dengan Allah (mempersukutukan-Nya), melakukan sihir, membunuh jiwa yang diharamkan Allah membunuhnya melainkan dengan yang hak, memakan riba, memakan harta anak yatim, lari dari pertempuran dan menuduh perempuan Islam yang kahwin yang lalai dengan tuduhan berzina.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Tidaklah akan berzina seseorang, ketika ia berzina kalau ia seorang mukmin, dan tidak pula akan mencuri seseorang, ketika ia mencuri kalau ia seorang yang mukmin, dan tidak pula seseorang peminum akan -minum kalau ia beriman, dan tidak pula seseorang membunuh, apabila ia seorang yang mukmin.","r":"Bukhari dan Muslim"}],"te":"Killing Is a Major Sin"},{"t":"Pembunuhan Diadili Lebih Dahulu di Hari Kiamat","p":426,"v":2,"d":[{"y":"h","x":"Dari Ibnu Mas'ud r.a. dari Nabi s.a.w. beliau bersabda: Mulamula amal yang akan dihisab Tuhan di hari kiamat, ialah ibadat sembahyang. Dan mula-mula perkara yang akan dijatuhkan hukumannya (diadili) Tuhan antara manusia ialah perkara perempahan dara.","r":"Bukhari dan Muslim"}],"te":"Killing Is Judged First on the Day of Judgement"}],"p":423,"v":2,"te":"Homicide"},{"t":"Qisas dan Diyat","c":[{"t":"Macam-Macam Perbuatan Pembunuhan dan Melukai","p":427,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. bahawa seorang anak perempuan Nadhar telah menampar seorang anak perempuan lain, maka patahlah gigi taringnya, lalu mereka (keluarga) datang kepada Nabi s.a.w. maka beliau suruh membalaskan.","r":"Bukhari dan Muslim"}],"te":"Kinds of Killing and Wounding"},{"t":"Unsur-Unsur Qisas dan Diyat","p":428,"v":2,"d":[{"y":"a","s":5,"a":45,"b":45,"m":""}],"te":"Elements of Qisas and Diyat"},{"t":"Syarat-Syarat Wajib Qisas","p":429,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Diangkatkan dosa dari tiga perkara, dari orang tidur hingga ia bangun, dari anakanak hingga i ia besar dan dari orang gila hingga ia sembuh dari gilanya.","r":"Ahmad dan Abu Daud"},{"y":"h","x":"Dari Umar bin Khattab r.a. ia berkata: Telah aku dengar Rasulullah s.a.w. bersabda: Tidak boleh bapa diqisas sebab anaknya.","r":"Tirmizi"},{"y":"h","x":"Dari Suraqah bin Malik r.a. ia berkata: Pernah aku menghadiri Rasulullah s.a.w. ketika melakukan qisas bagi seorang bapa kerana perbuatan anaknya, dan tidak ada qisas anak kerana perbuatan bapanya.","r":"Tirmizi"},{"y":"a","s":2,"a":178,"b":178,"m":"Sesungguhnya bapa adalah menjadi sebab adanya anak. Dan tidaklah boleh anak menjadi sebab buat menghilangkan bapa. PN (Demikian Subulussalam). 3. Yang dibunuh sama darjat atau kurang dengan yang membunuh, di antaranya Islam sesama Islam, merdeka sesama merdeka, perempuan sesama perempuan dan. hamba sesama hamba. Firman Aan s.w.t. Du jag Sa Si ii LT WA dl Ad ia a AN a Pan Hai orang-orang yang beriman, diwajibkan atasmu qisas dalam perkara pembunuhan, merdeka sama merdeka, hamba sama hamba dan perempuan sama perempuan"},{"y":"h","x":"Dari Abu Juhaifah r.a. ia berkata, telah berkata Ali r.a. tentang peraturan yang ada dalam Al-Quran, iaitu diyat melepaskan tawanan, dan bahawa tidak dibunuh orang Islam sebab (membunuh) orang kafir.","r":"Bukhari dan Abu Daud"},{"y":"a","s":5,"a":45,"b":45,"m":""},{"y":"a","s":16,"a":126,"b":126,"m":""},{"y":"h","x":"Dari Anas r.a. bahawa seorang Yahudi pernah menyepitkan kepala seorang anak perempuan antara dua batu, lalu ditanyakan kepadanya: Siapa yang melakukan hal itu kepada engkau, betulkah si anu, hingga disebutkan orang nama orang Yahudi itu, lalu disyaratkannya dengan kepalanya. Maka didatangkanlah orang Yahudi itu, dan mengaku. Maka diperintahkan Rasulullah s.a.w. pula menyepitkan kepalanya, lantas disepitkan orang pula kepalanya dengan kedua buah batu tu.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ali r.a. ia berkata: Dan tidaklah boleh dibunuh orang mukmin dengan sebab orang kafir, dan tidak pula orang kafir yang telah mengikat janji selama berlaku perjanjiannya.","r":"Abu Daud dan Nasai"},{"y":"a","s":9,"a":29,"b":29,"m":"Dan tidaklah boleh dibunuh orang mukmin dengan sebab orang kafir, dan tidak pula orang kafir yang telah mengikat janji selama berlaku perjanjiannya. (Riwayat Abu Daud dan Nasai). Jadi orang-orang kafir dan orang-orang musyrik yang telah tunduk di bawah pemerintahan Islam, jiwa mereka dijamin atau dilindungi menurut hukum Islam. Firman Allah s.w.t.: a. - ha PEN Ka La Ke In An a Yala Hingga mereka orang-orang kafir mahu membayar pajak dari tangannya sendiri, dan mereka di bawah kekuasaan (orang Islam)"},{"y":"a","s":9,"a":6,"b":6,"m":""}],"te":"Conditions That Make Qisas Obligatory"},{"t":"Hal-Hal yang Menghalangi Perlaksanaan Hukuman Qisas","p":434,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Bila seorang laki-laki menahan seseorang, dan laki-laki yang ditahan itu dibunuh oleh yang lain, maka dibunuhlah orang membunuh itu, sedang orang yang menahan itu dipenjarakan.","r":"Daruqutni"},{"y":"a","s":4,"a":92,"b":92,"m":"Bila seorang laki-laki menahan seseorang, dan laki-laki yang ditahan itu dibunuh oleh yang lain, maka dibunuhlah orang membunuh itu, sedang orang yang menahan itu dipenjarakan. (Riwayat Daruqutni). Dalam riwayat As-Syafii, dari Ali bin Abu Talib; ditambahkan: Orang yang menahan dipenjarakan sampai mati. Manakala pembunuhan yang berlaku di luar negara Islam, maka Allah telah berfirman: Sa ga eo Kee kaa D Dun BORaKILk AY a Maka jika ada yang terbunuh itu dari kaum musuhmu, sedang ia orang mukmin, maka hukumannya ialah memerdekakan hamba yang mukmin"},{"y":"h","x":"Dari Said bin Musaiyyab r.a. bahawa Umar r.a. telah membunuh lima orang atau enam orang, yang telah membunuh seorang laki-laki secara tipuan di tempat yang sunyi, dan ia berkata: Andaikata kalau berkumpul atasnya (atas laki-laki yang telah mati itu) semua penduduk Shun'a nescaya aku bunuh mereka sekaliannya kerana lakilaki yang seorang itu.","r":"Syafi"}],"te":"What Prevents Carrying Out Qisas"},{"t":"Cara Melaksanakan Qisas Anggota","p":436,"v":2,"te":"How Qisas for Limbs Is Carried Out"}],"p":427,"v":2,"d":[{"y":"a","s":2,"a":179,"b":179,"m":""}],"te":"Retaliation (Qisas) and Blood Money (Diyat)"},{"t":"Diyat (Denda)","c":[{"t":"Erti Diyat dan yang Mewajibkannya","p":437,"v":2,"te":"Meaning of Diyat and What Makes It Due"},{"t":"Diyat Mughallazah (Berat)","p":437,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari neneknya, dari Nabi s.a.w. beliau bersabda: Sesiapa yang membunuh orang mukmin dengan sengaja diserahkanlah perkaranya kepada wali-wali (keluarga yang terbunuh) itu, maka jika mereka kehendaki, boleh pembunuhnya dibunuh pula, dan jika mereka kehendaki, mereka boleh menerima diyat, iaitu 30 ekor unta yang berumur 3 tahun, dan 30 ekor unta yang berumur 4 tahun dan 40 ekor unta yang sedang hamil. Dan sesuatu yang mereka perdamaikan atasnya (selain dari aturan di atas) maka hal itu dibolehkan bagi mereka, dan yang demikian itu ialah untuk memperberat perkara diyat.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari neneknya, dari Nabi s.a.w. beliau bersabda: Diyat pembunuh yang syabah 'amad (serupa dengan yang disengaja), ialah mughallazah, seperti diyat aah yang sengaja, dan si pembunuh itu tidak boleh dibunuh. Dan Umar r.a. menghukum dengan cara ini.","r":"Abu Daud"},{"y":"h","x":"Dari Ali r.a. berkataia berhubung dengan soal pembunuhan yang tidak disengaja (syabah 'amad): Tiga puluh tiga ekor unta yang berumur tiga tahun, tiga puluh tiga ekor unta yang berumur 4 tahun dan tiga puluh empat ekor unta yang sedang bunting.","r":"Abu Daud"}],"te":"Heavy Diyat (Mughallazah)"},{"t":"Diyat Mukhaffafah (Ringan)","p":439,"v":2,"d":[{"y":"h","x":"Dari Abdullah bin Mas'ud r.a. Rasulullah bersabda: Dalam perkara pembunuhan yang tersalah diyatnya adalah 20 ekor unta yang berumur 3 tahun, 20 ekor unta yang berumur 4 tahun, 20 ekor unta betina yang berumur 2 tahun, 20 ekor unta betina yang berumur 1 tahun dan 20 ekor unta jantan yang berumur 2 tahun.","r":"Abu Daud dan Tirmizi"}],"te":"Light Diyat (Mukhaffafah)"},{"t":"Diyat Pembunuhan Tersalah yang Diberatkan","p":440,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Sesungguhnya manusia yang keras kepala kepada Allah ada tiga, iaitu orang yang melakukan pembunuhan di Haramillah, atau yang membunuh orang yang bukan hak dibunuh (muhrim), atau yang membunuh untuk membalaskan dendam orang Jahiliah.","r":"Ibnu Hibban"},{"y":"h","x":"Dari Abdullah bin Amr bin Ashr.a. dari Nabis.a.w. beliau bersabda: Ketahuilah, bahawa diyat tersalah ialah diyat syabah 'amad, jika pembunuhan itu dilakukan dengan cambuk atau dengan tongkat, ialah 100 ekor unta, yang 40 ekor daripadanya sedang bunting.","r":"Abu Daud dan Nasai"}],"te":"Increased Diyat for Accidental Killing"},{"t":"Diyat Doktor dan Wanita","p":440,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuaib r.a. dari bapanya, dari datuknya dari Nabi s.a.w. beliau bersabda: Sesiapa yang mengatakan dirinya pandai ubat (doktor/dukun), sedang ia tidak kenal orang sebagai tabib (pandai ubat), maka dia wajib menjamin.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Muaz r.a. ia berkata: Bersabda Rasulullah s.a.w.: “Diyat wanita seperdua diyat laki-laki.” - pa","r":"Baihaqi"},{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya, dari Nabi s.a.w. beliau bersabda: Diyat wanita adalah seperdua diyat likilaki hingga sepertiga diyatnya.","r":"Nasai dan Daruqutni"}],"te":"Diyat for Doctors and for Women"},{"t":"Diyat Kafir Zimmi dan Mu'ahid","p":443,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuiab dari bapanya dari datuknya, katanya: Bersabda Rasulullah s.a.w.: “Diyat kafir zimmi adalah seperdua diyat I 1 y ”. orang Islam","r":"Ahmad dan Nasai"},{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya ia berkata: Bersabda Rasulullah s.a.w.: “Diyat kafir mw'ahid adalah seperdua diyat orang merdeka.”.","r":"Abu Daud"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Pernah dua orang perempuan suku Huzail berbunuh-bunuhan, lalu salah seorang dari keduanya melempar yang lain dengan batu, maka terbunuhlah perempuan itu dan anak yang di dalam perutnya. Mereka mengadu kepada Rasulullah s.a.w. maka Rasulullah s.a.w. menghukumkan, bahawa diyat janinnya (anak yang masih dalam perut) itu seorang hamba laki-laki t Ra ; : ; a dad a","r":"Bukhari dan Muslim"}],"te":"Diyat for a Zimmi or a Mu'ahid"},{"t":"Nilai Diyat Pembunuhan yang Disengaja","p":444,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya ia berkata: Adalah kimat diyat di masa Rasulullah s.a.w. 800 dinar atau 8,000 dirham, dan diyat ahli kitab ketika itu (Yahudi — Nasrani) seperdua diyat kaum Muslimin, dan aturan itu berjalan sampai Umar menjadi Khalifah. Pada satu kali pernah Umar berdiri membaca khutbah, ia berkata: Ketahuilah, sesungguhnya unta telah mahal harganya (habis), maka Umar wajibkan membayar kimatnya atas orang yang mempunyai emas 1,000 dinar, dan orang yang mempunyai perak 12,000 dan atas orang yang mempunyai sapi 200 ekor, dan atas orang yang mempunyai kambing 2,000 ekor, dan atas orang yang mempunyai bahan pakaian 100 pasang dan ditinggalkan (tidak menerangkan) diyat kafir zimmi, dan tidak dihapuskannya.","r":"Abu Daud dan Tirmizi"}],"te":"Value of Diyat for Deliberate Killing"},{"t":"Nilai Diyat Pembunuhan yang Tersalah","p":445,"v":2,"te":"Value of Diyat for Accidental Killing"},{"t":"Catatan Lanjut Diyat","p":446,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya, ia berkata: Pernah Nabi s.a.w. memberikan diyat menurut harganya atas pembunuhan yang tersalah, kepada penduduk kampung dan kota sebanyak 400 dinar, atau wang perak seharga dengan itu, dan diyat menurut nilai harga unta. Apabila unta mahal, ditinggikannya kimatnya, dan bila murah, diturunkannya kimatnya. Dan di masa Rasulullah s.a.w. pernah sampai kimat itu antara 400 hingga 8,000 dihar atau wang perak seharga dirham, dan dihukumkannya atas orang yang mempun yai sapi sebanyak 200 ekor, dan atas orang yang mempunyai kambing sebanyak 2,000 ekor, kemudian beliau bersabda: Diyat itu ialah pusaka yang harus dibahagikan antara wariswaris atas kaum kerabat mereka, maka baki yang tinggal untuk dsobah.","r":"Nasai dan Daud"}],"te":"Further Notes on Diyat"},{"t":"Diyat Anggota Badan","p":446,"v":2,"te":"Diyat for Body Parts"}],"p":437,"v":2,"d":[{"y":"a","s":2,"a":178,"b":178,"m":""}],"te":"Blood Money (Diyat)"},{"t":"Penjelasan Semua Hukuman Jinayat","c":[{"t":"Hukuman Pembunuh yang Sengaja","p":447,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Si pembunuh tidak dapat mewarisi (jadi waris).","r":"Tirmizi dan Ibnu Majah"},{"y":"h","x":"Dari Ali r.a. ia berkata: Bersabda Rasulullah s.a.w. : “Si pembunuh tidak berhak menerima wasiat.”","r":"Baihaqi"}],"te":"Punishment for Deliberate Killing"},{"t":"Hukuman Pembunuhan Syabah Amad","p":448,"v":2,"te":"Punishment for Semi-Deliberate Killing"},{"t":"Hukuman Pembunuhan yang Tersalah","p":449,"v":2,"te":"Punishment for Accidental Killing"},{"t":"Hukuman Perbuatan Jenayah selain daripada Pembunuhan","p":449,"v":2,"te":"Punishment for Crimes Other Than Killing"},{"t":"Kafarat (Denda)","p":450,"v":2,"d":[{"y":"a","s":4,"a":92,"b":92,"m":""},{"y":"h","x":"Dari Wailah bin Asqa' r.a. ia berkata: Pernah kaihi datang kepada Nabi s.a.w. mengenai perkara seorang kawan kami, dan sudah semestinya ia masuk neraka sebab membunuh, maka bersabda Rasulullah s.a.w.: Merdekakanlah seorang budak perempuan dan nanti Allah akan memerdekakan anggota-anggota yang membunuh itu dari api neraka dengan tiap-tiap anggota hamba yang dimerdekakanya itu.","r":"Abu Daud"}],"te":"Expiation (Kafarah)"}],"p":447,"v":2,"te":"Summary of All Criminal Punishments"},{"t":"Qasamah","p":452,"v":2,"te":"Collective Oath (Qasamah)"},{"t":"Orang yang Lepas dari Diyat dan Qisas","p":453,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Tali itu adalah lubang lepas, dan lubang perigi itu adalah lubang lepas, dan binatang-binatang ternak itu adalah binatang lepas, dan pada barang-barang rikaz itu (lihat bab zakat) wajib dikeluarkan zakatnya seperlimanya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Pernah datang seorang lakilaki kepada Nabi s.a.w. lalu dia bertanya: Ya Rasulullah bagaimana pendapat engkau, jika datang seorang laki-laki yang hendak merampas hartaku. Nabi menjawab: Jangan engkau berikan. Ia berkata pula: Bagaimana pendapat engkau kalau ia memerangi aku? Nabi menjawab: Perangilah dia Ia bertanya lagi: Bagaimana pendapat engkau kalau ia membunuh aku? Nabi menjawab: Engkau mati syahid. Ia bertanya pula: Bagaimana pendapat engkau, jika aku yang membunuh dia. Nabi menjawab: Ia masuk neraka.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Andaikata seseorang manusia melihat-lihat ke dalam bilik engkau, dengan tidak seizin engkau, lalu engkau lempar dia dengan batu, lantas kena matanya, tidaklah engkau berdosa. Dan pada suatu riwayat Tidak wajib qisas dan tidak pula diyat.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Imran bin Hussein r.a.: Bahawa seorang laki-laki pernah menggigit tangan seorang laki-laki lain, lalu ditanggalkan tangannya itu dari mulut orang itu, maka jatuhlah dua taringnya, lalu mereka berselisih dan mengadu kepada Nabi s.a.w. Beliau bersabda: Seseorang yang menggigit saudaranya seperti laki-laki itu, maka tidaklah wajib diyat di atas engkau.","r":"Bukhari dan Muslim"}],"te":"Those Exempt from Diyat and Qisas"}],"p":420,"v":2,"te":"Book of Criminal Law (Crimes and Hudud)"},{"t":"Kitab Hudud","c":[{"t":"Asas Hudud","p":455,"v":2,"c":[{"t":"Hukum Jenayah Hudud dan Unsurunsurnya","p":455,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Apakah engkau akan membela membatalkan hukuman dalam perkara sesuatu hudud dari hudud Allah?","r":"Bukhari dan Muslim"}],"te":"Hudud Crimes and Their Elements"},{"t":"Diperlukan Alat-Alat Bukti","p":457,"v":2,"d":[{"y":"h","x":"Dari Ali r.a., dari Nabi s.a.w. beliau bersabda: Batalkanlah hukuman had sebab ada keraguan.","r":"Baihaqi"},{"y":"h","x":"Dari Aisyah r.a., dari Nabi s.a.w. beliau bersabda: Batalkanlah menjatuhkan hukuman had dari kaum muslimin menurut kesanggupanmu. Maka jika kamu peroleh bagi seseorang muslim jalan keluar (lari, atau bersembunyi, atau jalan untuk membatalkan), maka biarkanlah jalannya itu diturutinya. Kerana sesungguhnya Imam (Hakim) lebih baik ia keliru dalam perkara memaafkan, daripada ia keliru (salah) dalam menjatuhkan hukuman.","r":"Tirmizi dan Hakim"},{"y":"h","x":"Dari Amr bin Syuib, dari bapanya, dari datuknya ia berkata: Telah bersabda Rasulullah s.a.w.: Maafkanlah olehmu (maaf-memaafkanlah kamu), dalam perkara hudud, pada apa-apa yang terjadi antaramu. Sebab semua perkara yang telah sampai kepadaku mengenai hukuman had, maka hukuman itu mesti aku jatuhkan.","r":"Abu Daud"}],"te":"Evidence Is Required"},{"t":"Jenis-Jenis Hukum Jenayah Hudud","p":458,"v":2,"te":"Kinds of Hudud Crimes"}],"te":"Basics of Hudud"},{"t":"Hukum Jenayah Murtad","c":[{"t":"Erti Murtad","p":460,"v":2,"d":[{"y":"a","s":2,"a":217,"b":217,"m":""}],"te":"Meaning of Apostasy"},{"t":"Yang Menyebabkan Murtad","p":460,"v":2,"d":[{"y":"a","s":5,"a":73,"b":73,"m":""},{"y":"h","x":"Dari Abu Zar r.a. sesungguhnya ia pernah mendengar Rasulullah s.a.w. bersabda: “Sesiapa yang memanggilkan seorang laki-laki dengan panggilan kafir, atau dikatakannya musuh Allah, padahal ia bukan seperti yang dikatakannya itu maka kembali kata-kata itu kepada yang mengatakan.” :..","r":"Bukhari dan Muslim"}],"te":"What Causes Apostasy"},{"t":"Orang yang Dipaksa Murtad","p":463,"v":2,"d":[{"y":"a","s":16,"a":106,"b":106,"m":"a AL p - D PAR Sa da A A SS S - a soh. *. ape Sesiapa yang kafir kepada Allah sesudah ia beriman kecuali orang yang terpaksa, sedang hatinya masih tetap beriman. Tetapi orang yang terbuka dadanya kepada kekafiran, maka marahlah Allah kepadanya dan bagi mereka disediakan seksaan yang besar"}],"te":"One Forced into Apostasy"},{"t":"Hukuman Orang yang Murtad","p":463,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbasr.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang menukar agamanya, maka bunuhlah dia.","r":"Bukhari"},{"y":"h","x":"Dari Abdullah bin Mas'ud r.a. dari Nabi s.a.w. beliau bersabda: Tidak halal darah manusia yang Islam, yang ia mengaku bahawa tiada tuhan melainkan Allah, dan bahawasanya aku Rasulullah, melainkan dengan salah satu tiga perkara yang mana jiwa harus dibayar dengan jiwa qisas: Saib (janda) yang berzina, orang yang meninggalkan agamanya (Islam) dan orang yang memisahkan diri dari h Isl jamaah orang Islam.'","r":"Bukhari dan Muslim"}],"te":"Punishment for Apostasy"},{"t":"Orang yang Meninggalkan Sembahyang dengan Sengaja","p":464,"v":2,"d":[{"y":"h","x":"Dari Burairah r.a. dari Nabi s.a.w. beliau bersabda: Perjanjian yang ada antara kita kaum Muslimin dan antara mereka yang bukan Islam ialah sembahyang, maka sesiapa yang meninggalkan sembahyang itu tidak sesungguhnya ia telah kafir.","r":"Tirmizi"}],"te":"One Who Deliberately Abandons Prayer"},{"t":"Putus Hubungan antara Murtad dengan Muslim dalam Perkara Hukum","p":465,"v":2,"d":[{"y":"h","x":"Dari Nabi s.a.w. beliau bersabda: “Si muslim tidak dapat mewarisi si kafir, dan si kafir tidak pula dapat mewarisi si muslim.”, p :","r":"Bukhari dan Muslim"}],"te":"Legal Ties Between an Apostate and a Muslim Are Cut"}],"p":460,"v":2,"te":"Apostasy (Riddah)"},{"t":"Hukum Jenayah Penyamunan (Hirabah)","c":[{"t":"Erti Penyamunan","p":467,"v":2,"te":"Meaning of Highway Robbery"},{"t":"Hukuman bagi Penyamun dan Pelaksanaannya","p":467,"v":2,"te":"Punishment for Robbers and Its Execution"},{"t":"Pengaruh Taubat Si Penyamun","p":469,"v":2,"d":[{"y":"a","s":5,"a":34,"b":34,"m":"Kecuali kalau mereka (penyamun) itu taubat, sebelum kamu menguasainya (sebelum ditangkap)"}],"te":"The Effect of a Robber's Repentance"},{"t":"Hak Ulil Amri dalam Perkara Memberikan Hukuman Terhadap Penyamun yang Taubat","p":469,"v":2,"d":[{"y":"a","s":4,"a":59,"b":59,"m":""}],"te":"The Authorities' Right in Punishing a Repentant Robber"}],"p":466,"v":2,"d":[{"y":"a","s":5,"a":33,"b":34,"m":""}],"te":"Highway Robbery (Hirabah)"},{"t":"Hukum Jenayah Bughat","c":[{"t":"Erti Bughat","p":471,"v":2,"d":[{"y":"h","x":"Dari Nabi s.a.w. beliau bersabda: Mendengar dan mentaati (terhadap Imam yang adil), merupakan kewajipan di atas manusia muslim, pada apa yang ia sukai atau yang ia benci, selama ia tidak diperintah melakukan maksiat. Bila ia diperintah melakukan maksiat, maka tidaklah boleh didengar dan ditaati.","r":"Bukhari dan Muslim"}],"te":"Meaning of Bughat"},{"t":"Asal Mula Terjadi Kaum Bughat","p":473,"v":2,"d":[{"y":"h","x":"Dari Abdullah bin Syaddad ia berkata: Berkata Ali r.a. kepada kaum Khawarij: “Kamu boleh berbuat sekehendak hatimu dan antara kami dan antaramu hendaklah ada perjanjian, iaitu supaya kamu jangan menumpahkan darah yang diharamkan (membunuh), kamu jangan merompak di jalan, kamu jangan menganiaya seseorang (menyamun dan sebagainya). Jika kamu berbuat yang sedemikian itu, penyerangan akan diteruskan terhadap kamu ki li, ; ” sekatan","r":"Ahmad dan Hakim"}],"te":"How Rebellion Arises"},{"t":"Gerombolan Bughat yang Tertangkap","p":473,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Tahukah engkau, bagaimana hukum Allah dalam perkara orangorang yang telah jadi kaum bughat (gerombolan) dari umat ini? Seseorang daripada sahabat berkata:  Allah dan Rasul-Nya yang lebih tahu. Rasulullah berkata: Tidak boleh ditambah lukanya, tidak boleh dibunuh tawanannya, tidak perlu dicari mana yang lari dan tidak boleh dibahagi-bahagikan rampasannya.","r":"Al-Bazzar dan Hakim"}],"te":"Captured Rebel Bands"},{"t":"Penyelesaian Perkara Bughat","p":475,"v":2,"d":[{"y":"h","x":"Dari Arfajah r.a. ia berkata: Pernah aku dengar Rasulullah s.a.w. bersabda: Akan terjadi bermacam-macam kekacauan. Maka sesiapa yang hendak menyelesaikan urusan umat yang berada di tangan pimpinan tertinggi, maka pukullah dia (bunuh) di mana saja ia berada. Z $ e #5 eg -. se pi PARA Kat Us Ad Baa Naa NE.) a","r":"Muslim"}],"te":"Settling a Rebellion"},{"t":"Orang yang Mencela Nabi Muhammad ﷺ","p":477,"v":2,"d":[{"y":"h","x":"Dari Ali r.a. bahawasanya seorang Yahudi pernah mencaci Nabi s.a.w., lalu ia jatuh ketika itu. Lantas seorang laki-laki mencekiknya hingga ia mati. Oleh Rasulullah s.a.w. dibatalkan hukuman qisas tuk dirinya. untuk dirinya","r":"Abu Daud"}],"te":"One Who Insults Prophet Muhammad ﷺ"}],"p":471,"v":2,"d":[{"y":"a","s":49,"a":9,"b":9,"m":""}],"te":"Rebellion (Bughat)"},{"t":"Hukum Jenayah Perzinaan","c":[{"t":"Zina Adalah Salah Satu Dosa Besar","p":478,"v":2,"d":[{"y":"a","s":17,"a":32,"b":32,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. Bahawasanya Rasulullah s.a.w. bersabda: Jauhilah tujuh macam dosa yang sangat merbahayakan: Ditanya orang: Apakah yang tujuh itu ya, Rasulullah? Rasulullah menjawab: Mempersekutukan Allah, melakukan sihir, membunuh jiwa yang diharamkan Allah membunuhnya melainkan dengan yang hak, memakan harta anak yatim, berzina, lari dari medan perang, dan menuduhkan lacur terhadap wanita mukmin yang terpelihara. Jiwanya terjaga.","r":"Bukhari dan Muslim"}],"te":"Zina Is a Major Sin"},{"t":"Erti Perzinaan dan Hukumannya","p":479,"v":2,"d":[{"y":"a","s":4,"a":15,"b":16,"m":""},{"y":"a","s":24,"a":2,"b":2,"m":""},{"y":"h","x":"Dari Nabi s.a.w. ia bersabda: Ambillah olehmu (peraturan) daripada aku. Ahnbillah (peraturan) daripada aku. Sungguh Allah telah memberikan jalan untuk mereka, iaitu: Bikir sama bikir (perawan dan jejaka), hukumannya dicambuk sebanyak 100 kali cambuk dan dibuang selama satu tahun. Janda sama janda, hukumannya dicambuk sebanyak 100 kali cambuk serta direjam.","r":"Muslim dan Abu Daud"}],"te":"Meaning of Zina and Its Punishment"},{"t":"Erti Rejam dan Cambuk","p":482,"v":2,"d":[{"y":"h","x":"Dari Abu Bakrah, dari bapanya: Bahawasanya Nabi s.a.w. akan merejam seorang wanita, lalu dibuatnya orang baginya lubang di Sunduwah. Pa","r":"Abu Daud"}],"te":"Meaning of Stoning and Flogging"},{"t":"Hukuman Cambuk dan Buangan","p":482,"v":2,"d":[{"y":"h","x":"Dari Zaid bin Khalid Al-Juhanni r.a. ia berkata: Pernah aku dengar Nabi s.a.w. memerintahkan dalam perkara orang yang berzina yang belum muhshin, supaya dijatuhkan hukuman cambuk sebanyak 100 kali dan diasingkan satu tahun.","r":"Bukhari dan Nasai"}],"te":"Flogging and Banishment"},{"t":"Hukuman Hamba Seperdua Hukuman Orang yang Merdeka","p":483,"v":2,"d":[{"y":"a","s":4,"a":25,"b":25,"m":""},{"y":"h","x":"Dari Ali r.a. telah bersabda ia dalam khutbahnya: Hai manusia, dirikanlah had atas hambamu itu, iaitu yang muhshin di antara mereka dan yang tidak mushin.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Abu Hurairahr.a. dari Nabi s.a.w. beliau bersabda: Apabila hamba perempuan berzina dan telah nyata kesalahannya, pukullah dia dan jangan dicela. Kemudian bila ia berzina pula, pukullah ia dan jangan dicela. Kemudian jika ia berzina juga pada kali yang ketiga, maka juallah ia sekalipun dengan segumpal rambut.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: “Jauhilah segala kekotoran ini, yang telah dilarang Allah mengerjakannya. Sesiapa yang telah berbuat kekotoran itu, hendaklah ia tutupi dengan tutupan Allah, dan hendaklah ia taubat kepada Allah, kerana sesungguhnya orang-orang yang melahirkan rahsianya kepada kami, akan kami jalankan hukuman Allah Azza Wajallah ke atasnya.”,.","r":"Hakim"}],"te":"A Slave's Punishment Is Half a Free Person's"},{"t":"Perlu Minta Penjelasan sebelum Hukuman Dijatuhkan","p":485,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Tatkala datang Maiz bin Malik kepada Nabi s.a.w. Nabi bersabda kepadanya: “Barangkali engkau baru mencium atau baru memegang saja atau barangkali baru melihat.” Ia menjawab: “Bukan, ya Rasulullah.” Rasulullah s.a.w. bertanya: “Engkau sudah muhshin?” Ia menjawab: “Sudah!” Lalu diperintahkan oleh Rasulullah s.a.w. untuk direjamnya.","r":"Bukhari"},{"y":"a","s":4,"a":15,"b":15,"m":"ag a P PENA 2 5 Mi D a aa Si An Su - n g g jg : Da yo dl AW dy ku Dan orang-orang yang berbuat kekejian di antara kaum wanita, maka kemukakanlah saksi atas mereka seramai empat orang saksi dari pihakmu"}],"te":"Clarification Is Needed Before Punishment"},{"t":"Perempuan yang Dirogol, Berzina dan Hukuman Terhadap Perempuan Hamil","p":487,"v":2,"d":[{"y":"h","x":"Dari Alqamah bin Wail, mengenai kisah seorang wanita yang pernah dipaksa untuk berzina, ia berkata: Bersabda Nabi s.a.w. kepadanya: “Pergilah engkau, sesungguhnya Allah telah mengampuni dosamu.” Dan beliau berkata pula kepada laki-laki yang telah memaksa perempuan itu berzina: “Rejamlah dia”.","r":"Tirmizi"},{"y":"h","x":"Dari Ali r.a. bahawa ia telah berkata di dalam kutbahnya: Maka bahawa seorang hamba perempuan Rasullullah s.a.w. telah berzina, lalu beliau menyuruh aku mencambuknya, kebetulan ia sedang dalam bernifas, maka aku takut jika mencambuknya dapat membunuhnya. Lalu aku beritahu hal itu kepada Nabi s.a.w., maka beliau bersabda: Baik perbuatan engkau.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Imran bin Husseinr.a. bahawa seorang wanita suku Juhainah pernah datang kepada Nabi s.a.w. sedang ia dalam hamil kerana berzina, maka ia berkata: Ya Nabi Allah, telah sampai kepadaku hukum had, maka lakukanlah atasku had itu. Lantas Nabi Allah s.a.w. memanggil walinya, dan beliau bersabda: Berbuat baiklah kepadanya (jangan dicela-cela), bila ia telah melahirkan anak, bawalah dia kepadaku. Diperbuat oranglah semua perintah beliau. (Setelah selesai ia melahirkan lalu dibawa kepada Nabi). Nabi Allah s.a.w. memerintahkan, lalu aku tutupkan kainnya ke badannya, kemudian beliau memerintahkan, lalu direjamnya perempuan itu sampai man","r":"Muslim"}],"te":"Rape Victims, Zina, and Punishment of a Pregnant Woman"}],"p":478,"v":2,"te":"Adultery and Fornication (Zina)"},{"t":"Liwath","c":[{"t":"Erti Liwath","p":488,"v":2,"d":[{"y":"a","s":7,"a":80,"b":81,"m":""},{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang melihat orang yang melakukan perbuatan kaum Luth, maka bunuhlah yang mengerjakan itu dan orang yang jadi amradnya.","r":"Abu Daud dan Ahmad"}],"te":"Meaning of Liwat"},{"t":"Bersetubuh dengan Binatang","p":490,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang mendatangi binatang (untuk melepaskan nafsunya), maka bunuhlah dia dan bunuhlah binatang itu bersama-sama dengan da","r":"Abu Daud dan Tirmizi"}],"te":"Bestiality"},{"t":"Bersetubuh dengan Mahram Sendiri","p":490,"v":2,"d":[{"y":"h","x":"Dari Al-Bara bin Azib r.a. ia berkata: Pernah aku bertemu dengan pak cikku, dan sertanya ada sebilah pedang, lalu aku bertanya: Hendak ke mana pak cik? Dia menjawab: Aku disuruh oleh Rasulullah s.a.w. menemui seorang laki-laki yang telah menikahi perempuan janda bapanya dan aku diperintahkan supaya memukul tengkuknya dan mengambil hartanya.","r":"Abu Daud dan Tirmizi"}],"te":"Incest"}],"p":488,"v":2,"te":"Sodomy (Liwat)"},{"t":"Hukum Jenayah Qazaf","c":[{"t":"Erti Qazaf","p":491,"v":2,"d":[{"y":"a","s":24,"a":4,"b":4,"m":""}],"te":"Meaning of Qazaf"},{"t":"Wanita yang tidak Mengaku Berzina","p":492,"v":2,"d":[{"y":"h","x":"Dari Sahal bin Saad r.a. bahawa seorang laki-laki pernah datang kepada Nabi s.a.w. dan ia mengaku telah berzina dengan seorang wanita dan disebutnya namanya. Lantas Nabi s.a.w. mengutus seorang kepada wanita itu, lalu ditanyainya perempuan tersebut, wanita itu tidak mengaku. Laki-laki itu dijatuhi hukuman oleh Nabi s.a.w. dan wanita itu dibebaskannya.","r":"Abu Daud dan Nasai"}],"te":"A Woman Who Denies Zina"}],"p":491,"v":2,"te":"False Accusation of Zina (Qazaf)"},{"t":"Hukuman Tukang Sihir","p":493,"v":2,"d":[{"y":"a","s":2,"a":102,"b":102,"m":""},{"y":"h","x":"Dari Jundud r.a. dari Nabi s.a.w. beliau bersabda: Had tukang sihir adalah dibunuh dengan pedang.","r":"Tirmizi dan Hakim"}],"te":"Punishment of Sorcerers"},{"t":"Hukum Jenayah Pencurian","c":[{"t":"Erti Pencurian dan Hukumannya","p":494,"v":2,"d":[{"y":"a","s":5,"a":38,"b":38,"m":""}],"te":"Meaning of Theft and Its Punishment"},{"t":"Cara Melakukan Hukuman Potong Tangan","p":494,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawa Rasulullah s.a.w. bersabda dalam perkara orang yang mencuri: Jika seseorang mencuri, maka potonglah tangannya. Kemudian jika ia mencuri lagi, potong kakinya. Kemudian jika ia masih mencuri lagi potonglah tangannya. Kemudian jika ia masih mencuri juga lagi potonglah kakinya.","r":"Syafii"}],"te":"How the Hand Is Cut"},{"t":"Syarat-Syarat untuk Menjatuhkan Hukuman Potong Tangan","p":494,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: “Belum boleh dipotong tangan orang yang mencuri, melainkan apabila ada sej lebih.”, perapan nan ana","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Amr bin Syuaib r.a. dari bapanya, dari datuknya ia berkata: Pernah Rasulullah s.a.w. ditanya; tentang buah-buahan yang tergantung: Sesiapa yang mengambilnya dengan mulutnya kerana ada hajat (lapar) tidak untuk disimpan, maka tidak ada sesuatu hukuman di atasnya. Dan sesiapa yang mengeluarkan sesuatu daripadanya, maka wajib ia menggantinya dua kali lipat dan dijatuhi hukuman. Dan sesiapa yang mencuri daripadanya akan sesuatu, sesudah ia diletakkan di dalam jaring (tempat mengeringkan tamar), yang sampai seharga semijan, maka wajib dijatuhi hukuman potong tangan ke atasnya.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Fudhalah bin Ubaid r.a. ia berkata: “Telah dihadapkan oleh Rasulullah s.a.w. seorang pencuri, lalu dipotong orang tangannya, kemudian disuruh gantungkan tangan pencuri itu, lalu digantungkan oranglah di tengkuknya.” ! Dana.","r":"Tirmizi dan Nasai"}],"te":"Conditions for Cutting the Hand"},{"t":"Perbuatan-Perbuatan yang tidak Mewajibkan Hukuman Potong Tangan","p":498,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. beliau bersabda: Tidaklah wajib melakukan pemotongan tangan atas orang yang khianat, dan tidak pula atas orang yang menggertak, dan tidak pula atas orang yang menyambar.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Busr bin Artat r.a. ia berkata: Pernah aku dengar Nabi s.a.w. bersabda: Tidak boleh dilakukan potong tangan di medan perang.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Abdullah bin Umar r.a. ia berkata: Pernah Nabi s.a.w. ditanya orang tentang buah-buahan yang tergantung di pohonnya, maka beliau menjawab: Sesiapa yang dapat mengambilnya dengan mulutnya kerana sangat hajat (kerana haus dan lapar), tidak untuk disimpannya, maka tidaklah ada hukuman atasnya. Dan sesiapa yang mengeluarkan sesuatu daripadanya, maka wajib atasnya mengganti yang seumpama itu serta iqab (seksa, menurut pertimbangan hakim).","r":"Abu Daud dan Nasai"}],"te":"Acts That Do Not Require Cutting the Hand"},{"t":"Menjatuhkan Hukuman tidak boleh Dibeza-Bezakan","p":500,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Hanya sesungguhnya telah celaka orang-orang dari sebelummu, kerana mereka selalu: Bila si pencuri di kalangan mereka orang yang syariif' (bangsawan atau keluarga orang besar), mereka biarkan saja (tidak mereka hukum). Dan bila terjadi pencurian di kalangan mereka orang bawahan (tidak berkuasa atau rakyat biasa), mereka jatuhkan hukuman kepadanya. Demi Allah. Andaikata si Fatimah puteri Muhammad sendiri yang mencuri, pasti aku potong tangannya.","r":"Bukhari dan Muslim"}],"te":"Punishment Must Be Applied Without Discrimination"},{"t":"Penetapan Pencurian","p":501,"v":2,"te":"Proving Theft"}],"p":494,"v":2,"te":"Theft"},{"t":"Hukum Jenayah Minum Arak","c":[{"t":"Erti Minum Arak","p":501,"v":2,"d":[{"y":"a","s":5,"a":90,"b":90,"m":""}],"te":"Meaning of Drinking Alcohol"},{"t":"Bahan-Bahan Pembuatan Arak","p":502,"v":2,"d":[{"y":"a","s":16,"a":67,"b":67,"m":""},{"y":"h","x":"Dari buah anggur, tamar, madu, gandum dan syair (gandum). Dan yang dinamakan arak (khamar) ialah barang yang menghilangkan akal fikiran.","r":"Bukhari dan Muslim"}],"te":"What Alcohol Is Made From"},{"t":"Ukuran Minuman yang Dipandang Memabukkan","p":503,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. pernah berkata: “Tiaptiap yang memabukkan dinamakan khamar dan tiap-tiap yang memabukkan haram hukumnya.” l :","r":"Muslim"},{"y":"h","x":"Dari Jabir r.a. dari Rasulullah s.a.w. beliau bersabda: Sesuatu yang dapat memabukkan apabila banyak, maka sedikitnya pun juga haram.","r":"Ahmad dan Tirmizi"}],"te":"How Much Counts as Intoxicating"},{"t":"Hukuman Orang yang Meminum Arak","p":504,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. bahawa Nabi s.a.w. dalam perkara minum arak telah mencambuk dengan ranting kurma dan dengan terompah, kemudian mencambuk pula Abu Bakar sebanyak 40 kali cambuk. Tatkala sampai ke masa Khalifah Umar, dan manusia telah dekat ke desa-desa dan kampung-kampung, ia bertanya: Bagaimana pendapatmu dalam perkara mencambuk orang minum arak? Maka menjawab Abdur Rahman bin Auf: Aku berpendapat bahawa engkau melakukan hukum minum arak itu seperti hukumnya had yang paling ringan. Maka Umar mencambuk sebanyak 80 kali cambuk.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Muawiyah r.a. dari Nabi s.a.w. bahawa beliau berkata tentang perkara orang yang meminum arak: Bila seseorang telah meminumnya, maka cambuklah dia, kemudian jika ia meminumnya lagi maka cambuklah dia, kemudian jika ia meminumnya lagi pada kali ketiga, maka cambuklah dia. Kemudian jika ia meminumnya lagi pada kali yang keempat, maka pancunglah (penggallah) lehernya.","r":"Ahmad dan Abu Daud"}],"te":"Punishment for Drinking Alcohol"},{"t":"Syarat Melaksanakan Hukuman Orang yang Minum Arak","p":505,"v":2,"d":[{"y":"h","x":"Dari Abu Sasan r.a. ia berkata: Pernah hadir bersama Usmanr.a. dan disampaikan orang bahawa ada seseorang yang bernama Walid, sungguh ia telah sembahyang subuh dua rakaat, kemudian ia berkata: Akan aku tambahikah sembahyang itu untukmu. Lalu menjadi saksi atasnya dua orang laki-laki dan salah seorang di antaranya bernama Humran. Ia menyaksikan bahawa Walid itu betul telah minum arak. Dan menjadi saksi pula yang lain, bahawa ia memang telah melihatnya muntah-muntah. Maka berkata Usman: Ia tidak akan muntah melainkan sesudah ia minum arak. Lantas ia berkata: Ya Ali bangunlah, maka deralah dia.","r":"Muslim dan Abu Daud"}],"te":"Conditions for Punishing a Drinker"},{"t":"Arak Bukan Ubat tetapi Penyakit","p":506,"v":2,"d":[{"y":"h","x":"Dari Wail Al-Hadrami,. bahawa, Tharik bin Suwaid r.a. pernah bertanya kepada Nabi s.a.w. tentang arak yang digunakan untuk ubat. Lantas Rasulullah s.a.w. bersabda: Arak itu bukan ubat, Itap penyanyi,","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Ummu Salamah r.a. dari Nabi s.a.w. beliau bersabda: Sesungguhnya Allah tidak menjadikan ubatmu pada barang yang diharamkan ke atasmu.","r":"Baihaqi dan Ibnu Hibban"}],"te":"Alcohol Is Not a Medicine but a Disease"},{"t":"Tempat Melaksanakan Hukuman","p":507,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. * ia berkata: Bersabda Rasulullah s.a.w.: Tidak boleh dijalankan hukuman di masjid.","r":"Tirmizi dan Hakim"}],"te":"Where Punishment Is Carried Out"}],"p":501,"v":2,"te":"Drinking Alcohol"},{"t":"Hukum Jenayah Takzir","c":[{"t":"Erti Takzir","p":508,"v":2,"d":[{"y":"h","x":"Dari Nabi s.a.w. ia bersabda: Tidak boleh dilakukan cambuk lebih dari sepuluh kali, kecuali dalam perkara had daripada had Allah.","r":"Muslim"},{"y":"h","x":"Dari Nukman bin Basyir r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang menyampaikan (sesuatu hukuman) kepada hukuman had dalam perkara yang bukan hukum jenayah had, maka orang itu termasuk orang yang melanggar batas.","r":"Al-Baihaqi"},{"y":"h","x":"Dari Bahzi bin Hakim, dari bapanya dari a Bahawa Rasulullah s.a.w. pernah menahan seseorang lelaki kerana salah ' sangka, kemudian dibebaskannya kembali.","r":"Tirmizi dan Abu Daud"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bahawa Rasulullah s.a.w. pernah memukul dan melakukan pembuangan, dan bahawasanya Abu Bakar pernah memukul dan melakukan pembuangan. Dan bahawasanya Umar pernah memukul dan melakukan pembuangan.","r":"Tirmizi dan Hakim"}],"te":"Meaning of Takzir"},{"t":"Orang yang Belum Kenal Kejahatan","p":511,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a.: Bahawasanya Rasulullah s.a.w. telah bersabda: Maafkanlah seseorang yang belum mengerti kejahatan itu akan kesalahan mereka, kecuali hukuman had.","r":"Ahmad dan Abu Daud"}],"te":"One New to Wrongdoing"}],"p":508,"v":2,"d":[{"y":"a","s":48,"a":9,"b":9,"m":""}],"te":"Discretionary Punishment (Takzir)"},{"t":"Shial","c":[{"t":"Erti Shial","p":512,"v":2,"d":[{"y":"a","s":2,"a":194,"b":194,"m":""},{"y":"h","x":"Dari Said bin Zaid r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesiapa yang terbunuh mempertahankan hartanya, maka matinya mati syahid. Dan sesiapa yang terbunuh dalam mempertahankan darahnya (dirinya), maka matinya mati syahid. Dan sesiapa yang terbunuh dalam mempertahankan agamanya, maka matinya mati syahid. Dan sesiapa yang terbunuh dalam mempertahankan keluarganya, maka matinya mati syahid.","r":"Tirmizi dan Abu Daud"}],"te":"Meaning of Self-Defence"},{"t":"Cara Bertahan dari Shial","p":513,"v":2,"te":"How to Defend Against an Attacker"},{"t":"Membunuh Si Pengancam sebelum Ia Membunuh","p":514,"v":2,"d":[{"y":"h","x":"Dari Abi Hurairah r.a.: Bahawasanya pernah datang seorang lakilaki kepada Nabi s.a.w. lalu ia berkata: Ya Rasulullah! Bagaimana pendapat engkau; jika datang seseorang hendak mengambil barangku? Rasulullah menjawab: Jangan diberikan. Laki-laki itu bertanya lagi: Bagaimana jika ia hendak membunuhku. Rasulullah menjawab: Bunuhlah dia lebih dahulu. Ia bertanya lagi: Bagaimana pendapat engkau, jika aku yang dibunuhnya lebih dahulu. Rasulullah menjawab: Engkau mati syahid. Laki-laki itu bertanya lagi: Bagaimana pendapat engkau, jika aku yang membunuhnya lebih dahulu. Rasulullah menjawab: Dia masuk neraka..","r":"Muslim"}],"te":"Killing the Attacker Before He Kills"},{"t":"Perbuatan yang Menimbulkan Tanggungjawab","p":515,"v":2,"te":"Acts That Create Liability"},{"t":"Perbuatan-Perbuatan yang Menghilangkan Tanggungjawab","p":516,"v":2,"te":"Acts That Remove Liability"},{"t":"Hal-Hal yang Membenarkan","p":516,"v":2,"te":"Justifying Circumstances"}],"p":512,"v":2,"te":"Self-Defence (Sail)"},{"t":"Khatan","c":[{"t":"Erti Khatan","p":517,"v":2,"d":[{"y":"a","s":4,"a":125,"b":125,"m":""}],"te":"Meaning of Circumcision"},{"t":"Khatan Termasuk Fitrah","p":517,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairahr.a., dari Nabi s.a.w. beliau telah bersabda: Fitrah itu ada lima macam iaitu, khatan, mencukur bulu kemaluan, mengerat kuku, mencukur bulu ketiak dan memotong misai.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ummu Atiyah r.a.: Bahawa seorang perempuan pernah berkhatan (dikhatankan oleh Ummu Atiyah) di Madinah, lalu Nabi s.a.w. bersabda kepadanya: Jangan terlalu engkau dalamkan khatannya, kerana yang demikian itu, sangat menguntungkan bagi perempuan, dan lebih disukai oleh suami.","r":"Abu Daud dan Thabrani"}],"te":"Circumcision Is Part of the Fitrah"}],"p":517,"v":2,"te":"Circumcision"}],"p":455,"v":2,"te":"Book of Hudud"},{"t":"Kitab Imarah","c":[{"t":"Asas Imarah","p":519,"v":2,"c":[{"t":"Erti Imarah dan yang Berhak Memimpin Negara","p":519,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umarr.a. dari Nabi s.a.w. beliau bersabda: Sentiasalah pemerintahan ini di dalam tangan bangsa Quraisy selama masih tinggal di golongan mereka dua orang.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Muawiyah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesungguhnya pemerintahan ini jadi hak selalu di tangan bangsa Quraisy. Mereka tidak boleh dilangkahi oleh seorang pun. Siapa yang melangkahi akan dimasukkan Tuhan ia ke dalam neraka, selama pemerintah Quraisy itu masih menegakkan agama.'","r":"Bukhari"}],"te":"Meaning of Imarah and Who May Lead the State"},{"t":"Kaum Quraisy Adalah Ikutan Manusia","p":520,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Manusia itu mengikut kepada kaum Quraisy dalam urusan ini iaitu keislaman mereka mengikut kepada keislaman kaum Quraisy, dan dalam perkara kekafiran mereka mengikut kepada kekafirannya. Dan dalam satu riwayat, bahawa manusia itu mengikut kepada kaum Quraisy dalam perkara yang baik dan dalam perkara yang jahat.","r":"Muslim"}],"te":"The Quraisy Are Leaders of the People"},{"t":"Khalifah dan Raja","p":521,"v":2,"d":[{"y":"h","x":"Dari Safinah r.a. dari Nabi s.a.w. beliau bersabda: “Khalifah yang ada di kalangan umatku adalah selama 30 tahun. Kemudian rajalah yang berkuasa sesudah itu.” Berkata Safinah: Hitunglah dahulu mulai dari Khalifah Abu Bakar Sidik, Khalifah Umar, Khalifah Usman dan Khalifah Ali, lalu kita peroleh lamanya 30 tahun.","r":"Tirmizi dan Abu Daud"}],"te":"Caliphs and Kings"},{"t":"Perlantikan Khalifah","p":522,"v":2,"d":[{"y":"h","x":"Dari Ibnu Amr r.a.: Bahawasanya Nabi s.a.w. telah bersabda: Tidak halal bagi tiga orang yang mereka ada di dataran bumi, melainkan wajib di atas mereka, mengangkat salah seorang mereka jadi pemimpin.","r":"Ahmad"}],"te":"Appointing the Caliph"},{"t":"Syarat Orang yang Akan Dilantik Menjadi Khalifah","p":523,"v":2,"te":"Conditions for One Appointed Caliph"},{"t":"Baipat dan Sistem Perlantikan Ketua Negara","p":524,"v":2,"d":[{"y":"a","s":48,"a":10,"b":10,"m":""},{"y":"a","s":3,"a":159,"b":159,"m":"Ks ata SA ora a Jl; DE Maka disebabkan rahmat dari Allah-lah kamu berlaku lemah lembut terhadap mereka. Sekiranya kamu bersikap keras lagi berhati kasar, tentulah mereka menjauhkan diri dari sekelilingmu kerana itu maafkanlah mereka, mohonkanlah ampun bagi mereka dan bermesyuaratlah dengan mereka dalam urusan itu. Kemudian apabila kamu telah membulatkan tekad, maka bertawakallah kepada Allah. Sesungguhnya Allah menyukai orang-orang yang bertawakal kepada-Nya"}],"te":"Pledge of Allegiance (Bai'ah) and Choosing a Head of State"},{"t":"Kewajipan Memberikan Bapat dan Cara Melaksanakannya","p":526,"v":2,"d":[{"y":"h","x":"Dari Nabi s.a.w. ia berkata: Dan sesiapa yang mati dan belum memberikan bai'atnya, matilah ia sebagaimana mati orang jahiliah.","r":"Muslim"},{"y":"h","x":"Dari Abu Hurairahr.a. dari Nabi s.a.w. beliau bersabda:  aa guhnya tidak ada Nabi sesudahku, dan akan ada banyak khalifahkhalifah (banyak bilangan). Mereka bertanya: Apakah yang hendak engkau perintahkan kepada kami. Nabi menjawab: Sempurnakanlah bai'at yang pertama lalu yang pertama pula (sesudahnya), dan berikanlah kepada mereka hak mereka masing-masing.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ubadah bin Shamit r.a. ia berkata: Pernah kami mengikat janji setia (bai'at) terhadap Nabi s.a.w. supaya kami patuh dan taat kepada perintah dalam waktu susah dan senang, dalam waktu rajin dan malas. Kami berjanji akan tetap setia sekali pun sampai pilihan orang lain jatuh di atas diri kami, dan kami berjanji tidak akan mengambil (merebut) kekuasaan dari ahlinya. Dan kami berjanji mengatakan yang hak di mana saja kami berada. Kerana Allah kami tidak takut akan celaan orang yang mencela.","r":"Bukhari dan Muslim"}],"te":"The Duty to Give Allegiance and How It Is Done"}],"te":"Basics of Leadership"},{"t":"Perlantikan Gabenor atau Ketua Daerah","c":[{"t":"Hukum Perlantikan Ketua Daerah","p":527,"v":2,"d":[{"y":"h","x":"Dari Said bin Abu Bardah r.a. dari bapanya, ia berkata: Pernah Nabi s.a.w. mengutus bapaku dan Muaz bin Jabal ke negeri Yaman, beliau berkata: Hendaklah kamu mempermudah dan janganlah kamu mempersukar keadaan rakyat, dan hendaklah membawa kegembiraan, dan jangan suka berselisih, hendaklah kamu turut menuruti.","r":"Bukhari dan Muslim"}],"te":"Ruling on Appointing District Heads"},{"t":"Kalau Negara dalam Jajahan Kuffar","p":528,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. telah berkata: Rasulullah s.a.w. bersabda: Sesiapa yang melantik seseorang dalam satu bangsa (menjadi pemimpin), sedang di kalangan bangsa itu ada orang yang lebih reda kerana Allah (lebih layak), maka ia telah khianat terhadap Allah, Rasul-Nya dan kaum Mukmimin.","r":"Hakim dan Baihaqi"}],"te":"If the Country Is Under Non-Muslim Rule"},{"t":"Jika Pemerintahan Kafir atau Zus-Syaukah Telah Hilang","p":529,"v":2,"te":"If Non-Muslim or Powerful Rule Has Ended"},{"t":"Kewajipan Mentaati Pemimpin","p":530,"v":2,"d":[{"y":"a","s":4,"a":59,"b":59,"m":""},{"y":"h","x":"Dari Abu Hurairah r.a. daru Nabi s.a.w. beliau bersabda: Sesiapa yang mentaati aku maka sesungguhnya ia telah mentaati Allah. Dan sesiapa yang menderhakai aku, maka sesungguhnya ia telah menderhakai Allah. Dan sesiapa yang mentaati pemimpin maka sesungguhnya ia telah mentaati aku. Dan sesiapa yang menderhakai pemimpin, maka sesungguhnya ia telah menderhakai aku.","r":"Bukhari dan Muslim"}],"te":"The Duty to Obey Leaders"},{"t":"Pemimpin Islam yang tidak Diangkat oleh Umat Islam","p":531,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Mendengar dan taat, wajib atas manusia yang beragama Islam pada sesuatu yang disukainya atau yang tidak disukainya, selama ia tidak disuruh berbuat maksiat, maka jika diperintah berbuat maksiat, maka tidak boleh mendengarkan dan tidak boleh pula mentaatinya.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: “Sesiapa yang keluar dari taat dan memisahkan diri dari jemaah kemudian ia mati, maka matinya itu sebagai mati orang jahiliah (mati kafir).” Ri, Sabda Rasulullah s.a.w.:","r":"Muslim"},{"y":"h","x":"Dari Auf bin Malik, dari Nabi s.a.w. beliau bersabda: “Apabila kamu melihat sesuatu perbuatan yang kamu benci pada pemimpinmu bencilah amal perbuatannya itu dan janganlah sampai kamu..... * ” menarik dirimu dari mentaatinya.","r":"Muslim"}],"te":"Muslim Leaders Not Chosen by the Muslims"},{"t":"Menteri-Menteri dan Ketua Negara","p":533,"v":2,"d":[{"y":"a","s":20,"a":29,"b":35,"m":""},{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. Kepa Apabila Allah hendak memberi kebaikan kepada seseorang ketua negara, Allah sertakan padanya menteri-menteri yang jujur. Apabila ia lupa, Allah mengingatikannya dan apabila ia ingat Allah menolong nya. Dan apabila Allah mengkhendaki ketua negara yang lain daripada itu. (pemimpin yang tidak jujur), maka Allah sertakan padanya menteri yang jahat, jika ia lupa Allah tidak mengingatkannya dan jika ia ingat, Allah tidak menolongnya.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Buraidahr.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang sudah kami pekerjakan atas sesuatu pekerjaan, maka telah kami tentukan baginya upahnya (gajinya), maka apa-apa yang diambilnya selain dari itu, maka adalah ia orang yang khianat.","r":"Abu Daud dan Hakim"}],"te":"Ministers and the Head of State"},{"t":"Kewajipan Pemimpin","p":535,"v":2,"d":[{"y":"a","s":4,"a":57,"b":57,"m":""},{"y":"h","x":"Dari Aisyah r.a., dari Nabi s.a.w. beliau bersabda: “Dalam rumahku ini katanya: Ya Allah sesiapa yang memerintah sesuatu dari urusan umatku, lalu ia persulit urusan itu di atas mereka, maka sulit pulalah urusan di atasnya. Dan sesiapa yang memerintah sesuatu umatku, lalu ia sayang dengan mereka, maka sayang pulalah mereka kepadanya.”,","r":"Muslim"}],"te":"Duties of Leaders"}],"p":527,"v":2,"te":"Appointing Governors and District Heads"},{"t":"Qadhak","c":[{"t":"Erti Qadhak dan Susunan Pengadilan","p":536,"v":2,"d":[{"y":"a","s":4,"a":105,"b":105,"m":""},{"y":"a","s":5,"a":44,"b":44,"m":""}],"te":"Meaning of Qadha' and the Court System"},{"t":"Hakim Terbahagi Atas Tiga Bahagian","p":538,"v":2,"d":[{"y":"h","x":"Dari Abu Buraidah, dari bapanya r.a. dari Nabi s.a.w. beliau bersabda: Hakim itu ada tiga macam: Satu macam di dalam syurga tempatnya, dan yang dua macam di dalam neraka. Adapun yang di dalam syurga tempatnya ialah hakim yang mengerti akan yang benar, lalu ia menghukum dengan yang benar itu. Dan hakim yang mengerti akan kebenaran, lalu dilakukannya penindasan dalam menjalankan hukum (kerana disuap dan sebagainya), maka dia akan masuk neraka. Dan hakim yang menghukum manusia atas kejahilan, maka dia akan masuk neraka.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang dijadikan hakim di antara manusia maka sungguh ia telah disembelih dengan tidak memakai pisau.","r":"Abu Daud dan Tirmizi"}],"te":"Judges Are of Three Kinds"},{"t":"Bagi Hakim Wajib Mencari Keadilan dalam Mengadili Manusia","p":539,"v":2,"d":[{"y":"a","s":4,"a":57,"b":57,"m":""},{"y":"a","s":21,"a":78,"b":78,"m":""},{"y":"h","x":"Dari Amr bin Ash, dari Nabi s.a.w. beliau bersabda: “Apabila seorang hakim menghukum, lalu ia berijtihad, maka betul ijtihadnya itu, maka baginya bersedia dua pahala. Dan apabila ia menghukum, lalu ia berijtihad, maka salah ijtihadnya itu, maka baginya tersedia buah pahala.” ; pa","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Haris bin Amr, dari sahabat-sahabat Muaz, bahawa Rasulullah s.a.w. tatkala mengutus Muaz ke negeri Yaman ia bertanya kepadanya: Bagaimanakah caranya engkau menghukum (mengadili)? Muaz menjawab: Aku menghukum menurut apa yang ada dalam kitab Allah. Rasulullah bertanya pula: Jika tidak ada bertemu dalam kitab Allah? Muaz menjawab: Lalu dengan sunah Rasulullah s.a.w. Rasulullah bertanya pula: Jika tidak bertemu dalam sunah Rasulullah? Ia menjawab: Aku berijtihad (aku berusaha sedapat-dapatnya) menurut fikiranku. Rasulullah bersabda: Alhamdulillah (puji-pujian bagi Allah) yang telah memberi taufik akan utusan Rasulullah s.a.w.","r":"Tirmizi"}],"te":"Judges Must Seek Justice When Judging People"},{"t":"Kesopanan dalam Menghukum","p":541,"v":2,"d":[{"y":"h","x":"Dari Abdul Rahman bin Abu Bakrah r.a. ia berkata: Bersabda Rasulullah s.a.w.: Hakim tidak boleh menjatuhkan hukuman kepada dua orang yang berperkara ketika ia sedang dalam keadaan marah.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdullah bin Zubair r.a. ia berkata: Rasulullah s.a.w. telah menjatuhkan hukuman sedang kedua orang yang berselisih itu duduk di had, hakim. uduk di hadapan hakim","r":"Abu Daud"},{"y":"h","x":"Dari Ali r.a. ia berkata: Bersabda Rasullah s.a.w.: Apabila dua orang laki-laki minta hukum kepada engkau, maka janganlah engkau putuskan hukum bagi yang pertama sebelum engkau dengar perkataan yang kedua, dengan begitu engkau akan mengetahui cara menghukum mereka. Berkata Ali: Sentiasalah aku menjadi kadi (menghukum seperti itu) sesudah itu.","r":"Ahmad dan Abu Daud"}],"te":"Manners of Judging"},{"t":"Haram Hukumnya Menerima Wang Suap","p":542,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Telah dikutuki oleh Rasulullah s.a.w. akan orang yang memberi wang suap dan yang menerimanya dalam perkara hukum.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Muaz bin Jabal r.a. ia berkata: Telah diutus aku oleh Rasulullah s.a.w. ke negeri Yaman, tatkala aku telah berangkat di waktu malam, disuruhnya aku pulang, maka Rasulullah s.a.w. bersabda: Janganlah kamu terima sesuatu dengan tidak seizinku, sebab hal yang semacam itu termasuk penipuan dan siapa yang menipu ia akan dihadapkan dengan perbuatannya (penipuan) itu di hari kiamat, kerana itulah engkau aku panggil kembali, dan sekarang teruslah engkau berangkat untuk melakukan tugasmu.","r":"Tirmizi"}],"te":"Accepting Bribes Is Forbidden"},{"t":"Turun dari Jabatan","p":545,"v":2,"te":"Leaving Office"},{"t":"Pendakwa dan Terdakwa","p":545,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. dari Nabi s.a.w. bersabda: “Seandainya manusia itu diberi menurut dakwa mereka, nescaya mendakwalah mereka akan darah dan harta orang lain, akan tetapi sumpah hak atas orang yang terdakwa.” ! |","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abdullah Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: “Keterangan (saksi) adalah hak atas orang yang mendakwa, sedang sumpah adalah hak atas orang yang terdakwa.”","r":"Tirmizi"},{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Nabi s.a.w. pernah membalikkan sumpah atas orang yang meminta hak.","r":"Daruqutni"}],"te":"Claimant and Defendant"},{"t":"Keterangan dan Alat-Alat Bukti","p":547,"v":2,"d":[{"y":"h","x":"Dari Abu Umaiyah Al-Makhzumi r.a. ia Da “Pernah dini kepada Rasulullah s.a.w. (seseorang) dengan membawa seorang pencuri yang telah mengaku sebenarnya ia mencuri, sedang barangbarang yang dicurinya itu tidak terdapat padanya. Rasulullah s.a.w. berkata kepadanya: Barangkali bukan engkau yang mencuri. Ia menjawab: Ya, betul saya telah mencuri. Diulangnya ucapannya itu sampai tiga kali. Lalu diperintahkan oleh Nabi supaya dijatuhi huk ti tangan.” Sana maa ia","r":"Abu Daud dan Nasai"},{"y":"a","s":3,"a":18,"b":18,"m":""}],"te":"Testimony and Evidence"},{"t":"Erti Saksi, Rukun dan Syaratsyaratnya","p":548,"v":2,"d":[{"y":"a","s":2,"a":282,"b":282,"m":"Aku bersaksi..... Syarat-syarat orang yang akan dijadikan saksi itu ialah: Pertama: Mukallaf, iaitu sudah baligh berakal, maka tidaklah sah atau diterima jadi saksi anak kecil, kerana belum berakal. Firman Allah s.w.t.: $   P. eo - na - ma oo 7 (jo Ka Lan YA al a gg Pr Ia Aga Ia Dan kemukakanlah dua orang saksi di antara orang laki-lakimu"},{"y":"a","s":65,"a":2,"b":2,"m":""},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Telah bersabda Rasulullah s.a.w.: Sesungguhnya tidak boleh dijadikan saksi orang yang khianat, lakilaki atau perempuan. Dan tidak boleh orang yang dengki jadi saksi atas saudaranya. Dan tidak boleh pula orang yang diam dalam satu rumahtangga bagi orang yang serumah dengan dia.","r":"Ahmad dan Abu Daud"}],"te":"Meaning, Pillars and Conditions of Witnesses"},{"t":"Saksi-Saksi untuk Macam-Macam","p":550,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Orang-orang (memperkatakan, bahawa ada orang) melihat anak bulan, lalu aku sampaikan kepada Rasulullah s.a.w. bahawa aku telah melihatnya. Lantas beliau berpuasa dan menyuruh manusia mempuasakan bulan Ramadan itu.","r":"Abu Daud dan Ibnu Hibban"},{"y":"h","x":"Dari Zuhri ia berkata: Telah berjalan hukum syariat Nabi s.a.w. iaitu tidak boleh perempuan menjadi saksi dalam perkara had, dan tidak pula pada waktu nikah, dan tidak pula dalam perkara talak.","r":"Malik"},{"y":"h","x":"Dari Zuhri ia berkata: Telah berjalan hukum syariat, bahawa perempuan boleh menjadi saksi iaitu pada barang yang tidak dapat dilihat kecuali oleh perempuan pula, iaitu perkara perempuan melahirkan dan aib-aib kaum perempuan.","r":"Abu Shaibah"},{"y":"a","s":2,"a":282,"b":282,"m":""},{"y":"h","x":"Dari Ibnu Abbas r.a. bahawa Nabi s.a.w. pernah memutuskan hukum dengan sumpah dan seorang saksi laki-laki.","r":"Muslim dan Abu Daud"}],"te":"Witnesses for Different Cases"},{"t":"Saksi Palsu Merupakan Salah Satu Dosa Besar","p":552,"v":2,"d":[{"y":"h","x":"Dari Khuraim bin Fatik r.a. ia berkata: Telah pn Nabi s.a.w.: Samalah dosa saksi yang dusta dengan syirik kepada Allah. Ucapan ini diulangi beliau sampai tiga kali, kemudian beliau baca ayat: Maka jauhilah olehmu najis, berhala-berhala dan jauhilah perkataan dosa, semata-mata kerana takut kepada Allah dan tidak memperserikatakan-Nya.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Bakar r.a. dari Nabi s.a.w. beliau bersabda: Mahukah kamu aku ceritakan dosa yang sebesar-besarnya? Mereka menjawab: Mahu, ya Rasulullah. Nabi berkata: Mempersekutukan Allah, menderhakai ibu bapa dan menjadi saksi yang dusta atau mengatakan yang dusta.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Umarr.a. dari Nabi s.a.w. beliau bersabda: Sentiasalah telapak kaki saksi yang dusta itu, hingga Allah mewajibkan neraka baginya.","r":"Ibnu Majah"}],"te":"False Testimony Is a Major Sin"},{"t":"Hakim boleh Berpegang kepada Fakta dari Masing-Masing yang Berperkara Secara Zahir","p":554,"v":2,"d":[{"y":"h","x":"Dari Ummu Salamah r.a. ia berkata: Telah bersabda Rasulullah s.a.w: Aku hanya seorang manusia dan sesungguhnya kamu mengadakan perselisihan kepadaku, barangkali di antara kamu ada yang lebih pandai dalam bersoal-jawab dari yang lain. Lalu aku jatuhkan putusan baginya menurut keterangan yang aku dengar daripadanya. Maka sesiapa yang telah aku putuskan hukumnya dan dia beroleh kemenangan dari saudaranya dalam sesuatu perkara, janganlah ia ambil kemenangan yang bukan haknya itu, kerana itu bererti aku telah memotongkan baginya sepotong dari api neraka.","r":"Bukhari dan Muslim"}],"te":"A Judge May Rely on the Outward Facts of Each Party"}],"p":536,"v":2,"d":[{"y":"a","s":17,"a":23,"b":23,"m":""}],"te":"Judiciary (Qadha')"},{"t":"Sumpah","c":[{"t":"Erti Sumpah dan Kegunaannya","p":556,"v":2,"te":"Meaning and Purpose of Oaths"},{"t":"Sumpah yang Sah hanya dengan Nama Allah atau dengan Sifatnya","p":557,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. dari Nabi s.a.w. beliau bersabda: Hai umat Muhammad, demi Allah, andaikata kamu mengetahui akan apa yang aku ketahui nescaya kamu akan banyak menangis dan akan sedikit tertawa.","r":"Bukhari"},{"y":"h","x":"Dari Ibnu Abbas r.a. Bahawasanya Nabi s.a.w. pernah bersabda kepada seorang laki-laki yang disuruhnya bersumpah, katanya: Bersumpahlah kamu dengan nama Allah, yang tidak ada tuhan melainkan Dia, kalau memang betul tidak ada haknya pada kamu sedikit pun.","r":"Abu Daud dan Nasai"},{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Pernah Nabi s.a.w. bersumpah: Tidak, demi yang memutarbalikkan hati.","r":"Bukhari dan Abu Daud"}],"te":"An Oath Is Valid Only by Allah's Name or Attributes"},{"t":"Bersumpah dengan selain Allah Musyrik Hukumnya","p":558,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesiapa yang bersumpah bukan dengan nama Allah, maka sungguh ia telah musyrik.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Buraidah, dari bapanya r.a., dari Nabi s.a.w. beliau bersabda: Sesiapa yang bersumpah lalu ia berkata: Sesungguhnya aku lepas dari agama Islam, maka jika ia berdusta, maka adalah sebagaimana yang telah diucapkannya itu dan jika ia benar, maka ia sekali-kali tidak dapat kembali kepada Islam secara selamat.","r":"Abu Daud dan Nasai"}],"te":"Swearing by Other Than Allah Is Shirk"},{"t":"Sumpah Dusta Termasuk Dosa Besar","p":559,"v":2,"d":[{"y":"h","x":"Dari Abdullah bin Umar dari Nabi s.a.w. beliau bersabda: Dosa besar ialah syirik dengan Allah, dan menderhakai kedua orang ibubapa, membunuh diri dan sumpah yang dusta.","r":"Bukhari"}],"te":"A False Oath Is a Major Sin"},{"t":"Sumpah yang tidak Memberatkan","p":560,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. tentang firman Allah Taala yang berbunyi: Allah tidak menyeksamu dengan sebab sumpahmu yang kosong. Dan dikatakan pula ayat itu diturunkan pada katanya seseorang: Bukan, demi Allah, dan: Ya, demi Allah.","r":"Bukhari"},{"y":"h","x":"Dari Aisyah r.a. bahawa Rasulullah s.a.w. bersabda: Itu perkataan laki-laki di rumahnya: Sekali-kali bukan, demi Allah, dan betul, demi Allah.","r":"Abu Daud dan Ibnu Hibban"},{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang bersumpah dengan suatu sumpah, lalu ia berkata: Insya Allah, maka sungguh ia telah lepas dari sumpahnya.","r":"Tirmizi dan Ibnu Majah"}],"te":"Oaths That Are Not Binding"},{"t":"Memberatkan Sumpah","p":561,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. bahawa Nabi s.a.w. bersabda: Tiga macam orang yang Allah tidak akan berkata-kata dengan mereka pada hari kiamat, dan Allah tidak akan membersihkan mereka serta bagi mereka azab yang pedih. Rasulullah menghitung, di antaranya laki-laki yang mengucapkan suatu sumpah yang dusta sesudah sembahyang Asar, dan dengan sumpahnya itu ia hendak mengambil harta orang Islam.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Jabir r.a. dari Nabi s.a.w. beliau bersabda: Tidaklah mengucapkan seseorang di dekat mimbarku ini akan suatu sumpah yang dusta, sekalipun mengenai sebuah penggosok gigi yang telah hijau, melainkan telah tersedialah tempatnya dalam neraka.","r":"Abu Daud dan Nasai"},{"y":"a","s":3,"a":77,"b":77,"m":"Letakkanlah tanganmu di atas surah ini, lalu dibacakan ayat yang berbunyi: Pat Po a P z Sa ena Wala Sg Sr 3 Zn BH Sesungguhnya orang-orang yang menukar janji Allah dan sumpah mereka dengan harga yang murah, mereka ini tidaklah mendapat i hari akhirat. N Keuntungan dihari akhura"},{"y":"a","s":66,"a":2,"b":2,"m":"ii 3 Sa A a Aa Sa ka a Si Yaa * Sungguh Allah telah mewajibkan kebebasan sumpahmu, sedang Allah itu adalah perapan dan dia Maha mengetahui lagi bijaksana"},{"y":"h","x":"Dari Abu Al-Asy'ari r.a. ia berkatta: Telah bersabda Rasulullah s.a.w.: Dan sesungguhnya aku, demi Allah jika Allah menghendaki, tidaklah aku bersumpah atas sesuatu sumpah, lalu aku melihat yang lebih baik daripadanya, melainkan aku membayar kifarat sumpahku itu, dan aku datangkanlah sesuatu yang lebih baik itu.","r":"Muslim dan Nasai"}],"te":"Making an Oath Weightier"},{"t":"Surat Menyurat","p":564,"v":2,"d":[{"y":"a","s":2,"a":282,"b":282,"m":"ikatan (ijab kabul) diperlukan surat menyurat, gunanya untuk menghindarkan pertengkaran dan perselisihan di kemudian hari. Allah berfirman di dalam Al-Quran: N; 04 0. an Sa a Bai Dan saksikanlah olehmu, bila kamu telah berjual beli, dan tidak boleh diberati jurutulis dan tidak pula orang yang jadi saksi"},{"y":"a","s":2,"a":282,"b":282,"m":"ikatan (ijab kabul) diperlukan surat menyurat, gunanya untuk menghindarkan pertengkaran dan perselisihan di kemudian hari. Allah berfirman di dalam Al-Quran: N; 04 0. an Sa a Bai Dan saksikanlah olehmu, bila kamu telah berjual beli, dan tidak boleh diberati jurutulis dan tidak pula orang yang jadi saksi. (Surah Al-Baqarah, ayat 282). Dalam ayat sebelumnya Allah berfirman pula: Ks da daki YAY al sal 3, gn Bila kamu berhutang dengan sesuatu hutang hingga waktu yang dijanjikan, maka tuliskanlah hutang itu"}],"te":"Correspondence"}],"p":556,"v":2,"d":[{"y":"a","s":51,"a":23,"b":23,"m":""}],"te":"Oaths"},{"t":"Nazar","c":[{"t":"Erti Nazar","p":565,"v":2,"d":[{"y":"a","s":2,"a":270,"b":270,"m":"se - Dan barang yang telah kamu belanjakan dari sesuatu perbelanjaan, atau kamu bernazar dari sesuatu nazar, maka sesungguhnya Allah telah mengetahuinya, dan tidaklah ada pertolongan bagi orang yang aniaya"}],"te":"Meaning of Nazar"},{"t":"Yang tidak boleh Dinazarkan","p":566,"v":2,"d":[{"y":"h","x":"Dari Imran bin Hushain r.a. dari Nabi s.a.w. beliau bersabda: Tidak boleh menyempurnakan nazar dalam perkara maksiat, dan tidak pula pada sesuatu barang yang tidak dimiliki oleh seorang hampar )-","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Ibnu Abbasr.a. ia berkata: Telah bersabda Rasulullah s.a.w. dalam perkara seorang laki-laki yang bernazar, ia berkata akan berdiri terus, tidak akan duduk, tidak akan berlindung, tidak akan ' berkata-kata dan akan puasa terus, katanya: Suruhlah dia supaya berkata-kata, berlindung, duduk, dan hendaklah ia sempurnakan Pera","r":"Bukhari"}],"te":"What May Not Be Vowed"},{"t":"Nazar Mayat Wajib Dibayarkan","p":566,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Pernah Sa'ad bin Ubadah meminta keterangan kepada Rasulullah s.a.w. dalam perkara nazar yang wajib atas ibunya yang telah meninggal dunia sebelum nazar itu dapat dibayarkan. Rasulullah s.a.w. bersabda: “Hendaklah engkau bayarkan nazarnya itu.”, g :","r":"Bukhari dan Muslim"}],"te":"A Deceased Person's Vow Must Be Fulfilled"},{"t":"Bernazar ke Tempat-Tempat Tertentu","p":568,"v":2,"d":[{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya, bahawa seorang perempuan pernah bertanya: Ya Rasulullah! Sesungguhnya aku pernah bernazar menyembelih (binatang ternak) ke tempat itu dan itu. Iaitu tempat yang pernah orang Jahiliah menyembelih padanya. Rasulullah s.a.w. menjawab: Apakah untuk memuliakan patung? Perempuan itu menjawab: Bukan. Rasulullah s.a.w. bertanya lagi: Apakah untuk memuliakan patung?'' Perempuan itu menjawab: Bukan. Rasulullah bersabda lagi: Sempurnakanlah nazar engkau.","r":"Abu Daud"}],"te":"Vowing to Go to Particular Places"},{"t":"Nazar yang Mewajibkan Kifarat","p":569,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Bersabda Rasulullah s.a.w.: Sesiapa yang bernazar dengan sesuatu nazar yang tidak disebutkannya, maka kifaratnya ialah kifarat sumpah. Dan sesiapa yang bernazar dengan sesuatu nazar dalam perkara maksiat, maka kifaratnya ialah kifarat sumpah, dan sesiapa yang bernazar dengan suatu nazar tidak dapat dikerjakannya maka kifaratnya ialah kifarat sumpah, dan sesiapa yang bernazar dengan suatu nazar yang dapat dilakukannya maka hendaklah ia sempurnakan nazarnya itu.'","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Uqbah bin Amir, dari Nabi s.a.w. beliau bersabda: “Kifarat nazar ialah kifarat sumpah.” :,","r":"Muslim dan Abu Daud"}],"te":"Vows That Require Expiation"},{"t":"Kifarat Sumpah dan Nazar","p":570,"v":2,"d":[{"y":"a","s":5,"a":89,"b":89,"m":""},{"y":"h","x":"Dari Nafi' r.a. ia berkata: Adalah Ibnu Umar r.a. mengeluarkan zakat bulan Ramadan (zakat fitrah) dengan cupak Nabi s.a.w. iaitu cupak yang mula-mula (dipakai oleh Nabi), dan pada kifarat sumpah dengan cupak Nabi s.a.w.","r":"Bukhari"}],"te":"Expiation for Oaths and Vows"}],"p":565,"v":2,"te":"Vows (Nazar)"}],"p":519,"v":2,"te":"Book of Leadership (Imarah)"},{"t":"Kitab Jihad","c":[{"t":"Asas Jihad","p":571,"v":2,"c":[{"t":"Erti Jihad dan Gunanya Perang Disyariatkan","p":571,"v":2,"d":[{"y":"a","s":2,"a":190,"b":190,"m":""},{"y":"a","s":2,"a":193,"b":193,"m":""},{"y":"a","s":22,"a":39,"b":39,"m":""}],"te":"Meaning of Jihad and Why Fighting Was Prescribed"},{"t":"Hukum Berperang","p":573,"v":2,"d":[{"y":"a","s":2,"a":216,"b":216,"m":""},{"y":"a","s":9,"a":122,"b":122,"m":""},{"y":"h","x":"Dari Anas r.a. bahawa Nabi s.a.w. telah bersabda: Perangilah olehmu orang-orang musyrik itu dengan harta bendamu, dengan di  d d li d, h a irimu dan dengan idahmu","r":"Abu Daud dan Nasai"}],"te":"Ruling on Fighting"},{"t":"Macam-Macam Fardu Kifayah","p":574,"v":2,"te":"Kinds of Collective Obligation (Fardu Kifayah)"},{"t":"Panggilan Masuk Islam","p":575,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. bahawa Rasulullah s.a.w. bersabda:  Aku diperintah untuk memerangi manusia hingga mereka mengaku, bahawa tiada Tuhan selain Allah, dan bahawa Muhammad Rasulullah (utusan-Nya), dan mahu mengeluarkan zakat. Apabila mereka telah mengerjakan yang demikian, terpeliharalah darah mereka dan harta mereka daripadaku, kecuali dengan hak Islam dan perhitungan mereka dengan Allah.","r":"Bukhari dan Muslim"}],"te":"The Call to Islam"},{"t":"Syarat-Syarat Wajib Berperang","p":579,"v":2,"d":[{"y":"a","s":9,"a":123,"b":123,"m":""},{"y":"a","s":8,"a":65,"b":65,"m":""},{"y":"a","s":24,"a":61,"b":61,"m":""}],"te":"Conditions That Make Fighting Obligatory"},{"t":"Jihad bagi Wanita","p":581,"v":2,"d":[{"y":"h","x":"Dari Aisyah r.a. ia berkata: Pernah aku bertanya: Ya Rasulullah wajibkah atas kaum wanita berperang? Nabi menjawab: Ya, akan tetapi peperangannya tidaklah berbunuh-bunuhan padanya, iaitu Bal dan waran.","r":"Baihaqi dan Ibnu Majah"}],"te":"Jihad for Women"},{"t":"Orang yang Haram Pergi Perang","p":581,"v":2,"d":[{"y":"h","x":"Dari Ibnu Amr bin Ash r.a. bahawa Rasulullah s.a.w. pernah bersabda: Allah mengampuni dosa orang-orang yang mati syahid dikecualikan perkara hutang piutangnya.","r":"Muslim"},{"y":"h","x":"Dari Muawiyah r.a. bahawa bapanya, Jahimah pernah datang kepada Nabi s.a.w. hendak berunding tentang pergi berperang, lalu Rasulullah s.a.w. bersabda: Apakah engkau ada ibu? menjawab: Ia menjawab: Ada. Rasulullah s.a.w. bersabda: Temanilah (rawat) dia, kerana sesungguhnya syurga terletak di bawah telapak kakinya.","r":"Nasai"}],"te":"Those Forbidden to Go to War"},{"t":"Mengadakan Pertahanan Terhadap Musuh yang Menyerang","p":583,"v":2,"d":[{"y":"a","s":2,"a":190,"b":190,"m":""},{"y":"a","s":8,"a":60,"b":60,"m":""},{"y":"h","x":"Dari Abdullah bin Abu Aufa r.a. bahawa Rasulullah s.a.w. bersabda: Hai manusia, janganlah kamu bercita-cita mencari musuh, dan mintalah kepada Tuhan keselamatan, maka bila kamu menjumpai mereka, hendaklah kamu bertahan dan Ketahuilah, bahawasanya syurga di bawah bayangan pedang.","r":"Bukhari dan Muslim"}],"te":"Defending Against an Attacking Enemy"},{"t":"Perlawanan Dilakukan Satu Lawan Dua","p":584,"v":2,"d":[{"y":"a","s":8,"a":65,"b":65,"m":""},{"y":"a","s":8,"a":66,"b":66,"m":""}],"te":"One Against Two"},{"t":"Perempuan boleh Turut Perang Sebagai Jururawat","p":585,"v":2,"d":[{"y":"h","x":"Dari Ummu Athiyah r.a. ia berkata: Pernah aku a berserta Nabi s.a.w. sebanyak tujuh kali dan aku menggantikan mereka dalam kenderaan mereka, lalu aku buatkan makanan bagi mereka, dan aku ubat orang-orang yang luka, dan aku rawat orang-orang yang sakit.","r":"Muslim"},{"y":"h","x":"Dari Anas r.a. ia berkata: Pernah Nabi s.a.w. pergi berperang berserta Ummu Sulaim dan beberapa orang perempuan kaum Ansar menyertainya, lalu mereka bekerja mencarikan air (mengusahakan minuman) dan mengubati orang-orang sakit.","r":"Muslim dan Abu Daud"}],"te":"Women May Join as Nurses"}],"te":"Basics of Jihad"},{"t":"Mati Syahid","c":[{"t":"Erti Mati Syahid","p":587,"v":2,"d":[{"y":"h","x":"Dari Abu Darda' dari Nabi s.a.w. beliau Pak Orangorang yang mati syahid dapat membela (menolong) seramai 70 orang Keluarganya.","r":"Abu Daud"}],"te":"Meaning of Martyrdom"},{"t":"Niat Berjihad","p":588,"v":2,"d":[{"y":"h","x":"Dari Abu Musa r.a. ia berkata: Pernah datang seorang laki-laki kepada Nabi s.a.w. lalu berkata: Laki-laki yang berperang untuk mengharapkan rampasan, dan laki-laki yang berperang mengharap akan disebut-sebut orang namanya, dan laki-laki yang berperang kerana mengharap untuk dilihat orang keberaniannya, maka siapakah yang berperang di jalan Allah? Rasulullah menjawab: Sesiapa yang berperang dengan niat supaya kalimat Allah tinggi, maka itulah orang yang berperang di jalan Allah.","r":"Bukhari dan Muslim"}],"te":"The Intention for Jihad"},{"t":"Hal-Hal yang Penting dalam Perang","p":589,"v":2,"d":[{"y":"h","x":"Dari Abdullah bin Abu Aufa meriwayatkan bahawa Rasulullah s.a.w. Pernah di saat beliau akan menemui musuhnya beliau berhenti beberapa ketika untuk berdoa kepada Allah: Ya Allah, Yang menurunkan kitab, yang menghembuskan angin dan yang dapat memecah belahkan tentera musuh, usirlah mereka dan tolonglah kami untuk mengalahkan mereka.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Peperangan ialah tipu muslihat., :.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Muhallab bin Abu Shufrah r.a. ia berkata: Telah bercerita kepadaku seseorang yang pernah mendengar Nabi s.a.w. bersabda: Apabila kamu diserbu di waktu malam maka hendaklah ada tandamu Haa Miim La Yunsorun.","r":"Abu Daud dan Nasai"}],"te":"Important Matters in War"},{"t":"Bendera Rasulullah ﷺ","p":590,"v":2,"d":[{"y":"h","x":"Dari Al-Barak bin Azib r.a. bahawa ia pernah ditanya orang tentang bendera perang Rasulullah s.a.w. maka ia berkata: Adalah bendera itu berwarna hitam empat persegi dibuat daripada kain buna","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Adalah bendera perang Rasulullah s.a.w. hitam warnanya, dan benderanya yang biasa (bendera besar) warnanya putih.","r":"Tirmizi"}],"te":"The Banner of the Messenger ﷺ"},{"t":"Orang-Orang yang tidak boleh Dibunuh","p":591,"v":2,"d":[{"y":"h","x":"Dari Anas r.a. bahawa Nabis.a.w. bersabda: Berangkadah kamu dengan nama Allah dan dengan Allah, dan atas agama Rasulullah. Dan janganlah kamu bunuh orang tua yang sudah lanjut usianya, dan jangan anak-anak kecil, dan jangan pula kaum wanita. Dan janganlah kamu berkhianat, dan kumpulkanlah rampasanmu, dan berbuat baiklah kamu. Sesungguhnya Allah suka kepada orang yang berbuat baik.","r":"Abu Daud"},{"y":"h","x":"Dari Anas r.a. bahawa Nabis.a.w. bersabda: Berangkadah kamu dengan nama Allah dan dengan Allah, dan atas agama Rasulullah. Dan janganlah kamu bunuh orang tua yang sudah lanjut usianya, dan jangan anak-anak kecil, dan jangan pula kaum wanita. Dan janganlah kamu berkhianat, dan kumpulkanlah rampasanmu, dan berbuat baiklah kamu. Sesungguhnya Allah suka kepada orang yang berbuat baik. (Riwayat Abu Daud). Sabda Rasulullah pula:, aa Pe, sb, SEA ARA aa Tm PI Aa KA Keta Pam JEP ua a an D SA sl, ss) MM lg, Jari Nuaim bin Mas'ud Al-Asyja'i, bahawa Nabi s.a.w. pernah bersabda kepada dua orang utusan Musailamah, ketika beliau membaca suratnya: Apakah yang kamu keduanya katakan? (Bagaimana pendapat kamu keduanya tentang isi surat ini)? Utusan itu menjawab: Kami keduanya berpendapat, sebagaimana pendapatnya. Nabi berkata: Demi Allah, kalaulah tidak kerana para utusan itu tidak boleh dibunuh, nescaya aku patahkan batang lehermu keduanya. -","r":"Abu Daud dan Ahmad"}],"te":"Those Who May Not Be Killed"},{"t":"Mata-Mata Musuh boleh Dibunuh","p":591,"v":2,"d":[{"y":"h","x":"Dari Salmah bin Akwa*? ia berkata: Pernah datang kepada Nabi s.a.w. seorang mata-mata kaum musyrik sedang Rasulullah s.a.w. dalam perjalanan, lalu beliau duduk berserta sahabat-sahabatnya bercerita-cerita, kemudian ia pergi, maka Nabi s.a.w. bersabda: Carilah dia lalu bunuhlah, lantas aku membunuhnya.","r":"Bukhari"}],"te":"Enemy Spies May Be Killed"},{"t":"Menanam Mata-Mata Dibenarkan Dalam Islam Kalau untuk Kepentingan Islam","p":593,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. ia berkata: Bersabda Rasulullah s.a.w. pada hari peperangan Ahzab (perang sekutu): Siapakah yang sanggup memberikan rahsia musuh kepada kami? Maka menjawab Zubair: Aku. Beliau mengulangi pertanyaan itu hingga tiga kali dan selalu dijawab oleh Zubair. Kemudian bersabda Rasulullah s.a.w.: Sesungguhnya bagi tiap-tiap Nabi ada pembantunya, dan bahawasanya pembantuku ialah Zubair.","r":"Bukhari dan Muslim"}],"te":"Placing Spies Is Allowed in Islam for the Interest of Islam"}],"p":587,"v":2,"d":[{"y":"a","s":3,"a":169,"b":169,"m":"A, MA dl a dg Dan janganlah kamu mengira bahawa orang-orang yang gugur di jalan Allah itu mati, bahkan mereka itu hidup di sisi Tuhannya dengan mendapat rezeki, mereka dalam keadaan gembira disebabkan kurnia Allah diberikannya kepada mereka"}],"te":"Martyrdom"},{"t":"Tawanan","c":[{"t":"Tawanan (Catatan)","p":594,"v":2,"d":[{"y":"a","s":8,"a":70,"b":70,"m":"ooo P. 0. s P) F *isi. A SA a al JUN dy Hai Nabi (Muhammad), katakanlah kepada orang-orang tawanan yang ada di dalam tanganmu, jika Allah mengetahui kebaikan hatimu, akan didatangkan-Nya kebaikan kepadamu pula, iaitu yang telah diambil-Nya daripadamu"}],"te":"Prisoners of War (Notes)"},{"t":"Keputusan yang boleh Diambil oleh Panglima Perang","p":594,"v":2,"d":[{"y":"a","s":47,"a":4,"b":4,"m":""}],"te":"Decisions a Commander May Take"},{"t":"Pandangan Islam Terhadap Orang yang Bukan Islam","p":595,"v":2,"te":"Islam's View of Non-Muslims"}],"p":594,"v":2,"te":"Prisoners of War"},{"t":"Rampasan","c":[{"t":"Ghanimah dan Pengertiannya","p":596,"v":2,"d":[{"y":"h","x":"Dari Abu Amrah r.a. bahawa Nabi s.a.w. telah memberikan untuk kuda dua bahagian dan bagi tiap-tiap seorang satu bahagian, maka adalah jumlah bagi orang yang Lerkuda tiga bahagian.","r":"Abu Daud"},{"y":"a","s":8,"a":41,"b":41,"m":""}],"te":"Ghanimah and Its Meaning"},{"t":"Al-Faiu' dan Pengertiannya","p":598,"v":2,"d":[{"y":"a","s":59,"a":6,"b":6,"m":""},{"y":"a","s":59,"a":7,"b":7,"m":""}],"te":"Al-Fai' and Its Meaning"},{"t":"Salab dan Pengertiannya","p":599,"v":2,"d":[{"y":"h","x":"Dari Auf bin Malik, bahawa Nabi s.a.w. telah menetapkan memberikan salab kepada orang yang membunuh, dan tidak dibahagikan lima.","r":"Abu Daud dan Ibnu Hibban"}],"te":"Salab and Its Meaning"},{"t":"Nafal dan Pengertiannya","p":600,"v":2,"d":[{"y":"a","s":8,"a":1,"b":1,"m":""},{"y":"h","x":"Dari Habib bin Salmah r.a. ia berkata: Adalah Nabi s.a.w. mengambil seperempat sesudah seperlima, dan sepertiga sesudah seperlima bila ia telah kembali.","r":"Abu Daud dan Tirmizi"},{"y":"a","s":9,"a":29,"b":29,"m":""},{"y":"h","x":"Dari Abdul Rahman bin Auf, bahawasanya Nabi s.a.w. telah mengambil pajak dari kaum Majusi (di) Hajar.","r":"Bukhari dan Abu Daud"},{"y":"h","x":"Dari Anas r.a. ia berkata: “Telah diutus oleh Nabi s.a.w. Khalid bin Walid kepada raja Ukaidir di Daumah, kemudian mereka datang bersama-sama dengan dia kepada Nabi s.a.w., lalu Rasulullah menjamin keselamatannya dan didamaikan dengan jalan memb jak.” ayar paja","r":"Abu Daud"}],"te":"Nafal and Its Meaning"},{"t":"Ukuran Pajak Setiap Kepala","p":602,"v":2,"d":[{"y":"h","x":"Dari Muaz bin Jabal r.a. ia berkata: “Telah diutus aku oleh Rasulullah s.a.w. ke negeri Yaman, dan disuruhnya aku memungut dari tiap-tiap orang laki-laki yang telah baligh sedinar atau yang seharganya dengan kain Ma'afir.”. :","r":"Abu Daud dan Ibnu Majah"},{"y":"h","x":"Dari Mujahid r.a. bahawa ia pernah ditanya orang tentang penduduk Syam dalam perkara pajak yang diwajibkan atas mereka, iaitu empat dinar, dan kepada penduduk Yaman diwajibkan atas mereka satu dinar. Ia berkata: Diputuskan demikian itu, melihat kaya miskin orang.","r":"Bukhari"}],"te":"Poll Tax per Head"},{"t":"Al-Usyur (Cukai)","p":603,"v":2,"te":"Tithe (Al-Usyur)"}],"p":596,"v":2,"te":"Spoils of War"},{"t":"Ajaran Islam Adalah Tinggi","c":[{"t":"Al-Muhadanah (Perletakan Senjata)","p":605,"v":2,"d":[{"y":"a","s":8,"a":61,"b":61,"m":""},{"y":"h","x":"Dari Miswar bin. Makhzamah r.a. bahawa mereka (ahli Mekah) telah berdamai untuk menghentikan perang selama sepuluh tahun, yang manusia dapat aman selama itu, dan bahawa antara kita ada satu perjanjian yang mengikat, dan sesungguhnya selama itu tidak boleh mencuri dan tidak boleh khianat.","r":"Abu Daud"}],"te":"Truce (Al-Muhadanah)"},{"t":"Syarat dan Rukun Muhadanah","p":606,"v":2,"d":[{"y":"h","x":"Dari Al-Bara' r.a. ia berkata: Tatkala Nabi s.a.w. dikepung orang untuk memasuki Kaabah (di Mekah), Nabi membuat perdamaian dengan ahli Mekah supaya beliau boleh masuk ke Mekah, lalu beliau tinggal di Mekah selama tiga hari, dan beliau tidak dapat masuk ke Mekah melainkan dengan meletakkan senjata, iaitu pedang dalam sarungnya.","r":"Bukhari dan Muslim"},{"y":"a","s":9,"a":1,"b":3,"m":""},{"y":"a","s":9,"a":1,"b":1,"m":"Waktu tentera Islam telah kuat, Allah menurunkan ayatNya kepada Rasulullah s.a.w. PE PR Era a Ka ju Saga Kebebasan daripada Allah dan Rasul-Nya"}],"te":"Conditions and Pillars of a Truce"},{"t":"Perjanjian-Perjanjian yang Dapat Menjamin Keamanan Orang Kafir","p":607,"v":2,"d":[{"y":"a","s":9,"a":6,"b":6,"m":""}],"te":"Agreements That Guarantee the Safety of Non-Muslims"}],"p":604,"v":2,"d":[{"y":"h","x":"Dari Aiz bin Amr Al-Muzanni, dari Nabi s.a.w. beliau bersabda: “Islam itu tinggi dan tidak dapat diatasi.”.,","r":"Daruqutni"}],"te":"The Teachings of Islam Are Supreme"},{"t":"Perlumbaan","c":[{"t":"Erti Perlumbaan","p":607,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. ia pernah berkata: Pernah Nabi s.a.w. berlumba berpacu kuda dan kuda beliau itu sungguh-sungguh telah beliau andam, lalu beliau lepaskan dari Hatya' dan kesudahannya Saniyah Wada'. Dan pernah pula Nabi s.a.w. memperlumbakan kuda beliau antara kuda-kuda jantan yang kudanya itu tidak diandam lebih dahulu, mulai dari Saniyah hingga masjid Bani Zuraiq. Dan adalah Ibnu Umar ada dalam orang yang berlumba.","r":"Bukhari dan Muslim"},{"y":"h","x":"Dari Anas r.a. berkata: “Adalah Nabi s.a.w. mempunyai seekor unta betina, yang bernama Al-Adhba' (sebelah telinga dilubangkan), yang tidak pernah didahului. Lalu datang seorang Arab membawa seekor unta gadis, lalu didahuluinya unta Rasulullah s.a.w. tadi.” £","r":"Bakai dan Nrerei"},{"y":"h","x":"Dari Uqbah bin Amir r.a. ia berkata: Pernah aku mendengar Nabi s.a.w. sedang di atas mimbar bersabda: Dan sediakanlah olehmu untuk menghadapi kekuatan mereka apa yang dapat kamu usahakan. Ketahuilah, bahawa kekuatan itu ialah memanah. Ketahuilah bahawa kekuatan itu ialah memanah. Ketahuilah bahawa kekuatan ialah memanah.","r":"Muslim dan Abu Daud"},{"y":"h","x":"Dari Aisyah r.a. ia berkata: Pernah aku berserta Nabi s.a.w. dalam satu perjalanan. Lalu aku berlumba lari dengan beliau, maka aku mendahului lari beliau. Maka waktu aku membawa daging, aku pernah pula berlumba dengan beliau, lalu beliau mendahului aku. Lalu beliau bersabda: Ini dengan sebab berlumba.","r":"Abu Daud"}],"te":"Meaning of Racing"},{"t":"Syarat-Syarat Mengadakan Perlumbaan","p":611,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Tidaklah boleh memberikan hadiah untuk berlumba, kecuali dalam perlumbaan unta, kuda atau perlumbaan dengan anak panah.","r":"Abu Daud dan Tirmizi"},{"y":"h","x":"Dari Abu Hurairah r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang memasukkan kuda antara dua ekor kuda, dan kuda itu belum dipercayai bahawa ia yang akan dahulu, maka tidaklah mengapa, tetapi jika diyakini dia yang akan menang maka itu adalah masuk judk","r":"Ahmad dan Abu Daud"}],"te":"Conditions for Holding a Race"},{"t":"Mengadu Binatang","p":3,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Telah Ana oleh Nabi s.a.w. mengadu binatang-binatang.","r":"Abu Daud dan Tirmizi"}],"te":"Animal Fighting"}],"p":607,"v":2,"te":"Racing"},{"t":"Merdeka","c":[{"t":"Erti Merdeka","p":613,"v":2,"d":[{"y":"a","s":90,"a":11,"b":14,"m":""}],"te":"Meaning of Freeing Slaves"},{"t":"Merdeka Anak dan Bapa","p":613,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairahr.a. dari Nabi s.a.w. beliau bersabda: “Belumlah menyamai (mengimbangi) anak akan bapanya melainkan apabila diperolehnya bapanya itu dalam keadaan hamba, lalu dibelinya, lantas dimerdekakannya.” ;,","r":"Muslim"},{"y":"h","x":"Dari Samurah bin Jundub r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang memiliki seseorang yang haram dinikahinya, maka Orang ru telah merdeka,","r":"Abu Daud dan Tirmizi"}],"te":"Freedom of Child and Father"},{"t":"Hamba Syarikat","p":614,"v":2,"d":[{"y":"h","x":"Dari Ibnu Umar r.a. dari Nabi s.a.w. beliau bersabda: Sesiapa yang telah memerdekakan seorang hamba yang dimiliki bersama, maka atasnyalah kemerdekaannya seluruhnya jika ia ada harta yang sampai seharga hamba itu. Tetapi apabila ia tidak ada harta, merdekalah daripadanya apa yang telah dimerdekakannya.","r":"Bukhari dan Muslim"}],"te":"A Jointly Owned Slave"},{"t":"Hamba Mukatab","p":615,"v":2,"d":[{"y":"a","s":24,"a":33,"b":33,"m":"- ha | SS SE ke Sesi Da sa, jg se. 0 0. hon AR Kn a Dan yang meminta surat-menyurat (kitabah) dari hamba-hambamu, maka surat menyuratlah dengan mereka, jika kamu mengetahui ada kebaikannya pada mereka"},{"y":"h","x":"Dari Amr bin Syuaib, dari bapanya, dari datuknya r.a. dari Nabi s.a.w. beliau bersabda: “Seorang hamba yang membuat perjanjian atas seratus uqiyah, lalu dia membayarnya (semua) kecuali sepuluh uqiyah, maka hamba itu masih dinamakan hamba. Dan seorang hamba yang membuat perjanjian atas seratus dinar, lalu dia membayarnya (semua) kecuali sepuluh dinar, maka hamba itu masih dinamakan hamba.”. Ma","r":"Tirmizi dan Abu Daud"},{"y":"a","s":24,"a":33,"b":33,"m":"Aku terima kitabah yang demikian itu. 2. Ganti dari hutang atau manfaat yang dijanjikan, yang sifatnya terperinci, sekurang-kurangnya dua kali ansuran atau lebih dengan menyatakan ukuran dan sifat penggantinya itu serta bilangan perinciannya. Bila gantinya itu telah diberikan oleh hamba, seperti membuat rumah atau kerja di kebun, maka mestilah penghulunya itu menghapuskan bila ada kekurangan-kekurangan yang tidak begitu banyak, gunanya ialah untuk menolong hamba itu. Firman Allah s.w.t.: a 3; Dan berikanlah olehmu kepada mereka harta Allah yang telah diberikan-Nya kepadamu"}],"te":"A Slave Under Contract (Mukatab)"},{"t":"Hamba Mudabbar","p":617,"v":2,"d":[{"y":"h","x":"Dari Jabir r.a. bahawa seorang laki-laki kaum Ansar pernah memerdekakan seorang hamba sesudah ia mati, yang tidak ada baginya harta selain hamba itu, maka sampailah khabar itu kepada Nabi s.a.w. Lantas beliau bersabda: “Siapakah yang hendak membelinya daripadaku?” Maka dibelilah oleh Nuaim bin Abdullah dengan harga lapan ratus dirham, lalu diserahkanyalah wang itu kepadanya.","r":"Bukhari dan Muslim"}],"te":"A Slave Freed on the Owner's Death (Mudabbar)"},{"t":"Ummul Walad","p":618,"v":2,"d":[{"y":"h","x":"Dari Ibnu Abbas r.a. ia berkata: Bersabda Rasulullah s.a.w.: Mana-mana hamba perempuan yang telah melahirkan anak kerana tuannya, maka hamba itu merdeka sesudah penghulunya itu meninggal.","r":"Ibnu Majah dan Hakim"},{"y":"h","x":"Dari Ibnu Umarr.a. dari Nabi s.a.w. bahawa beliau telah melarang menjual ibu anak (ummul walad), dan beliau bersabda: Tidak boleh mereka dijual, diberikan dan tidak pula boleh diwariskan, yang dengan dia tuannya dapat bersenang-senang selama ia hidup, dan bila tuannya telah meninggal, maka ia menjadi orang yang merdeka.","r":"Daruqutni"}],"te":"Mother of the Owner's Child (Ummul Walad)"},{"t":"Keutamaan Merdekakan Hamba","p":619,"v":2,"d":[{"y":"h","x":"Dari Abu Hurairah r.a. ia berkata: Bersabda Rasulullah s.a.w. Sesiapa di antara orang muslim yang telah memerdekakan hamba yang muslim, Allah akan melepaskan tiap-tiap anggotanya dengan satu anggota hamba yang dimerdekakannya dari neraka.","r":"Bukhari dan Muslim"}],"te":"Virtue of Freeing Slaves"}],"p":613,"v":2,"te":"Freeing Slaves"}],"p":571,"v":2,"te":"Book of Jihad"}],"p":420,"v":2,"te":"Quarter of Criminal Law (Jinayat)"}],"te":"Shafi'i Fiqh"};
